def print_grid(grid):
    """
    Prints the current state of the grid.
    """
    for row in grid:
        print(''.join(row))
    print()

def find_player(grid):
    """
    Finds the current position of the player 'P' in the grid.
    Returns a tuple (row, column) if found, otherwise None.
    """
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == 'P':
                return i, j
    return None

def move_player(grid, direction):
    """
    Moves the player in the specified direction if possible.
    """
    px, py = find_player(grid)
    if direction == 'L' and grid[px][py - 1] != '#':
        grid[px][py], grid[px][py - 1] = grid[px][py - 1], grid[px][py]
    elif direction == 'R' and grid[px][py + 1] != '#':
        grid[px][py], grid[px][py + 1] = grid[px][py + 1], grid[px][py]
    elif direction == 'U' and grid[px - 1][py] != '#':
        grid[px][py], grid[px - 1][py] = grid[px - 1][py], grid[px][py]
    elif direction == 'D' and grid[px + 1][py] != '#':
        grid[px][py], grid[px + 1][py] = grid[px + 1][py], grid[px][py]

def items_collected(grid):
    """
    Checks if all items 'I' have been collected.
    Returns True if all items are collected, otherwise False.
    """
    return all(cell != 'I' for row in grid for cell in row)

def game_loop(grid, moves):
    """
    Runs the game loop, processing each move and printing the grid.
    """
    print("Welcome to the Collecting Items Game!")
    print_grid(grid)

    for move in moves:
        if move in 'LRUD':
            move_player(grid, move)
            print_grid(grid)
        else:
            print("Invalid move, try again.")
        if items_collected(grid):
            print("Congratulations! You've collected all items.")
            break

# Example grid setup:
grid = [
    ['#', '#', '#', '#', '#'],
    ['#', 'P', 'I', '#', '#'],
    ['#', '#', 'I', '#', '#'],
    ['#', '#', '#', '#', '#'],
]

# Example moves:
moves = "LRDD"

game_loop(grid, moves)
