class BankAccount:
    def __init__(self, account_holder, initial_balance=0):
        """Initialize a new bank account with the given account holder and initial balance."""
        self.account_holder = account_holder
        self.balance = initial_balance

    def deposit(self, amount):
        """Deposit a specified positive amount into the account."""
        if amount < 0:
            raise ValueError("Deposit amount must be positive.")
        self.balance += amount

    def withdraw(self, amount):
        """Withdraw a specified positive amount from the account, ensuring sufficient funds."""
        if amount < 0:
            raise ValueError("Withdrawal amount must be positive.")
        if amount > self.balance:
            raise ValueError("Insufficient funds.")
        self.balance -= amount

    def get_balance(self):
        """Return the current balance of the account."""
        return self.balance

    def __str__(self):
        """Return a string representation of the account."""
        return f"BankAccount({self.account_holder}, Balance: {self.balance})"
