def generate_permutations(s):
    """
    Generates all possible permutations of a given string using recursion.

    :param s: A string consisting of distinct characters.
    :yield: Each permutation of the string as a string.
    """
    if len(s) == 1:
        yield s
    for i, char in enumerate(s):
        for perm in generate_permutations(s[:i] + s[i+1:]):
            yield char + perm
