import importlib.util
import sys
import os
import builtins

def restricted_dict():
    """
    Returns a dictionary of builtins with restricted access.
    """
    restricted_builtins = {k: v for k, v in builtins.__dict__.items() if k not in ['open', 'eval', 'exec', 'compile']}
    for module in ['os', 'sys', 'socket', 'subprocess', 'shutil', 'io']:
        restricted_builtins.pop(module, None)
    return restricted_builtins

def load_and_execute_module(module_path, function_name):
    """
    Loads and executes a specified function from a module located at module_path.
    """
    spec = importlib.util.spec_from_file_location("module.name", module_path)
    module = importlib.util.module_from_spec(spec)
    restricted_globals = restricted_dict()
    try:
        spec.loader.exec_module(module, restricted_globals)
        func = getattr(module, function_name)
        func()
    except FileNotFoundError:
        print(f"Module file {module_path} not found.")
    except AttributeError:
        print(f"Function {function_name} not found in module {module_path.split('/')[-1]}.")

def main(directory, function_name):
    """
    Main function to iterate over all Python files in the specified directory and execute the specified function.
    """
    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.endswith('.py'):
                module_path = os.path.join(root, file)
                load_and_execute_module(module_path, function_name)

if __name__ == '__main__':
    import argparse
    parser = argparse.ArgumentParser(description='Dynamically load and execute modules from a directory.')
    parser.add_argument('directory', help='The directory containing the Python modules.')
    parser.add_argument('function', help='The name of the function to be executed in each module.')
    args = parser.parse_args()
    main(args.directory, args.function)
