import json

def extract_emails(data):
    """
    Recursively extracts email addresses from a nested JSON structure.

    :param data: The JSON data, which can be a dictionary or a list.
    :return: A list of email addresses found in the data.
    """
    email_addresses = []
    if isinstance(data, dict):
        for key, value in data.items():
            if key == 'email' and isinstance(value, str) and '@' in value:
                email_addresses.append(value)
            email_addresses.extend(extract_emails(value))
    elif isinstance(data, list):
        for item in data:
            email_addresses.extend(extract_emails(item))
    return email_addresses

def main():
    """
    Main function to read the JSON file and print all email addresses found.
    Handles exceptions for file not found and invalid JSON format.
    """
    try:
        with open('data.json', 'r') as file:
            data = json.load(file)
    except FileNotFoundError:
        print("Error: The file 'data.json' was not found.")
        return
    except json.JSONDecodeError:
        print("Error: The file 'data.json' is not a valid JSON file.")
        return

    email_addresses = extract_emails(data)
    if not email_addresses:
        print("No email addresses found.")
    else:
        for email in email_addresses:
            print(email)

if __name__ == "__main__":
    main()
