from typing import List, Optional

def most_common_string(strings: List[str]) -> Optional[str]:
    """
    Returns the most common string in the list. If there are multiple strings with the same highest frequency,
    returns the one that appears first in the list. Returns None if the list is empty.
    """
    if not strings:
        return None

    frequency = {}
    for string in strings:
        if string in frequency:
            frequency[string] += 1
        else:
            frequency[string] = 1

    max_count = max(frequency.values())
    for string in strings:
        if frequency[string] == max_count:
            return string
