from typing import Callable

def is_prime(n: int) -> bool:
    """Check if a number is a prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def track_progress(interval: int, offset: int = 0) -> Callable[[int], bool]:
    """Create a tracker function based on a prime-number-based schedule."""
    if not is_prime(interval):
        raise ValueError("The interval must be a prime number.")

    def tracker(global_step: int) -> bool:
        """Determine if the global step should be tracked."""
        return global_step >= offset and (global_step - offset) % interval == 0

    return tracker
