def matrix_multiply(A, B):
    """ Multiplies two 2x2 matrices A and B and returns the resulting matrix. """
    return [
        [A[0][0] * B[0][0] + A[0][1] * B[1][0], A[0][0] * B[0][1] + A[0][1] * B[1][1]],
        [A[1][0] * B[0][0] + A[1][1] * B[1][0], A[1][0] * B[0][1] + A[1][1] * B[1][1]]
    ]

def matrix_power(matrix, n):
    """ Computes the power of a matrix up to n using exponentiation by squaring and returns the resulting matrix. """
    result = [[1, 0], [0, 1]]  # Identity matrix
    base = matrix

    while n > 0:
        if n % 2 == 1:
            result = matrix_multiply(result, base)
        base = matrix_multiply(base, base)
        n //= 2

    return result

def fibonacci(n):
    """ Returns the nth Fibonacci number using matrix exponentiation. """
    if n == 0:
        return 0
    elif n == 1:
        return 1

    F = [[1, 1], [1, 0]]  # Transformation matrix for Fibonacci sequence
    result = matrix_power(F, n - 1)

    return result[0][0]  # The top left cell of the matrix is F(n)

# Example usage:
n = 1000
print(f"Fibonacci number F({n}) is: {fibonacci(n)}")
