import math

def closest_to_origin(coords):
    """
    Returns the tuple with the smallest Euclidean distance to the origin (0, 0).

    :param coords: List of tuples, where each tuple contains two integers representing the x and y coordinates.
    :return: Tuple representing the coordinates closest to the origin.
    """
    def euclidean_distance(coord):
        return math.sqrt(coord[0]**2 + coord[1]**2)

    return min(coords, key=euclidean_distance)
