def validate_blog_post(blog_post):
    """
    Validates a blog post dictionary based on specific conditions.

    Parameters:
    blog_post (dict): A dictionary representing a blog post with keys 'author', 'created_utc', 'tags', 
                      'num_comments', 'is_explicit', 'content', and 'title'.

    Returns:
    bool: True if the blog post is valid, False otherwise.
    """
    if not isinstance(blog_post, dict):
        return False

    if 'author' not in blog_post or not isinstance(blog_post['author'], str) or blog_post['author'] == "":
        return False

    if 'created_utc' not in blog_post or not isinstance(blog_post['created_utc'], int) or blog_post['created_utc'] <= 0:
        return False

    if 'tags' not in blog_post or not isinstance(blog_post['tags'], list) or len(blog_post['tags']) == 0:
        return False
    if not all(isinstance(tag, str) and len(tag) <= 20 for tag in blog_post['tags']):
        return False
    if len(blog_post['tags']) != len(set(blog_post['tags'])):
        return False

    if 'num_comments' not in blog_post or not isinstance(blog_post['num_comments'], int) or blog_post['num_comments'] < 0:
        return False

    if 'is_explicit' not in blog_post or not isinstance(blog_post['is_explicit'], bool):
        return False

    if 'content' not in blog_post or not isinstance(blog_post['content'], str) or blog_post['content'] == "" or blog_post['content'] == '[removed]':
        return False

    if 'title' not in blog_post or not isinstance(blog_post['title'], str) or blog_post['title'] == "":
        return False

    return True
