def count_key_occurrences(dict_list):
    """
    Counts the occurrences of each key across a list of dictionaries.

    Parameters:
    dict_list (list of dict): A list where each element is a dictionary.

    Returns:
    dict: A dictionary with keys from the input dictionaries and values representing the count of dictionaries containing each key.
    """
    key_counts = {}

    for dictionary in dict_list:
        for key in dictionary:
            if key in key_counts:
                key_counts[key] += 1
            else:
                key_counts[key] = 1

