class Resource:
    def __init__(self, name, quantity):
        self.name = name
        self.quantity = quantity

    def __repr__(self):
        return f"{self.name}({self.quantity})"

class ProcessPlanner:
    def __init__(self):
        self.resources = {}
        self.process_history = []

    def add_resource(self, name, quantity):
        """Adds a resource with the given name and quantity to the planner."""
        if name in self.resources:
            self.resources[name].quantity += quantity
        else:
            self.resources[name] = Resource(name, quantity)

    def check_availability(self, required_resources):
        """Checks if the required resources are available in the required quantities."""
        for resource_name, quantity in required_resources:
            if self.resources.get(resource_name, Resource("", 0)).quantity < quantity:
                return False
        return True

    def use_resources(self, required_resources):
        """Decreases the quantity of the required resources."""
        for resource_name, quantity in required_resources:
            self.resources[resource_name].quantity -= quantity

    def log_process(self, process_name, required_resources):
        """Logs the process with the required resources."""
        self.process_history.append((process_name, required_resources))

    def plan_process(self, process_name, required_resources):
        """Plans a process if possible, updating resources and logging the process."""
        if not self.check_availability(required_resources):
            print(f"Not enough resources to plan {process_name}.")
            return

        if self.already_found_combination(required_resources):
            print(f"Can't reuse resources! Process {process_name} failed.")
            return

        self.use_resources(required_resources)
        self.log_process(process_name, required_resources)
        print(f"Planned {process_name}. Remaining Resources: {self.resources}")

    def already_found_combination(self, required_resources):
        """Checks if the exact combination of resources has been used before."""
        already_used = sorted(required_resources)
        past_processes = [sorted(resources) for name, resources in self.process_history]
        return already_used in past_processes

    def report_remaining_resources(self):
        """Reports the current available resources."""
        print("Current available resources: ", self.resources)

# Example usage:
planner = ProcessPlanner()
planner.add_resource('Wood', 10)
planner.add_resource('Steel', 5)
planner.add_resource('Cement', 15)

planner.plan_process('Build Frame', [('Wood', 5), ('Steel', 2)])
planner.plan_process('Build Floor', [('Cement', 10), ('Steel', 1)])
planner.plan_process('Paint Wall', [('Wood', 5), ('Steel', 2)])  # Should fail due to no new resources combination
planner.plan_process('Construct Roof', [('Steel', 1), ('Wood', 3), ('Cement', 5)])
planner.report_remaining_resources()
