class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Insert a new value into the BST."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        """Helper method to insert a new value into the BST recursively."""
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert(node.right, key)

    def find(self, key):
        """Return True if the value is present in the BST, otherwise return False."""
        return self._find(self.root, key)

    def _find(self, node, key):
        """Helper method to find a value in the BST recursively."""
        if node is None:
            return False
        if node.val == key:
            return True
        elif key < node.val:
            return self._find(node.left, key)
        else:
            return self._find(node.right, key)

    def delete(self, key):
        """Remove a value from the BST if it exists."""
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        """Helper method to delete a value from the BST recursively."""
        if node is None:
            return node

        if key < node.val:
            node.left = self._delete(node.left, key)
        elif key > node.val:
            node.right = self._delete(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            min_larger_node = self._find_min(node.right)
            node.val = min_larger_node.val
            node.right = self._delete(node.right, min_larger_node.val)

        return node

    def _find_min(self, node):
        """Helper method to find the node with the minimum value in a subtree."""
        current = node

        while current.left is not None:
            current = current.left

        return current
