def length_of_lis(nums):
    """
    Returns the length of the longest increasing subsequence in the given list of positive integers.

    :param nums: List[int] - A list of positive integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    dp = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

