def merge_dictionaries(dict_list):
    """
    Merges a list of dictionaries into a single dictionary with keys sorted lexicographically.
    Each key maps to a list of values sorted in descending order based on the dictionary's position.

    :param dict_list: List of dictionaries with the same keys.
    :return: Merged dictionary with sorted keys and values.
    """
    if not dict_list:
        return {}

    result_dict = {key: [] for key in dict_list[0]}

    for idx, d in enumerate(dict_list):
        for key in d:
            result_dict[key].append((idx, d[key]))

    for key in result_dict:
        result_dict[key].sort(key=lambda x: (-x[0], x[1]))

    for key in result_dict:
        result_dict[key] = [value for _, value in result_dict[key]]

    result_dict = {key: result_dict[key] for key in sorted(result_dict.keys())}

    return result_dict
