        'task4': [['file9.txt', 'file10.txt'], ['newfile9.txt', 'newfile10.txt']],
    }

    if task not in tasks:
        return {}

    raw_files, new_files = tasks[task]
    valid_extensions = ('.txt', '.log')
    file_name_mapping = {}

    for raw_file, new_file in zip(raw_files, new_files):
