def classify_sentiment(sentence: str) -> str:
    """
    Classify the sentiment of a given sentence as 'positive', 'negative', or 'neutral'
    based on the presence of predefined positive and negative words.

    :param sentence: A string representing the sentence to be analyzed.
    :return: A string representing the sentiment of the sentence.
    """
    positive_lexicon = {"good", "great", "excellent", "happy", "positive", "love", "fantastic", "well", "superb", "joyful"}
    negative_lexicon = {"bad", "terrible", "poor", "sad", "negative", "hate", "worst", "ill", "terrible", "angry"}

    sentence = sentence.lower()
    positive_count = 0
    negative_count = 0

    words = sentence.split()
    for word in words:
        if word in positive_lexicon:
            positive_count += 1
        elif word in negative_lexicon:
            negative_count += 1

    if positive_count > negative_count:
        return "positive"
    elif positive_count < negative_count:
        return "negative"
    else:
        return "neutral"
