def calculate_student_scores(student_scores):
    """
    Computes the total score, number of tests, and average score for each student,
    sorts the results in descending order based on total score, and returns the sorted list.

    :param student_scores: Dictionary with student names as keys and lists of scores as values.
    :return: List of tuples with student names and their computed statistics.
    """
    result_dict = {}

    for student, scores in student_scores.items():
        total_score = 0
        count = 0
        for score in scores:
            total_score += score
            count += 1
        if count != 0:
            average_score = round(total_score / count)
        else:
            average_score = 0

        result_dict[student] = [total_score, count, average_score]

    sorted_list = [(student, stats) for student, stats in result_dict.items()]

    n = len(sorted_list)
    for i in range(n):
        for j in range(0, n-i-1):
            if sorted_list[j][1][0] < sorted_list[j+1][1][0]:
                sorted_list[j], sorted_list[j+1] = sorted_list[j+1], sorted_list[j]

    return sorted_list
