def merge_dicts_with_priority(*dict_args):
    """
    Merges multiple dictionaries with priority given to later dictionaries.
    Handles nested dictionaries and overwrites values from earlier dictionaries
    with those from later ones at all levels of nesting.

    :param dict_args: Variable number of dictionary arguments to merge.
    :return: A single merged dictionary with priority given to later dictionaries.
    """
    def merge(d1, d2):
        for k, v in d2.items():
            if isinstance(d1.get(k), dict) and isinstance(v, dict):
                d1[k] = merge(d1[k], v)
            else:
                d1[k] = v
        return d1

    result = {}
    for dictionary in dict_args:
        result = merge(result, dictionary)

    return result
