def infix_to_postfix(expression):
    """
    Convert an infix expression to postfix notation using the shunting-yard algorithm.

    :param expression: A string representing the infix expression.
    :return: A string representing the postfix expression.
    """
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    left_associative = {'+', '-', '*', '/'}
    right_associative = {'^'}

    stack = []
    output = []

    import re
    tokens = re.findall(r'\w|\+|\-|\*|\/|\^|\(|\)', expression)

    for token in tokens:
        if token.isalpha():
            output.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()
        elif token in precedence:
            while (stack and stack[-1] != '(' and
                   (precedence[stack[-1]] > precedence[token] or
                    (precedence[stack[-1]] == precedence[token] and token in left_associative))):
                output.append(stack.pop())
            stack.append(token)

    while stack:
        output.append(stack.pop())

    return ' '.join(output)

