def remove_gaps(sequence):
    """
    Recursively removes all gap characters ('-') from the given DNA sequence.

    :param sequence: A string representing the DNA sequence with possible gaps.
    :return: A string representing the DNA sequence without any gaps.
    """
    # Base case: if the sequence is empty, return it
    if sequence == '':
        return ''
    # Recursive case: if the first character is a gap, skip it and process the rest
    elif sequence[0] == '-':
        return remove_gaps(sequence[1:])
    # Recursive case: if the first character is not a gap, keep it and process the rest
    else:
        return sequence[0] + remove_gaps(sequence[1:])
