def process_data(data):
    """
    Recursively processes a nested dictionary, replacing None values with empty lists.

    :param data: A dictionary with keys as identifiers and values as lists, None, or nested dictionaries.
    :return: A new dictionary with None values replaced by empty lists.
    """
    processed_data = {}

    for key, value in data.items():
        if isinstance(value, dict):
            processed_data[key] = process_data(value)
        elif value is None:
            processed_data[key] = []
        else:
            processed_data[key] = value

