def memoize(f):
    """
    Decorator to memoize a function to avoid redundant calculations.
    """
    cache = {}
    def helper(x):
        if x not in cache:			
            cache[x] = f(x)
        return cache[x]
    return helper

@memoize
def fibonacci(n):
    """
    Compute the n-th Fibonacci number using recursion with memoization.

    Parameters:
    n (int): The term in the Fibonacci sequence to compute.

    Returns:
    int: The n-th Fibonacci number.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

