class HashTable:
    def __init__(self, size=10):
        self.size = size
        self.table = [[] for _ in range(self.size)]

    def _hash(self, key):
        """Compute the hash index for a given key."""
        return key % self.size

    def set(self, key, value):
        """Set the value for a given key in the hash table."""
        index = self._hash(key)
        for pair in self.table[index]:
            if pair[0] == key:
                pair[1] = value
                return
        self.table[index].append([key, value])

    def get(self, key):
        """Retrieve the value for a given key from the hash table."""
        index = self._hash(key)
        for pair in self.table[index]:
            if pair[0] == key:
                return pair[1]
        return None

def fibonacci(n, memo=None):
    """Compute the nth Fibonacci number using recursion and memoization."""
    if memo is None:
        memo = HashTable()
    if n < 2:
        return n
    if memo.get(n) is not None:
        return memo.get(n)
    result = fibonacci(n-1, memo) + fibonacci(n-2, memo)
    memo.set(n, result)
    return result

# Example usage:
print(fibonacci(10))  # Output: 55
