def create_depth_maps(tuples_list):
    """
    Constructs two dictionaries mapping each depth to the maximum and minimum unique values found at that depth.

    :param tuples_list: List of tuples, where each tuple contains a value and a depth.
    :return: Two dictionaries, one for maximum values and one for minimum values at each depth.
    """
    max_depth_map = {}
    min_depth_map = {}
    unique_values_at_depth = {}

    for value, depth in tuples_list:
        if depth not in unique_values_at_depth:
            unique_values_at_depth[depth] = set()

        if value not in unique_values_at_depth[depth]:
            unique_values_at_depth[depth].add(value)

            if depth not in max_depth_map:
                max_depth_map[depth] = value
                min_depth_map[depth] = value
            else:
                max_depth_map[depth] = max(max_depth_map[depth], value)
                min_depth_map[depth] = min(min_depth_map[depth], value)

    return max_depth_map, min_depth_map

