def parse_expression(expression):
    """
    Parses a mathematical expression into a list of tokens.

    :param expression: A string representing a mathematical expression.
    :return: A list of tokens from the expression.
    """
    def is_digit_or_dot(c):
        return c.isdigit() or c == '.'

    def is_exponent_char(c):
        return c in ('e', 'E')

    def is_operator(c):
        return c in '+-*/'

    def is_parenthesis(c):
        return c in '()'

    tokens = []
    current_token = ''
    i = 0
    n = len(expression)

    while i < n:
        c = expression[i]

        if is_digit_or_dot(c):
            current_token += c
            if i + 1 < n and is_exponent_char(expression[i + 1]):
                current_token += expression[i + 1]
                i += 2
                if i < n and expression[i] in '+-':
                    current_token += expression[i]
                    i += 1
                while i < n and is_digit_or_dot(expression[i]):
                    current_token += expression[i]
                    i += 1
            else:
                i += 1
        elif is_operator(c):
            if current_token:
                tokens.append(current_token)
                current_token = ''
            tokens.append(c)
            i += 1
        elif is_parenthesis(c):
            if current_token:
                tokens.append(current_token)
                current_token = ''
            tokens.append(c)
            i += 1
        elif c == ' ':
            if current_token:
                tokens.append(current_token)
                current_token = ''
            i += 1
        else:
            i += 1

    if current_token:
        tokens.append(current_token)

    return tokens
