class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """
        Inserts a new node with the specified key into the BST.
        :param key: The key of the new node to be inserted.
        """
        new_node = TreeNode(key)
        if self.root is None:
            self.root = new_node
        else:
            self._insert_recursively(self.root, new_node)

    def _insert_recursively(self, node, new_node):
        if new_node.val <= node.val:
            if node.left is None:
                node.left = new_node
            else:
                self._insert_recursively(node.left, new_node)
        else:
            if node.right is None:
                node.right = new_node
            else:
                self._insert_recursively(node.right, new_node)

    def search(self, key):
        """
        Searches for a node with the specified key in the BST.
        :param key: The key to search for.
        :return: True if a node with the key exists, False otherwise.
        """
        return self._search_recursively(self.root, key)

    def _search_recursively(self, node, key):
        if node is None:
            return False
        if key == node.val:
            return True
        elif key < node.val:
            return self._search_recursively(node.left, key)
        else:
            return self._search_recursively(node.right, key)

    def delete(self, key):
        """
        Deletes the node with the specified key from the BST.
        :param key: The key of the node to be deleted.
        """
        self.root = self._delete_recursively(self.root, key)

    def _delete_recursively(self, node, key):
        if node is None:
            return node
        if key < node.val:
            node.left = self._delete_recursively(node.left, key)
        elif key > node.val:
            node.right = self._delete_recursively(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left
            min_larger_node = self._get_min(node.right)
            node.val = min_larger_node.val
            node.right = self._delete_recursively(node.right, min_larger_node.val)
        return node

    def _get_min(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current
