    if not isinstance(order['customer_name'], str) or not order['customer_name']:
        return False

    if not isinstance(order['delivery_address'], str) or not order['delivery_address']:
        return False

    if not isinstance(order['order_date'], str) or not re.match(r'^\d{4}-\d{2}-\d{2}$', order['order_date']):
        return False

    try:
        datetime.strptime(order['order_date'], '%Y-%m-%d')
    except ValueError:
        return False

    return True
