def get_task(task_id):
    """
    Retrieve a single task by its ID.

    :param task_id: ID of the task to retrieve.
    :return: JSON response with the task if found, otherwise 404 error.
    """
    task = find_task(task_id)
    if task is None:
        abort(404)
    return jsonify({'task': task})

@app.route('/tasks', methods=['POST'])
def create_task():
    """
    Create a new task.

    :return: JSON response with the created task and 201 status code.
    """
    if not request.json or 'title' not in request.json:
        abort(400, description="Ensure that title field is present in the JSON body")

    task = {
        'id': len(tasks) + 1,
        'title': request.json['title'],
        'description': request.json.get('description', ""),
        'done': False
    }
    tasks.append(task)
    return jsonify({'task': task}), 201

@app.route('/tasks/<int:task_id>', methods=['PUT'])
def update_task(task_id):
    """
    Update an existing task.

    :param task_id: ID of the task to update.
    :return: JSON response with the updated task if found, otherwise 404 error.
    """
    task = find_task(task_id)
    if task is None:
        abort(404)

    task['title'] = request.json.get('title', task['title'])
    task['description'] = request.json.get('description', task['description'])
    task['done'] = request.json.get('done', task['done'])
    return jsonify({'task': task})

@app.route('/tasks/<int:task_id>', methods=['DELETE'])
def delete_task(task_id):
    """
    Delete a task by its ID.

    :param task_id: ID of the task to delete.
    :return: JSON response with a result field set to True if found, otherwise 404 error.
    """
    task = find_task(task_id)
    if task is None:
        abort(404)

    tasks.remove(task)
    return jsonify({'result': True})

