import json

def extract_error_code(response: str) -> str:
    """
    Extracts the value associated with the key 'errorCode' (case-insensitive) from a JSON string.

    :param response: A string representing a JSON object.
    :return: The value of the 'errorCode' key as a string, or an empty string if not found or invalid JSON.
    """
    try:
        data = json.loads(response)
    except json.JSONDecodeError:
        return ""

    def find_error_code(d):
        if isinstance(d, dict):
            for key, value in d.items():
                if key.lower() == "errorcode":
                    return value
                if isinstance(value, (dict, list)):
                    found = find_error_code(value)
                    if found:
                        return found
        elif isinstance(d, list):
            for item in d:
                found = find_error_code(item)
                if found:
                    return found
        return None

    error_code = find_error_code(data)
    return error_code if isinstance(error_code, str) else ""
