def get_scraping_params(params):
    """
    Validates and processes the input parameters for a web scraping application.

    Parameters:
    - params (dict): A dictionary containing the parameters 'url', 'delay', and 'max_pages'.

    Returns:
    - dict: A dictionary with validated or default values for 'url', 'delay', and 'max_pages'.
    """
    # Define default parameters
    defaults = {
        'url': 'http://example.com',
        'delay': 1.0,           # Delay in seconds between requests
        'max_pages': 10
    }

    # Validate and assign parameters
    validated_params = {}
    for key, value in defaults.items():
        if key in params:
            if (key == 'url' and isinstance(params[key], str) and params[key].startswith('http')):
                validated_params[key] = params[key]
            elif key == 'delay' and isinstance(params[key], (int, float)) and params[key] >= 0:
                validated_params[key] = float(params[key])
            elif key == 'max_pages' and isinstance(params[key], int) and params[key] > 0:
                validated_params[key] = params[key]
            else:
                error_msg = f"Invalid value for parameter '{key}'. Using default value '{value}'."
                print(error_msg)
                validated_params[key] = value
        else:
            error_msg = f"Parameter '{key}' missing. Using default value '{value}'."
            print(error_msg)
            validated_params[key] = value

    return validated_params

