def convert_to_ascii(input_dict):
    """
    Converts all string keys and values in the dictionary to lowercase ASCII.
    If a key or value cannot be converted to ASCII, it is ignored.

    :param input_dict: Dictionary with string keys and values of any type.
    :return: A new dictionary with keys and values converted to lowercase ASCII.
    """
    def is_ascii(s):
        try:
            s.encode('ascii')
            return True
        except UnicodeEncodeError:
            return False

    def to_ascii(s):
        return s.lower().encode('ascii').decode('ascii')

    result = {}
    for key, value in input_dict.items():
        if isinstance(key, str) and isinstance(value, str):
            if is_ascii(key) and is_ascii(value):
                new_key = to_ascii(key)
                new_value = to_ascii(value)
                result[new_key] = new_value
    return result

