def flatten_json(y):
    """
    Recursively flattens a JSON object into a single-level dictionary.

    Parameters:
    y (dict): The JSON object to flatten.

    Returns:
    dict: A single-level dictionary with keys as the path to the value in the original JSON.
    """
    out = {}

    def flatten(x, name=''):
        if isinstance(x, dict):
            for a in x:
                flatten(x[a], name + a + '/')
        else:
            out[name[:-1]] = x

    flatten(y)
    return out

