def organize_courses(scheduled_courses):
    """
    Organizes a list of scheduled courses into a dictionary structured by year and term.

    Parameters:
    scheduled_courses (list of tuples): Each tuple contains the course name, a tuple of term and year,
                                        the credit value, and a list of prerequisites.

    Returns:
    dict: A dictionary organized by year and term with course details.
    """
    organized_dict = {}

    for course_name, (term, year), credit, prerequisites in scheduled_courses:
        if year not in organized_dict:
            organized_dict[year] = {}

        if term not in organized_dict[year]:
            organized_dict[year][term] = {'courses': [], 'total_credits': 0, 'prerequisites': {}}

        organized_dict[year][term]['courses'].append(course_name)
        organized_dict[year][term]['total_credits'] += credit
        organized_dict[year][term]['prerequisites'][course_name] = prerequisites

    return organized_dict
