def transform_nested_dict(nested_dict, transform_func):
    """
    Recursively applies a transformation function to all keys in a nested dictionary.

    Args:
    nested_dict (dict): The nested dictionary to transform.
    transform_func (function): The function to apply to each key.

    Returns:
    dict: A new dictionary with transformed keys.
    """
    def transform(k, v):
        if isinstance(v, dict):
            return transform_func(k), transform_nested_dict(v, transform_func)
        elif isinstance(v, list):
            return transform_func(k), [transform_nested_dict(item, transform_func) if isinstance(item, dict) else item for item in v]
        else:
            return transform_func(k), v

    return {new_k: new_v for k, v in nested_dict.items() for new_k, new_v in [transform(k, v)]}
```

