def has_property(node, property_name):
    """
    Recursively checks if a given property exists in a nested dictionary or list structure.

    :param node: A dictionary or a list of dictionaries representing the graph.
    :param property_name: A string representing the name of the property to search for.
    :return: True if the property is found, False otherwise.
    """
    if isinstance(node, dict):
        if property_name in node:
            return True
        for value in node.values():
            if has_property(value, property_name):
                return True
    elif isinstance(node, list):
        for item in node:
            if has_property(item, property_name):
                return True
    return False
