class Library:
    def __init__(self, books=None):
        """Initialize the library with a list of available books and a set of borrowed books."""
        self.available_books = books if books else []
        self.borrowed_books = set()

    def add_book(self, book_name):
        """Add a new book to the library if it is not already present."""
        if book_name not in self.available_books:
            self.available_books.append(book_name)
            print(f"Book '{book_name}' added to the library.")
        else:
            print(f"Book '{book_name}' is already in the library.")

    def remove_book(self, book_name):
        """Remove a book from the library if it is available. If the book is borrowed, it cannot be removed."""
        if book_name in self.available_books:
            self.available_books.remove(book_name)
            print(f"Book '{book_name}' removed from the library.")
        elif book_name in self.borrowed_books:
            print(f"Book '{book_name}' is currently borrowed and cannot be removed.")
        else:
            print(f"Book '{book_name}' not found in the library.")

    def list_books(self):
        """List all available books in the library."""
        print("Available Books:")
        for book in self.available_books:
            print("-", book)
        print()

    def borrow_book(self, book_name):
        """Borrow a book from the library if it is available."""
        if book_name in self.available_books:
            self.available_books.remove(book_name)
            self.borrowed_books.add(book_name)
            print(f"Book '{book_name}' has been borrowed.")
        elif book_name in self.borrowed_books:
            print(f"Book '{book_name}' is already borrowed.")
        else:
            print(f"Book '{book_name}' is not available in the library.")

    def return_book(self, book_name):
        """Return a book to the library if it was borrowed."""
        if book_name in self.borrowed_books:
            self.borrowed_books.remove(book_name)
            self.available_books.append(book_name)
            print(f"Book '{book_name}' has been returned.")
        else:
            print(f"Book '{book_name}' was not borrowed from the library.")
