from typing import List, Union, Callable, Optional

def sum_if_valid(lst: List[Union[int, List]], is_valid: Callable[[int], bool]) -> Optional[int]:
    def flatten(lst: List[Union[int, List]]) -> int:
        """Flatten a nested list of integers."""
        for item in lst:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    for num in flatten(lst):
        if not is_valid(num):
            return None
    return sum(num for num in flatten(lst) if is_valid(num))
