def find_max_diff(lst):
    """
    Computes the maximum difference between any two elements in the list,
    where the larger element appears after the smaller one.

    Parameters:
    lst (list): A list of integers.

    Returns:
    int or None: The maximum difference or None if the list is empty.
    """
    def helper(arr, idx, min_val, max_diff):
        if idx == len(arr):
            return max_diff
        if arr[idx] < min_val:
            return helper(arr, idx + 1, arr[idx], max_diff)
        elif arr[idx] - min_val > max_diff:
            return helper(arr, idx + 1, min_val, arr[idx] - min_val)
        else:
            return helper(arr, idx + 1, min_val, max_diff)

    if not lst:
        return None
    return helper(lst, 1, lst[0], 0)
```

