def classify_sentences(sentences):
    """
    Classifies each sentence in the list into 'positive', 'negative', or 'neutral'
    based on the presence of specific sentiment words.

    :param sentences: List of sentences to classify.
    :return: List of classifications corresponding to each sentence.
    """
    # Define the sets of positive and negative words
    positive_words = {"happy", "joyful", "excellent", "fantastic", "good", "great"}
    negative_words = {"sad", "angry", "terrible", "bad", "poor", "awful"}

    # Function to classify a single sentence
    def classify(sentence):
        words = set(sentence.lower().split())
        if words.intersection(positive_words):
            return "positive"
        elif words.intersection(negative_words):
            return "negative"
        else:
            return "neutral"

    # Classify each sentence in the list
    return [classify(sentence) for sentence in sentences]
