def custom_multiplication_table(number: int, length: int) -> str:
    """
    Generates a multiplication table for a given number up to a specified length.

    :param number: The base number for the multiplication table.
    :param length: The number of multiples to generate.
    :return: A string containing the multiplication results separated by spaces.
    """
    def multiply_and_concatenate(current: int, count: int) -> str:
        if count == 0:
            return ""
        elif count == 1:
            return str(number * current)
        else:
            return str(number * current) + " " + multiply_and_concatenate(current + 1, count - 1)

    return multiply_and_concatenate(1, length)
