import json

def convert_to_nested_dict(json_obj_str):
    """
    Convert a JSON object string to a nested dictionary structure where each value is wrapped in a dictionary with the key 'value'.

    :param json_obj_str: A string containing a JSON object.
    :return: A nested dictionary with each value wrapped in {'value': ...}.
    """
    def nest_dict(data):
        if isinstance(data, dict):
            return {k: nest_dict(v) for k, v in data.items()}
        elif isinstance(data, list):
            return [nest_dict(item) for item in data]
        else:
            return {'value': data}

