import json

def increment_integers(json_str):
    """
    Increment all integer values in a nested JSON structure by 1.

    :param json_str: A JSON string representing a nested data structure.
    :return: A new JSON string with all integer values incremented by 1.
    """
    def increment_values(data):
        if isinstance(data, dict):
            return {k: increment_values(v) for k, v in data.items()}
        elif isinstance(data, list):
            return [increment_values(item) for item in data]
        elif isinstance(data, int):
            return data + 1
        else:
            return data

    data = json.loads(json_str)
    incremented_data = increment_values(data)
    return json.dumps(incremented_data)

