def search(budget, prices):
    """
    Returns a string of unique coffee bean prices that can be afforded within the given budget,
    sorted in ascending order and formatted with a dollar sign prefix.

    :param budget: Integer representing the budget.
    :param prices: List of integers representing the prices of coffee beans.
    :return: String of formatted, unique, and sorted prices.
    """
    result = []
    for i in range(len(prices)):
        if prices[i] <= budget:
            found = False
            for j in range(len(result)):
                if result[j] == prices[i]:
                    found = True
                    break
            if not found:
                result.append(prices[i])
    for i in range(len(result) - 1):
        for j in range(i + 1, len(result)):
            if result[i] > result[j]:
                temp = result[i]
                result[i] = result[j]
                result[j] = temp
    formatted_result = ",".join("$" + str(price) for price in result)
    return formatted_result
