def sieve_of_eratosthenes(max_num):
    """Generate a list of prime numbers up to max_num using the Sieve of Eratosthenes algorithm."""
    is_prime = [True] * (max_num + 1)
    p = 2
    while p * p <= max_num:
        if is_prime[p]:
            for i in range(p * p, max_num + 1, p):
                is_prime[i] = False
        p += 1
    return [p for p in range(2, max_num + 1) if is_prime[p]]

def filter_primes_from_list(numbers):
    """Return a new list containing only the prime numbers from the input list."""
    if not numbers:
        return []
    max_num = max(numbers)
    primes = set(sieve_of_eratosthenes(max_num))
    return [num for num in numbers if num in primes]
