def is_numeric(s):
    """Check if a string starts with a number."""
    return s[0].isdigit()

def to_numeric_key(s):
    """Convert a string starting with a number to a tuple of its numeric part and the rest of the string."""
    i = 0
    while i < len(s) and s[i].isdigit():
        i += 1
    return (int(s[:i]), s[i:])

def custom_sort(strings):
    """Sort a list of strings according to the specified rules."""
    numeric_strings = []
    non_numeric_strings = []

    for s in strings:
        if is_numeric(s):
            numeric_strings.append(s)
        else:
            non_numeric_strings.append(s)

    numeric_strings_sorted = merge_sort_strings(numeric_strings, to_numeric_key)
    non_numeric_strings_sorted = merge_sort_strings(non_numeric_strings)

    return numeric_strings_sorted + non_numeric_strings_sorted

def merge_sort_strings(strings, key=None):
    """Custom merge sort that optionally uses a key function."""
    if len(strings) <= 1:
        return strings

    mid = len(strings) // 2
    left_half = merge_sort_strings(strings[:mid], key)
    right_half = merge_sort_strings(strings[mid:], key)

    return merge(left_half, right_half, key)

def merge(left, right, key=None):
    """Merge two sorted lists."""
    sorted_list = []
    i = j = 0

    while i < len(left) and j < len(right):
        left_val = left[i]
        right_val = right[j]

        if key:
            left_val = key(left[i])
            right_val = key(right[j])

        if left_val < right_val:
            sorted_list.append(left[i])
            i += 1
        else:
            sorted_list.append(right[j])
            j += 1

    sorted_list.extend(left[i:])
    sorted_list.extend(right[j:])

    return sorted_list
