def find_prime_factors(n):
    """
    Returns a list of all prime factors of n in ascending order.
    Each prime factor appears in the list as many times as it divides n.

    :param n: Integer, the number to factorize
    :return: List of integers, the prime factors of n
    """
    if n <= 1:
        return []

    spf = list(range(n + 1))
    for i in range(4, n + 1, 2):
        spf[i] = 2

    for i in range(3, int(n**0.5) + 1, 2):
        if spf[i] == i:
            for j in range(i * i, n + 1, i):
                if spf[j] == j:
                    spf[j] = i

    prime_factors = []
    while n != 1:
        prime_factors.append(spf[n])
        n //= spf[n]

    return prime_factors

# Example usage:
