from math import gcd

class Fraction:
    def __init__(self, numerator=0, denominator=1):
        """
        Initialize a Fraction object.

        :param numerator: The numerator of the fraction.
        :param denominator: The denominator of the fraction. Must not be zero.
        """
        if denominator == 0:
            raise ValueError("Denominator cannot be zero.")
        g = gcd(numerator, denominator)
        self.numerator = numerator // g
        self.denominator = denominator // g
        if self.denominator < 0:
            self.numerator = -self.numerator
            self.denominator = -self.denominator

    def simplify(self):
        """
        Simplify the fraction to its simplest form.
        """
        g = gcd(self.numerator, self.denominator)
        self.numerator //= g
        self.denominator //= g

    def __add__(self, other):
        """
        Add two Fraction objects.

        :param other: Another Fraction object.
        :return: A new Fraction object representing the sum.
        """
        if isinstance(other, Fraction):
            return Fraction(self.numerator * other.denominator + other.numerator * self.denominator, self.denominator * other.denominator)
        else:
            return NotImplemented

    def __sub__(self, other):
        """
        Subtract two Fraction objects.

        :param other: Another Fraction object.
        :return: A new Fraction object representing the difference.
        """
        if isinstance(other, Fraction):
            return Fraction(self.numerator * other.denominator - other.numerator * self.denominator, self.denominator * other.denominator)
        else:
            return NotImplemented

    def __mul__(self, other):
        """
        Multiply two Fraction objects.

        :param other: Another Fraction object.
        :return: A new Fraction object representing the product.
        """
        if isinstance(other, Fraction):
            return Fraction(self.numerator * other.numerator, self.denominator * other.denominator)
        else:
            return NotImplemented

    def __truediv__(self, other):
        """
        Divide two Fraction objects.

        :param other: Another Fraction object.
        :return: A new Fraction object representing the quotient.
        """
        if isinstance(other, Fraction):
            if other.numerator == 0:
                raise ZeroDivisionError("Cannot divide by a fraction with numerator zero.")
            return Fraction(self.numerator * other.denominator, self.denominator * other.numerator)
        else:
            return NotImplemented

    def __lt__(self, other):
        """
        Compare if one Fraction object is less than another.

        :param other: Another Fraction object.
        :return: True if self is less than other, False otherwise.
        """
        if isinstance(other, Fraction):
            return self.numerator * other.denominator < other.numerator * self.denominator
        else:
            return NotImplemented

    def __le__(self, other):
        """
        Compare if one Fraction object is less than or equal to another.

        :param other: Another Fraction object.
        :return: True if self is less than or equal to other, False otherwise.
        """
        if isinstance(other, Fraction):
            return self.numerator * other.denominator <= other.numerator * self.denominator
        else:
            return NotImplemented

    def __eq__(self, other):
        """
        Compare if two Fraction objects are equal.

        :param other: Another Fraction object.
        :return: True if self is equal to other, False otherwise.
        """
        if isinstance(other, Fraction):
            return self.numerator == other.numerator and self.denominator == other.denominator
        else:
            return NotImplemented

    def __ne__(self, other):
        """
        Compare if two Fraction objects are not equal.

        :param other: Another Fraction object.
        :return: True if self is not equal to other, False otherwise.
        """
        if isinstance(other, Fraction):
            return not (self.numerator == other.numerator and self.denominator == other.denominator)
        else:
            return NotImplemented

    def __gt__(self, other):
        """
        Compare if one Fraction object is greater than another.

        :param other: Another Fraction object.
        :return: True if self is greater than other, False otherwise.
        """
        if isinstance(other, Fraction):
            return self.numerator * other.denominator > other.numerator * self.denominator
        else:
            return NotImplemented

    def __ge__(self, other):
        """
        Compare if one Fraction object is greater than or equal to another.

        :param other: Another Fraction object.
        :return: True if self is greater than or equal to other, False otherwise.
        """
        if isinstance(other, Fraction):
            return self.numerator * other.denominator >= other.numerator * self.denominator
        else:
            return NotImplemented

    def __str__(self):
        """
        Return a string representation of the Fraction object.

        :return: A string in the format "numerator/denominator".
        """
        return f"{self.numerator}/{self.denominator}"

    def __repr__(self):
        """
        Return an official string representation of the Fraction object.

        :return: A string in the format "Fraction(numerator, denominator)".
        """
        return f"Fraction({self.numerator}, {self.denominator})"
