def remove_duplicates_and_sort(dup_list: list) -> list:
    """
    Removes duplicates from the input list and sorts the remaining elements in ascending order.

    :param dup_list: List of integers with possible duplicates.
    :return: A new list with duplicates removed and elements sorted in ascending order.
    """
    # Step 1: Remove duplicates
    unique_list = []
    for num in dup_list:
        if num not in unique_list:
            unique_list.append(num)

    # Step 2: Sort the list using Bubble Sort
    n = len(unique_list)
    for i in range(n):
        for j in range(0, n-i-1):
            if unique_list[j] > unique_list[j+1]:
                unique_list[j], unique_list[j+1] = unique_list[j+1], unique_list[j]

    return unique_list
