def has_cycle(graph):
    """
    Determines if a directed graph contains a cycle.

    :param graph: A dictionary representing the directed graph, where each key is a node
                  and its value is a list of adjacent nodes.
    :return: True if the graph contains a cycle, False otherwise.
    """
    visited = set()
    recursion_stack = set()

    def is_cyclic(node):
        visited.add(node)
        recursion_stack.add(node)

        for neighbor in graph.get(node, []):
            if neighbor in recursion_stack:
                return True
            if neighbor not in visited and is_cyclic(neighbor):
                return True
        recursion_stack.remove(node)
        return False

    for node in graph:
        if node not in visited:
            if is_cyclic(node):
                return True

    return False

