def prime_power_count(n):
    """
    Returns a dictionary with prime factors of n as keys and their respective counts as values.

    :param n: A positive integer
    :return: A dictionary with prime factors and their counts
    """
    prime_factors_count = {}
    # Check for the number of 2s that divide n
    while n % 2 == 0:
        prime_factors_count[2] = prime_factors_count.get(2, 0) + 1
        n //= 2

    # n must be odd at this point, so a skip of 2 (i.e., i = i + 2) can be used
    for i in range(3, int(n**0.5) + 1, 2):
        # While i divides n, add i and divide n
        while n % i == 0:
            prime_factors_count[i] = prime_factors_count.get(i, 0) + 1
            n //= i

    # This condition is to check if n is a prime number greater than 2
    if n > 2:
        prime_factors_count[n] = prime_factors_count.get(n, 0) + 1

    return prime_factors_count

# Example usage:
print(prime_power_count(12))  # Output: {2: 2, 3: 1}
print(prime_power_count(15))  # Output: {3: 1, 5: 1}
print(prime_power_count(16))  # Output: {2: 4}
