def reconcile_data(mapping_lib, world_bank):
    """
    Reconciles two datasets: country names (mapping_lib) and GDP data (world_bank).

    :param mapping_lib: dictionary with country codes and their names
    :param world_bank: dictionary with country codes as keys and GDP data as values (dict)
    :return: a dictionary with country codes and names from mapping_lib that have GDP data, 
             and a set with country codes without GDP data in world_bank
    """
    valid_mapping_lib = {code: name for code, name in mapping_lib.items() if isinstance(code, str) and isinstance(name, str)}
    matches = {}
    non_matches = set()

    for code, name in valid_mapping_lib.items():
        if isinstance(world_bank.get(code), dict):
            matches[code] = name
        else:
            non_matches.add(code)

    return matches, non_matches
