def merge_dicts_with_priority(d1, d2, priority_keys, override_keys):
    """
    Merges two dictionaries with specific priority and override rules.

    Parameters:
    d1 (dict): The first dictionary.
    d2 (dict): The second dictionary.
    priority_keys (list): List of keys with priority from d1.
    override_keys (list): List of keys that override priority from d2.

    Returns:
    dict: The merged dictionary following the specified rules.
    """
    merged_dict = {}
    all_keys = set(d1.keys()) | set(d2.keys())

    for key in all_keys:
        if key in d1 and key in d2:
            if key in override_keys:
                merged_dict[key] = d2[key]
            elif key in priority_keys:
                merged_dict[key] = d1[key]
            else:
                merged_dict[key] = d2[key]
        elif key in d1:
            merged_dict[key] = d1[key]
        elif key in d2:
            merged_dict[key] = d2[key]

    return merged_dict
