def encode_sentence(sentence, word_to_num):
    """
    Encodes a sentence into a list of integers using a given word-to-number mapping
    and finds the longest palindromic subsequence in the encoded sentence.

    :param sentence: List of words to be encoded.
    :param word_to_num: Dictionary mapping words to unique integers.
    :return: Tuple containing the encoded sentence and the longest palindromic subsequence.
    """
    # Encode the sentence into a list of integers
    encoded_sentence = [word_to_num[word] for word in sentence]

    # Function to find the longest palindromic subsequence
    def longest_palindromic_subsequence(seq):
        n = len(seq)
        dp = [[0] * n for _ in range(n)]

        # Every single element is a palindrome of length 1
        for i in range(n):
            dp[i][i] = 1

        # Build the table. The outer loop is for substrings of increasing length
        for length in range(2, n + 1):  # length is the length of the substring
            for i in range(n - length + 1):
                j = i + length - 1
                if seq[i] == seq[j]:
                    dp[i][j] = dp[i + 1][j - 1] + 2
                else:
                    dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

        # Function to get the longest palindromic subsequence
        def get_lps(i, j, dp):
            if i > j:
                return []
            if i == j:
                return [seq[i]]
            if seq[i] == seq[j]:
                return [seq[i]] + get_lps(i + 1, j - 1, dp) + [seq[j]]
            else:
                if dp[i + 1][j] > dp[i][j - 1]:
                    return get_lps(i + 1, j, dp)
                else:
                    return get_lps(i, j - 1, dp)

        return get_lps(0, n - 1, dp)

    # Fetch the longest palindromic subsequence of encoded sentence
    palindromic_subsequence = longest_palindromic_subsequence(encoded_sentence)

    return encoded_sentence, palindromic_subsequence
```

