class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Inserts a new key into the binary search tree."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert(self.root, key)

    def _insert(self, root, key):
        """Helper method to insert a key recursively."""
        if root.val < key:
            if root.right is None:
                root.right = TreeNode(key)
            else:
                self._insert(root.right, key)
        else:
            if root.left is None:
                root.left = TreeNode(key)
            else:
                self._insert(root.left, key)

    def search(self, key):
        """Searches for a key in the binary search tree and returns the node if found, otherwise returns None."""
        return self._search(self.root, key)

    def _search(self, root, key):
        """Helper method to search for a key recursively."""
        if root is None or root.val == key:
            return root
        if root.val < key:
            return self._search(root.right, key)
        return self._search(root.left, key)

    def delete(self, key):
        """Deletes a key from the binary search tree if it exists."""
        self.root = self._delete(self.root, key)

    def _delete(self, root, key):
        """Helper method to delete a key recursively."""
        if root is None:
            return root

        if key < root.val:
            root.left = self._delete(root.left, key)
        elif key > root.val:
            root.right = self._delete(root.right, key)
        else:
            if root.left is None:
                return root.right
            elif root.right is None:
                return root.left

            temp = self._min_value_node(root.right)
            root.val = temp.val
            root.right = self._delete(root.right, temp.val)
        return root

    def _min_value_node(self, node):
        """Helper method to find the node with the minimum value in a subtree."""
        current = node
        while current.left is not None:
            current = current.left
        return current
