def find_first_local_minimum(nums):
    """
    Returns the index of the first occurrence of a local minimum in the list.
    A local minimum is an element smaller than its immediate neighbors.

    :param nums: List of integers
    :return: Index of the first local minimum or -1 if no local minimum exists
    """
    if not nums:
        return -1
    elif len(nums) == 1:
        return 0
    elif len(nums) == 2:
        return 0 if nums[0] < nums[1] else 1

    for i in range(1, len(nums) - 1):
        if nums[i] < nums[i - 1] and nums[i] < nums[i + 1]:
            return i

    if nums[0] < nums[1]:
        return 0
    elif nums[-1] < nums[-2]:
        return len(nums) - 1

    return -1

