def find_error_nums(nums):
    """
    Finds the duplicate and missing numbers in the given array using O(1) extra space.

    :param nums: List[int] - An array of integers where 1 <= nums[i] <= n and len(nums) = n + 1.
    :return: List[int] - A list containing the duplicate number and the missing number.
    """
    duplicate = missing = -1

    for num in nums:
        index = abs(num) - 1
        if nums[index] < 0:
            duplicate = abs(num)
        else:
            nums[index] = -nums[index]

    for i in range(len(nums)):
        if nums[i] > 0:
            missing = i + 1
            break

    return [duplicate, missing]
