class Matrix:
    def __init__(self, data):
        """
        Initialize a Matrix object with the given data.

        :param data: List of lists representing the matrix.
        :raises ValueError: If the input is not a well-formed matrix.
        """
        if not all(isinstance(row, list) for row in data):
            raise ValueError("Matrix should be a list of lists")
        if not data or not all(len(row) == len(data[0]) for row in data):
            raise ValueError("All rows in the matrix must have the same number of columns")
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0])

    def __str__(self):
        """
        Return a string representation of the matrix.

        :return: String representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])

    def add(self, other):
        """
        Add two matrices.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the sum of the two matrices.
        :raises ValueError: If the matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to add")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def subtract(self, other):
        """
        Subtract one matrix from another.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the difference of the two matrices.
        :raises ValueError: If the matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to subtract")
        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiply two matrices.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the product of the two matrices.
        :raises ValueError: If the number of columns in the first matrix is not equal to the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to number of rows in the second matrix")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(other.rows)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def transpose(self):
        """
        Transpose the matrix.

        :return: A new Matrix object representing the transpose of the matrix.
        """
        result = [
            [self.data[i][j] for i in range(self.rows)] for j in range(self.cols)
        ]
        return Matrix(result)


