def validate_input(input_data, required_fields, optional_fields):
    """
    Validates the input data based on required and optional fields.

    Parameters:
    - input_data (dict): The input data dictionary.
    - required_fields (list): List of required fields using dot notation.
    - optional_fields (list): List of optional fields using dot notation.

    Returns:
    - tuple: (valid, validated_data) where valid is a boolean and validated_data is a dictionary.
    """
    def get_nested_value(data, key_spec):
        keys = key_spec.split('.')
        current_value = data
        for key in keys:
            if '[' in key and ']' in key:
                list_key, index_str = key.split('[')
                index = int(index_str.strip(']'))
                current_value = current_value.get(list_key, [])
                if isinstance(current_value, list) and index < len(current_value):
                    current_value = current_value[index]
                else:
                    return None
            else:
                current_value = current_value.get(key)
                if current_value is None:
                    return None
        return current_value

    def is_non_empty(value):
        if value is None:
            return False
        if isinstance(value, (list, dict, str)):
            return len(value) > 0
        return True

    validated_data = {}
    valid = True

    for field in required_fields:
        value = get_nested_value(input_data, field)
        if not is_non_empty(value):
            valid = False
        else:
            last_key = field.split('.')[-1].split('[')[0]
            validated_data[last_key] = value

    for field in optional_fields:
        value = get_nested_value(input_data, field)
        if is_non_empty(value):
            last_key = field.split('.')[-1].split('[')[0]
            validated_data[last_key] = value

    return valid, validated_data
