def convert_to_python_type(data, conversion_fn):
    """
    Recursively applies a conversion function to all elements in a nested data structure.

    Parameters:
    - data: The data structure to be converted (int, float, str, list, tuple, dict).
    - conversion_fn: A lambda function that takes an input and returns a converted output.

    Returns:
    - The data structure with all elements converted according to conversion_fn.
    """
    if isinstance(data, (int, float, str)):
        return conversion_fn(data)
    elif isinstance(data, list):
        return [convert_to_python_type(item, conversion_fn) for item in data]
    elif isinstance(data, tuple):
        return tuple(convert_to_python_type(item, conversion_fn) for item in data)
    elif isinstance(data, dict):
        return {key: convert_to_python_type(value, conversion_fn) for key, value in data.items()}
    else:
        raise ValueError(f"Unsupported data type: {type(data)}")
```

