def find_largest_prime_factor(n):
    """Return the largest prime factor of n."""

    def is_prime(num):
        """Check if a number is prime."""
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    prime_factor = None
    d = 2
    while d * d <= n:
        while n % d == 0:
            prime_factor = d
            n //= d
        d += 1
    if n > 1:
        prime_factor = n

    return prime_factor

