def is_balanced_parentheses(expression: str) -> bool:
    """
    Checks if the parentheses in the given expression are balanced.

    :param expression: A string containing characters including parentheses, braces, and brackets.
    :return: True if the parentheses are balanced, False otherwise.
    """
    matching_parentheses = {'(': ')', '{': '}', '[': ']'}
    stack = []

    for char in expression:
        if char in matching_parentheses:
            stack.append(char)
        elif char in matching_parentheses.values():
            if not stack or matching_parentheses[stack.pop()] != char:
                return False

    return not stack

