def scale_temperatures(temperatures):
    """
    Scales a list of temperatures to a range of [-1, 1] while preserving their relative differences.

    :param temperatures: List of integers representing daily temperatures.
    :return: List of floats representing the scaled temperatures.
    """
    if not temperatures:
        return []

    min_temp = temperatures[0]
    max_temp = temperatures[0]

    for temp in temperatures:
        if temp < min_temp:
            min_temp = temp
        if temp > max_temp:
            max_temp = temp

    temp_range = max_temp - min_temp

    if temp_range == 0:
        return [0] * len(temperatures)

    scaled_temperatures = [(temp - min_temp) * 2 / temp_range - 1 for temp in temperatures]

    return scaled_temperatures
