import functools

def gcd(a, b):
    """Compute the greatest common divisor of a and b using the Euclidean algorithm."""
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    """Compute the least common multiple of a and b."""
    return a * b // gcd(a, b)

def find_lcm_of_list(numbers):
    """Find the least common multiple of a list of numbers."""
    return functools.reduce(lcm, numbers)
