def validate_brackets(s):
    """
    Checks if the brackets in the string s are balanced.

    :param s: A string containing characters including '(', ')', '{', '}', '[', ']', and other non-bracket characters.
    :return: True if the brackets are balanced, False otherwise.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
