def organize_books_by_genre_and_publisher(books):
    """
    Organizes books into a nested dictionary structure by genre and publisher.

    Parameters:
    books (list of dict): A list of dictionaries, each representing a book with keys 'title', 'author', 'genre', and 'publisher'.

