```python
class Matrix:
    def __init__(self, data):
        """
        Initialize a Matrix object with the given 2D list of real numbers.

        :param data: List of lists, where each inner list represents a row of the matrix.
        :raises ValueError: If the input data is not a valid matrix (rows of unequal length).
        """
        if not data or not all(len(row) == len(data[0]) for row in data):
            raise ValueError("Invalid matrix data: Each row must have the same number of columns.")
        self.data = [row[:] for row in data]  # Deep copy to avoid mutation of input data
        self.rows = len(data)
        self.cols = len(data[0])

    def __str__(self):
        """
        Return a string representation of the matrix.

        :return: String with each row of the matrix on a new line and elements separated by tabs.
        """
        return '\n'.join(['\t'.join(map(str, row)) for row in self.data])

    def __add__(self, other):
        """
        Add two matrices of the same dimensions.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the sum of the two matrices.
        :raises ValueError: If the matrices do not have the same dimensions.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for addition.")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __sub__(self, other):
        """
        Subtract two matrices of the same dimensions.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the difference of the two matrices.
        :raises ValueError: If the matrices do not have the same dimensions.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for subtraction.")
        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __mul__(self, other):
        """
        Multiply two matrices where the number of columns in the first matrix matches the number of rows in the second matrix.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the product of the two matrices.
        :raises ValueError: If the number of columns in the first matrix does not match the number of rows in the second matrix.
        """
        if not isinstance(other, Matrix) or self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must match the number of rows in the second matrix for multiplication.")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def transpose(self):
        """
        Transpose the matrix.

        :return: A new Matrix object representing the transpose of the original matrix.
        """
        result = [
            [self.data[i][j] for i in range(self.rows)]
            for j in range(self.cols)
        ]
        return Matrix(result)
