from functools import reduce

def b2d(binary_string: str) -> int:
    """
    Converts a binary string to its decimal equivalent without using built-in conversion functions, loops, or recursion.

    :param binary_string: A string representing a binary number.
    :return: An integer representing the decimal equivalent of the binary string.
    """
    def add_bit(acc, bit):
        return (acc << 1) | (ord(bit) - ord('0'))

    return reduce(add_bit, binary_string, 0)
