def encode_text(text, shift):
    """
    Encodes a given text using a Caesar cipher with a specified shift value.

    Parameters:
    text (str): The input string to be encoded.
    shift (int): The shift value for the Caesar cipher.

    Returns:
    str: The encoded string.
    """
    def shift_char(c, shift):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + shift) % 26 + ord('A'))
        else:
            return c

    if shift < 0:
        shift = 26 + shift  # Convert negative shift to equivalent positive shift
    return ''.join(shift_char(c, shift) for c in text)
