class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedList:
    def __init__(self):
        """Initialize an empty linked list."""
        self.head = None

    def append(self, value):
        """Add a node with the specified value to the end of the linked list."""
        new_node = Node(value)
        if not self.head:
            self.head = new_node
            return
        last_node = self.head
        while last_node.next:
            last_node = last_node.next
        last_node.next = new_node

    def insert(self, value):
        """Add a node with the specified value at the beginning of the linked list."""
        new_node = Node(value)
        new_node.next = self.head
        self.head = new_node

    def delete(self, value):
        """Remove the first node with the specified value from the linked list."""
        current_node = self.head

        if current_node and current_node.value == value:
            self.head = current_node.next
            current_node = None
            return

        prev = None
        while current_node and current_node.value != value:
            prev = current_node
            current_node = current_node.next

        if current_node is None:
            return

        prev.next = current_node.next
        current_node = None

    def find(self, value):
        """Return the node with the specified value, or None if no such node exists."""
        current_node = self.head
        while current_node:
            if current_node.value == value:
                return current_node
            current_node = current_node.next
        return None
