def check_valid_student_ids(student_ids, valid_ids):
    """
    Checks if all student IDs in the student_ids list are present in the valid_ids list.

    :param student_ids: List of student IDs to be validated.
    :param valid_ids: Sorted list of valid student IDs.
    :return: True if all student IDs are valid, False otherwise.
    """
    valid_id_index = 0
    number_of_valid_ids = len(valid_ids)

    for student_id in student_ids:
        found = False
        while valid_id_index < number_of_valid_ids and not found:
            if valid_ids[valid_id_index] == student_id:
                found = True
            elif valid_ids[valid_id_index] > student_id:
                return False
            else:
                valid_id_index += 1

        if not found:
            return False

    return True
