def find_root_with_highest_weight(nodes):
    """
    Finds a root node with the highest weight in a directed graph.
    If multiple root nodes have the same highest weight, returns the one with the smallest identifier.
    If no root nodes exist, returns the node with the lowest weight.
    If multiple nodes have the same lowest weight, returns the one with the smallest identifier.

    :param nodes: List of tuples (node_id, parent_nodes, weight)
    :return: Integer representing the node identifier that meets the criteria
    """
    from collections import defaultdict

    child_to_parent = defaultdict(set)
    node_weight = {}

    for node, parents, weight in nodes:
        for parent in parents:
            child_to_parent[node].add(parent)
        node_weight[node] = weight

    root_nodes = [node for node in node_weight if not child_to_parent[node]]

    if root_nodes:
        return max(root_nodes, key=lambda x: (node_weight[x], -x))
    else:
        return min(nodes, key=lambda x: (x[2], x[0]))[0]
