def is_prime(num):
    """Check if a number is prime."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def findPrimesInRange(m, n):
    """Return a list of all prime numbers in the range [m, n]."""
    primes = []
    for num in range(m, n + 1):
        if is_prime(num):
            primes.append(num)
    return primes

