    if user is None:
        abort(404)
    return jsonify(user)


@app.route('/users/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    """
    Updates the user with the specified id using the provided name and optional email.
    Returns a 404 error if the user does not exist.
