import random

def median_and_mode(numbers):
    """
    Computes the median and mode of a list of integers without using built-in sorting or mode functions.

    Parameters:
    numbers (list): A list of 500 integers between 1 and 1000 inclusive.

    Returns:
    tuple: A tuple containing the median and mode of the list.
    """
    # Step 1: Sort the list using bubble sort
    n = len(numbers)
    for i in range(n):
        for j in range(0, n-i-1):
            if numbers[j] > numbers[j+1]:
                numbers[j], numbers[j+1] = numbers[j+1], numbers[j]

    # Step 2: Calculate the median
    if n % 2 == 1:
        median = numbers[n // 2]
    else:
        median = (numbers[n // 2 - 1] + numbers[n // 2]) / 2

    # Step 3: Find the mode
    frequency = {}
    for num in numbers:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    max_count = 0
    mode = None
    for num, count in frequency.items():
        if count > max_count:
            max_count = count
            mode = num
        elif count == max_count:
            mode = min(mode, num)

    return median, mode

# Generate a list of 500 random integers between 1 and 1000
random_numbers = []
for _ in range(500):
    random_numbers.append(random.randint(1, 1000))

# Calculate the median and mode
