def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def filter_primes(lst):
    """Filter out prime numbers from a list of integers, ignoring non-integer values."""
    return [num for num in lst if isinstance(num, int) and is_prime(num)]
