def sort_tickets(tickets):
    """
    Sorts a list of concert tickets by 'Price' in ascending order.
    If two tickets have the same price, they are sorted by 'Date' in ascending order.

    :param tickets: List of dictionaries, each representing a concert ticket.
    :return: A new list of dictionaries sorted by 'Price' and 'Date'.
    """
    def compare(t1, t2):
        if t1['Price'] != t2['Price']:
            return (t1['Price'] > t2['Price']) - (t1['Price'] < t2['Price'])
        else:
            return (t1['Date'] > t2['Date']) - (t1['Date'] < t2['Date'])

    def bubble_sort(arr):
        n = len(arr)
        for i in range(n):
            for j in range(0, n-i-1):
                if compare(arr[j], arr[j+1]) > 0:
                    arr[j], arr[j+1] = arr[j+1], arr[j]
        return arr

    return bubble_sort(tickets)

