def count_direct_subordinates(org_structure):
    """
    Computes the number of direct subordinates for each employee in the organizational structure.

    :param org_structure: List of dictionaries representing the organizational structure.
    :return: Dictionary with employee names as keys and the number of direct subordinates as values.
    """
    subordinate_count = {}

    def traverse_hierarchy(employee):
        nonlocal subordinate_count
        subordinate_count[employee['name']] = len(employee['subordinates'])
        for subordinate in employee['subordinates']:
            traverse_hierarchy(subordinate)

    for employee in org_structure:
        traverse_hierarchy(employee)

    return subordinate_count

