def factorial(n):
    """
    Calculate the factorial of a given number n.

    :param n: Integer, the number to calculate the factorial for.
    :return: Integer, the factorial of n.
    """
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

def lexicographical_rank(s):
    """
    Calculate the lexicographical rank of the string s among all its unique permutations.

    :param s: String, the input string consisting of lowercase English letters.
    :return: Integer, the 1-based rank of the string s.
    """
    rank = 1
    n = len(s)
    count_map = {}

    for char in s:
        if char in count_map:
            count_map[char] += 1
        else:
            count_map[char] = 1

    for i in range(n):
        smaller = 0
        for char in count_map:
            if char < s[i]:
                smaller += count_map[char]

        denominator = 1
        for count in count_map.values():
            denominator *= factorial(count)

        rank += smaller * (factorial(n - i - 1) // denominator)

        count_map[s[i]] -= 1
        if count_map[s[i]] == 0:
            del count_map[s[i]]

    return rank

# Example usage:
s = "string"
print(lexicographical_rank(s))  # Output: 596
