class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class Tree:
    def __init__(self):
        self.root = None

    def add_node(self, value):
        """Inserts a new node with the given value into the BST."""
        new_node = TreeNode(value)
        if self.root is None:
            self.root = new_node
        else:
            current = self.root
            while True:
                if value < current.value:
                    if current.left is None:
                        current.left = new_node
                        break
                    else:
                        current = current.left
                else:
                    if current.right is None:
                        current.right = new_node
                        break
                    else:
                        current = current.right

    def find_node(self, value):
        """Searches for a node with the specified value in the BST.

        Returns the node if found, otherwise returns None."""
        current = self.root
        while current is not None:
            if current.value == value:
                return current
            elif value < current.value:
                current = current.left
            else:
                current = current.right
        return None

    def inorder_traversal(self):
        """Returns a list of values obtained by performing an inorder traversal of the BST."""
        elements = []
        def inorder_helper(node):
            if node is not None:
                inorder_helper(node.left)
                elements.append(node.value)
                inorder_helper(node.right)
        inorder_helper(self.root)
        return elements
