def flatten_list(nested_list):
    """
    Flattens a nested list and returns a list containing only non-empty strings and integers.

    :param nested_list: List of elements which may include integers, strings, and other lists.
    :return: A flat list containing only non-empty strings and integers.
    """
    def _flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from _flatten(item)
            elif isinstance(item, (int, str)) and item != '':
                yield item

    return list(_flatten(nested_list))
