def is_prime(n):
    """Determine if a given integer is a prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def count_primes(lst):
    """Count the number of prime numbers in the provided list of integers."""
    return sum(1 for num in lst if is_prime(num))

# Sample input
sample_input = [3, 4, -1, 5, 5, 2, 0]
# Function call
print(count_primes(sample_input))  # Output: 4
