def searchMatrix(matrix, target):
    """
    Searches for a target value in a matrix sorted in ascending order both row-wise and column-wise.

    :param matrix: List[List[int]] - The matrix to search within.
    :param target: int - The target value to search for.
    :return: Tuple[int, int] or int - The indices (row, col) of the target if found, otherwise -1.
    """
    if not matrix or not matrix[0]:
        return -1

    rows, cols = len(matrix), len(matrix[0])
    row, col = 0, cols - 1

    while row < rows and col >= 0:
        if matrix[row][col] == target:
            return (row, col)
        elif matrix[row][col] < target:
            row += 1
        else:
            col -= 1

    return -1
```

