def get_nested_value(data, keys):
    """
    Retrieves the value from a nested dictionary based on a list of keys.
    Wildcard '*' matches any single key at that level in the dictionary.

    :param data: A nested dictionary.
    :param keys: A list of keys, which may include wildcard characters '*'.
    :return: The value corresponding to the keys in the given order, or None if any key is not found.
    """
    for key in keys:
        if key == "*":
            if isinstance(data, dict):
                key = next(iter(data))
            else:
                return None
        if isinstance(data, dict) and key in data:
            data = data[key]
        else:
            return None
    return data
