def parse_urls(urls):
    """
    Parses a list of URLs and returns a dictionary mapping each URL (without query parameters)
    to a dictionary of its query parameters.

    :param urls: List of URLs as strings.
    :return: Dictionary with URLs as keys and dictionaries of query parameters as values.
    """
    result = {}
    for url in urls:
        if '?' in url:
            main_url, query = url.split('?', 1)
        else:
            main_url = url
            query = ''

        params = {}
        if query:
            for pair in query.split('&'):
                key, value = pair.split('=', 1)
                params[key] = value

        result[main_url] = params

    return result

