import json

def extract_key_value(json_string, target_key):
    """
    Parses a JSON string and returns the value associated with the target key.
    Handles nested JSON objects and arrays. Returns None if the key is not found.

    :param json_string: JSON string to parse.
    :param target_key: Key whose value needs to be retrieved.
    :return: The value of the target key or None if not found.
    """
    try:
        data = json.loads(json_string)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON string")

    def recursive_search(json_data, key):
        if isinstance(json_data, dict):
            for k, v in json_data.items():
                if k == key:
                    return v
                elif isinstance(v, (dict, list)):
                    result = recursive_search(v, key)
                    if result is not None:
                        return result
        elif isinstance(json_data, list):
            for item in json_data:
                result = recursive_search(item, key)
                if result is not None:
                    return result
        return None

    return recursive_search(data, target_key)
