def concatenate_elements(nested_list):
    """
    Perform a depth-first traversal of a nested list of integers and return a string
    of all integers separated by a comma and a space.

    :param nested_list: List of integers or nested lists of integers
    :return: String of integers separated by a comma and a space
    """
    def dfs(element):
        if isinstance(element, list):
            result = []
            for item in element:
                result.extend(dfs(item))
            return result
        else:
            return [str(element)]

    flat_list = dfs(nested_list)
    return ', '.join(flat_list)
```

