import json

def flatten_json(json_str):
    """
    Flattens a nested JSON structure into a single-level dictionary with dot-separated keys.

    :param json_str: A string representing a JSON object.
    :return: A dictionary with flattened keys and corresponding values.
    """
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    data = json.loads(json_str)
    return _flatten(data)
```

