def find_duplicates(strings):
    """
    Identifies and returns a dictionary of strings that appear more than once in the list.

    :param strings: List of strings to be analyzed.
    :return: Dictionary with duplicate strings as keys and their counts as values.
    """
    string_count = {}
    duplicates = {}

    for string in strings:
        if string in string_count:
            string_count[string] += 1
        else:
            string_count[string] = 1

    for string, count in string_count.items():
        if count > 1:
            duplicates[string] = count

    return duplicates

