def merge_dicts(dictA, dictB):
    """
    Merges two dictionaries, preferring user-defined integer values from dictB over default values from dictA.
    Only integer values are considered valid for inclusion in the resulting dictionary.

    :param dictA: Dictionary containing default values.
    :param dictB: Dictionary containing user-defined values.
    :return: A new dictionary with merged values, containing only integer values.
    """
    dictC = {}
    for key in set(dictA) | set(dictB):
        value = dictB.get(key, dictA.get(key))
        if isinstance(value, int):
            dictC[key] = value
    return dictC

