def bubble_sort(arr):
    """
    Sorts a list of numbers using the Bubble Sort algorithm.

    Parameters:
    arr (list): A list of numbers to be sorted.

    Returns:
    list: The sorted list.
    """
    n = len(arr)
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

def insertion_sort(arr):
    """
    Sorts a list of numbers using the Insertion Sort algorithm.

    Parameters:
    arr (list): A list of numbers to be sorted.

    Returns:
    list: The sorted list.
    """
    for i in range(1, len(arr)):
        key = arr[i]
        j = i-1
        while j >= 0 and key < arr[j]:
            arr[j+1] = arr[j]
            j -= 1
        arr[j+1] = key
    return arr

def optimize_sort(numbers):
    """
    Sorts a list of numbers using an optimized sorting strategy based on the list's length.

    Parameters:
    numbers (list): A list of numbers to be sorted.

    Returns:
    list: The sorted list.
    """
    if len(numbers) < 10:
        return bubble_sort(numbers)
    elif 10 <= len(numbers) <= 100:
        return insertion_sort(numbers)
    else:
        return sorted(numbers)
