def is_palindrome_anagram(s):
    """
    Determines if the characters of the string `s` can be rearranged to form a palindrome.

    :param s: A string consisting of lowercase English letters.
    :return: True if the characters can be rearranged to form a palindrome, False otherwise.
    """
    # Create a dictionary to count the frequency of each character
    char_count = {}

    # Count the frequency of each character in the string
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Count how many characters have an odd frequency
    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1

    # A string can be rearranged to form a palindrome if at most one character has an odd frequency
    return odd_count <= 1
