from typing import Dict, Any

def is_class_definition(doc_output: Dict[str, Any]) -> bool:
    """
    Determines if the given nested dictionary structure represents a class definition.

    Args:
    - doc_output: A dictionary representing a programming language's documentation output.

    Returns:
    - True if the structure contains a class definition, False otherwise.
    """
    def check_for_class(d: Any) -> bool:
        if isinstance(d, dict):
            if d.get('type') == 'class':
                return True
            for value in d.values():
                if check_for_class(value):
                    return True
        elif isinstance(d, list):
            for item in d:
                if check_for_class(item):
                    return True
        return False

    return check_for_class(doc_output)
