def sum_of_primes(limit):
    """
    Calculate the sum of all prime numbers up to and including the given limit.

    :param limit: An integer representing the upper bound up to which prime numbers should be summed.
    :return: An integer representing the sum of all prime numbers up to and including the limit.
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    prime_sum = 0
    for num in range(2, limit + 1):
        if is_prime(num):
            prime_sum += num
    return prime_sum

# Example usage:
