    def add_member(self, name):
        """Add a library member if they are not already registered."""
        if name not in self.members:
            self.members.append(name)
            print(f"Member '{name}' added to the library.")
        else:
            print(f"Member '{name}' is already in the library.")

    def remove_member(self, name):
        """Remove a library member if they exist."""
        if name in self.members:
            self.members.remove(name)
            print(f"Member '{name}' removed from the library.")
            books_to_remove = [book for book, member in self.borrowed_books.items() if member == name]
            for book in books_to_remove:
                del self.borrowed_books[book]
        else:
            print(f"Member '{name}' not found in the library.")

    def borrow_book(self, title, member_name):
        """Allow a registered member to borrow a book if the book is available."""
        if title in self.books and member_name in self.members and title not in self.borrowed_books:
            self.borrowed_books[title] = member_name
            print(f"Book '{title}' borrowed by '{member_name}'.")
        elif title not in self.books:
            print(f"Book '{title}' not found in the library.")
        elif member_name not in self.members:
            print(f"Member '{member_name}' not found in the library.")
        else:
            print(f"Book '{title}' is already borrowed.")

    def return_book(self, title):
        """Allow a member to return a borrowed book."""
        if title in self.borrowed_books:
            del self.borrowed_books[title]
            print(f"Book '{title}' returned to the library.")
        else:
            print(f"Book '{title}' was not borrowed.")

    def list_books(self):
        """Return a list of all books in the library."""
        return self.books

    def list_members(self):
        """Return a list of all registered members."""
        return self.members
