from typing import List

class Matrix:
    def __init__(self, data: List[List[int]]):
        """Initialize the matrix with the given 2D list data."""
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if data else 0

    def add(self, other: 'Matrix') -> 'Matrix':
        """Add two matrices of the same dimensions and return the resulting matrix."""
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to be added")

        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def subtract(self, other: 'Matrix') -> 'Matrix':
        """Subtract the second matrix from the first matrix and return the resulting matrix."""
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to be subtracted")

        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other: 'Matrix') -> 'Matrix':
        """Multiply the first matrix by the second matrix and return the resulting matrix."""
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must match number of rows in the second matrix for multiplication")

        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __str__(self) -> str:
        """Return a string representation of the matrix."""
        return '\n'.join([' '.join(map(str, row)) for row in self.data])
