def is_cyclic(graph):
    """
    Detects if there is a cycle in a directed graph represented as an adjacency list.

    :param graph: A dictionary representing the graph where keys are nodes and values are lists of adjacent nodes.
    :return: True if the graph contains a cycle, False otherwise.
    """
    visited = set()
    rec_stack = set()

    def dfs(v):
        visited.add(v)
        rec_stack.add(v)

        for neighbour in graph.get(v, []):
            if neighbour in rec_stack:
                return True
            if neighbour not in visited:
                if dfs(neighbour):
                    return True

        rec_stack.remove(v)
        return False

    for node in graph:
        if node not in visited:
            if dfs(node):
                return True
    return False

# Example usage:
graph = {
    0: [1],
    1: [2],
    2: [3],
    3: [1]
}

print(is_cyclic(graph))  # Output: True
