def isBalanced(expression):
    """
    Determines if the brackets in the given expression are balanced.

    :param expression: A string containing characters including {}, (), and [].
    :return: True if the brackets are balanced, False otherwise.
    """
    stack = []
    matching_bracket = {")": "(", "}": "{", "]": "["}

    for char in expression:
        if char in matching_bracket.values():
            stack.append(char)
        elif char in matching_bracket.keys():
            if not stack or matching_bracket[char] != stack.pop():
                return False

    return not stack
