def parse_gene_location(location):
    """
    Parses a gene location string and returns a tuple containing the chromosome name,
    start position, and end position.

    :param location: A string representing the gene location in the format "chromosome:start-end".
    :return: A tuple (chromosome_name, start_position, end_position).
    """
    chromosome = ''
    start = ''
    end = ''

    state = 'chromosome'
    for char in location:
        if state == 'chromosome':
            if char == ':':
                state = 'start'
            else:
                chromosome += char
        elif state == 'start':
            if char == '-':
                state = 'end'
            else:
                start += char
        elif state == 'end':
            end += char

    return chromosome, int(start), int(end)
