def longest_common_prefix(strs):
    """
    Determines the length of the longest common prefix among all strings in the list.

    :param strs: List of strings
    :return: Length of the longest common prefix
    """
    if not strs:
        return 0
    elif "" in strs:
        return 0

    prefix = strs[0]

    for string in strs[1:]:
        while string[:len(prefix)] != prefix and prefix:
            prefix = prefix[:-1]

    return len(prefix)
