def count_leaf_nodes(tree):
    """
    Counts the number of leaf nodes in a binary tree represented as a nested dictionary.

    :param tree: A dictionary representing the binary tree.
    :return: An integer representing the number of leaf nodes.
    """
    def is_leaf(node):
        return 'left' not in node and 'right' not in node

    def count_recursive(node):
        if not node:
            return 0
        if is_leaf(node):
            return 1
        return count_recursive(node['left']) + count_recursive(node['right'])

    return count_recursive(tree)
