def find_root(a, high=None, low=0):
    """
    Helper recursive function to find the integer square root of a number.

    :param a: The number to find the integer square root of.
    :param high: The upper bound for the binary search.
    :param low: The lower bound for the binary search.
    :return: The integer square root of the number.
    """
    if high is None:
        high = a
    if low > high:
        return high
    mid = (low + high) // 2
    if mid * mid == a:
        return mid
    elif mid * mid > a:
        return find_root(a, high=mid-1, low=low)
    else:
        return find_root(a, high=high, low=mid+1)

def dmca_root(a):
