def get_formatted_name(first_name, last_name, middle_names=None):
    """
    Formats a person's full name by capitalizing the first letter of each primary name
    and handling middle names according to their length.

    Parameters:
    - first_name (str): The first name of the person.
    - last_name (str): The last name of the person.
    - middle_names (list of str, optional): A list of middle names or initials.

    Returns:
    - str: The formatted full name.
    """
