            return name.upper()
        else:
            return name.capitalize()

    formatted_first_name = capitalize_name(first_name)
    formatted_last_name = capitalize_name(last_name)

    if middle_names:
        formatted_middle_names = ' '.join(capitalize_name(name) for name in middle_names)
        full_name = f"{formatted_first_name} {formatted_middle_names} {formatted_last_name}"
