def invert_mapping(old_map):
    """
    Inverts a dictionary, handling complex, immutable keys and values,
    including nested dictionaries. If a value appears multiple times,
    the last occurrence overwrites the previous ones.

    :param old_map: Original dictionary to invert
    :return: An inverted dictionary
    """
    def invert_dict(mapping):
        inverted = {}
        for key, value in mapping.items():
            if isinstance(value, dict):
                inverted.update({k: key for k in invert_dict(value).keys()})
            else:
                inverted[value] = key
        return inverted

    return invert_dict(old_map)
