def move_character(position, direction):
    """
    Calculate the new position of a character on an infinite grid after moving in a specified direction.

    Parameters:
    position (tuple): A tuple (x, y) representing the current position of the character.
    direction (str): A string representing the direction of the move ("up", "down", "left", "right").

    Returns:
    tuple: A tuple (x', y') representing the new position of the character after the move.

    Raises:
    ValueError: If the direction is not one of the valid options ("up", "down", "left", "right").
