def find_field_indices(all_fields, required_fields, optional_fields):
    """
    Returns two dictionaries containing the indices of required and optional fields in the all_fields list.

    Parameters:
    all_fields (list): A list of field names.
    required_fields (set): A set of required field names.
    optional_fields (set): A set of optional field names.

    Returns:
    tuple: Two dictionaries, the first for required fields and the second for optional fields.

    Raises:
    RuntimeError: If a required field is not found in all_fields.
    """
    required_fields_index = {}
    optional_fields_index = {}

    for index, field_name in enumerate(all_fields):
        if field_name in required_fields:
            required_fields_index[field_name] = index
        elif field_name in optional_fields:
            optional_fields_index[field_name] = index

    for field_name in required_fields:
        if field_name not in required_fields_index:
            raise RuntimeError(f"No field called {field_name}")

    return required_fields_index, optional_fields_index
