def secure_end(text: str, piece: str, lc: bool = False) -> bool:
    """
    Checks if the given string `text` ends with another string `piece` under specific conditions.
    If `lc` is True, the comparison is case-insensitive. The function returns True if `text` ends
    with `piece` and False otherwise. The comparison only proceeds if `piece` contains at least one digit.
    If the length of `text` is less than the length of `piece`, the function returns False.

    :param text: The string to be checked.
    :param piece: The string to check for at the end of `text`.
    :param lc: Boolean flag to determine if the comparison should be case-insensitive.
    :return: True if `text` ends with `piece` under the given conditions, False otherwise.
    """
    if not any(char.isdigit() for char in piece):
        return False

    if len(text) < len(piece):
        return False

    if lc:
        return text.lower().endswith(piece.lower())
    else:
        return text.endswith(piece)
