class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def bstFromPreorder(preorder):
    """
    Constructs a binary search tree from the given preorder traversal list.

    :param preorder: List[int] - The preorder traversal of the BST.
    :return: TreeNode - The root node of the constructed BST.
    """
    if not preorder:
        return None

    root = TreeNode(preorder[0])
    n = len(preorder)

    for i in range(1, n):
        value = preorder[i]
        current = root
        while (current.left and value < current.val) or (current.right and value >= current.val):
            if value < current.val:
                current = current.left
            else:
                current = current.right

        if value < current.val:
            current.left = TreeNode(value)
        else:
            current.right = TreeNode(value)

    return root
```

