class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with the given 2D list `data`.
        Raises a `ValueError` if `data` is not a valid 2D list with consistent row lengths.
        """
        if not data or not all(len(row) == len(data[0]) for row in data):
            raise ValueError("Data must be a 2D list with consistent row lengths.")
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0])

    def __add__(self, other):
        """
        Adds two matrices of the same dimensions.
        Raises a `ValueError` if dimensions do not match.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same dimensions for addition.")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __sub__(self, other):
        """
        Subtracts one matrix from another of the same dimensions.
        Raises a `ValueError` if dimensions do not match.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same dimensions for subtraction.")
        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __mul__(self, other):
        """
        Multiplies two matrices if the number of columns in the first matrix equals the number of rows in the second matrix.
        Also supports scalar multiplication.
        Raises a `ValueError` or `TypeError` for incompatible operations.
        """
        if isinstance(other, (int, float)):  # Scalar multiplication
            result = [
                [self.data[i][j] * other for j in range(self.cols)]
                for i in range(self.rows)
            ]
            return Matrix(result)
        elif isinstance(other, Matrix):
            if self.cols != other.rows:
                raise ValueError("Number of columns in the first matrix must be equal to the number of rows in the second matrix for multiplication.")
            result = [
                [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
                for i in range(self.rows)
            ]
            return Matrix(result)
        else:
            raise TypeError("Operation not supported with the given operand type.")

    def __str__(self):
        """
        Returns a string representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])

# Example usage:
matrix1 = Matrix([[1, 2], [3, 4]])
matrix2 = Matrix([[2, 0], [1, 2]])

print("Matrix 1:")
print(matrix1)
