class BankAccount:
    """A simple bank account system with deposit, withdrawal, and balance inquiry functionalities."""

    def __init__(self, initial_balance=0):
        """Initialize a new bank account with an optional initial balance."""
        if initial_balance < 0:
            raise ValueError("Initial balance must be non-negative.")
        self._balance = initial_balance

    def deposit(self, amount):
        """Deposit a specified amount into the bank account."""
        if amount <= 0:
            raise ValueError("Deposit amount must be positive.")
        self._balance += amount

    def withdraw(self, amount):
        """Withdraw a specified amount from the bank account."""
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive.")
        if amount > self._balance:
            raise ValueError("Insufficient funds")
        self._balance -= amount

    @property
    def balance(self):
        """Return the current balance of the bank account."""
        return self._balance

    def __str__(self):
        """Return a string representation of the bank account."""
        return f"BankAccount(balance={self._balance})"
