def is_carmichael(n):
    """
    Check if a number is a Carmichael number.

    :param n: Integer to check.
    :return: True if n is a Carmichael number, False otherwise.
    """
    if n < 2:
        return False
    for i in range(2, n):
        if pow(i, n, n) != i:
            return False
    return True

