class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        """Adds an item to the top of the stack."""
        self.items.append(item)  # O(1) average, but O(n) worst case due to list resizing

    def pop(self):
        """Removes and returns the top item from the stack. Returns None if the stack is empty."""
        if not self.is_empty():
            return self.items.pop()  # O(1)
        return None

    def peek(self):
        """Returns the top item from the stack without removing it. Returns None if the stack is empty."""
        if not self.is_empty():
            return self.items[-1]  # O(1)
        return None

    def is_empty(self):
        """Returns True if the stack is empty, otherwise False."""
        return len(self.items) == 0  # O(1)

    def size(self):
        """Returns the number of items in the stack."""
        return len(self.items)  # O(1)


class Queue:
    def __init__(self):
        self.items = []

    def push(self, item):
        """Adds an item to the end of the queue."""
        self.items.append(item)  # O(1) average, but O(n) worst case due to list resizing

    def pop(self):
        """Removes and returns the front item from the queue. Returns None if the queue is empty."""
        if not self.is_empty():
            return self.items.pop(0)  # O(n)
        return None

    def peek(self):
        """Returns the front item from the queue without removing it. Returns None if the queue is empty."""
        if not self.is_empty():
            return self.items[0]  # O(1)
        return None

    def is_empty(self):
        """Returns True if the queue is empty, otherwise False."""
        return len(self.items) == 0  # O(1)

    def size(self):
        """Returns the number of items in the queue."""
        return len(self.items)  # O(1)
```

