import json

def create_geojson(pois):
    """
    Converts a list of POIs into a GeoJSON FeatureCollection.

    Parameters:
    pois (list of dict): Each dictionary should have keys: 'name', 'latitude', 'longitude'

    Returns:
    dict: A GeoJSON FeatureCollection containing the POIs
    """
    feature_collection = {
        "type": "FeatureCollection",
        "features": []
    }

    for poi in pois:
        feature = {
            "type": "Feature",
            "geometry": {
                "type": "Point",
                "coordinates": [round(poi['longitude'], 6), round(poi['latitude'], 6)]
            },
            "properties": {
                "name": poi['name']
            }
        }
        feature_collection['features'].append(feature)

    return feature_collection

