def flatten_dict(nested_dict, parent_key='', sep='_'):
    """
    Flattens a nested dictionary into a single-level dictionary with concatenated keys separated by underscores.

    :param nested_dict: The nested dictionary to flatten.
    :param parent_key: The base key string for recursion (used internally).
    :param sep: The separator to use between keys.
    :return: A single-level dictionary with flattened keys.
    """
    items = {}
    for k, v in nested_dict.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.update(flatten_dict(v, new_key, sep=sep))
        else:
            items[new_key] = v
    return items

