    """
    Creates a new blog post.
    Expects a JSON payload with 'title' and 'content'.
    Returns the created blog post with a 201 status code.
    Returns a 400 error if the payload is invalid.
    """
    if not request.json or 'title' not in request.json or 'content' not in request.json:
        abort(400)
    new_post = {
        'id': blog_posts[-1]['id'] + 1 if blog_posts else 1,
        'title': request.json['title'],
        'content': request.json['content']
    }
    blog_posts.append(new_post)
