class Library:
    def __init__(self):
        self.inventory = {}

    def add_book(self, title, author):
        """
        Adds a new book to the inventory with the given title and author.
        If the book already exists, increments the count of that book.
        """
        if (title, author) in self.inventory:
            self.inventory[(title, author)] += 1
        else:
            self.inventory[(title, author)] = 1

    def remove_book(self, title, author):
        """
        Removes a book from the inventory. If the book exists, decrements the count of that book.
        If the count reaches zero, the book is completely removed from the inventory.
        """
        if (title, author) in self.inventory:
            self.inventory[(title, author)] -= 1
            if self.inventory[(title, author)] == 0:
                del self.inventory[(title, author)]

    def list_books(self):
        """
        Returns a list of all books in the inventory, sorted by title.
        Each book is represented as a string in the format "Title by Author (count)".
        """
        return sorted([f"{title} by {author} ({count})" for (title, author), count in self.inventory.items()])
