def filter_elements(lst, condition):
    """
    Recursively filters elements in the list based on the given condition.

    Parameters:
    lst (list): The list of elements to filter.
    condition (function): A function that takes an element and returns a boolean.

    Returns:
    list: A new list containing only the elements that satisfy the condition.
    """
    def recurse(index, result):
        if index == len(lst):
            return result
        elif condition(lst[index]):
            return recurse(index + 1, result + [lst[index]])
        else:
            return recurse(index + 1, result)

    return recurse(0, [])
