def check_connect_four_winner(grid):
    """
    Determines if there is a winner in a Connect Four game and returns the winning positions.

    Parameters:
    grid (list of list of str): A 7x6 grid representing the Connect Four board.

    Returns:
    tuple: A tuple containing a boolean and a list of tuples. The boolean is True if a player has won,
           and False otherwise. The list contains the coordinates (row, column) of the four connected
           tokens that form the winning line if a win is found, or an empty list if no winner is found.
    """
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Check horizontal lines
    for row in range(rows):
        for col in range(cols - 3):
            if grid[row][col] != '-' and all(grid[row][col] == grid[row][col+i] for i in range(4)):
                return True, [(row, col+i) for i in range(4)]

    # Check vertical lines
    for col in range(cols):
        for row in range(rows - 3):
            if grid[row][col] != '-' and all(grid[row][col] == grid[row+i][col] for i in range(4)):
                return True, [(row+i, col) for i in range(4)]

    # Check diagonal lines (down right)
    for row in range(rows - 3):
        for col in range(cols - 3):
            if grid[row][col] != '-' and all(grid[row][col] == grid[row+i][col+i] for i in range(4)):
                return True, [(row+i, col+i) for i in range(4)]

    # Check diagonal lines (down left)
    for row in range(rows - 3):
        for col in range(3, cols):
            if grid[row][col] != '-' and all(grid[row][col] == grid[row+i][col-i] for i in range(4)):
                return True, [(row+i, col-i) for i in range(4)]

    return False, []
