def find_duplicates(lst):
    """
    Identifies and returns a dictionary of all duplicate integers in the list along with their frequency.

    Parameters:
    lst (list): A list of integers.

    Returns:
    dict: A dictionary with duplicate integers as keys and their frequencies as values, sorted by keys.
    """
    frequency_dict = {}
    for item in lst:
        if item in frequency_dict:
            frequency_dict[item] += 1
        else:
            frequency_dict[item] = 1

    duplicates = {k: v for k, v in frequency_dict.items() if v > 1}
    return dict(sorted(duplicates.items()))
