def convert_string_type(constant_string, input_string):
    """
    Convert constant_string to the same type as input_string using a custom ASCII encoding table.

    Parameters:
    constant_string (str): The string to be converted, must contain only ASCII characters.
    input_string (str or bytes): The string whose type will be used as a reference for conversion.

    Returns:
    str or bytes: The converted constant_string with the same type as input_string.

    Raises:
    ValueError: If constant_string contains non-ASCII characters.
    """
    # Generate custom encoding/decoding table (ASCII to byte/char map)
    ascii_to_bytes = {chr(i): bytes([i]) for i in range(128)}
    bytes_to_ascii = {bytes([i]): chr(i) for i in range(128)}

    # Check if constant_string only contains ASCII characters
    if not all(ord(c) < 128 for c in constant_string):
        raise ValueError("constant_string must only contain ASCII characters")

    # If types are the same, return constant_string as is
    if type(constant_string) == type(input_string):
        return constant_string

    # Convert constant_string based on the type of input_string
    if isinstance(input_string, bytes):
        # Convert constant_string to bytes using the encoding table
        return b''.join(ascii_to_bytes[char] for char in constant_string)
    elif isinstance(input_string, str):
        # Convert constant_string from bytes to str using the decoding table
        return ''.join(bytes_to_ascii[bytes([ord(char)])] for char in constant_string)
