def generate_primes(limit):
    """
    Generates prime numbers from 2 up to the specified limit using a generator.

    :param limit: The upper bound for generating prime numbers (inclusive).
    :yield: Prime numbers starting from 2 up to the limit.
    """
    if limit < 2:
        return
    yield 2
    primes = [2]
    for num in range(3, limit + 1, 2):
        is_prime = True
        for p in primes:
            if p * p > num:
                break
            if num % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
            yield num
