```python
def find_key_in_ordered_branches(target_key, nested_dict):
    """
    Returns the value associated with target_key if it exists in the dictionary
    and only if the branch containing the key maintains lexicographical order at all levels.
    Otherwise, returns None.
    """
    def is_lexicographically_ordered(dictionary):
        """
        Checks if the keys of the dictionary are in lexicographical order.
        """
        keys = list(dictionary.keys())
        return keys == sorted(keys)

    def search_in_dict(d, key):
        """
        Recursively searches for the key in the dictionary, considering only branches
        that are lexicographically ordered.
        """
        if not is_lexicographically_ordered(d):
            return None
        if key in d:
            return d[key]
        for k, v in d.items():
            if isinstance(v, dict):
                result = search_in_dict(v, key)
                if result is not None:
                    return result
        return None

    return search_in_dict(nested_dict, target_key)
