def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def extract_primes(numbers):
    """Extract and return a sorted list of prime numbers from the input list."""
    primes = [num for num in numbers if is_prime(num)]
    return sorted(primes)

