    Parses a JSON string and extracts all unique keys, including nested keys.

    :param json_str: A string representing a valid JSON object.
    :return: A set of unique keys found in the JSON structure.
    """
    def recursive_extract(obj, keys=set()):
        if isinstance(obj, dict):
            for key, value in obj.items():
                keys.add(key)
                recursive_extract(value, keys)
        elif isinstance(obj, list):
            for item in obj:
