def circular_search(target, nums):
    """
    Searches for the target in a circularly sorted array using binary search.

    Parameters:
    target (int): The integer to search for.
    nums (List[int]): The circularly sorted array of integers.

    Returns:
    int: The index of the target if found, otherwise -1.
    """
    def search(nums, left, right, target):
        if left > right:
            return -1

        mid = (left + right) // 2

        if nums[mid] == target:
            return mid

        if nums[left] <= nums[mid]:  # Left side is sorted
            if nums[left] <= target <= nums[mid]:
                return search(nums, left, mid - 1, target)
            else:
                return search(nums, mid + 1, right, target)
        else:  # Right side is sorted
            if nums[mid] <= target <= nums[right]:
                return search(nums, mid + 1, right, target)
            else:
                return search(nums, left, mid - 1, target)

    return search(nums, 0, len(nums) - 1, target)
