def is_binary_tree(parents):
    """
    Determines if the given tree represented by the list of parent indices is a binary tree.

    :param parents: List[int] where parents[i] is the parent of the node at index i.
    :return: True if the tree is a binary tree, False otherwise.
    """
    if parents[0] != -1:
        return False

    children_count = {}

    for index in range(1, len(parents)):
        parent = parents[index]

        if parent >= len(parents) or parent < 0:
            return False

        if parent in children_count:
            children_count[parent] += 1
        else:
            children_count[parent] = 1

        if children_count[parent] > 2:
            return False

    return True
