def is_balanced(s):
    """
    Determines if the input string has balanced parentheses, square brackets, and curly braces.

    :param s: A string that may contain various characters.
    :return: True if the string has balanced brackets, otherwise False.
    """
    matching = {')': '(', ']': '[', '}': '{'}
    stack = []

    for char in s:
        if char in matching.values():
            stack.append(char)
        elif char in matching:
            top_element = stack.pop() if stack else '#'
            if matching[char] != top_element:
                return False

    return not stack

