def extract_words(text, remove_empty):
    """
    Returns a generator yielding words from the input string, excluding content within parentheses.
    If remove_empty is True, empty strings are excluded from the output.

    :param text: A string containing words, spaces, punctuation, and possibly nested parentheses.
    :param remove_empty: A boolean indicating whether to exclude empty strings from the output.
    :return: A generator yielding words from the input string.
    """
    import re
    stack = []
    current_word = []
    for char in text:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack:
                stack.pop()
        elif not stack:
            if char == ' ':
                if current_word:
                    word = ''.join(current_word)
                    if not (remove_empty and word == ''):
                        yield word
                    current_word = []
            else:
                current_word.append(char)
    if current_word:
        word = ''.join(current_word)
        if not (remove_empty and word == ''):
            yield word
