def compare_elements(element1, element2):
    """
    Compares two elements and returns 1 if element1 is greater, 0 if they are equal, and -1 if element1 is less.
    If either element is a dictionary, returns 0.
    """
    # Check if either element is a dictionary
    if isinstance(element1, dict) or isinstance(element2, dict):
        return 0

    # Determine the type of comparison based on the types of elements
    if type(element1) is not type(element2):
        return 0

    # Convert elements to strings for comparison if they are not lists or numbers
    if not isinstance(element1, (int, float, list)):
        element1 = str(element1)
        element2 = str(element2)

    # Use subtraction to determine the relationship between elements
    if isinstance(element1, (int, float)):
        diff = element1 - element2
    elif isinstance(element1, list):
        # Compare lists based on their lengths and elements
        len_diff = len(element1) - len(element2)
        if len_diff != 0:
            return 1 if len_diff > 0 else -1
        # If lengths are equal, compare elements one by one
        for e1, e2 in zip(element1, element2):
            result = compare_elements(e1, e2)
            if result != 0:
                return result
        return 0  # Lists are equal
    else:
        # Compare strings lexicographically
        diff = 0
        for c1, c2 in zip(element1, element2):
            diff = ord(c1) - ord(c2)
            if diff != 0:
                break
        if diff == 0:
            diff = len(element1) - len(element2)

    # Determine the result based on the difference
    if diff > 0:
        return 1
    elif diff < 0:
        return -1
    else:
        return 0
