def SubstitutionDecrypt(ciphertext: str, key: dict) -> str:
    """
    Decrypts a given ciphertext using a monoalphabetic substitution cipher.

    Parameters:
    ciphertext (str): The encrypted text to be decrypted.
    key (dict): A dictionary mapping each letter in the ciphertext to a corresponding letter in the plaintext.

    Returns:
    str: The decrypted plaintext.
    """
    reverse_key = {v: k for k, v in key.items()}
    plaintext = []

    for char in ciphertext:
        if char.isalpha():
            original_char = reverse_key[char.lower()]
            plaintext.append(original_char.upper() if char.isupper() else original_char)
        else:
            plaintext.append(char)

    return ''.join(plaintext)
