        if not self.head:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node

    def remove_node(self, key):
        """
        Removes the first node with the specified key from the list.
        Prints an error message if the list is empty or the key is not found.
        """
        if not self.head:
            print("Error: List is empty, cannot remove node.")
            return

        if self.head.data == key:
            self.head = self.head.next
            return

        current = self.head
        while current.next and current.next.data != key:
            current = current.next

        if not current.next:
            print("Error: Key not found in the list.")
            return

        current.next = current.next.next

    def display_list(self):
        """
        Prints the elements of the list in order, followed by 'None'.
        Prints "List is empty." if the list is empty.
        """
        if not self.head:
            print("List is empty.")
            return
        current = self.head
        while current:
            print(current.data, end=" -> ")
            current = current.next
        print("None")
