def parse_ranges(input_str):
    """
    Parses a string containing numbers and ranges, returning a sorted list of unique integers.

    :param input_str: A string with numbers and ranges separated by commas.
    :return: A sorted list of unique integers.
    """
    if len(input_str) > 1000:
        raise ValueError("Input string must be no more than 1000 characters long.")

    parts = input_str.replace(' ', '').split(',')
    numbers = set()

    for part in parts:
        if '-' in part:
            start, end = map(int, part.split('-'))
            numbers.update(range(start, end + 1))
        else:
            numbers.add(int(part))

    return sorted(numbers)
