def length_of_lis(arr):
    """
    Finds the length of the longest strictly increasing subsequence in the given array.

    :param arr: List[int] - The input array of integers.
    :return: int - The length of the longest strictly increasing subsequence.
    """
    if not arr:
        return 0

    dp = [1] * len(arr)

    for i in range(1, len(arr)):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

