def longest_increasing_subsequence(nums):
    """
    Returns the length of the longest increasing subsequence in the given list of integers.

    :param nums: List[int] - A list of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    # dp[i] will hold the length of the longest increasing subsequence that ends with nums[i]
    dp = [1] * len(nums)

    # Build the dp array where each dp[i] represents the LIS ending at index i
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # The length of the longest increasing subsequence is the maximum value in dp array
    return max(dp)
