def find_common_elements(list1, list2):
    """
    Finds the common elements between two lists, including duplicates, without using built-in set operations.

    Parameters:
    list1 (list of int): The first list of integers.
    list2 (list of int): The second list of integers.

    Returns:
    list of int: A list containing the common elements between list1 and list2, including duplicates.
    """
    # Create a dictionary to store the count of each element in list1
    count_dict1 = {}
    for item in list1:
        if item in count_dict1:
            count_dict1[item] += 1
        else:
            count_dict1[item] = 1

    # Create a dictionary to store the count of each element in list2
    count_dict2 = {}
    for item in list2:
        if item in count_dict2:
            count_dict2[item] += 1
        else:
            count_dict2[item] = 1

    # Find common elements and consider the minimum count from both dictionaries
    common_elements = []
    for key in count_dict1:
        if key in count_dict2:
            min_count = min(count_dict1[key], count_dict2[key])
            for _ in range(min_count):
                common_elements.append(key)

    return common_elements

# Example usage:
list1 = [1, 2, 2, 3, 4]
list2 = [2, 2, 3, 5]
