def find_max_occurrences(strings):
    """
    Finds the string with the highest frequency in the given list and returns it
    along with its frequency in a dictionary. If there are multiple strings with the
    same maximum frequency, returns any one of them. Returns an empty dictionary
    if the input list is empty.

    :param strings: List of strings
    :return: Dictionary with the most frequent string and its count
    """
    if not strings:
        return {}

    occurrences = {}

    for string in strings:
        if string in occurrences:
            occurrences[string] += 1
        else:
            occurrences[string] = 1

    max_string = max(occurrences, key=occurrences.get)
    return {max_string: occurrences[max_string]}
