def flatten(nested_list):
    """Recursively flattens a nested list of integers."""
    for item in nested_list:
        if isinstance(item, list):
            yield from flatten(item)
        else:
            yield item

def check_uniformity(data):
    """Checks if the absolute difference between consecutive elements in a flattened list is uniform."""
    flat_data = list(flatten(data))

    if len(flat_data) < 2:
        return True  # Not enough elements to compare, but assume uniformity

    expected_diff = abs(flat_data[1] - flat_data[0])

    for i in range(1, len(flat_data) - 1):
        if abs(flat_data[i+1] - flat_data[i]) != expected_diff:
            return False

    return True

# Example usage:
print(check_uniformity([1, 3, 5, 7]))  # Should return True
print(check_uniformity([5, 5, 5, 5]))  # Should return True
print(check_uniformity([1, 2, 4, 8]))  # Should return False
print(check_uniformity([1, [3, 5], 7]))  # Should return True
print(check_uniformity([5, [5, [5]], 5]))  # Should return True
print(check_uniformity([1, [2, [4]], 8]))  # Should return False
