class DataObj:
    def __init__(self, data=None):
        self.data = data if data is not None else {}

def dataObj2Str(data_obj):
    """
    Converts a DataObj instance into a string representation without any whitespace characters.

    :param data_obj: An instance of DataObj.
    :return: A string representing the configuration data.
    """
    def build_str(item):
        if isinstance(item, DataObj):
            return ''.join(build_str(k) + build_str(v) for k, v in item.data.items())
        elif isinstance(item, str):
            return item
        elif isinstance(item, list):
            return ''.join(build_str(i) for i in item)
        else:
            return str(item)

    return build_str(data_obj)
