def is_prime(num):
    """Check if a number is prime."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def sieve_of_eratosthenes(max_num):
    """Generate a list of prime numbers up to max_num using the Sieve of Eratosthenes."""
    is_prime_list = [True] * (max_num + 1)
    p = 2
    while p * p <= max_num:
        if is_prime_list[p]:
            for i in range(p * p, max_num + 1, p):
                is_prime_list[i] = False
        p += 1
    return [p for p in range(2, max_num + 1) if is_prime_list[p]]

def filter_primes(number_list):
    """Return a list of prime numbers from the given number_list."""
    if not number_list:
        return []
    max_num = max(number_list)
    prime_numbers = set(sieve_of_eratosthenes(max_num))
    return [num for num in number_list if num in prime_numbers]

# Example usage:
