class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def search_bst(root, value):
    """
    Searches for a node with the given value in a binary search tree.

    :param root: TreeNode, the root of the BST
    :param value: int, the value to search for
    :return: TreeNode or None, the node containing the value or None if not found
    """
    if root is None or root.val == value:
        return root

    if value > root.val:
        return search_bst(root.right, value)

    return search_bst(root.left, value)

def insert_into_bst(root, val):
    """
    Inserts a value into the BST.

    :param root: TreeNode, the root of the BST
    :param val: int, the value to insert
    :return: TreeNode, the root of the BST after insertion
    """
    if root is None:
        return TreeNode(val)

    if val < root.val:
        root.left = insert_into_bst(root.left, val)
    else:
        root.right = insert_into_bst(root.right, val)

    return root

