def find_first_occurrences(str_in, chars, index=0, result=None):
    """
    Recursively finds the first occurrence of each character in chars within str_in.

    :param str_in: The input string to search within.
    :param chars: A list of characters to find in the string.
    :param index: The current index in the string being checked.
    :param result: A dictionary to store the first occurrence indices of characters.
    :return: A dictionary with characters as keys and their first occurrence indices as values.
    """
    if result is None:
        result = {char: None for char in chars}

    if index == len(str_in):
        return result

    result = {k: (index if k == str_in[index] and result[k] is None else v) for k, v in result.items()}

    return find_first_occurrences(str_in, chars, index + 1, result)
