class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        """Inserts a value into the BST."""
        self.root = self._insert_recursively(self.root, value)

    def _insert_recursively(self, node, value):
        if node is None:
            return TreeNode(value)
        if value < node.value:
            node.left = self._insert_recursively(node.left, value)
        elif value > node.value:
            node.right = self._insert_recursively(node.right, value)
        return node

    def delete(self, value):
        """Deletes a value from the BST."""
        self.root = self._delete_recursively(self.root, value)

    def _delete_recursively(self, node, value):
        if node is None:
            return node

        if value < node.value:
            node.left = self._delete_recursively(node.left, value)
        elif value > node.value:
            node.right = self._delete_recursively(node.right, value)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            node.value = self._min_value_node(node.right).value
            node.right = self._delete_recursively(node.right, node.value)

        return node

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current

    def search(self, value):
        """Searches for a value in the BST and returns True if found, False otherwise."""
        return self._search_recursively(self.root, value)

    def _search_recursively(self, node, value):
        if node is None:
            return False
        if node.value == value:
            return True
        elif value < node.value:
            return self._search_recursively(node.left, value)
        else:
            return self._search_recursively(node.right, value)

    def inorder_traversal(self):
        """Returns a list of values obtained by performing an in-order traversal of the BST."""
        return self._inorder_traversal_recursively(self.root)

    def _inorder_traversal_recursively(self, node):
        result = []
        if node is not None:
            result = self._inorder_traversal_recursively(node.left)
            result.append(node.value)
            result += self._inorder_traversal_recursively(node.right)
        return result
