class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with a 2D list `data`.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def __str__(self):
        """
        Returns a string representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])

    def add(self, other):
        """
        Adds two matrices and returns the result.
        Raises a ValueError if the dimensions do not match.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices dimensions must match for addition.")

        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def subtract(self, other):
        """
        Subtracts one matrix from another and returns the result.
        Raises a ValueError if the dimensions do not match.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices dimensions must match for subtraction.")

        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiplies two matrices and returns the result.
        Raises a ValueError if the number of columns in the first matrix is not equal to the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to number of rows in the second matrix for multiplication.")

        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

