class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Inserts a new key into the binary search tree."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        """Helper recursive method to insert a value in the BST."""
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert(node.right, key)

    def delete(self, key):
        """Deletes a key from the binary search tree."""
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        """Helper recursive method to delete a value in the BST."""
        if node is None:
            return node
        if key < node.val:
            node.left = self._delete(node.left, key)
        elif key > node.val:
            node.right = self._delete(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            node.val = self._min_value_node(node.right).val
            node.right = self._delete(node.right, node.val)

        return node

    def in_order_traversal(self):
        """Returns a list of keys in the tree in in-order traversal order."""
        elements = []
        stack = []
        current = self.root

        while stack or current is not None:
            while current is not None:
                stack.append(current)
                current = current.left

            current = stack.pop()
            elements.append(current.val)
            current = current.right

        return elements

    def find_min(self):
        """Returns the minimum key in the tree."""
        if self.root is None:
            return None
        return self._min_value_node(self.root).val

    def _min_value_node(self, node):
        """Helper method to find the node with the minimum key value."""
        current = node
        while current.left is not None:
            current = current.left
        return current
