        return nested_dict

    lowercase_dict = {}
    for key, value in nested_dict.items():
        new_key = key.lower()
        if isinstance(value, dict):
            value = convert_keys_to_lowercase(value)
        lowercase_dict[new_key] = value
    return lowercase_dict

