def word_frequency_analysis(text):
    """
    Analyzes the frequency of words in the given text and returns a dictionary
    with words sorted by frequency in descending order and lexicographically in ascending order.

    :param text: A string containing words separated by spaces and punctuation.
    :return: A dictionary with words as keys and their frequencies as values.
    """
    def custom_isalpha(c):
        """
        Checks if a character is an alphabetic letter.

        :param c: A single character.
        :return: True if the character is alphabetic, False otherwise.
        """
        return ('a' <= c <= 'z') or ('A' <= c <= 'Z')

    def to_lower(c):
        """
        Converts an uppercase letter to lowercase.

        :param c: A single character.
        :return: The lowercase version of the character if it's uppercase, otherwise the character itself.
        """
        if 'A' <= c <= 'Z':
            return chr(ord(c) + 32)
        return c

    def build_word(word):
        """
        Constructs a word from a sequence of characters, converting them to lowercase and filtering out non-alphabetic characters.

        :param word: A string of characters.
        :return: A string containing only lowercase alphabetic characters.
        """
        new_word = ''
        for char in word:
            if custom_isalpha(char):
                new_word += to_lower(char)
        return new_word

    i = 0
    words = {}
    n = len(text)

    while i < n:
        if custom_isalpha(text[i]):
            start = i
            while i < n and custom_isalpha(text[i]):
                i += 1
            word = build_word(text[start:i])
            if word:
                if word in words:
                    words[word] += 1
                else:
                    words[word] = 1
        else:
            i += 1

    frequency_list = []
    for word, freq in words.items():
        frequency_list.append((word, freq))

    for j in range(1, len(frequency_list)):
        key = frequency_list[j]
        i = j - 1
        while i >= 0 and ((frequency_list[i][1] < key[1]) or (frequency_list[i][1] == key[1] and frequency_list[i][0] > key[0])):
            frequency_list[i + 1] = frequency_list[i]
            i -= 1
        frequency_list[i + 1] = key

    result = {}
    for word, freq in frequency_list:
        result[word] = freq

    return result
