def merge_sorted_lists(list1, list2):
    """
    Merges two sorted lists and returns a new sorted list containing only the elements
    that appear in both lists with a combined frequency greater than one.

    :param list1: List[int] - First sorted list of integers.
    :param list2: List[int] - Second sorted list of integers.
    :return: List[int] - Sorted list of common elements with frequency > 1.
    """
    i, j = 0, 0
    result = []
    frequency = {}

    while i < len(list1) and j < len(list2):
        if list1[i] < list2[j]:
            if list1[i] in frequency:
                frequency[list1[i]] += 1
            i += 1
        elif list1[i] > list2[j]:
            if list2[j] in frequency:
                frequency[list2[j]] += 1
            j += 1
        else:
            element = list1[i]
            if element not in frequency:
                frequency[element] = 2
            else:
                frequency[element] += 1
            i += 1
            j += 1

    for element, count in frequency.items():
        if count > 1:
            result.append(element)

    return result
