def count_anagrams(words):
    """
    Returns a dictionary with words as keys and the count of their anagrams in the list as values.

    :param words: List of strings
    :return: Dictionary with words and their anagram counts
    """
    anagram_counts = {}
    anagram_dict = {}

    for word in words:
        sorted_word = ''.join(sorted(word))
        if sorted_word not in anagram_dict:
            anagram_dict[sorted_word] = []
        anagram_dict[sorted_word].append(word)

    for sorted_word, anagrams in anagram_dict.items():
        count = len(anagrams)
        for word in anagrams:
            anagram_counts[word] = count

    return anagram_counts
