def find_duplicate_elements(nums):
    """
    Finds and returns a list of duplicate elements in the input list,
    sorted in descending order without duplicates.

    :param nums: List of integers
    :return: List of integers that appear more than once, sorted in descending order
    """
    count_map = {}
    duplicates = set()

    for num in nums:
        if num in count_map:
            count_map[num] += 1
            duplicates.add(num)
        else:
            count_map[num] = 1

