def process_commits(commits):
    """
    Processes a list of commit objects and returns a dictionary with commit hashes as keys
    and commit messages as values. Only the commit with the lexicographically smallest hash
    is included for commits with duplicate messages. Commits with non-alphanumeric hashes are ignored.

    :param commits: List of dictionaries, each containing 'hash' and 'message' keys.
    :return: Dictionary with commit hashes as keys and commit messages as values.
    """
    commit_dict = {}
    for commit in commits:
        commit_hash = commit['hash']
        commit_message = commit['message']

        if not commit_hash.isalnum():
            continue

        if commit_message in commit_dict:
            if commit_hash < commit_dict[commit_message][0]:
                commit_dict[commit_message] = (commit_hash, commit_message)
        else:
            commit_dict[commit_message] = (commit_hash, commit_message)

    result = {hash_val: msg for msg, (hash_val, _) in commit_dict.items()}
    return result
