def evaluate_expression(expression):
    """
    Evaluates a mathematical expression given as a string without using eval() or any built-in parsing libraries.

    :param expression: A string representing the mathematical expression.
    :return: The result of the expression as an integer or float, or an error message as a string.
    """
    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ValueError("Division by zero.")
            values.append(left / right)

    def greater_precedence(op1, op2):
        return precedence(op1) > precedence(op2)

    def evaluate():
        operators = []
        values = []
        i = 0
        while i < len(expression):
            if expression[i] == ' ':
                i += 1
                continue
            if expression[i] in '0123456789':
                j = i
                while j < len(expression) and expression[j] in '0123456789.':
                    j += 1
                values.append(float(expression[i:j]))
                i = j
            elif expression[i] in '+-*/':
                while (operators and operators[-1] != '(' and
                       greater_precedence(operators[-1], expression[i])):
                    apply_operator(operators, values)
                operators.append(expression[i])
                i += 1
            elif expression[i] == '(':
                operators.append(expression[i])
                i += 1
            elif expression[i] == ')':
                while operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # pop '('
                i += 1
            else:
                raise ValueError("Invalid character in expression")
        while operators:
            apply_operator(operators, values)
        return values[0]

    try:
        return evaluate()
    except Exception as e:
        return f"Error: {e}"
```

