def merge_dicts(dict1, dict2):
    """
    Merges two dictionaries of dictionaries by taking the union of keys and
    performing element-wise multiplication of values in sub-dictionaries.

    Parameters:
    dict1 (dict): The first dictionary of dictionaries.
    dict2 (dict): The second dictionary of dictionaries.

    Returns:
    dict: The merged dictionary with element-wise products where applicable.
    """
    all_keys = set(dict1.keys()).union(set(dict2.keys()))
    dict_res = {}

    for key in all_keys:
        subdict1 = dict1.get(key, {})
        subdict2 = dict2.get(key, {})
        subdict_res = {}

        all_subkeys = set(subdict1.keys()).union(set(subdict2.keys()))

        for subkey in all_subkeys:
            val1 = subdict1.get(subkey, 1)
            val2 = subdict2.get(subkey, 1)
            subdict_res[subkey] = val1 * val2

        dict_res[key] = subdict_res

    return dict_res

