def binary_search(arr, target):
    """
    Perform a binary search on a sorted array to find the index of the target element.

    Parameters:
    arr (list of int): The sorted array to search.
    target (int): The target element to find in the array.

    Returns:
    int: The index of the target element if found, otherwise -1.
    """
    def helper(left, right):
        if left > right:
            return -1  # Target is not present in array

        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            return helper(mid + 1, right)
        else:
            return helper(left, mid - 1)

    return helper(0, len(arr) - 1)
```

```python
def convert_string(s):
    """
    Converts a string to an integer or float if possible, otherwise returns the original string.

    :param s: The input string to be converted.
    :return: An integer, float, or the original string based on the input.
    """
    def is_integer(string):
        """
        Checks if the given string represents a valid integer.

        :param string: The string to check.
        :return: True if the string is a valid integer, False otherwise.
        """
        if string == "":
            return False
        if string[0] == '-' or string[0] == '+':
            string = string[1:]
        for char in string:
            if ord('0') <= ord(char) <= ord('9'):
                continue
            return False
        return True

    def is_float(string):
        """
        Checks if the given string represents a valid float.

        :param string: The string to check.
        :return: True if the string is a valid float, False otherwise.
        """
        if string == "":
            return False
        if string[0] == '-' or string[0] == '+':
            string = string[1:]
        parts = string.split('.')
        if len(parts) > 2:
            return False
        if len(parts) == 1:
            return is_integer(parts[0])
        return (is_integer(parts[0]) or parts[0] == "") and is_integer(parts[1])

    s = s.strip()
    if is_integer(s):
        sign = -1 if s[0] == '-' else 1
        start_index = 1 if s[0] in ['-', '+'] else 0
        result = 0
        for char in s[start_index:]:
            result = result * 10 + (ord(char) - ord('0'))
        return sign * result

    elif is_float(s):
        sign = -1 if s[0] == '-' else 1
        start_index = 1 if s[0] in ['-', '+'] else 0
        integer_part, fractional_part = s[start_index:].split('.', 1) if '.' in s[start_index:] else (s[start_index:], "0")
        integer_value = 0
        for char in integer_part:
            integer_value = integer_value * 10 + (ord(char) - ord('0'))
        fractional_value = 0
        fractional_level = 1
        for char in fractional_part:
            fractional_level *= 10
            fractional_value = fractional_value * 10 + (ord(char) - ord('0'))
        return sign * (integer_value + fractional_value / fractional_level)
    else:
        return s
