def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def number_to_words(n):
    """Convert a number to its corresponding English words."""
    ones = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    if 1 <= n < 10:
        return ones[n]
    elif 10 <= n < 20:
        return teens[n - 10]
    elif 20 <= n < 100:
        ten, one = divmod(n, 10)
        return tens[ten] + ('' if one == 0 else ones[one])
    else:
        return str(n)

def custom_camel_case(s):
    """Convert a string to custom camel case format."""
    words = s.split('_')
    result = [words[0].lower()]
    for word in words[1:]:
        if word.isdigit():
            number = int(word)
            if is_prime(number):
                word = number_to_words(number)
            else:
                word = str(number)
        result.append(word.capitalize())
    return ''.join(result)

