def merge_and_dedupe(list1, list2):
    """
    Merges two ordered lists into a single list without duplicates,
    preserving the relative order of elements from the original lists.

    :param list1: First ordered list of integers.
    :param list2: Second ordered list of integers.
    :return: A new list with elements in non-decreasing order and without duplicates.
    """
    merged = []
    index1, index2 = 0, 0
    len1, len2 = len(list1), len(list2)

    while index1 < len1 and index2 < len2:
        if list1[index1] < list2[index2]:
            if not merged or merged[-1] != list1[index1]:
                merged.append(list1[index1])
            index1 += 1
        elif list1[index1] > list2[index2]:
            if not merged or merged[-1] != list2[index2]:
                merged.append(list2[index2])
            index2 += 1
        else:
            if not merged or merged[-1] != list1[index1]:
                merged.append(list1[index1])
            index1 += 1
            index2 += 1

    while index1 < len1:
        if not merged or merged[-1] != list1[index1]:
            merged.append(list1[index1])
        index1 += 1

    while index2 < len2:
        if not merged or merged[-1] != list2[index2]:
            merged.append(list2[index2])
        index2 += 1

    return merged
