def has_cycle(graph):
    """
    Detects if a directed graph contains a cycle.

    :param graph: A dictionary representing the graph as an adjacency list.
    :return: True if the graph contains a cycle, False otherwise.
    """
    visited = set()
    recursion_stack = set()

    def is_cyclic(v):
        visited.add(v)
        recursion_stack.add(v)

        for neighbour in graph[v]:
            if neighbour in recursion_stack:
                return True
            if neighbour not in visited:
                if is_cyclic(neighbour):
                    return True

        recursion_stack.remove(v)
        return False

    for node in graph:
        if node not in visited:
            if is_cyclic(node):
                return True
    return False

# Example usage:
graph = {
