def find_max_length(nums):
    """
    Finds the length of the longest contiguous subarray with an equal number of 0s and 1s.

    :param nums: List[int] - A list of integers consisting of 0s and 1s.
    :return: int - The length of the longest contiguous subarray with an equal number of 0s and 1s.
    """
    count = {0: -1}
    max_length = 0
    current_sum = 0

    for index, num in enumerate(nums):
        if num == 0:
            current_sum -= 1
        else:
            current_sum += 1

        if current_sum in count:
            subarray_length = index - count[current_sum]
            if subarray_length > max_length:
                max_length = subarray_length
        else:
            count[current_sum] = index

    return max_length

