class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False
        self.index = -1

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word, index):
        """Inserts a word into the Trie with its corresponding index."""
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True
        node.index = index

    def search(self, word):
        """Searches for a word in the Trie and returns its index if found, otherwise -1."""
        node = self.root
        for char in word:
            if char in node.children:
                node = node.children[char]
            else:
                return -1
        if node.is_end_of_word:
            return node.index
        return -1

def convert_to_indices(ground_truth, classes):
    """
    Converts the ground_truth list into a list of indices based on the classes list using a Trie.

    :param ground_truth: List of strings representing the ground truth values.
    :param classes: List of unique strings representing the classes.
    :return: List of integers representing the indices of the ground_truth elements in the classes list.
    """
    trie = Trie()

    for idx, cls in enumerate(classes):
        trie.insert(cls, idx)

    return [trie.search(value) for value in ground_truth]
