class TemperatureConverter:
    def __init__(self, celsius=None, fahrenheit=None, kelvin=None):
        self.celsius = celsius
        self.fahrenheit = fahrenheit
        self.kelvin = kelvin

    @classmethod
    def from_celsius(cls, celsius):
        """Creates a TemperatureConverter object initialized with a Celsius temperature."""
        return cls(celsius=celsius)

    @classmethod
    def from_fahrenheit(cls, fahrenheit):
        """Creates a TemperatureConverter object initialized with a Fahrenheit temperature."""
        return cls(fahrenheit=fahrenheit)

    @classmethod
    def from_kelvin(cls, kelvin):
        """Creates a TemperatureConverter object initialized with a Kelvin temperature."""
        return cls(kelvin=kelvin)

    def celsius_to_fahrenheit(self, celsius=None):
        """Converts a temperature from Celsius to Fahrenheit."""
        if celsius is None:
            celsius = self.celsius
        return (celsius * 9/5) + 32

    def celsius_to_kelvin(self, celsius=None):
        """Converts a temperature from Celsius to Kelvin."""
        if celsius is None:
            celsius = self.celsius
        return celsius + 273.15

    def fahrenheit_to_celsius(self, fahrenheit=None):
        """Converts a temperature from Fahrenheit to Celsius."""
        if fahrenheit is None:
            fahrenheit = self.fahrenheit
        return (fahrenheit - 32) * 5/9

    def fahrenheit_to_kelvin(self, fahrenheit=None):
        """Converts a temperature from Fahrenheit to Kelvin."""
        if fahrenheit is None:
            fahrenheit = self.fahrenheit
        return self.fahrenheit_to_celsius(fahrenheit) + 273.15

    def kelvin_to_celsius(self, kelvin=None):
        """Converts a temperature from Kelvin to Celsius."""
        if kelvin is None:
            kelvin = self.kelvin
        return kelvin - 273.15

    def kelvin_to_fahrenheit(self, kelvin=None):
        """Converts a temperature from Kelvin to Fahrenheit."""
        if kelvin is None:
            kelvin = self.kelvin
        return self.celsius_to_fahrenheit(self.kelvin_to_celsius(kelvin))


