class Stream:
    def __init__(self, id, parameters, traces, tag=None):
        self.id = id
        self.parameters = parameters
        self.traces = traces
        self.tag = tag

class Trace:
    def __init__(self, attributes, tag=""):
        self.attributes = attributes
        self.tag = tag

    def __eq__(self, other):
        return self.attributes == other.attributes

    def __hash__(self):
        return hash(tuple(sorted(self.attributes.items())))

    def update_tag(self, tag):
        self.tag = tag

def process_streams(streams):
    """
    Processes a list of Stream objects and returns a dictionary with unique stream IDs as keys
    and combined parameters as values. Each Trace object within a Stream is assigned the Stream's tag.
    Duplicate Trace objects are removed.

    :param streams: List of Stream objects
    :return: Dictionary with stream IDs as keys and combined parameters as values
    """
    from collections import defaultdict

    result = defaultdict(lambda: {'parameters': {}, 'traces': set()})

    for stream in streams:
        result[stream.id]['parameters'].update(stream.parameters)
        tag = getattr(stream, 'tag', "")
        for trace in stream.traces:
            trace.update_tag(tag)
            result[stream.id]['traces'].add(trace)

    final_result = {stream_id: data['parameters'] for stream_id, data in result.items()}
    return final_result
