import json

def calculate_average_grades(json_object):
    """
    Calculate the average grade for each course from a JSON object.

    Parameters:
    json_object (str or dict): A JSON object or a string representation of a JSON object.

    Returns:
    dict: A dictionary with course names as keys and their average scores as values.
    """
    # Load JSON object from string or directly take the dictionary
    if isinstance(json_object, str):
        data = json.loads(json_object)
    else:
        data = json_object

    # Dictionary to hold course average scores
    course_averages = {}

    # Iterate through each course
    for course in data['courses']:
        course_name = course['name']
        assignments = course['assignments']

        # Calculate the sum of scores and the number of assignments
        total_score = sum(assignment['score'] for assignment in assignments)
        num_assignments = len(assignments)

        # Calculate average score for the course
        average_score = total_score / num_assignments

        # Add course and its average score to the dictionary
        course_averages[course_name] = average_score

    return course_averages

