class QueryOptimizer:
    def __init__(self, query=None):
        """
        Initializes the QueryOptimizer with an optional query string.

        :param query: The base query string.
        """
        self.query = query or ""
        self.includes = set()
        self.nested_includes = {}

    def include(self, attribute):
        """
        Adds a top-level attribute to be included in the query.

        :param attribute: The attribute to include.
        :return: The QueryOptimizer instance for method chaining.
        """
        self.includes.add(attribute)
        return self

    def nested_include(self, attribute, nested_attributes):
        """
        Adds nested attributes to a specified attribute.

        :param attribute: The parent attribute.
        :param nested_attributes: A list of nested attributes.
        :return: The QueryOptimizer instance for method chaining.
        """
        if attribute not in self.nested_includes:
            self.nested_includes[attribute] = set()
        self.nested_includes[attribute] |= set(nested_attributes)
        return self

    def optimize(self):
        """
        Generates the optimized query string with included attributes.

        :return: The optimized query string.
        """
        includes_clause = ', '.join(self.includes)
        nested_includes_clause = ', '.join(
            f"{attribute}{{{', '.join(nested_attributes)}}}" 
            for attribute, nested_attributes in self.nested_includes.items()
        )
        if includes_clause and nested_includes_clause:
            return f"{self.query} include: {includes_clause}, {nested_includes_clause}"
        elif includes_clause:
            return f"{self.query} include: {includes_clause}"
        elif nested_includes_clause:
            return f"{self.query} include: {nested_includes_clause}"
        else:
            return self.query

    @classmethod
    def standalone(cls, query, includes=None, nested_includes=None):
        """
        Optimizes the query string using standalone operation.

        :param query: The base query string.
        :param includes: A list of attributes to include.
        :param nested_includes: A dictionary of nested attributes.
        :return: The optimized query string.
        """
        optimizer = cls(query)
        if includes:
            for attribute in includes:
                optimizer.include(attribute)
        if nested_includes:
            for attribute, nested_attributes in nested_includes.items():
                optimizer.nested_include(attribute, nested_attributes)
        return optimizer.optimize()
