def convert_to_json_serializable(data):
    """
    Converts a complex data structure into a JSON-serializable format.
    All string values are converted to lowercase.

    Parameters:
    data (dict, list, str, int, float, bool, None): The input data structure.

    Returns:
    dict, list, str, int, float, bool, None: A JSON-serializable data structure.
    """
    if isinstance(data, str):
        return data.lower()
    elif isinstance(data, dict):
        return {convert_to_json_serializable(k): convert_to_json_serializable(v) for k, v in data.items()}
    elif isinstance(data, list):
        return [convert_to_json_serializable(item) for item in data]
    elif isinstance(data, (int, float, bool, type(None))):
        return data
    else:
        raise ValueError(f"Data type {type(data)} is not JSON serializable")
