def convert_to_base(s, b):
    """
    Convert a string representing a number in any base between 2 and 16 to an integer in base b.

    :param s: String representing the number, may include base prefixes and spaces.
    :param b: The base to convert the number to, must be between 2 and 16.
    :return: The integer value of the number in base b, or -1 if conversion is not possible.
    """
    s = s.strip()
    if b < 2 or b > 16:
        return -1
    if s.startswith('0x') or s.startswith('0X'):
        if b != 16:
            return -1
        base_prefix_length = 2
        base = 16
    elif s.startswith('0o') or s.startswith('0O'):
        if b != 8:
            return -1
        base_prefix_length = 2
        base = 8
    elif s.startswith('0b') or s.startswith('0B'):
        if b != 2:
            return -1
        base_prefix_length = 2
        base = 2
    else:
        base_prefix_length = 0
        base = b

    valid_chars = '0123456789ABCDEFabcdef'
    for char in s[base_prefix_length:]:
        if char not in valid_chars[:base]:
            return -1

    try:
        if base_prefix_length > 0:
            return int(s, base)
        else:
            return int(s, b)
    except ValueError:
        return -1
