def character_count(input_string):
    """
    Takes a string as input and returns a dictionary where the keys are the characters 
    in the string (case-insensitive) and the values are the counts of how many times 
    each character appears in the string, ignoring whitespace.

    :param input_string: A string to count characters from
    :return: A dictionary with characters as keys and their counts as values
    """
    char_count_dict = {}
    input_string = input_string.lower()

    for char in input_string:
        if char.isspace():
            continue
        if char in char_count_dict:
            char_count_dict[char] += 1
        else:
            char_count_dict[char] = 1

    return char_count_dict
