def count_quadrants(coordinates):
    """
    Recursively counts the number of coordinates in each quadrant of the Cartesian plane.

    :param coordinates: List of tuples, where each tuple contains two integers (x, y).
    :return: Tuple of four integers representing the count of coordinates in quadrants I, II, III, and IV.
    """
    def count_rec(index, q1, q2, q3, q4):
        if index == len(coordinates):
            return q1, q2, q3, q4
        x, y = coordinates[index]
        if x > 0 and y > 0:
            return count_rec(index + 1, q1 + 1, q2, q3, q4)
        elif x < 0 and y > 0:
            return count_rec(index + 1, q1, q2 + 1, q3, q4)
        elif x < 0 and y < 0:
            return count_rec(index + 1, q1, q2, q3 + 1, q4)
        elif x > 0 and y < 0:
            return count_rec(index + 1, q1, q2, q3, q4 + 1)
        else:
            return count_rec(index + 1, q1, q2, q3, q4)

    return count_rec(0, 0, 0, 0, 0)
