def is_valid_ipv4_address(s):
    """
    Determines if the given string s is a valid IPv4 address.

    :param s: A string representing the potential IPv4 address.
    :return: True if s is a valid IPv4 address, otherwise False.
    """
    parts = s.split('.')

    if len(parts) != 4:
        return False

    for part in parts:
        if not part.isdigit():
            return False
        if not 0 <= int(part) <= 255:
            return False
        if part != str(int(part)):
            return False

    return True
