def count_prime_numbers(limit):
    """
    Counts the number of prime numbers up to a given limit (inclusive) using the Sieve of Eratosthenes algorithm.

    Parameters:
    limit (int): The upper limit up to which prime numbers are counted.

    Returns:
    int: The count of prime numbers up to and including the limit.
    """
    if limit < 2:
        return 0

    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False

    for num in range(2, int(limit**0.5) + 1):
        if is_prime[num]:
            for multiple in range(num * num, limit + 1, num):
                is_prime[multiple] = False

    return sum(is_prime)
```

