    Returns a list of exercise IDs that the user with the given user_id has completed,
    considering only the sequences of consecutive completions.

    :param user_id: Integer representing the user's ID.
    :param user_exercise_list: List of UserExercise objects.
    :return: List of integers representing the exercise IDs completed by the user.
    """
    completed_exercises = [ue for ue in user_exercise_list if ue.user_id == user_id and ue.completion_status]
    completed_exercises.sort(key=lambda ue: ue.exercise_id)

    exercise_counts = {}
    current_exercise = None
    current_streak = 0

    for exercise in completed_exercises:
        if exercise.exercise_id == current_exercise:
            current_streak += 1
        else:
            if current_exercise is not None:
                if current_exercise not in exercise_counts or exercise_counts[current_exercise] < current_streak:
                    exercise_counts[current_exercise] = current_streak
            current_exercise = exercise.exercise_id
            current_streak = 1

    if current_exercise is not None:
        if current_exercise not in exercise_counts or exercise_counts[current_exercise] < current_streak:
            exercise_counts[current_exercise] = current_streak

    return [exercise_id for exercise_id, _ in sorted(exercise_counts.items())]
