def find_longest_common_prefix(strings_list):
    """
    Finds the longest common prefix among all strings in the given list.

    :param strings_list: List of strings to evaluate.
    :return: The longest common prefix as a string, or an empty string if no common prefix exists.
    """
    if not strings_list:
        return ""

    shortest_str = min(strings_list, key=len)

    for i, char in enumerate(shortest_str):
        for other in strings_list:
            if other[i] != char:
                return shortest_str[:i]

    return shortest_str
