import json

def json_to_nested_dict(json_string):
    """
    Converts a JSON string into a nested dictionary with keys representing unique paths to leaf nodes.

    :param json_string: A string representing a valid JSON structure.
    :return: A dictionary with paths as keys and corresponding values from the JSON structure.
    """
    def parse_json(obj, path="", result={}):
        if isinstance(obj, dict):
            for k, v in obj.items():
                parse_json(v, f"{path}.{k}" if path else k, result)
        elif isinstance(obj, list):
            for i, item in enumerate(obj):
                parse_json(item, f"{path}[{i}]", result)
        else:
            result[path] = obj
        return result

    data = json.loads(json_string)
    return parse_json(data)
