def convert_to_imperial(value, unit):
    """
    Convert a given value in a metric unit of measurement to its Imperial equivalent.

    Parameters:
    - value: The numeric value to convert.
    - unit: The string representation of the unit to convert from.

    Returns:
    - A float representing the converted value, or an error message string if input is invalid.
    """
    try:
        # Conversion factors
        cm_to_in = 0.393701
        m_to_ft = 3.28084
        kg_to_lb = 2.20462
        c_to_f = lambda c: (c * 9/5) + 32

        if not isinstance(value, (int, float)):
            raise ValueError('Value must be a number.')

        if not isinstance(unit, str):
            raise ValueError('Unit must be a string.')

        unit = unit.lower()
        if unit == 'centimeters':
            return value * cm_to_in
        elif unit == 'meters':
            return value * m_to_ft
        elif unit == 'kilograms':
            return value * kg_to_lb
        elif unit == 'celsius':
            return c_to_f(value)
        else:
            return f'Conversion for the unit "{unit}" is not supported.'
    except Exception as e:
        return str(e)
