def find_closest_pair(numbers, k):
    """
    Finds and returns a pair of integers (a, b) from the list `numbers` such that
    the absolute difference between a and b is equal to k. If multiple pairs exist,
    returns any one of them. If no such pair exists, returns None.

    :param numbers: List of integers
    :param k: Integer representing the target difference
    :return: Tuple of two integers or None
    """
    numbers_set = set(numbers)

    for number in numbers:
        candidate1 = number + k
        candidate2 = number - k

        if candidate1 in numbers_set:
            return (number, candidate1)

        if candidate2 in numbers_set:
            return (number, candidate2)

