class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Insert a new node with the given key in the BST."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert_rec(self.root, key)

    def _insert_rec(self, node, key):
        """Helper method to insert recursively."""
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert_rec(node.left, key)
        elif key > node.val:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert_rec(node.right, key)

    def delete(self, key):
        """Delete a node with the given key from the BST."""
        self.root = self._delete_rec(self.root, key)

    def _delete_rec(self, node, key):
        """Helper method to delete recursively."""
        if node is None:
            return node

        if key < node.val:
            node.left = self._delete_rec(node.left, key)
        elif key > node.val:
            node.right = self._delete_rec(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            node.val = self.min_value_node(node.right).val
            node.right = self._delete_rec(node.right, node.val)

        return node

    def search(self, key):
        """Search for a node with the given key in the BST."""
        return self._search_rec(self.root, key)

    def _search_rec(self, node, key):
        """Helper method to search recursively."""
        if node is None or node.val == key:
            return node is not None
        if key < node.val:
            return self._search_rec(node.left, key)
        else:
            return self._search_rec(node.right, key)

    def in_order_traversal(self):
        """Return the in-order traversal of the tree."""
        return self._in_order_rec(self.root)

    def _in_order_rec(self, node):
        """Helper method to do in-order traversal recursively."""
        res = []
        if node:
            res = self._in_order_rec(node.left)
            res.append(node.val)
            res = res + self._in_order_rec(node.right)
        return res

    def pre_order_traversal(self):
        """Return the pre-order traversal of the tree."""
        return self._pre_order_rec(self.root)

    def _pre_order_rec(self, node):
        """Helper method to do pre-order traversal recursively."""
        res = []
        if node:
            res.append(node.val)
            res = res + self._pre_order_rec(node.left)
            res = res + self._pre_order_rec(node.right)
        return res

    def post_order_traversal(self):
        """Return the post-order traversal of the tree."""
        return self._post_order_rec(self.root)

    def _post_order_rec(self, node):
        """Helper method to do post-order traversal recursively."""
        res = []
        if node:
            res = self._post_order_rec(node.left)
            res = res + self._post_order_rec(node.right)
            res.append(node.val)
        return res

    def min_value_node(self, node):
        """Find the node with the minimum value in the BST."""
        current = node
        while current.left is not None:
            current = current.left
        return current

    def node_count(self):
        """Count the number of nodes in the BST."""
        return self._node_count_rec(self.root)

    def _node_count_rec(self, node):
        """Helper method to count nodes recursively."""
        if node is None:
            return 0
        else:
            return 1 + self._node_count_rec(node.left) + self._node_count_rec(node.right)

    def is_balanced(self):
        """Check if the BST is balanced."""
        return self._check_balance(self.root)[0]

    def _check_balance(self, node):
        """Helper method to check balance recursively, also return height."""
        if node is None:
            return True, 0

        left_balanced, left_height = self._check_balance(node.left)
        right_balanced, right_height = self._check_balance(node.right)

        balanced = (left_balanced and right_balanced and abs(left_height - right_height) <= 1)
        height = 1 + max(left_height, right_height)
        return balanced, height
