def check_alternating_sorted(init_list):
    """
    Determines if a list of integers is sorted in an alternating pattern.

    Parameters:
    init_list (list): A list of integers.

    Returns:
    bool: True if the list is sorted in an alternating pattern, False otherwise.
    """
    # Base cases for recursion
    if len(init_list) <= 2:
        return True

    # Helper function to check the alternating pattern
    def alternating_pattern(i, is_ascending):
        if i == len(init_list) - 1:
            return True
        if is_ascending:
            if init_list[i] < init_list[i + 1]:
                return alternating_pattern(i + 1, False)
            else:
                return False
        else:
            if init_list[i] > init_list[i + 1]:
                return alternating_pattern(i + 1, True)
            else:
                return False

    # Start checking from the first element, assuming the pattern starts with ascending
    return alternating_pattern(0, True) or alternating_pattern(0, False)
