from datetime import datetime, date

def validate_date(date_string: str, default_date: date) -> date:
    """
    Parses a date string and returns a date object based on the format.
    If parsing fails, returns the default date.

    :param date_string: A string representing a date.
    :param default_date: A date object to be returned if parsing fails.
    :return: A date object representing the parsed date or the default date.
    """
    formats = ["%m/%d/%Y", "%d-%m-%Y", "%Y.%m.%d"]
    separators = ["/", "-", "."]

    for sep, fmt in zip(separators, formats):
        if sep in date_string:
            try:
                return datetime.strptime(date_string, fmt).date()
            except ValueError:
                continue
    return default_date
