def process_arguments(*args, **kwargs):
    """
    Processes a variable number of positional and keyword arguments according to specific rules.

    Positional arguments are converted to strings with trailing spaces removed.
    Keyword arguments are converted to "key=value" strings, with underscores removed from keys.
    If a keyword argument's value is a list, each element is appended as a separate "key=value" string.

    :param args: Variable number of positional arguments.
    :param kwargs: Variable number of keyword arguments.
    :return: List of processed strings.
    """
    result = []

    for arg in args:
        if isinstance(arg, str):
            arg = arg.rstrip()
        result.append(str(arg))

    for key, value in kwargs.items():
        if key.endswith('_'):
            key = key[:-1]

        if isinstance(value, list):
            for item in value:
                result.append(f"{key}={item}")
        else:
            result.append(f"{key}={value}")

    return result
