class Line:
    def __init__(self, slope, y_intercept):
        self.slope = slope
        self.y_intercept = y_intercept

def find_intersection(line1, line2):
    """
    Returns the intersection point of two lines as a tuple (x, y).
    If the lines are parallel or coincident, returns None.

    :param line1: First Line object
    :param line2: Second Line object
    :return: Tuple (x, y) of intersection point or None
    """
    # Check if both lines are vertical
    if line1.slope == float('inf') and line2.slope == float('inf'):
        if line1.y_intercept == line2.y_intercept:
            return (line1.y_intercept, None)  # Coincident vertical lines
        else:
            return None  # Parallel vertical lines

    # Check if the first line is vertical
    if line1.slope == float('inf'):
        x = line1.y_intercept
        y = line2.slope * x + line2.y_intercept
        return (x, y)

    # Check if the second line is vertical
    if line2.slope == float('inf'):
        x = line2.y_intercept
        y = line1.slope * x + line1.y_intercept
        return (x, y)

    # Check if lines are parallel or coincident
    if line1.slope == line2.slope:
        if line1.y_intercept == line2.y_intercept:
            return (None, None)  # Coincident lines
        else:
            return None  # Parallel lines

    # Calculate intersection point
    x = (line2.y_intercept - line1.y_intercept) / (line1.slope - line2.slope)
    y = line1.slope * x + line1.y_intercept
    return (x, y)
