def compare_route_components(list_1, list_2):
    """
    Compares two lists of route components lexicographically, considering strings with numerical suffixes
    as greater than purely alphabetical strings.

    :param list_1: List of strings representing the first route components.
    :param list_2: List of strings representing the second route components.
