def evaluate_postfix(expression):
    """
    Evaluates a given postfix expression using a stack.

    :param expression: A string representing the postfix expression.
    :return: A float representing the result of the postfix expression evaluation.
    """
    stack = []
    operators = set(['+', '-', '*', '/'])

    for token in expression.split():
        if token in operators:
            right = stack.pop()
            left = stack.pop()
            if token == '+':
                result = left + right
            elif token == '-':
                result = left - right
            elif token == '*':
                result = left * right
            elif token == '/':
                result = left / right
            stack.append(result)
        else:
            stack.append(float(token))

    return stack.pop()

