def find_range_and_median(lst: list) -> tuple:
    """
    Flattens a nested list of integers and returns a tuple containing the range
    and median of the flattened list. The range is the difference between the
    maximum and minimum values, and the median is the middle value when sorted.
    If the list is empty, returns (0, None).
    """
    def flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    flat_list = list(flatten(lst))
    flat_list.sort()

    if not flat_list:
        return (0, None)

    range_value = max(flat_list) - min(flat_list)

    n = len(flat_list)
    if n % 2 == 1:
        median = flat_list[n // 2]
    else:
        median = (flat_list[n // 2 - 1] + flat_list[n // 2]) / 2

    return (range_value, median)
