class BinaryTree:
    def __init__(self, value, left=None, right=None):
        """
        Initializes a tree node with the given value and optional left and right children.

        :param value: The value of the node.
        :param left: The left child of the node (default is None).
        :param right: The right child of the node (default is None).
        """
        self.value = value
        self.left = left
        self.right = right

    def insert(self, value):
        """
        Inserts a new value into the BST.

        :param value: The value to be inserted.
        """
        if value < self.value:
            if self.left is not None:
                self.left.insert(value)
            else:
                self.left = BinaryTree(value)
        else:
            if self.right is not None:
                self.right.insert(value)
            else:
                self.right = BinaryTree(value)

    def find(self, value):
        """
        Returns True if the value exists in the BST, False otherwise.

        :param value: The value to be searched.
        :return: Boolean indicating if the value is found.
        """
        if value == self.value:
            return True
        elif value < self.value and self.left is not None:
            return self.left.find(value)
        elif value > self.value and self.right is not None:
            return self.right.find(value)
        return False

    def get_max(self):
        """
        Returns the maximum value in the BST.

        :return: The maximum value in the BST.
        """
        if self.right is not None:
            return self.right.get_max()
        return self.value

    def get_min(self):
        """
        Returns the minimum value in the BST.

        :return: The minimum value in the BST.
        """
        if self.left is not None:
            return self.left.get_min()
        return self.value
