def bst_lca(root, p, q):
    """
    Finds the lowest common ancestor (LCA) of two given nodes p and q in a binary search tree (BST).

    :param root: TreeNode, the root of the BST
    :param p: TreeNode, one of the nodes for which to find the LCA
    :param q: TreeNode, the other node for which to find the LCA
    :return: TreeNode, the LCA of nodes p and q
    """
    current = root
    while current:
        if p.val < current.val and q.val < current.val:
            current = current.left
        elif p.val > current.val and q.val > current.val:
            current = current.right
        else:
            return current
