class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        """Inserts a new node with the given value into the tree."""
        new_node = TreeNode(value)
        if self.root is None:
            self.root = new_node
        else:
            self._insert(self.root, new_node)

    def _insert(self, node, new_node):
        if new_node.value < node.value:
            if node.left is None:
                node.left = new_node
            else:
                self._insert(node.left, new_node)
        else:
            if node.right is None:
                node.right = new_node
            else:
                self._insert(node.right, new_node)

    def delete(self, value):
        """Deletes the node with the given value from the tree."""
        self.root = self._delete(self.root, value)

    def _delete(self, node, value):
        if node is None:
            return node

        if value < node.value:
            node.left = self._delete(node.left, value)
        elif value > node.value:
            node.right = self._delete(node.right, value)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            node.value = self._min_value_node(node.right).value
            node.right = self._delete(node.right, node.value)

        return node

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current

    def find(self, value):
        """Returns True if a node with the given value exists in the tree, otherwise returns False."""
        return self._find(self.root, value)

    def _find(self, node, value):
        if node is None:
            return False
        if value == node.value:
            return True
        if value < node.value:
            return self._find(node.left, value)
        return self._find(node.right, value)

    def inorder_traversal(self):
        """Returns a list of values in the tree in sorted order."""
        return self._inorder_traversal(self.root)

    def _inorder_traversal(self, node):
        res = []
        if node:
            res = self._inorder_traversal(node.left)
            res.append(node.value)
            res = res + self._inorder_traversal(node.right)
        return res
