def find_prime_sum(n):
    """
    Calculate the sum of the first n prime numbers.

    Parameters:
    n (int): The number of prime numbers to sum.

    Returns:
    int or None: The sum of the first n prime numbers, or None if n <= 0.
    """
    def is_prime(num, divisor=None):
        """
        Check if a number is prime using recursion.

        Parameters:
        num (int): The number to check.
        divisor (int, optional): The current divisor to check against num.

        Returns:
        bool: True if num is prime, False otherwise.
        """
        if num <= 1:
            return False
        if divisor is None:
            divisor = num - 1
        if divisor == 1:
            return True
        if num % divisor == 0:
            return False
        return is_prime(num, divisor - 1)

    def sum_of_primes(count, current_number, prime_sum, prime_count):
        """
        Recursively find the sum of the first n prime numbers.

        Parameters:
        count (int): The number of primes left to find.
        current_number (int): The current number to check for primality.
        prime_sum (int): The current sum of found prime numbers.
        prime_count (int): The count of found prime numbers.

        Returns:
        int: The sum of the first n prime numbers.
        """
        if count <= 0:
            return prime_sum
        if is_prime(current_number):
            return sum_of_primes(count - 1, current_number + 1, prime_sum + current_number, prime_count + 1)
        else:
            return sum_of_primes(count, current_number + 1, prime_sum, prime_count)

    if n <= 0:
        return None

    return sum_of_primes(n, 2, 0, 0)
