import threading

def memoized_property(method):
    """
    A decorator to create a memoized property.

    This decorator wraps a method in a class to a property that caches the result.
    If a new value is needed, the method is called. The cached result avoids recomputation.
    """
    attribute_name = f"_{method.__name__}_memoized_property"

    def getter(self):
        """
        Getter method for the memoized property.

        Ensures thread safety and caches the result of the method call.
        """
        with self._lock:
            if not hasattr(self, attribute_name):
                setattr(self, attribute_name, method(self))
            return getattr(self, attribute_name)

    return property(getter)


class FactorialCalculator:
    def __init__(self, number):
        """
        Initializes the FactorialCalculator with a number and a lock for thread safety.
        """
        self.number = number
        self._lock = threading.Lock()

    @memoized_property
    def factorial(self):
        """Memoized property for calculating factorial of a number."""
        return self._calculate_factorial(self.number)

    def _calculate_factorial(self, num):
        """
        Helper method to calculate the factorial of a number.

        Raises ValueError if the number is negative.
        """
        if num < 0:
            raise ValueError("Factorial is not defined for negative numbers")
        if num == 0 or num == 1:
            return 1
        result = 1
        for i in range(2, num + 1):
            result *= i
        return result
