def find_primes_in_range(start, end):
    """
    Identifies all prime numbers within a specified range [start, end].

    Parameters:
    start (int): The beginning of the range.
    end (int): The end of the range.

    Returns:
    list: A list of prime numbers within the specified range, inclusive of the endpoints if they are prime.
    """
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = []
    for num in range(start, end + 1):
        if is_prime(num):
            primes.append(num)
    return primes
