    def remove_book(self, isbn):
        """Remove a book from the library if it exists and is not borrowed."""
        if isbn not in self.books:
            print(f"No book found with ISBN {isbn}.")
        elif self.books[isbn]['borrowed']:
            print(f"Book with ISBN {isbn} is currently borrowed and cannot be removed.")
        else:
            del self.books[isbn]
            print(f"Book with ISBN {isbn} has been removed.")

    def borrow_book(self, isbn):
        """Allow a user to borrow a book if it is available."""
        if isbn not in self.books:
            print(f"No book found with ISBN {isbn}.")
        elif self.books[isbn]['borrowed']:
            print(f"Book with ISBN {isbn} is already borrowed.")
        else:
            self.books[isbn]['borrowed'] = True
            print(f"Book '{self.books[isbn]['title']}' by {self.books[isbn]['author']} has been borrowed.")

    def return_book(self, isbn):
        """Allow a user to return a borrowed book."""
        if isbn not in self.books:
            print(f"No book found with ISBN {isbn}.")
        elif not self.books[isbn]['borrowed']:
            print(f"Book with ISBN {isbn} is not currently borrowed.")
        else:
            self.books[isbn]['borrowed'] = False
            print(f"Book '{self.books[isbn]['title']}' by {self.books[isbn]['author']} has been returned.")
