def calculate_expression(num1, num2, op):
    """
    Perform a mathematical operation on two numbers based on the given operation code.

    Parameters:
    num1 (int): The first number.
    num2 (int): The second number.
    op (int): The operation code (0 for addition, 1 for subtraction, 2 for multiplication, 3 for division).

    Returns:
    float or None: The result of the operation rounded to two decimal places, or None if the operation is invalid or division by zero occurs.
    """
    try:
        if op == 0:
            result = num1 + num2
        elif op == 1:
            result = num1 - num2
        elif op == 2:
            result = num1 * num2
        elif op == 3:
            if num2 == 0:
                return None
            result = num1 / num2
        else:
            return None
        return round(result, 2)
    except Exception as e:
        print(f"An error occurred: {e}")
        return None
