def find_most_common_candies(candies):
    """
    Finds the most common number(s) of candies among the children.

    :param candies: List of integers representing the number of candies each child has.
    :return: List of integers representing the most common number(s) of candies in ascending order.
    """
    frequency = {}

    for candy in candies:
        if candy in frequency:
            frequency[candy] += 1
        else:
            frequency[candy] = 1

    max_freq = 0
    for count in frequency.values():
        if count > max_freq:
            max_freq = count

    most_common = []
    for candy, count in frequency.items():
        if count == max_freq:
            most_common.append(candy)

    return sorted(most_common)
