def longest_increasing_subsequence(nums):
    """
    Returns the length of the longest increasing subsequence in the list.

    :param nums: List[int] - A list of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    tails = []

    for num in nums:
        index = bisect.bisect_left(tails, num)
        if index == len(tails):
            tails.append(num)
        else:
            tails[index] = num

    return len(tails)
