def find_first_missing_positive(nums):
    """
    Finds the smallest missing positive integer in the given list of integers.

    :param nums: List[int] - The input list of integers.
    :return: int - The smallest missing positive integer.
    """
    n = len(nums)

    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = n + 1

    for i in range(n):
        num = abs(nums[i])
        if num <= n:
            index = num - 1
            if nums[index] > 0:
                nums[index] = -nums[index]

    for i in range(n):
        if nums[i] > 0:
            return i + 1

    return n + 1

