def find_longest_subsequence(arr):
    """
    Finds the length of the longest increasing subsequence in the given list of integers.

    :param arr: List of integers
    :return: Length of the longest increasing subsequence
    """
    def binary_search(sub, target):
        low, high = 0, len(sub) - 1
        while low <= high:
            mid = (low + high) // 2
            if sub[mid] < target:
                low = mid + 1
            else:
                high = mid - 1
        return low

    if not arr:
        return 0

    sub = []
    for num in arr:
        pos = binary_search(sub, num)
        if pos == len(sub):
            sub.append(num)
        else:
            sub[pos] = num

    return len(sub)
