def is_connected(graph):
    """
    Determines if the given graph is connected.

    :param graph: List[List[int]], an adjacency matrix representing the graph.
    :return: bool, True if the graph is connected, False otherwise.
    """
    n = len(graph)
    visited = [False] * n

    def dfs(node):
        stack = [node]
        while stack:
            current = stack.pop()
            if not visited[current]:
                visited[current] = True
                for neighbor in range(n):
                    if graph[current][neighbor] == 1 and not visited[neighbor]:
                        stack.append(neighbor)

    if n > 0:
        dfs(0)

    return all(visited)
