class BinaryTreeNode:
    def __init__(self, value):
        """
        Initializes a new node with the given value and no children.
        """
        self.value = value
        self.left = None
        self.right = None

    def insert(self, value):
        """
        Inserts a new value into the BST.
        """
        if value < self.value:
            if self.left is None:
                self.left = BinaryTreeNode(value)
            else:
                self.left.insert(value)
        elif value > self.value:
            if self.right is None:
                self.right = BinaryTreeNode(value)
            else:
                self.right.insert(value)

    def search(self, value):
        """
        Searches for a value in the BST.
        Returns True if the value is found, False otherwise.
        """
        if value < self.value:
            if self.left is None:
                return False
            else:
                return self.left.search(value)
        elif value > self.value:
            if self.right is None:
                return False
            else:
                return self.right.search(value)
        else:
            return True

    def delete(self, value):
        """
        Deletes a value from the BST.
        Handles all three cases: leaf node, node with one child, and node with two children.
        """
        if value < self.value:
            if self.left is not None:
                self.left = self.left.delete(value)
        elif value > self.value:
            if self.right is not None:
                self.right = self.right.delete(value)
        else:
            if self.left is None:
                return self.right
            elif self.right is None:
                return self.left

            min_larger_node = self.right
            while min_larger_node.left is not None:
                min_larger_node = min_larger_node.left

            self.value = min_larger_node.value
            self.right = self.right.delete(min_larger_node.value)

        return self

    def inorder_traversal(self):
        """
        Returns a list of values in the BST in in-order traversal order.
        """
        elements = []
        if self.left:
            elements += self.left.inorder_traversal()

        elements.append(self.value)

        if self.right:
            elements += self.right.inorder_traversal()

        return elements
