def flatten_dict(d, parent_key=()):
    """
    Flattens a dictionary of nested dictionaries into a single-level dictionary.

    Parameters:
    d (dict): The dictionary to flatten.
    parent_key (tuple): A tuple representing the current key path (used for recursion).

    Returns:
    dict: A new dictionary with keys as tuples of the original keys and values as the corresponding values.
    """
    items = []
    for k, v in d.items():
        new_key = parent_key + (k,)
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key).items())
        else:
            items.append((new_key, v))
    return dict(items)

