def create_ranges(input_list):
    """
    Converts a list of strings representing ranges or single integers into a list of zero-indexed ranges.

    :param input_list: List of strings, where each string is either a single integer or a range in the format 'X-Y'.
    :return: List of lists, where each inner list contains two integers representing the start and end of a range.
    """
    def parse_range(s):
        try:
            parts = s.split('-')
            if len(parts) == 1:
                num = int(parts[0])
                return [num - 1, num - 1]
            elif len(parts) == 2:
                start = int(parts[0])
                end = int(parts[1])
                if start <= end:
                    return [start - 1, end - 1]
        except ValueError:
            pass
        return None

    return [rng for rng in (parse_range(s) for s in input_list) if rng is not None]
