def convert_data_types(data, keys_to_convert):
    def parse_integer(value):
        """
        Convert a string to an integer without using built-in functions.
        """
        if value.lstrip('-').isdigit():
            result = 0
            negative = value.startswith('-')
            for char in value.lstrip('-'):
                result = result * 10 + ord(char) - ord('0')
            return -result if negative else result
        return value

    def parse_float(value):
        """
        Convert a string to a float without using built-in functions.
        """
        if '.' in value and value.replace('.', '', 1).lstrip('-').isdigit():
            integer_part, decimal_part = value.split('.')
            negative = value.startswith('-')
            integer_part = integer_part.lstrip('-')
            integer_value = 0
            decimal_value = 0
            power = 1

            for char in integer_part:
                integer_value = integer_value * 10 + ord(char) - ord('0')

            for char in decimal_part:
                decimal_value = decimal_value * 10 + ord(char) - ord('0')
                power *= 10

            return -float(integer_value + decimal_value / power) if negative else float(integer_value + decimal_value / power)
        return value

    def parse_boolean(value):
        """
        Convert a string to a boolean without using built-in functions.
        """
        if value.lower() == 'true':
            return True
        elif value.lower() == 'false':
            return False
        return value

    for key in keys_to_convert:
        if key in data:
            value = data[key]
            parsed_value = parse_boolean(value)
            if isinstance(parsed_value, bool):
                data[key] = parsed_value

            parsed_value = parse_integer(value)
            if isinstance(parsed_value, int):
                data[key] = parsed_value

            parsed_value = parse_float(value)
            if isinstance(parsed_value, float):
                data[key] = parsed_value

    return data
