def generate_command_list(invoke_step, prereqs):
    """
    Generates a list of commands to be executed in either a container or host environment.

    Parameters:
    - invoke_step: A dictionary specifying the commands for the container or host environment.
    - prereqs: An object containing additional information such as environment variables and working directories.

    Returns:
    - A tuple containing the environment ('container' or 'host') and the list of commands.
    """
    envs = {env.split('=')[0]: env.split('=')[1] for env in prereqs.get('envs', [])}
    layer_workdir = prereqs.get('layer_workdir')
    host_path = prereqs.get('host_path')

    commands = []

    if 'container' in invoke_step:
        if layer_workdir:
            commands.append(f"cd {layer_workdir}")
        if envs:
            for var, value in envs.items():
                commands.append(f"export {var}={value}")
        for command in invoke_step['container']:
            for var in envs:
                env_placeholder = f"{{{{{var}}}}}"
                if env_placeholder in command:
                    command = command.replace(env_placeholder, envs[var])
            commands.append(command)
        return 'container', commands

    elif 'host' in invoke_step:
        if host_path:
            commands.append(f"cd {host_path}")
        for command in invoke_step['host']:
            for var in envs:
                env_placeholder = f"{{{{{var}}}}}"
                if env_placeholder in command:
                    command = command.replace(env_placeholder, envs[var])
            commands.append(command)
        return 'host', commands

    return '', []
