def validate_parentheses(s):
    """
    Determines if the given string of parentheses is valid.

    Args:
    s (str): A string consisting of '(', ')', '{', '}', '[' and ']'.

    Returns:
    bool: True if the sequence is valid, False otherwise.
    """
    stack = []
    matching_parentheses = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or stack[-1] != matching_parentheses[char]:
                return False
            stack.pop()

    return not stack
