def validate_ip(ip_address):
    """
    Validates if the given string is a valid IPv4 address.

    :param ip_address: A string representing the IP address to validate.
    :return: True if the IP address is valid, False otherwise.
    """
    parts = ip_address.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        num = int(part)
        if num < 0 or num > 255:
            return False
        if part != str(num):
            return False
    return True
