def format_sequence(sequence):
    """
    Recursively formats each element in the given sequence according to specified rules:
    - Integers remain unchanged.
    - Floats are formatted to two decimal places.
    - Strings have leading and trailing whitespace removed.
    - Lists and tuples are processed recursively.

    :param sequence: An iterable containing integers, floats, strings, lists, and tuples.
    :return: A new sequence with formatted elements.
    """
    formatted_sequence = []

    for element in sequence:
        if isinstance(element, int):
            formatted_sequence.append(element)
        elif isinstance(element, float):
            formatted_sequence.append(f"{element:.2f}")
        elif isinstance(element, str):
            formatted_sequence.append(element.strip())
        elif isinstance(element, (list, tuple)):
            formatted_sequence.append(format_sequence(element))
        else:
            formatted_sequence.append(element)

    return type(sequence)(formatted_sequence)
