def get_data_shapes(input_shape, output_shape, num_classes, batch_size=None):
    """
    Processes the input and output shapes and returns them in a standardized format.

    Parameters:
    - input_shape: A tuple, list, or dictionary representing the shape of the input data.
    - output_shape: A tuple or list representing the shape of the output data.
    - num_classes: An integer representing the number of classes for the output data.
    - batch_size: An optional integer representing the batch size.

    Returns:
    - A tuple containing the processed input_shape, output_shape (with batch size prepended), and num_classes.
    """
    def parse_input_shape(shape):
        if isinstance(shape, (tuple, list)):
            return shape
        elif isinstance(shape, dict):
            return {k: parse_input_shape(v) for k, v in shape.items()}
        else:
            raise ValueError("Invalid input shape format. Expected tuple, list, or dictionary.")

    if batch_size is None:
        if isinstance(input_shape, (tuple, list)):
            batch_size = input_shape[0]
        elif isinstance(input_shape, dict):
            batch_size = next(iter(input_shape.values()))[0]
        else:
            raise ValueError("Cannot determine batch size from input shape.")

    input_shape = parse_input_shape(input_shape)

    if isinstance(output_shape, (tuple, list)):
        output_shape = (batch_size, *output_shape)
    else:
        raise ValueError("Invalid output shape format. Expected tuple or list.")

    return input_shape, output_shape, num_classes
