def deepFilter(json_obj, keys_to_remove):
    """
    Recursively filters out items from a deserialized JSON object based on a list of keys.

    :param json_obj: The deserialized JSON object to filter.
    :param keys_to_remove: A list of keys to be removed from the JSON object.
    :return: A new JSON object with the specified keys removed.
    """
    if isinstance(json_obj, dict):
        return {k: deepFilter(v, keys_to_remove) for k, v in json_obj.items() if k not in keys_to_remove}
    elif isinstance(json_obj, list):
        return [deepFilter(item, keys_to_remove) for item in json_obj]
    else:
        return json_obj

