def remove_duplicates(sequence):
    """
    Removes duplicate elements from the input sequence while preserving the order of first occurrence.

    Parameters:
    sequence (list, tuple, or str): The input sequence from which duplicates are to be removed.

    Returns:
    list, tuple, or str: A new sequence of the same type as the input with duplicates removed.
    """
    seen = set()
    result = []
    for item in sequence:
        if item not in seen:
            seen.add(item)
            result.append(item)

    if isinstance(sequence, tuple):
        return tuple(result)
    elif isinstance(sequence, str):
        return ''.join(result)
    else:
        return result
