def decode_installer_log(log):
    """
    Parses a log message and returns a dictionary representing the parsed data.

    :param log: A string representing the log message.
    :return: A dictionary with parsed key-value pairs.
    """
    if not log:
        return {}

    result = {}

    for pair in log.split(';'):
        if '=' not in pair:
            return {}

        key, value = pair.split('=', 1)
        keys = key.split(':')

        d = result
        for k in keys[:-1]:
            if k not in d or not isinstance(d[k], dict):
                d[k] = {}
            d = d[k]

        d[keys[-1]] = value

    return result

