def flatten_dict(nested_dict, parent_key='', sep='_', seen=None):
    """
    Flattens a nested dictionary into a flat dictionary.

    Parameters:
    nested_dict (dict or list): The nested dictionary or list to flatten.
    parent_key (str): The base key string for recursion.
    sep (str): The separator to use between keys.
    seen (set): A set of object IDs to track seen objects and avoid circular references.

    Returns:
    dict: A flat dictionary with concatenated keys.
    """
    if seen is None:
        seen = set()

    obj_id = id(nested_dict)
    if obj_id in seen:
        return {}
    seen.add(obj_id)

    flattened = {}
    if isinstance(nested_dict, dict):
        for key, value in nested_dict.items():
            new_key = f"{parent_key}{sep}{key}" if parent_key else key
            if isinstance(value, dict):
                flattened.update(flatten_dict(value, new_key, sep, seen))
            elif isinstance(value, list):
                for index, item in enumerate(value):
                    item_key = f"{new_key}{sep}{index}"
                    if isinstance(item, (dict, list)):
                        flattened.update(flatten_dict(item, item_key, sep, seen))
                    else:
                        flattened[item_key] = item
            else:
                flattened[new_key] = value
    elif isinstance(nested_dict, list):
        for index, item in enumerate(nested_dict):
            item_key = f"{parent_key}{sep}{index}"
            if isinstance(item, (dict, list)):
                flattened.update(flatten_dict(item, item_key, sep, seen))
            else:
                flattened[item_key] = item
    return flattened

# Example usage:
print(flatten_dict({'a': 1, 'b': {'c': 2, 'd': [3, 4]}}))
print(flatten_dict({'x': [{'y': 5, 'z': 6}, {'y': 7, 'z': 8}]}))
```

