def validate_brackets(s):
    """
    Determines if the brackets in the string are balanced.

    :param s: A string containing characters including parentheses, square brackets, and curly braces.
    :return: True if the brackets are balanced, False otherwise.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if not stack or bracket_map[char] != stack.pop():
                return False

    return not stack
