def flatten_object(obj, parent_key='', sep='.'):
    """
    Recursively flattens a nested dictionary into a single-level dictionary 
    with keys in dot notation.

    :param obj: The dictionary to be flattened.
    :param parent_key: The base key string used in recursion.
    :param sep: The separator between keys.
    :return: A flattened dictionary with dot notation keys.
    """
    items = []
    for k, v in obj.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_object(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

