def longest_palindromic_substring(s: str) -> str:
    """
    Finds the longest palindromic substring in the given string `s` using recursion and memoization.

    :param s: The input string.
    :return: The longest palindromic substring.
    """
    def is_palindrome(l: int, r: int) -> bool:
        """
        Checks if the substring s[l:r+1] is a palindrome using memoization.

        :param l: The left index of the substring.
        :param r: The right index of the substring.
        :return: True if the substring is a palindrome, False otherwise.
        """
        if l >= r:
            return True
        if (l, r) not in memo:
            memo[(l, r)] = (s[l] == s[r]) and is_palindrome(l + 1, r - 1)
        return memo[(l, r)]

    def longest_palindrome(l: int, r: int) -> (int, int):
        """
        Recursively finds the longest palindromic substring within the range [l, r] using memoization.

        :param l: The left index of the current range.
        :param r: The right index of the current range.
        :return: A tuple (start, end) representing the indices of the longest palindromic substring.
        """
        if l > r:
            return (0, 0)
        if (l, r) not in palindrome_memo:
            if is_palindrome(l, r):
                palindrome_memo[(l, r)] = (l, r)
            else:
                left = longest_palindrome(l, r - 1)
                right = longest_palindrome(l + 1, r)
                if right[1] - right[0] > left[1] - left[0]:
                    palindrome_memo[(l, r)] = right
                else:
                    palindrome_memo[(l, r)] = left
        return palindrome_memo[(l, r)]

    memo = {}
    palindrome_memo = {}
    start, end = longest_palindrome(0, len(s) - 1)
    return s[start:end + 1]
