def find_prime_numbers(numbers):
    """
    Returns a sorted list of unique prime numbers from the input list.

    :param numbers: List of integers
    :return: Sorted list of unique prime numbers
    """
    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

