def ip_to_int32(ip_address):
    """
    Converts an IPv4 address string, possibly with a CIDR prefix, to its equivalent unsigned 32-bit integer.

    Parameters:
    ip_address (str): The IPv4 address string, which may include a CIDR prefix.

    Returns:
    int: The unsigned 32-bit integer representation of the IPv4 address, or -1 if the input is invalid.
    """
    def is_valid_ip(ip):
        parts = ip.split('.')
        if len(parts) != 4:
            return False
        for part in parts:
            if not part.isdigit():
                return False
            num = int(part)
            if num < 0 or num > 255:
                return False
        return True

    def ip_to_int(ip):
        parts = ip.split('.')
        num = 0
        for part in parts:
            num = (num << 8) + int(part)
        return num

    if '/' in ip_address:
        ip, cidr = ip_address.split('/')
        if not cidr.isdigit() or not (0 <= int(cidr) <= 32):
            return -1
    else:
        ip = ip_address

    if not is_valid_ip(ip):
        return -1

    return ip_to_int(ip)
```

