def solar_radiation_index(solar_radiation, clear_sky_radiation):
    """
    Calculate the Solar Radiation Index (SRI) based on the given solar radiation and clear-sky solar radiation data.

    Parameters:
    - solar_radiation: a float or a list of floats representing the measured solar radiation in MJ m-2 day-1.
    - clear_sky_radiation: a float or a list of floats representing the theoretical clear-sky solar radiation in MJ m-2 day-1.

    Returns:
    - A float or a list of floats representing the calculated Solar Radiation Index.
      Returns None for entries where clear-sky radiation is zero or negative.
    """
    def calculate_sri(sr, csr):
        if csr <= 0:
            return None
        return sr / csr

    if isinstance(solar_radiation, list) and isinstance(clear_sky_radiation, list):
        if len(solar_radiation) != len(clear_sky_radiation):
            raise ValueError("Both lists must have the same length.")
        return [calculate_sri(sr, csr) for sr, csr in zip(solar_radiation, clear_sky_radiation)]
    else:
        return calculate_sri(solar_radiation, clear_sky_radiation)
