def letter_combinations(digits: str) -> list:
    """
    Generate all possible letter combinations for a given string of digits.

    :param digits: A string containing digits from 2 to 9 inclusive.
    :return: A list of all possible letter combinations.
    """
    if not digits:
        return []

    digit_to_letters = {
        '2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
        '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'
    }

    def backtrack(combination: str, next_digits: str):
        if len(next_digits) == 0:
            output.append(combination)
        else:
            for letter in digit_to_letters[next_digits[0]]:
                backtrack(combination + letter, next_digits[1:])

    output = []
    backtrack("", digits)
    return output

