def is_balanced_parentheses(s):
    """
    Determines if the input string of parentheses, brackets, and braces is balanced.

    :param s: A string containing only the characters '(', ')', '{', '}', '[' and ']'.
    :return: True if the string is balanced, False otherwise.
    """
    matching_bracket = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in matching_bracket.values():
            stack.append(char)
        elif char in matching_bracket.keys():
            if not stack or matching_bracket[char] != stack.pop():
                return False

    return not stack

