def is_prime(n):
    """Check if a number is a prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def check_prime_sums(grid):
    """Check if the sum of each row and column is a prime number."""
    for row in grid:
        if not is_prime(sum(row)):
            return False
    for col in range(len(grid)):
        if not is_prime(sum(grid[row][col] for row in range(len(grid)))):
            return False
    return True

def get_valid_moves(grid):
    """Return possible directions the empty cell can be moved to maintain prime row and column sums."""
    for i, row in enumerate(grid):
        if 0 in row:
            row_index, col_index = i, row.index(0)
            break

    directions = {
        'up': (row_index - 1, col_index),
        'down': (row_index + 1, col_index),
        'left': (row_index, col_index - 1),
        'right': (row_index, col_index + 1)
    }

    valid_moves = {}

    for direction, (new_row, new_col) in directions.items():
        if 0 <= new_row < 3 and 0 <= new_col < 3:
            new_grid = [row[:] for row in grid]
            new_grid[row_index][col_index], new_grid[new_row][new_col] = new_grid[new_row][new_col], new_grid[row_index][col_index]
            valid_moves[direction] = check_prime_sums(new_grid)
        else:
            valid_moves[direction] = False

    return valid_moves
```

