def compute_factorials(numbers):
    """
    Computes the factorial for each integer in the input list and returns a dictionary.

    Parameters:
    numbers (list): A list of non-negative integers.

    Returns:
    dict: A dictionary with integers as keys and their factorials as values.
    """
    def factorial(n):
        if n == 0 or n == 1:
            return 1
        else:
            return n * factorial(n-1)

    return {num: factorial(num) for num in numbers}
