import math

def is_rational(n):
    """Check if a float is a rational approximation."""
    return n == float(int(n)) or n.is_integer() or math.isnan(n) or math.isinf(n)

def make_irrational(num):
    """Perturb a number to make it irrational."""
    irrational_add = 1.0 / math.sqrt(2) * 1e-10  # Small irrational value
    if random.choice([True, False]):
        irrational_add = -irrational_add
    return num + irrational_add

def draw_sample_exclude_inner(a, b, a_i, b_i):
    """
    Generate a random irrational number within the interval [a, b],
    excluding the interval (a_i, b_i).

    Raises:
        ValueError: If the inner range is not strictly within the outer range.
    """
    if not (a <= a_i < b_i <= b):
        raise ValueError("The inner range must be strictly within the outer range.")

    while True:
        num = random.uniform(a, b)
        if not (a_i <= num < b_i):
            if not is_rational(num):
                return num
            return make_irrational(num)
