def _event_matches_spec(event: dict, spec: Union[int, dict]) -> bool:
    """
    Determines if a given keyboard event matches a specified condition.

    Parameters:
    - event: A dictionary with keys 'key', 'modifier', and 'pressed'.
    - spec: An integer or a dictionary specifying the match condition.

    Returns:
    - True if the event matches the spec, False otherwise.
