def longest_increasing_subsequence(nums):
    """
    Returns the length of the longest increasing subsequence in the array.

    :param nums: List[int] - The input array of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    tails = []

    for num in nums:
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid

        if left == len(tails):
            tails.append(num)
        else:
            tails[left] = num

    return len(tails)

