def extract_email(json_data):
    """
    Recursively searches through a JSON object to find and return the email address.

    :param json_data: A JSON object which may contain nested dictionaries and lists.
    :return: The email address as a string if found, otherwise None.
    """
    if isinstance(json_data, dict):
        for key, value in json_data.items():
            if key == "email":
                return value
            elif isinstance(value, (dict, list)):
                result = extract_email(value)
                if result:
                    return result
    elif isinstance(json_data, list):
        for item in json_data:
            result = extract_email(item)
            if result:
                return result
    return None
