```python
def find_category_and_subcategory(data, item):
    """
    Finds the category and subcategory of a given item in a nested dictionary structure.

    Parameters:
    data (dict): A nested dictionary where each key maps to another dictionary.
    item (str): The item to be located within the nested dictionary.

    Returns:
    tuple or None: A tuple (category, subcategory) if the item is found, otherwise None.
    """
    for category, subcategories in data.items():
        for subcategory, items in subcategories.items():
            if item in items:
                return (category, subcategory)
    return None
