def longest_non_decreasing_subsequence_length(nums):
    """
    Returns the length of the longest non-decreasing subsequence in the given list of integers.

    :param nums: List[int] - A list of integers.
    :return: int - The length of the longest non-decreasing subsequence.
    """
    if not nums:
        return 0

    dp = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] >= nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

