def apply_to_structure_pair(f, structure_a, structure_b):
    """
    Applies a function f to corresponding elements in two nested data structures.

    Args:
        f (function): A function that takes two arguments and returns a single value.
        structure_a: The first nested data structure.
        structure_b: The second nested data structure.

    Returns:
        A new nested data structure with the same shape as structure_a and structure_b,
        but with elements replaced by the results of applying f.
    """
    def recursive_apply(a, b):
        if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
            return type(a)(recursive_apply(ai, bi) for ai, bi in zip(a, b))
        elif isinstance(a, dict) and isinstance(b, dict):
            return {k: recursive_apply(a[k], b[k]) for k in a}
        elif a is None or b is None:
            return None
        else:
            return f(a, b)

    return recursive_apply(structure_a, structure_b)
```

