class VotingSystem:
    def __init__(self):
        self.users = set()  # Store user names
        self.candidates = {}  # Map candidate names to their vote count
        self.results_calculated = False

    def register_user(self, user_name: str):
        """
        Register a new user in the system.
        :param user_name: Name of the user to register.
        """
        if user_name not in self.users:
            self.users.add(user_name)
            print(f"User {user_name} registered successfully.")
        else:
            print(f"User {user_name} is already registered.")

    def add_candidate(self, candidate_name: str):
        """
        Add a new candidate to the system.
        :param candidate_name: Name of the candidate to add.
        """
        if candidate_name not in self.candidates:
            self.candidates[candidate_name] = 0
            print(f"Candidate {candidate_name} added successfully.")
        else:
            print(f"Candidate {candidate_name} is already added.")

    def vote(self, user_name: str, candidate_name: str):
        """
        Allow a registered user to vote for a candidate.
        :param user_name: Name of the user voting.
        :param candidate_name: Name of the candidate receiving the vote.
        """
        if user_name not in self.users:
            print(f"User {user_name} is not registered.")
        elif candidate_name not in self.candidates:
            print(f"Candidate {candidate_name} does not exist.")
        else:
            if self.results_calculated:
                print("Voting has ended, you can no longer cast a vote.")
            else:
                self.candidates[candidate_name] += 1
                print(f"Vote cast for {candidate_name} by {user_name}.")

    def list_registered_users(self):
        """
        List all registered users in the system.
        """
        print("Registered Users:")
        for user in self.users:
            print(user)

    def list_candidates(self):
        """
        List all candidates in the system.
        """
        print("Candidates:")
        for candidate in self.candidates.keys():
            print(candidate)

    def display_results(self):
        """
        Display the final voting results and prevent further voting.
        """
        self.results_calculated = True
        print("Voting Results:")
        for candidate, votes in self.candidates.items():
            print(f"{candidate}: {votes} votes")
