def matrix_multiplication(matrix1, matrix2):
    """
    Multiplies two sparse matrices and returns the resulting matrix.

    :param matrix1: List of lists representing the first sparse matrix of shape (x, n).
    :param matrix2: List of lists representing the second sparse matrix of shape (n, x).
    :return: List of lists representing the resulting matrix of shape (x, x).
    """
    from collections import defaultdict

    sparse_matrix1 = defaultdict(lambda: defaultdict(int))
    sparse_matrix2 = defaultdict(lambda: defaultdict(int))

    for i in range(len(matrix1)):
        for j in range(len(matrix1[0])):
            if matrix1[i][j] != 0:
                sparse_matrix1[i][j] = matrix1[i][j]

    for i in range(len(matrix2)):
        for j in range(len(matrix2[0])):
            if matrix2[i][j] != 0:
                sparse_matrix2[i][j] = matrix2[i][j]

    result_sparse = defaultdict(lambda: defaultdict(int))

    for i in sparse_matrix1:
        for k in sparse_matrix1[i]:
            if k in sparse_matrix2:
                for j in sparse_matrix2[k]:
                    result_sparse[i][j] += sparse_matrix1[i][k] * sparse_matrix2[k][j]

    result_matrix = [[0] * len(matrix2[0]) for _ in range(len(matrix1))]
    for i in result_sparse:
        for j in result_sparse[i]:
            result_matrix[i][j] = result_sparse[i][j]

    return result_matrix
