def recursive_search(arr, target, left=0, right=None, calls=0):
    """
    Recursively searches for the target in a sorted array within a limited number of calls.

    Parameters:
    arr (list of int): The sorted array to search.
    target (int): The target integer to find.
    left (int): The starting index of the search range.
    right (int): The ending index of the search range.
    calls (int): The number of recursive calls made so far.

    Returns:
    int: The index of the target if found, otherwise -1.
    """
    if right is None:
        right = len(arr) - 1

    if calls >= len(arr).bit_length() + 2:
        raise RuntimeError("Too many recursive calls")

    if left > right:
        return -1

    mid = (left + right) // 2
    if arr[mid] == target:
        return mid
    elif arr[mid] < target:
        return recursive_search(arr, target, mid + 1, right, calls + 1)
    else:
        return recursive_search(arr, target, left, mid - 1, calls + 1)
