def trapezoidal_membership(x, a, b, c, d):
    """
    Calculate the membership value of a given input x within a trapezoidal fuzzy set defined by parameters a, b, c, and d.

    Parameters:
    x (float): The input value.
    a (float): The first parameter of the trapezoidal fuzzy set.
    b (float): The second parameter of the trapezoidal fuzzy set.
    c (float): The third parameter of the trapezoidal fuzzy set.
    d (float): The fourth parameter of the trapezoidal fuzzy set.

    Returns:
    float: The membership value of x within the trapezoidal fuzzy set.

    Raises:
    ValueError: If the parameters do not satisfy a < b < c < d.
    """
    if not (a < b < c < d):
        raise ValueError("Parameters must satisfy a < b < c < d")

    if x < a or x > d:
        return 0.0
    elif a <= x < b:
        return (x - a) / (b - a)
    elif b <= x <= c:
        return 1.0
    elif c < x <= d:
        return (d - x) / (d - c)
```

