def fibonacci(n):
    """
    Calculate the nth Fibonacci number using recursion.

    Parameters:
    n (int): The position in the Fibonacci sequence (1-indexed).

    Returns:
    int: The nth Fibonacci number.

    Raises:
    ValueError: If the input is not a positive integer within the range [1, 10].
    """
    if n <= 0 or n > 10:
        raise ValueError("Input should be a positive integer between 1 and 10.")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)
