class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        """Inserts a new node with the given value into the binary tree."""
        if not self.root:
            self.root = TreeNode(value)
        else:
            self._insert_recursively(self.root, value)

    def _insert_recursively(self, node, value):
        """Helper method to insert a new node recursively."""
        if value < node.value:
            if node.left is None:
                node.left = TreeNode(value)
            else:
                self._insert_recursively(node.left, value)
        else:
            if node.right is None:
                node.right = TreeNode(value)
            else:
                self._insert_recursively(node.right, value)

    def in_order_traversal(self):
        """Performs an in-order traversal of the binary tree and returns the values in a list."""
        return self._in_order_traversal_recursively(self.root)

    def _in_order_traversal_recursively(self, node):
        """Helper method to perform in-order traversal recursively."""
        traversal = []
        if node is not None:
            traversal = self._in_order_traversal_recursively(node.left)
            traversal.append(node.value)
            traversal = traversal + self._in_order_traversal_recursively(node.right)
        return traversal

    def is_balanced(self):
        """Checks if the binary tree is balanced."""
        return self._is_balanced_recursively(self.root) != -1

    def _is_balanced_recursively(self, node):
        """Helper method to check if the binary tree is balanced recursively."""
        if node is None:
            return 0

        left_height = self._is_balanced_recursively(node.left)
        if left_height == -1:
            return -1

        right_height = self._is_balanced_recursively(node.right)
        if right_height == -1 or abs(left_height - right_height) > 1:
            return -1

        return max(left_height, right_height) + 1
