def convert_strings_to_uppercase(obj):
    """
    Recursively converts all string properties of a JavaScript-like object to uppercase.

    :param obj: A JavaScript-like object (string, array, or dictionary).
    :return: The same object structure with all string properties converted to uppercase.
    """
    if isinstance(obj, str):
        return obj.upper()
    elif isinstance(obj, dict):
        return {key: convert_strings_to_uppercase(value) for key, value in obj.items()}
    elif isinstance(obj, list):
        return [convert_strings_to_uppercase(element) for element in obj]
    return obj
