import xml.etree.ElementTree as ET

def parse_xml(xml_data):
    """
    Parses an XML string and returns a dictionary representing the XML structure.

    Args:
    xml_data (str): A string containing the XML data.

    Returns:
    dict: A dictionary representing the XML structure.
    """
    root = ET.fromstring(xml_data)

    def parse_element(element):
        el_dict = {}
        for attr, value in element.attrib.items():
            el_dict[attr] = value
        text = element.text.strip() if element.text else ''
        if text:
            el_dict['text'] = text
        children = {}
        for child in element:
            child_dict = parse_element(child)
            if child.tag in children:
                if not isinstance(children[child.tag], list):
                    children[child.tag] = [children[child.tag]]
                children[child.tag].append(child_dict)
            else:
                children[child.tag] = child_dict
        if children:
            el_dict.update(children)
        return el_dict

    return {root.tag: parse_element(root)}
