def is_balanced_parentheses(expression):
    """
    Determines if the given expression with parentheses, brackets, and braces is balanced.

    :param expression: A string containing only '(', ')', '[', ']', '{', and '}'.
    :return: True if the expression is balanced, False otherwise.
    """
    stack = []
    matching_bracket = {')': '(', '}': '{', ']': '['}

    for char in expression:
        if char in matching_bracket.values():
            stack.append(char)
        elif char in matching_bracket.keys():
            if not stack or matching_bracket[char] != stack.pop():
                return False

    return not stack
