class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with the given 2D list.
        Raises ValueError if the input is not a valid matrix.
        """
        if not all(isinstance(row, list) for row in data):
            raise ValueError("Matrix should be a list of lists")
        if not data or not all(data):
            raise ValueError("Matrix should not be empty")
        if not all(len(row) == len(data[0]) for row in data):
            raise ValueError("All rows in the matrix should have the same number of columns")

        self.data = data
        self.rows = len(data)
        self.cols = len(data[0])

    def __add__(self, other):
        """
        Adds two matrices of the same dimensions.
        Raises ValueError if the dimensions do not match.
        """
        if not isinstance(other, Matrix):
            raise ValueError("Can only add another Matrix instance")
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for addition")

        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __sub__(self, other):
        """
        Subtracts two matrices of the same dimensions.
        Raises ValueError if the dimensions do not match.
        """
        if not isinstance(other, Matrix):
            raise ValueError("Can only subtract another Matrix instance")
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for subtraction")

        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __mul__(self, other):
        """
        Multiplies two matrices if the number of columns in the first matrix
        equals the number of rows in the second matrix.
        Raises ValueError if the dimensions are incompatible.
        """
        if not isinstance(other, Matrix):
            raise ValueError("Can only multiply another Matrix instance")
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to the number of rows in the second matrix for multiplication")

        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __str__(self):
        """
        Returns a string representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])

# Example usage:
try:
