def virtual_machine(instructions):
    """
    Simulates a simple virtual machine that processes a sequence of instructions.

    Parameters:
    instructions (str): A string containing the sequence of instructions separated by spaces.

    Returns:
    None
    """
    accumulator = None
    instruction_list = instructions.split()

    pc = 0
    while pc < len(instruction_list):
        instruction = instruction_list[pc]
        if instruction == "LOAD":
            try:
                pc += 1
                value = int(instruction_list[pc])
                accumulator = value
            except (IndexError, ValueError):
                print("Error: Invalid LOAD instruction.")
                break
        elif instruction == "ADD":
            try:
                pc += 1
                value = int(instruction_list[pc])
                if accumulator is not None:
                    accumulator += value
                else:
                    print("Error: Accumulator not initialized before ADD.")
                    break
            except (IndexError, ValueError):
                print("Error: Invalid ADD instruction.")
                break
        elif instruction == "SUB":
            try:
                pc += 1
                value = int(instruction_list[pc])
                if accumulator is not None:
                    accumulator -= value
                else:
                    print("Error: Accumulator not initialized before SUB.")
                    break
            except (IndexError, ValueError):
                print("Error: Invalid SUB instruction.")
                break
        elif instruction == "MUL":
            try:
                pc += 1
                value = int(instruction_list[pc])
                if accumulator is not None:
                    accumulator *= value
                else:
                    print("Error: Accumulator not initialized before MUL.")
                    break
            except (IndexError, ValueError):
                print("Error: Invalid MUL instruction.")
                break
        elif instruction == "DIV":
            try:
                pc += 1
                value = int(instruction_list[pc])
                if value == 0:
                    print("Error: Division by zero.")
                    break
                if accumulator is not None:
                    accumulator //= value
                else:
                    print("Error: Accumulator not initialized before DIV.")
                    break
            except (IndexError, ValueError):
                print("Error: Invalid DIV instruction.")
                break
        elif instruction == "PRINT":
            if accumulator is not None:
                print(accumulator)
            else:
                print("Error: Accumulator is not initialized.")
        elif instruction == "STOP":
            break
        else:
            print(f"Error: Unknown instruction '{instruction}'.")
            break
        pc += 1

