class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

    def insert(self, key):
        """
        Inserts a new node with the specified key into the BST.
        """
        if self.val is None:
            self.val = key
            return

        if key < self.val:
            if self.left is None:
                self.left = TreeNode(key)
            else:
                self.left.insert(key)
        else:
            if self.right is None:
                self.right = TreeNode(key)
            else:
                self.right.insert(key)

    def search(self, key):
        """
        Searches for a node with the specified key in the BST.
        Returns the node if found, otherwise returns None.
        """
        if self.val is None or self.val == key:
            return self

        if self.val < key:
            return self.right.search(key) if self.right else None

        return self.left.search(key) if self.left else None

    def delete(self, key):
        """
        Deletes the node with the specified key from the BST.
        If the key is not found, the tree remains unchanged.
        """
        if self is None:
            return self

        if key < self.val:
            self.left = self.left.delete(key) if self.left else None

        elif key > self.val:
            self.right = self.right.delete(key) if self.right else None

        else:
            if self.left is None:
                return self.right
            elif self.right is None:
                return self.left

            temp = self.right._min()
            self.val = temp.val
            self.right = self.right.delete(temp.val)

        return self

    def _min(self):
        """
        Returns the node with the smallest key in the BST.
        """
        current = self
        while current.left is not None:
            current = current.left
        return current
