    :param start_id: Integer, the identifier of the start dialogue.
    :param end_id: Integer, the identifier of the end dialogue.
    :return: String representing the path from start to end dialogue, or an empty string if no path exists.
    """
    dialogues_by_id = {d['Id']: d for d in dialogue_list}
    children = {d['Id']: [] for d in dialogue_list}

    for d in dialogue_list:
        if d['Parent'] is not None:
            children[d['Parent']].append(d['Id'])

    def find_path(current_id, end_id, path):
        if current_id == end_id:
            return '->'.join(path)
        for child_id in children[current_id]:
            result = find_path(child_id, end_id, path + [dialogues_by_id[child_id]['DisplayName']])
            if result:
                return result
        return None

    if start_id not in dialogues_by_id or end_id not in dialogues_by_id:
        return ''

    start_display_name = dialogues_by_id[start_id]['DisplayName']
    found_path = find_path(start_id, end_id, [start_display_name])

    return found_path if found_path else ''
