        self.usage = usage
        self.available = available

class StorageState:
    def __init__(self, used, total):
        self.used = used
        self.total = total

class NetworkState:
    def __init__(self, inbound, outbound):
        self.inbound = inbound
        self.outbound = outbound

class SystemSnapshot:
    def __init__(self, cpu=None, memory=None, storage=None, network=None):
        self.cpu = cpu
        self.memory = memory
        self.storage = storage
        self.network = network

def create_system_snapshot(states):
    """
    Creates a SystemSnapshot object from a dictionary of system states.

    Args:
        states (dict): A dictionary with keys 'cpu', 'memory', 'storage', 'network' 
                       and corresponding dictionaries with specific metrics.

    Returns:
        SystemSnapshot: An object representing the system snapshot.

    Raises:
        ValueError: If the input dictionary contains unknown components or incorrect keys.
    """
    expected_keys = {
        'cpu': {'usage', 'temperature'},
        'memory': {'usage', 'available'},
        'storage': {'used', 'total'},
        'network': {'inbound', 'outbound'}
    }

    for state, data in states.items():
        if state not in expected_keys:
            raise ValueError(f"Unknown state '{state}' provided")

        if set(data.keys()) != expected_keys[state]:
            missing = expected_keys[state] - set(data.keys())
            extra = set(data.keys()) - expected_keys[state]
            raise ValueError(f"Invalid keys for '{state}': missing={missing}, extra={extra}")

    cpu_state = CPUState(**states.get('cpu', {})) if 'cpu' in states else None
    memory_state = MemoryState(**states.get('memory', {})) if 'memory' in states else None
    storage_state = StorageState(**states.get('storage', {})) if 'storage' in states else None
    network_state = NetworkState(**states.get('network', {})) if 'network' in states else None

    return SystemSnapshot(cpu=cpu_state, memory=memory_state, storage=storage_state, network=network_state)
