def evaluate_formula(A, B, op):
    """
    Evaluates the expression A op B where op is one of the following operators:
    +, -, *, /, %, |, &, ^.

    Parameters:
    A (int): The first operand.
    B (int): The second operand.
    op (str): The operator to apply.

    Returns:
    int: The result of the expression A op B.
    """
    if op == '+':
        return A + B
    elif op == '-':
        return A - B
    elif op == '*':
        return A * B
    elif op == '/':
        return A // B
    elif op == '%':
        return A % B
    elif op == '|':
        return A | B
    elif op == '&':
        return A & B
    elif op == '^':
        return A ^ B
    else:
        raise ValueError("Unsupported operation")
