def find_prime_factors(numbers):
    """
    Returns a dictionary where the keys are numbers from the input list and the values are lists of their prime factors.

    :param numbers: List of positive integers
    :return: Dictionary with numbers as keys and lists of prime factors as values
    """
    def prime_factors(n):
        """
        Returns a sorted list of prime factors of a given number n.

        :param n: Positive integer
        :return: List of prime factors in ascending order
        """
        i = 2
        factors = set()
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors.add(i)
        if n > 1:
            factors.add(n)
        return sorted(factors)

    return {num: prime_factors(num) for num in numbers}
```

