        Removes a book from the library using its ISBN.
        If the book is currently borrowed, it cannot be removed.
        """
        for book in self.books:
            if book['isbn'] == isbn:
                if book['is_borrowed']:
                    print("Cannot remove a book that is currently borrowed.")
                    return
                self.books.remove(book)
                print("Book removed successfully.")
                return
        print("No book with this ISBN found in the library.")

    def borrow_book(self, isbn):
        """
        Marks a book as borrowed using its ISBN.
        If the book is already borrowed, it does not mark it as borrowed.
        """
        for book in self.books:
            if book['isbn'] == isbn:
                if book['is_borrowed']:
                    print("This book is already borrowed.")
                    return
                book['is_borrowed'] = True
                print("Book borrowed successfully.")
                return
        print("No book with this ISBN found in the library.")

    def return_book(self, isbn):
