        Marks a book as returned using its ISBN.
        If the book has not been borrowed, it does not mark it as returned.
        """
        for book in self.books:
            if book['isbn'] == isbn:
                if not book['is_borrowed']:
                    print("This book has not been borrowed.")
                    return
                book['is_borrowed'] = False
                print("Book returned successfully.")
                return
        print("No book with this ISBN found in the library.")

