class FrequencyNode:
    def __init__(self, key):
        """Initialize a node with a key and a frequency of 1."""
        self.key = key
        self.frequency = 1
        self.next = None

class FrequencyLinkedList:
    def __init__(self):
        """Initialize an empty linked list."""
        self.head = None

    def insert_or_update(self, key):
        """Insert a new key or update the frequency of an existing key."""
        current = self.head
        previous = None
        while current:
            if current.key == key:
                current.frequency += 1
                return
            previous = current
            current = current.next

        new_node = FrequencyNode(key)
        if previous:
            previous.next = new_node
        else:
            self.head = new_node

    def convert_to_dict(self):
        """Convert the linked list to a dictionary."""
        result = {}
        current = self.head
        while current:
            result[current.key] = current.frequency
            current = current.next
        return result

def create_frequency_dict(input_list):
    """Create a frequency dictionary from the input list without using built-in data structures."""
    freq_list = FrequencyLinkedList()
    for item in input_list:
        freq_list.insert_or_update(item)
    return freq_list.convert_to_dict()
