def find_satisfying_assignment(formula):
    """
    Finds a satisfying assignment for a given CNF formula.

    :param formula: List of clauses, where each clause is a list of literals.
                    Each literal is a tuple (variable, value).
    :return: Dictionary representing a satisfying assignment, or None if no such assignment exists.
    """
    def backtrack(assignment):
        if len(assignment) == len(variables):
            return True

        var = next(iter(variables - set(assignment.keys())))

        for value in [True, False]:
            if is_clause_satisfied(var, value):
                assignment[var] = value
                if backtrack(assignment):
                    return True
                del assignment[var]

        return False

    def is_clause_satisfied(var, value):
        """
        Checks if the current assignment satisfies all clauses involving the variable.

        :param var: Variable name.
        :param value: Boolean value assigned to the variable.
        :return: True if all clauses involving the variable are satisfied, False otherwise.
        """
        for clause in formula:
            clause_satisfied = False
            for literal in clause:
                if literal[0] == var and (value == literal[1]):
                    clause_satisfied = True
                    break
                elif literal[0] != var:
                    if var not in assignment:
                        continue
                    elif assignment[literal[0]] == literal[1]:
                        clause_satisfied = True
                        break
            if not clause_satisfied:
                return False
        return True

    variables = set()
    for clause in formula:
        for literal in clause:
            variables.add(literal[0])

    assignment = {}
    if backtrack(assignment):
        return assignment
    else:
        return None

