def validate_input(input_string: str) -> tuple:
    """
    Validates if the input string can be converted to a valid integer or float.

    Parameters:
    input_string (str): The string to be validated.

    Returns:
    tuple: A tuple containing a boolean indicating if the conversion is valid,
           and the converted number if valid, otherwise None.
    """
    input_string = input_string.strip()
    if not input_string:
        return (False, None)

    is_negative = False
    digits = []
    decimal_point_found = False
    decimal_part = []

    if input_string[0] == '-':
        is_negative = True
        input_string = input_string[1:]
    elif input_string[0] == '+':
        input_string = input_string[1:]

    for char in input_string:
        if char.isdigit():
            if decimal_point_found:
                decimal_part.append(char)
            else:
                digits.append(char)
        elif char == '.':
            if decimal_point_found:
                return (False, None)
            decimal_point_found = True
        else:
            return (False, None)

    if not digits and not decimal_part:
        return (False, None)

    integer_value = 0
    for digit in digits:
        integer_value = integer_value * 10 + (ord(digit) - ord('0'))

    float_value = integer_value
    decimal_value = 0
    if decimal_part:
        for digit in decimal_part:
            decimal_value = decimal_value * 10 + (ord(digit) - ord('0'))
        decimal_value /= 10 ** len(decimal_part)
        float_value += decimal_value

    if is_negative:
        float_value = -float_value

    if decimal_part:
        return (True, float_value)
    else:
        return (True, int(float_value))
