def parse_keywords_and_synonyms(input_string):
    """
    Parses a multiline string containing keywords and their synonyms separated by commas.

    Args:
    input_string (str): A multiline string where each line contains a keyword and its synonyms.

    Returns:
    list: A list of lists, where each inner list contains a keyword and its synonyms.
    """
    result = []
    i = 0
    line_start = 0

    while i < len(input_string):
        if input_string[i] == '\n':
            line = input_string[line_start:i]
            if line:
                words = []
                word_start = 0
                in_word = False

                for j in range(len(line)):
                    if line[j] == ',':
                        if in_word:
                            words.append(line[word_start:j].strip())
                            in_word = False
                    else:
                        if not in_word:
                            word_start = j
                            in_word = True
                        if j == len(line) - 1:
                            words.append(line[word_start:].strip())

                result.append(words)
            line_start = i + 1
        i += 1

    if line_start < len(input_string):
        line = input_string[line_start:]
        if line:
            words = []
            word_start = 0
            in_word = False

            for j in range(len(line)):
                if line[j] == ',':
                    if in_word:
                        words.append(line[word_start:j].strip())
                        in_word = False
                else:
                    if not in_word:
                        word_start = j
                        in_word = True
                    if j == len(line) - 1:
                        words.append(line[word_start:].strip())

            result.append(words)

    return result

