def find_duplicate_elements(nums):
    """
    Identifies duplicate elements in a list and returns a dictionary of duplicates with their counts.

    :param nums: List of integers
    :return: Dictionary with duplicate elements as keys and their counts as values
    """
    counts = {}
    duplicates = {}

    for num in nums:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    for num, count in counts.items():
        if count > 1:
            duplicates[num] = count

    return duplicates
