def create_class_from_dict(class_name, fields_dict):
    """
    Dynamically creates a class with fields and methods based on the provided dictionary.

    :param class_name: Name of the class to be created.
    :param fields_dict: Dictionary where keys are field names and values are field types.
    :return: A new class with the specified fields and methods.
    """
    def __init__(self, **kwargs):
        for field, field_type in fields_dict.items():
            if field in kwargs:
                if isinstance(kwargs[field], eval(field_type)):
                    setattr(self, field, kwargs[field])
                else:
                    raise ValueError(f"Expected type {field_type} for {field}, got {type(kwargs[field]).__name__} instead.")
            else:
                setattr(self, field, None)

    def display(self):
        """
        Prints each field name and its value in the format: "Field: <field_name>, Value: <field_value>".
        """
        for field in fields_dict.keys():
            print(f"Field: {field}, Value: {getattr(self, field)}")

    return type(class_name, (object,), {
        '__init__': __init__,
        'display': display
    })

