class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def postorder_traversal(root):
    """
    Perform a postorder traversal of a binary tree and return the node values in the traversal order.

    :param root: TreeNode, the root of the binary tree
    :return: List[int], the values of the nodes in postorder traversal
    """
    def traverse(node):
        if not node:
            return []
        return traverse(node.left) + traverse(node.right) + [node.value]

    return traverse(root)
