def boolean_matrix_vector_operation(mat, vec):
    """
    Computes the boolean vector res based on the given matrix mat and vector vec.
    Modifies mat in-place according to the result.

    :param mat: List[List[bool]] - The boolean matrix.
    :param vec: List[bool] - The boolean vector.
    :return: List[bool] - The resulting boolean vector.
    """
    if not mat or not vec or len(mat[0]) != len(vec):
        print("The matrix and vector cannot be multiplied.")
        return None

    m = len(mat)
    n = len(vec)
    res = [False] * m

    for i in range(m):
        for j in range(n):
            if mat[i][j] and vec[j]:
                res[i] = True
                break

    for i in range(m):
        if res[i]:
            for j in range(n):
                if mat[i][j]:
                    mat[i][j] = False

    return res
