def generate_primes(limit):
    """
    Generate a list of all prime numbers up to and including the given limit.

    Parameters:
    limit (int): The upper bound for generating prime numbers (inclusive).

    Returns:
    list: A list of prime numbers up to and including the limit.
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = []
    for num in range(2, limit + 1):
        if is_prime(num):
            primes.append(num)
    return primes

