        print(f"Error: {filename} does not exist.")
        return
    try:
        with open(filename, mode='r', newline='') as file:
            reader = csv.DictReader(file)
            columns_sums = {}
            columns_counts = {}

            for row in reader:
                for column in row:
                    value = row[column]
                    if is_number(value):
