                            columns_sums[column] = 0.0
                            columns_counts[column] = 0
                        columns_sums[column] += float(value)
                        columns_counts[column] += 1

            for column in columns_sums:
                average = columns_sums[column] / columns_counts[column]
                print(f"Average of column '{column}': {average:.2f}")

    except IOError:
        print(f"Error: {filename} is not readable.")
