def findMinInsertions(s):
    """
    Determine the minimum number of characters that need to be inserted into the string s to make it a palindrome.

    :param s: A string consisting of lowercase English letters.
    :return: An integer representing the minimum number of insertions needed.
    """
    def helper(l, r):
        if l >= r:
            return 0
        if s[l] == s[r]:
            return helper(l + 1, r - 1)
        else:
            return 1 + min(helper(l + 1, r), helper(l, r - 1))

    return helper(0, len(s) - 1)

