def can_form_palindrome_by_removing_one_char(s):
    """
    Determines if the string can be transformed into a palindrome by removing at most one character.

    :param s: Input string consisting of lowercase English letters.
    :return: True if the string can be transformed into a palindrome by removing at most one character, otherwise False.
    """
    def is_palindrome_range(i, j):
        return all(s[k] == s[j - k + i] for k in range(i, j))

    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            return is_palindrome_range(left + 1, right) or is_palindrome_range(left, right - 1)
        left, right = left + 1, right - 1
    return True

