def validate_nested_dictionaries(expected, real):
    """
    Validates if the real dictionary contains all keys and values present in the expected dictionary.

    :param expected: The dictionary or list representing the expected structure.
    :param real: The dictionary or list to be validated against the expected structure.
    :return: True if real contains all keys and values from expected, False otherwise.
    """
    if isinstance(expected, dict) and isinstance(real, dict):
        for key, exp_value in expected.items():
            if key not in real:
                return False
            real_value = real[key]
            if callable(exp_value):
                if not exp_value(real_value):
                    return False
            elif not validate_nested_dictionaries(exp_value, real_value):
                return False
        return True
    elif isinstance(expected, list) and isinstance(real, list):
        for exp_item in expected:
            found = False
            for real_item in real:
                if validate_nested_dictionaries(exp_item, real_item):
                    found = True
                    break
            if not found:
                return False
        return True
    else:
        return expected == real

