class FileSystemElement:
    def __init__(self, name):
        self.name = name

class File(FileSystemElement):
    def __init__(self, name, content):
        super().__init__(name)
        self.content = content

class Directory(FileSystemElement):
    def __init__(self, name):
        super().__init__(name)
        self.contents = {}

    def create_file(self, file_name, content):
        """
        Creates a file with the given name and content in the directory.
        Raises ValueError if a file or directory with the same name already exists.
        """
        if file_name in self.contents:
            raise ValueError(f"File {file_name} already exists in directory {self.name}.")
        self.contents[file_name] = File(file_name, content)

    def create_directory(self, dir_name):
        """
        Creates a directory with the given name in the directory.
        Raises ValueError if a file or directory with the same name already exists.
        """
        if dir_name in self.contents:
            raise ValueError(f"Directory {dir_name} already exists in directory {self.name}.")
        self.contents[dir_name] = Directory(dir_name)

    def delete_file(self, file_name):
        """
        Deletes a file with the given name from the directory.
        Raises ValueError if the file does not exist or if the name refers to a directory.
        """
        if file_name not in self.contents:
            raise ValueError(f"File {file_name} does not exist in directory {self.name}.")
        if not isinstance(self.contents[file_name], File):
            raise ValueError(f"{file_name} is a directory, not a file.")
        del self.contents[file_name]

    def delete_directory(self, dir_name):
        """
        Deletes a directory with the given name from the directory.
        Raises ValueError if the directory does not exist or if the name refers to a file.
        """
        if dir_name not in self.contents:
            raise ValueError(f"Directory {dir_name} does not exist in directory {self.name}.")
