def time_to_seconds(time_str):
    """
    Converts a time duration in the format "HH:MM:SS" or "HH:MM:SS.FF" to the total number of seconds.

    Parameters:
    time_str (str): The time duration as a string.

    Returns:
    int or float: The total number of seconds, or -1 if the input is invalid.
    """
    try:
        if '.' in time_str:
            whole_part, fractional_part = time_str.split('.')
            if len(fractional_part) > 2:
                return -1
            fractional_seconds = int(fractional_part) / (10 ** len(fractional_part))
        else:
            whole_part = time_str
            fractional_seconds = 0.0

        hours, minutes, seconds = map(int, whole_part.split(':'))

        if hours < 0 or hours > 23:
            return -1
        if minutes < 0 or minutes > 59:
            return -1
        if seconds < 0 or seconds > 59:
            return -1

        total_seconds = hours * 3600 + minutes * 60 + seconds + fractional_seconds
        return total_seconds

    except ValueError:
        return -1
