        self.value = value
        self.left = left
        self.right = right

def find_path(root, target):
    """
    Finds the path from the root node to the target node in a binary tree.

    :param root: TreeNode, the root of the binary tree.
    :param target: int, the value of the target node.
    :return: List[int], a list of node values representing the path from root to target.
             Returns an empty list if the target node does not exist.
    """
    def dfs(node, current_path):
        if not node:
            return []
        current_path = current_path + [node.value]
        if node.value == target:
            return current_path
        left_path = dfs(node.left, current_path)
        if left_path:
            return left_path
        right_path = dfs(node.right, current_path)
        if right_path:
            return right_path
        return []

    return dfs(root, [])
