def kth_smallest(root, k):
    """
    Returns the k-th smallest element in a binary search tree (BST).

    :param root: Node, the root of the BST.
    :param k: int, the order of the smallest element to find.
    :return: int, the k-th smallest element in the BST.
    """
    def inorder_traversal(node):
        if not node:
            return []
        return inorder_traversal(node.left) + [node.value] + inorder_traversal(node.right)

    sorted_elements = inorder_traversal(root)
    return sorted_elements[k-1]
