def find_longest_increasing_subsequence(arr):
    """
    Finds the length of the longest increasing subsequence in the given array.

    :param arr: List[int] - The input array of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not arr:
        return 0

    tails = []

    for num in arr:
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid

        if left == len(tails):
            tails.append(num)
        else:
            tails[left] = num

    return len(tails)

# Example usage:
# arr = [10, 9, 2, 5, 3, 7, 101, 18]
