def is_arithmetic_progression(numbers):
    """
    Determines if there exists a subsequence of the list that can be rearranged
    to form an arithmetic progression of length between 5 and 10, inclusive.

    :param numbers: List of integers
    :return: True if such a subsequence exists, otherwise False
    """
    def check_arithmetic(seq):
        difference = seq[1] - seq[0]
        return all(seq[i] - seq[i-1] == difference for i in range(2, len(seq)))

    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)

    for start in range(n - 4):
        for end in range(start + 4, min(start + 10, n)):
            if check_arithmetic(sorted_numbers[start:end + 1]):
                return True
    return False
