import math

def get_nth_prime(n):
    """Return the nth prime number using the Sieve of Eratosthenes algorithm.

    Args:
        n: A positive integer representing the position of the prime to return.

    Returns:
        The nth prime number.
    """
    if n < 1:
        raise ValueError("n must be a positive integer")

    if n == 1:
        return 2
    elif n == 2:
        return 3
    elif n == 3:
        return 5
    elif n == 4:
        return 7
    elif n == 5:
        return 11
    else:
        upper_bound = int(n * (math.log(n) + math.log(math.log(n)))) if n >= 6 else 15

    sieve = [True] * upper_bound
    sieve[0] = sieve[1] = False
    p = 2

    while p * p < upper_bound:
        if sieve[p]:
            for multiple in range(p * p, upper_bound, p):
                sieve[multiple] = False
        p += 1

    primes = [num for num, is_prime in enumerate(sieve) if is_prime]

    return primes[n - 1]
