class BinarySimulation:
    def __init__(self, binary_string):
        """Initialize the binary simulation with a given binary string."""
        self.bit_array = [int(bit) for bit in binary_string]
        self.N = len(self.bit_array)

    def toggle_range(self, i, j):
        """Toggle the bits from index i to j (inclusive, 1-based indexing)."""
        for idx in range(i - 1, j):
            self.bit_array[idx] ^= 1

    def query(self, i):
        """Return the value of the bit at index i (1-based indexing)."""
        return self.bit_array[i - 1]

    def binary_simulation(self, operations):
        """Process a list of operations and return the results of query operations."""
        results = []
        for operation in operations:
            if operation[0] == 'I':
                _, i, j = operation
                self.toggle_range(i, j)
            elif operation[0] == 'Q':
                _, i = operation
                result = self.query(i)
                results.append(result)
        return results

# Test the function
