def spiralOrder(matrix):
    """
    Returns the elements of the given 2D array in spiral order.

    :param matrix: List[List[int]] - A 2D list of integers.
    :return: List[int] - A list of integers representing the spiral order traversal.
    """
    if not matrix: 
        return []

    rows, cols = 0, 0
    row_end, col_end = len(matrix) - 1, len(matrix[0]) - 1
    result = []

    while (rows <= row_end) and (cols <= col_end):
        for col in range(cols, col_end + 1):
            result.append(matrix[rows][col])
        rows += 1

        for row in range(rows, row_end + 1):
            result.append(matrix[row][col_end])
        col_end -= 1

        if rows <= row_end:
            for col in range(col_end, cols - 1, -1):
                result.append(matrix[row_end][col])
            row_end -= 1

        if cols <= col_end:
            for row in range(row_end, rows - 1, -1):
                result.append(matrix[row][cols])
            cols += 1

    return result
