def is_prime(num):
    """Check if a number is prime."""
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def next_prime(current_prime):
    """Find the next prime number after the current prime."""
    next_candidate = current_prime + 1
    while not is_prime(next_candidate):
        next_candidate += 1
    return next_candidate

def build_word2id(corpus):
    """Build a dictionary mapping words to prime number IDs."""
    word2id = {}
    current_prime = 2  # Start with the smallest prime number

    for document in corpus:
        for word in document.split():
            if word not in word2id:
                word2id[word] = current_prime
                current_prime = next_prime(current_prime)

    # Add a special entry for OOV words
    word2id['<OOV>'] = -1

    return word2id
