class HashTable:
    def __init__(self, capacity=10):
        self.capacity = capacity
        self.table = [[] for _ in range(capacity)]
        self._size = 0

    def _hash(self, key):
        """Computes the hash index for a given key."""
        return hash(key) % self.capacity

    def put(self, key, value):
        """Inserts a key-value pair into the hash table. Updates the value if the key already exists."""
        index = self._hash(key)
        for kv_pair in self.table[index]:
            if kv_pair[0] == key:
                kv_pair[1] = value
                return
        self.table[index].append([key, value])
        self._size += 1

    def get(self, key):
        """Returns the value associated with the given key, or None if the key does not exist."""
        index = self._hash(key)
        for kv_pair in self.table[index]:
            if kv_pair[0] == key:
                return kv_pair[1]
        return None

    def remove(self, key):
        """Removes the key-value pair from the hash table. Returns True if the key was found and removed, otherwise False."""
        index = self._hash(key)
        for i, kv_pair in enumerate(self.table[index]):
            if kv_pair[0] == key:
                del self.table[index][i]
                self._size -= 1
                return True
        return False

    def size(self):
        """Returns the number of key-value pairs in the hash table."""
        return self._size
