    Determines if tree_a is a mirror image of tree_b when viewed from the bottom up.

    :param tree_a: TreeNode, root of the first binary tree
    :param tree_b: TreeNode, root of the second binary tree
    :return: bool, True if tree_a is a mirror image of tree_b, False otherwise
    """
    def bottom_up_check(node1, node2):
        if not node1 and not node2:
            return True
        if not node1 or not node2:
            return False
        return (node1.val == node2.val and 
                bottom_up_check(node1.left, node2.right) and
                bottom_up_check(node1.right, node2.left))

