def num_sum_diff(num1, num2, operation):
    """
    Computes the sum or difference of two numbers or lists of numbers based on the operation specified.

    Parameters:
    num1 (int or list of int): The first number or list of numbers.
    num2 (int or list of int): The second number or list of numbers.
    operation (str): The operation to perform, either "sum" or "diff".

    Returns:
    int or list of int or str: The result of the operation, or an error message if inputs are invalid.
    """
    if operation not in ["sum", "diff"]:
        return "Invalid operation"

    def is_valid_number(n):
        if isinstance(n, int):
            return True
        if isinstance(n, list):
            return all(isinstance(i, int) for i in n)
        return False

    if not (is_valid_number(num1) and is_valid_number(num2)):
        return "Invalid input"

    def perform_operation(a, b):
        if operation == "sum":
            return a + b
        elif operation == "diff":
            return abs(a - b)

    if isinstance(num1, list) and isinstance(num2, list):
        if len(num1) != len(num2):
            return "Invalid input"
        return [perform_operation(a, b) for a, b in zip(num1, num2)]

    return perform_operation(num1, num2)
