from collections import deque

def bfs_shortest_path(graph, start):
    """
    Finds the shortest path from a given starting node to all other nodes in an unweighted graph using BFS.

    :param graph: A dictionary representing the graph as an adjacency list.
    :param start: An integer representing the starting node.
    :return: A list of integers representing the nodes sorted by their shortest distance from the starting node.
    """
    distances = {vertex: float('inf') for vertex in graph}
    predecessors = {vertex: None for vertex in graph}

    distances[start] = 0
    queue = deque([start])

    while queue:
        current = queue.popleft()
        for neighbor in graph[current]:
            if distances[neighbor] == float('inf'):
                distances[neighbor] = distances[current] + 1
                predecessors[neighbor] = current
                queue.append(neighbor)

    return sorted(distances.keys(), key=lambda x: distances[x])
