    Recursively applies functions in a nested structure to a given context.

    Parameters:
    ctx (int): The context to which functions will be applied.
    expr (int, str, function, list, tuple, set): The nested structure containing functions and data types.

    Returns:
    int, str, list, tuple, set: The nested structure with functions replaced by their results.
    """
    if callable(expr):
        return expr(ctx)
    elif isinstance(expr, list):
        return [deep_apply(ctx, item) for item in expr]
    elif isinstance(expr, tuple):
        return tuple(deep_apply(ctx, item) for item in expr)
    elif isinstance(expr, set):
        return {deep_apply(ctx, item) for item in expr}
    else:
        return expr

