def deep_equal(value1, value2):
    """
    Recursively compares two values of any data type and returns True if they are deeply equal, False otherwise.

    :param value1: First value to compare.
    :param value2: Second value to compare.
    :return: Boolean indicating if the two values are deeply equal.
    """
    if type(value1) != type(value2):
        return False

    if isinstance(value1, list):
        if len(value1) != len(value2):
            return False
        return all(deep_equal(v1, v2) for v1, v2 in zip(value1, value2))

    elif isinstance(value1, dict):
        if value1.keys() != value2.keys():
            return False
        return all(deep_equal(value1[key], value2[key]) for key in value1)

    else:
        return value1 == value2
