class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with the given 2D list data.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def transpose(self):
        """
        Returns a new Matrix object that is the transpose of the current matrix.
        """
        transposed_data = [[self.data[j][i] for j in range(self.rows)] for i in range(self.cols)]
        return Matrix(transposed_data)

    def add(self, other):
        """
        Adds the current matrix to another Matrix object other and returns a new Matrix object.
        Raises a ValueError if the matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same dimensions to add.")
        added_data = [[self.data[i][j] + other.data[i][j] for j in range(self.cols)] for i in range(self.rows)]
        return Matrix(added_data)

    def multiply(self, other):
        """
        Multiplies the current matrix with another Matrix object other and returns a new Matrix object.
        Raises a ValueError if the number of columns in the first matrix is not equal to the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to the number of rows in the second matrix.")
        multiplied_data = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(multiplied_data)

    def display(self):
        """
        Prints the matrix in a readable format.
        """
        for row in self.data:
            print(" ".join(map(str, row)))
