def can_form_palindrome(s):
    """
    Determines if the string can be transformed into a palindrome by removing at most one character.

    :param s: Input string consisting of lowercase English letters.
    :return: True if the string can be transformed into a palindrome by removing at most one character, False otherwise.
    """
    def is_palindrome_range(i, j):
        return all(s[k] == s[j - k + i] for k in range(i, j))

    for i in range(len(s) // 2):
        if s[i] != s[~i]:
            return is_palindrome_range(i + 1, len(s) - i - 1) or is_palindrome_range(i, len(s) - i - 2)
    return True

