class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self, initial_data=None):
        self.head = None
        if initial_data:
            for item in initial_data:
                self.append(item)

    def append(self, data):
        if not self.head:
            self.head = Node(data)
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = Node(data)

    def to_list(self):
        lst = []
        current = self.head
        while current:
            lst.append(current.data)
            current = current.next
        return lst

def insert_at_position(val, seq, pos):
    """
    Inserts a value into a sequence at a specified position.

    Parameters:
    val: The value to be inserted.
    seq: The sequence (list, tuple, string, or LinkedList) into which the value is to be inserted.
    pos: The position at which the value should be inserted.

    Returns:
    The modified sequence with the value inserted, or the original sequence if insertion is not possible.
    """
    if isinstance(seq, list):
        if pos < 0 or pos > len(seq):
            return seq
        return seq[:pos] + [val] + seq[pos:]

    elif isinstance(seq, tuple):
        if pos < 0 or pos > len(seq):
            return seq
        return seq[:pos] + (val,) + seq[pos:]

    elif isinstance(seq, str):
        if pos < 0 or pos > len(seq) or len(val) != 1:
            return seq
        return seq[:pos] + val + seq[pos:]

    elif isinstance(seq, LinkedList):
        if pos < 0:
            return seq

        new_node = Node(val)
        if pos == 0:
            new_node.next = seq.head
            seq.head = new_node
        else:
            current = seq.head
            current_pos = 0
            while current and current_pos < pos - 1:
                current = current.next
                current_pos += 1
            if not current:
                return seq
            new_node.next = current.next
            current.next = new_node
        return seq

    return seq

# For testing the LinkedList implementation
