def find_sub_array(list1, list2):
    """
    Determines if list2 is a contiguous sub-array of list1 without using any built-in slicing, searching, or comparison functions.

    :param list1: List of integers.
    :param list2: List of integers to check as a sub-array.
    :return: True if list2 is a sub-array of list1, False otherwise.
    """
    len1 = 0
    while True:
        try:
            list1[len1]
            len1 += 1
        except IndexError:
            break

    len2 = 0
    while True:
        try:
            list2[len2]
            len2 += 1
        except IndexError:
            break

    if len2 == 0:
        return True
    if len2 > len1:
        return False

    for i in range(len1 - len2 + 1):
        match = True
        for j in range(len2):
            if list1[i + j] != list2[j]:
                match = False
                break
        if match:
            return True

    return False
