def reverse_word_order(sentence):
    """
    Reverses the order of words in the given sentence without altering the characters within each word.

    :param sentence: A string containing words separated by spaces.
    :return: A string with the order of words reversed.
    """
    def find_word_start(index):
        """Finds the start of the next word in the sentence."""
        while index < len(sentence) and sentence[index] == ' ':
            index += 1
        return index

    def find_word_end(index):
        """Finds the end of the current word in the sentence."""
        while index < len(sentence) and sentence[index] != ' ':
            index += 1
        return index

    if not sentence:
        return ""

    words = []
    index = 0

    while index < len(sentence):
        index = find_word_start(index)
        if index >= len(sentence):
            break

        end = find_word_end(index)
        word = ""
        for i in range(index, end):
            word += sentence[i]

        words.append(word)
        index = end

    reversed_words = []
    for i in range(len(words) - 1, -1, -1):
        reversed_words.append(words[i])

    result = ""
    for i in range(len(reversed_words)):
        result += reversed_words[i]
        if i < len(reversed_words) - 1:
            result += " "

    return result
