def can_add_word(grid, word, row, col, direction):
    """
    Determines if a word can be placed in a 20x20 grid starting from a specified position
    either horizontally or vertically without touching any other letters except at the corners.

    :param grid: List[List[str]] - A 20x20 grid of characters.
    :param word: str - The word to be placed.
    :param row: int - The starting row index.
    :param col: int - The starting column index.
    :param direction: str - The direction of placement ('horizontal' or 'vertical').
    :return: bool - True if the word can be placed, False otherwise.
    """
    rows = len(grid)
    cols = len(grid[0])
    word_length = len(word)

    if direction == 'horizontal':
        if col + word_length > cols:
            return False

        for i in range(col, col + word_length):
            if row > 0 and grid[row - 1][i] != '.':
                return False

        for i in range(col, col + word_length):
            if row < rows - 1 and grid[row + 1][i] != '.':
                return False

        for i in range(col, col + word_length):
            if grid[row][i] not in [word[i - col], '.'] or (i - col > 0 and row > 0 and grid[row - 1][i - 1] != '.') or (
                    i - col > 0 and row < rows - 1 and grid[row + 1][i - 1] != '.'):
                return False
        return True

    elif direction == 'vertical':
        if row + word_length > rows:
            return False

        for i in range(row, row + word_length):
            if col > 0 and grid[i][col - 1] != '.':
                return False

        for i in range(row, row + word_length):
            if col < cols - 1 and grid[i][col + 1] != '.':
                return False

        for i in range(row, row + word_length):
            if grid[i][col] not in [word[i - row], '.'] or (i - row > 0 and col > 0 and grid[i - 1][col - 1] != '.') or (
                    i - row > 0 and col < cols - 1 and grid[i - 1][col + 1] != '.'):
                return False
        return True

    else:
        return False
