def convert_to_strings(data, encoding="utf8"):
    """
    Recursively converts all bytes and byte-like objects at the deepest level of a nested data structure to strings.

    :param data: The nested data structure to be processed.
    :param encoding: The encoding to use for converting bytes to strings (default is "utf8").
    :return: The processed data structure with bytes converted to strings.
    """
    def convert(item):
        if isinstance(item, bytes):
            return item.decode(encoding)
        elif isinstance(item, (list, tuple)):
            return type(item)(convert(sub_item) for sub_item in item)
        elif isinstance(item, dict):
            return {convert(key): convert(value) for key, value in item.items()}
        else:
            return item

    return convert(data)
