        if name in self._inventory:
            self._inventory[name] += quantity
        else:
            self._inventory[name] = quantity

    def remove_item(self, name: str, quantity: int) -> None:
        """
        Removes the specified quantity of the item from the inventory.
        If the quantity to remove is greater than or equal to the current quantity of the item,
        the item is completely removed from the inventory.
        """
        if name in self._inventory:
            if self._inventory[name] <= quantity:
                del self._inventory[name]
            else:
                self._inventory[name] -= quantity

    def get_inventory(self) -> List[Tuple[str, int]]:
        """
        Returns a list of tuples representing the current items and their quantities in the inventory.
        """
        return list(self._inventory.items())
