def hexToByte(hex_string):
    """
    Converts a hexadecimal string to its corresponding ASCII string.

    Parameters:
    hex_string (str): A string of hexadecimal numbers separated by spaces.

    Returns:
    str: The ASCII string corresponding to the hexadecimal input, or an error message if the input is invalid.
    """
    def is_valid_hex_char(c):
        return '0' <= c <= '9' or 'a' <= c <= 'f' or 'A' <= c <= 'F'

    def hex_char_to_int(c):
        if '0' <= c <= '9':
            return ord(c) - ord('0')
        elif 'a' <= c <= 'f':
            return ord(c) - ord('a') + 10
        elif 'A' <= c <= 'F':
            return ord(c) - ord('A') + 10
        else:
            return None

    hex_values = hex_string.split()
    byte_string = bytearray()

    for hex_value in hex_values:
        if len(hex_value) != 2 or not (is_valid_hex_char(hex_value[0]) and is_valid_hex_char(hex_value[1])):
            return "Error: Invalid hexadecimal string"

        high_nibble = hex_char_to_int(hex_value[0])
        low_nibble = hex_char_to_int(hex_value[1])
        byte_value = (high_nibble << 4) | low_nibble
        byte_string.append(byte_value)

    return byte_string.decode('utf-8')
