def flatten_dict(d, parent_key='', sep='_'):
    """
    Flattens a nested dictionary, concatenating keys separated by sep.

    :param d: The dictionary to flatten.
    :param parent_key: The base key string to prepend to each key.
    :param sep: The separator between keys.
    :return: A new dictionary with flattened keys.
    """
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

