def compare_dicts(dict1, dict2):
    """
    Compares two dictionaries and returns a dictionary highlighting the differences.

    Parameters:
    dict1 (dict): The first dictionary.
    dict2 (dict): The second dictionary.

    Returns:
    dict: A dictionary representing the differences between dict1 and dict2.
    """
    diff = {}

    # Check for keys that are in either dict1 or dict2 but not both
    key_diff = set(dict1.keys()).symmetric_difference(set(dict2.keys()))

    for key in key_diff:
        if key in dict1:
            diff[key] = {"old": dict1[key], "new": None}
        else:
            diff[key] = {"old": None, "new": dict2[key]}

    # Check for differences in values for keys that are common in both dictionaries
    for key in set(dict1.keys()).intersection(set(dict2.keys())):
        if isinstance(dict1[key], dict) and isinstance(dict2[key], dict):
            nested_diff = compare_dicts(dict1[key], dict2[key])
            if nested_diff:
                diff[key] = nested_diff
        elif dict1[key] != dict2[key]:
            diff[key] = {"old": dict1[key], "new": dict2[key]}

    return diff

