def fibonacci(n):
    """
    Calculate the nth Fibonacci number using a naive recursive approach.

    :param n: The position in the Fibonacci sequence (0-indexed).
    :return: The nth Fibonacci number.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)


def fibonacci_memo(n, memo={}):
    """
    Calculate the nth Fibonacci number using memoization to optimize the recursive approach.

    :param n: The position in the Fibonacci sequence (0-indexed).
    :param memo: A dictionary to store previously computed Fibonacci numbers.
    :return: The nth Fibonacci number.
    """
    if n in memo:
        return memo[n]
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        memo[n] = fibonacci_memo(n-1, memo) + fibonacci_memo(n-2, memo)
        return memo[n]
