def extract_numbers_from_string(input_string):
    """
    Recursively extracts digits from the input string and returns them as a new string.

    :param input_string: A string containing a mix of digits and non-digit characters.
    :return: A string containing only the digits from the input string, in their original order.
    """
    def is_digit(char):
        """
        Recursively checks if a character is a digit.

        :param char: A single character string.
        :return: True if the character is a digit, False otherwise.
        """
        if not char:
            return False
        if ord(char) >= ord('0') and ord(char) <= ord('9'):
            return True
        return False

    def extract_digits(s):
        """
        Recursively extracts digits from the string s.

        :param s: The string from which digits are to be extracted.
        :return: A string containing only the digits from s, in their original order.
        """
        if not s:
            return ""
        if is_digit(s[0]):
            return s[0] + extract_digits(s[1:])
        else:
            return extract_digits(s[1:])

    return extract_digits(input_string)
