def split_expression(s):
    """
    Splits the given mathematical expression into two parts at the first occurrence
    of an operator not enclosed within any nested parentheses.

    :param s: A string representing a valid mathematical expression.
    :return: A tuple (left_part, operator, right_part) if an operator outside
             parentheses is found, otherwise returns an error message.
    """
    stack = []
    operators = {'+', '-', '*', '/'}

    for index, char in enumerate(s):
        if char == '(':
            stack.append(index)
        elif char == ')':
            if stack:
                stack.pop()
        elif char in operators:
            if not stack:
                left_part = s[:index].strip()
                right_part = s[index+1:].strip()
                return left_part, char, right_part

    return "Error: No operator found outside parentheses."
