def maxProfitWithRise(prices):
    """
    Calculate the maximum profit from a list of stock prices with the constraint
    that the stock can only be sold on a day when the stock price is strictly
    higher than the price on the previous day.

    :param prices: List[int] - A list of integers representing daily stock prices.
    :return: int - The maximum profit that can be made.
    """
    def helper(index, min_price, max_profit):
        if index == len(prices):
            return max_profit

        current_price = prices[index]

        if index > 0 and current_price > prices[index - 1]:
            potential_profit = current_price - min_price
            max_profit = max(max_profit, potential_profit)

        min_price = min(min_price, current_price)

        return helper(index + 1, min_price, max_profit)

    return helper(0, float('inf'), 0)
