def length_of_lis(nums):
    """
    Returns the length of the longest increasing subsequence in the list of integers.

    :param nums: List[int] - A list of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not nums:
        return 0
    n = len(nums)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

