class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def add(self, value):
        """
        Adds a new node with the specified value to the end of the list.
        """
        new_node = Node(value)
        if not self.head:
            self.head = new_node
            return
        last_node = self.head
        while last_node.next:
            last_node = last_node.next
        last_node.next = new_node

    def remove(self, value):
        """
        Removes the first node with the specified value from the list.
        """
        if not self.head:
            return

        if self.head.value == value:
            self.head = self.head.next
            return

        current_node = self.head
        while current_node.next:
            if current_node.next.value == value:
                current_node.next = current_node.next.next
                return
            current_node = current_node.next

    def display(self):
        """
        Prints the values of the nodes in the list, separated by " -> ".
        """
        current_node = self.head
        elements = []
        while current_node:
            elements.append(current_node.value)
            current_node = current_node.next
        print(" -> ".join(map(str, elements)) if elements else "")
