class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Insert a new node with the given key in the BST."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert_recursively(self.root, key)

    def _insert_recursively(self, node, key):
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert_recursively(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert_recursively(node.right, key)

    def search(self, key):
        """Search for a node with the given key in the BST."""
        return self._search_recursively(self.root, key)

    def _search_recursively(self, node, key):
        if node is None or node.val == key:
            return node
        if key < node.val:
            return self._search_recursively(node.left, key)
        return self._search_recursively(node.right, key)

    def delete(self, key):
        """Delete the node with the given key from the BST."""
        self.root = self._delete_recursively(self.root, key)

    def _delete_recursively(self, node, key):
        if node is None:
            return node

        if key < node.val:
            node.left = self._delete_recursively(node.left, key)
        elif key > node.val:
            node.right = self._delete_recursively(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            node.val = self._min_value_node(node.right).val
            node.right = self._delete_recursively(node.right, node.val)

        return node

    def _min_value_node(self, node):
        """Helper function to find the node with the minimum value in the BST."""
        current = node
        while current.left is not None:
            current = current.left
        return current

    def in_order_traversal(self):
        """Perform in-order traversal of the BST."""
        return self._in_order_recursively(self.root)

    def _in_order_recursively(self, node):
        res = []
        if node:
            res = self._in_order_recursively(node.left)
            res.append(node.val)
            res = res + self._in_order_recursively(node.right)
        return res

    def pre_order_traversal(self):
        """Perform pre-order traversal of the BST."""
        return self._pre_order_recursively(self.root)

    def _pre_order_recursively(self, node):
        res = []
        if node:
            res.append(node.val)
            res = res + self._pre_order_recursively(node.left)
            res = res + self._pre_order_recursively(node.right)
        return res

    def post_order_traversal(self):
        """Perform post-order traversal of the BST."""
        return self._post_order_recursively(self.root)

    def _post_order_recursively(self, node):
        res = []
        if node:
            res = self._post_order_recursively(node.left)
            res = res + self._post_order_recursively(node.right)
            res.append(node.val)
        return res
