def is_balanced(s: str) -> bool:
    """
    Determines if a string has balanced parentheses, brackets, and braces.

    :param s: A string containing only the characters '(', ')', '[', ']', '{', and '}'.
    :return: True if the string is balanced, otherwise False.
    """
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}
    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)
    return not stack
