def is_balanced(s: str) -> bool:
    """
    Determines if the input string of brackets is balanced.

    Args:
    s (str): A string consisting of '(', ')', '{', '}', '[', and ']'.

    Returns:
    bool: True if the string is balanced, False otherwise.
    """
    matching_bracket = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in matching_bracket.values():
            stack.append(char)
        elif char in matching_bracket.keys():
            if not stack or matching_bracket[char] != stack.pop():
                return False
        else:
            return False

    return not stack
