def title_case(text):
    """
    Transforms a given string such that the first character of each word is capitalized,
    and the rest of the characters in each word are in lowercase. If a word contains an
    apostrophe, all characters following the apostrophe remain in their original case.

    :param text: A string consisting of words separated by single spaces.
    :return: A transformed string with the specified capitalization rules.
    """
    def capitalize_word(word):
        apostrophe_index = word.find("'")
        if apostrophe_index != -1:
            return word[0].upper() + word[1:apostrophe_index].lower() + word[apostrophe_index:]
        else:
            return word.capitalize()

    return ' '.join(capitalize_word(word) for word in text.split())
