        return None

    def peek(self):
        """Returns the top item of the stack without removing it. Returns None if the stack is empty."""
        if not self.is_empty():
            return self.items[-1]
        return None

    def size(self):
        """Returns the number of items in the stack."""
        return len(self.items)

# Queue implementation using a list
class Queue:
    def __init__(self):
        self.items = []

    def is_empty(self):
        """Returns True if the queue is empty, otherwise False."""
        return len(self.items) == 0

    def enqueue(self, item):
        """Adds an item to the end of the queue."""
        self.items.append(item)

    def dequeue(self):
        """Removes and returns the front item of the queue. Returns None if the queue is empty."""
        if not self.is_empty():
            return self.items.pop(0)
        return None

    def peek(self):
        """Returns the front item of the queue without removing it. Returns None if the queue is empty."""
        if not self.is_empty():
            return self.items[0]
        return None

    def size(self):
        """Returns the number of items in the queue."""
        return len(self.items)
