class Graph:
    def __init__(self):
        self.adj_list = {}

    def add_edge(self, u, v):
        """
        Adds an undirected edge between vertices u and v.
        """
        if u not in self.adj_list:
            self.adj_list[u] = set()
        if v not in self.adj_list:
            self.adj_list[v] = set()

        self.adj_list[u].add(v)
        self.adj_list[v].add(u)

    def remove_edge(self, u, v):
        """
        Removes the edge between vertices u and v if it exists.
        """
        if u in self.adj_list and v in self.adj_list[u]:
            self.adj_list[u].remove(v)
        if v in self.adj_list and u in self.adj_list[v]:
            self.adj_list[v].remove(u)

    def neighbors(self, vertex):
        """
        Returns a list of all vertices adjacent to vertex.
        """
        return list(self.adj_list.get(vertex, []))

    def is_connected(self, u, v):
        """
        Returns True if there is a path between vertices u and v, otherwise returns False.
        """
        if u not in self.adj_list or v not in self.adj_list:
            return False
        visited = set()
        stack = [u]
        while stack:
            node = stack.pop()
            if node == v:
                return True
            visited.add(node)
            stack.extend(self.adj_list[node] - visited)
        return False
