def is_all_even(input_dict):
    """
    Determines if all values in the input dictionary are even numbers.

    Parameters:
    input_dict (dict): A dictionary with string keys and integer values.

    Returns:
    bool: True if all values are even, False otherwise.
    """
    # Check if the dictionary is empty, consider it as all even
    if not input_dict:
        return True

    # Recursive function to check evenness of each value
    def check_even(index):
        # Base case: If index is out of bounds, all values were even
        if index == len(input_dict):
            return True
        # Check if current value is even
        elif list(input_dict.values())[index] % 2 != 0:
            return False
        # Recur for the next index
        else:
            return check_even(index + 1)

    # Start the recursion from the first index
    return check_even(0)
