def find_value(pointer_str, data_dict):
    """
    Retrieves the value pointed to by pointer_str within the nested dictionary data_dict.

    :param pointer_str: A string of keys/indices separated by "->".
    :param data_dict: A nested dictionary containing the data.
    :return: The value pointed to by pointer_str, reversed if it's a string or list, or None if invalid.
    """
    pointers = pointer_str.split('->')
    current_value = data_dict

    for pointer in pointers:
        try:
            index = int(pointer)
            if isinstance(current_value, list) and 0 <= index < len(current_value):
                current_value = current_value[index]
            else:
                return None
        except ValueError:
            if isinstance(current_value, dict) and pointer in current_value:
                current_value = current_value[pointer]
            else:
                return None

    if isinstance(current_value, list):
        return current_value[::-1]
    elif isinstance(current_value, str):
        return current_value[::-1]
    else:
        return current_value
