def miller_rabin_twist(n, k):
    """
    Determines if a number n is likely to be prime using a modified Miller-Rabin test.

    Args:
    n (int): The number to test for primality.
    k (int): The number of iterations to run the test.

    Returns:
    bool: True if n might be prime after k tests, False if n is definitely composite.
    """
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False

    d = n - 1
    r = 0
    while d % 2 == 0:
        r += 1
        d //= 2

    def is_composite(a, d, n, r):
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            return False
        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                return False
        return True

    for i in range(1, k + 1):
        a = (1 << (1 << i)) + 1
        if a >= n:
            break
        if is_composite(a, d, n, r):
            return False

    return True
```

