def validate_color(color):
    """
    Validates if the input is a valid CSS color in hexadecimal format.

    Parameters:
    color (str, list, tuple): The color to validate, which can be a string, list, or tuple.

    Returns:
    bool, list, tuple: True if the color is valid, False otherwise. For lists and tuples,
                       returns a list or tuple of the same structure with boolean values.
    """
    def is_hex_digit(c):
        return ('0' <= c <= '9') or ('a' <= c <= 'f') or ('A' <= c <= 'F')

    def is_valid_hex_color(s):
        if not isinstance(s, str):
            return False
        if len(s) not in (4, 7) or s[0] != '#':
            return False
        return all(is_hex_digit(c) for c in s[1:])

    if isinstance(color, (list, tuple)):
        return type(color)(validate_color(c) for c in color)
    else:
        return is_valid_hex_color(color)
