def min_distance_recursive(word1, word2):
    """
    Computes the minimum number of operations required to transform word1 into word2 using a recursive approach.

    :param word1: The original string.
    :param word2: The target string.
    :return: The minimum number of operations required.
    """
    def helper(i, j):
        if i == 0:
            return j
        if j == 0:
            return i
        if word1[i - 1] == word2[j - 1]:
            return helper(i - 1, j - 1)
        else:
            insert = helper(i, j - 1) + 1
            delete = helper(i - 1, j) + 1
            replace = helper(i - 1, j - 1) + 1
            return min(insert, delete, replace)

    return helper(len(word1), len(word2))

