def memoize(f):
    """Decorator to memoize results of function f for prime inputs."""
    memo = {}
    def memoized_function(*args):
        if args[0] in memo:
            return memo[args[0]]
        result = f(*args)
        if is_prime(args[0]):
            memo[args[0]] = result
        return result
    return memoized_function

@memoize
def fibonacci(n):
    """Calculate the nth Fibonacci number using recursion."""
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)

