class Stack:
    def __init__(self):
        """Initialize an empty list to act as the stack."""
        self.items = []

    def is_empty(self):
        """Check if the stack is empty."""
        return len(self.items) == 0

    def push(self, item):
        """Add an item to the top of the stack."""
        self.items.append(item)

    def pop(self):
        """Remove the item from the top of the stack and return it.
        If the stack is empty, return the string "Stack is empty, cannot pop".
        """
        if not self.is_empty():
            return self.items.pop()
        else:
            return "Stack is empty, cannot pop"

    def peek(self):
        """Return the item at the top of the stack without removing it.
        If the stack is empty, return the string "Stack is empty, nothing to peek".
        """
        if not self.is_empty():
            return self.items[-1]
        else:
            return "Stack is empty, nothing to peek"

# Example usage:
if __name__ == "__main__":
    stack = Stack()
    print("Is stack empty?", stack.is_empty())
    stack.push(10)
    stack.push(20)
    stack.push(30)
    print("Top item in stack:", stack.peek())
    print("Item popped from stack:", stack.pop())
    print("Top item in stack after pop:", stack.peek())
    print("Is stack empty after pops?", stack.is_empty())
