def factors_with_prime_status(N):
    """
    Find all factors of N and determine if each factor is prime.

    :param N: Integer to find factors for.
    :return: List of tuples (factor, is_prime).
    """
    factors = []
    for i in range(1, int(N**0.5) + 1):
        if N % i == 0:
            factors.append((i, is_prime(i)))
            if i != N // i:
                factors.append((N // i, is_prime(N // i)))
    return sorted(factors)

