def infix_to_rpn(expression):
    """
    Convert an infix expression to a postfix expression (Reverse Polish Notation).

    :param expression: A string representing the infix expression.
    :return: A string representing the postfix expression.
    """
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    output = []
    operators = []

    for char in expression.split():
        if char.isdigit():
            output.append(char)
        elif char in precedence:
            while (operators and operators[-1] != '(' and
                   precedence[operators[-1]] >= precedence[char]):
                output.append(operators.pop())
            operators.append(char)
        elif char == '(':
            operators.append(char)
        elif char == ')':
            while operators and operators[-1] != '(':
                output.append(operators.pop())
            operators.pop()  # Remove '(' from stack

    while operators:
        output.append(operators.pop())

    return ' '.join(output)

# Example usage:
equation = "3 + 4 * 2 / ( 1 - 5 )"
rpn = infix_to_rpn(equation)
print(rpn)  # Output: 3 4 2 * 1 5 - / +
