def extract_middle_value(lst: list) -> any:
    """
    Extracts the innermost value of the middle dictionary in a list of dictionaries.

    Parameters:
    lst (list): A list containing an odd number of dictionaries, each with a single key-value pair.

    Returns:
    any: The innermost value of the middle dictionary.

    Raises:
    ValueError: If the list does not contain an odd number of dictionaries.
    """
    if len(lst) % 2 == 0:
        raise ValueError("List does not contain an odd number of dictionaries")

    middle_index = len(lst) // 2
    middle_dict = lst[middle_index]

    def find_innermost_value(d):
        if isinstance(d, dict):
            for key in d:
                return find_innermost_value(d[key])
        else:
            return d

    return find_innermost_value(middle_dict)
