import json
import re

def extract_emails(obj):
    """
    Recursively extracts all unique email addresses from a nested JSON object.

    :param obj: The JSON object (can be a dict, list, or string).
    :return: A set of unique email addresses.
    """
    email_pattern = re.compile(r"[a-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\.[a-z0-9!#$%&'*+/=?^_`{|}~-]+)*@(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z0-9](?:[a-z0-9-]*[a-z0-9])?")
    emails = set()

    if isinstance(obj, dict):
        for value in obj.values():
            emails.update(extract_emails(value))
    elif isinstance(obj, list):
        for item in obj:
            emails.update(extract_emails(item))
    elif isinstance(obj, str):
        matches = email_pattern.findall(obj)
        if matches:
            emails.update(matches)

    return emails

