def memoize(f):
    """
    Decorator function to cache results of the function `f`.
    """
    cache = {}
    def decorated_function(*args):
        if args in cache:
            return cache[args]
        result = f(*args)
        cache[args] = result
        return result
    return decorated_function

@memoize
def fibonacci(n):
    """
    Computes the nth Fibonacci number using memoization for efficiency.
    """
    if n in (0, 1):
        return n
    return fibonacci(n-1) + fibonacci(n-2)

