def find_value_by_key(json_obj, target_key):
    """
    Recursively searches for a target key in a JSON object and returns the associated value.

    :param json_obj: A well-formed JSON object (dict or list).
    :param target_key: The key to search for in the JSON object.
    :return: The value associated with the target key if found, otherwise None.
    """
    if isinstance(json_obj, dict):
        for key, value in json_obj.items():
            if key == target_key:
                return value
            elif isinstance(value, (dict, list)):
                result = find_value_by_key(value, target_key)
                if result is not None:
                    return result
    elif isinstance(json_obj, list):
        for item in json_obj:
            result = find_value_by_key(item, target_key)
            if result is not None:
                return result
    return None

