def remove_empty_values(d):
    """
    Recursively removes empty values from a nested dictionary.

    Args:
    d (dict): The nested dictionary to process.

    Returns:
    dict: A new dictionary with empty values removed.
    """
    def is_non_empty(value):
        return value not in ('', [], {}, set()) and value is not None

    def clean_dict(d):
        if isinstance(d, dict):
            return {k: clean_dict(v) for k, v in d.items() if is_non_empty(clean_dict(v))}
        elif isinstance(d, list):
            return [clean_dict(i) for i in d if is_non_empty(clean_dict(i))]
        else:
            return d

    return clean_dict(d)
