def bubble_sort_dictionary(d):
    """
    Sorts the keys of a dictionary using bubble sort.

    :param d: Dictionary to be sorted.
    :return: List of sorted keys.
    """
    keys = list(d.keys())
    n = len(keys)
    for i in range(n):
        for j in range(0, n-i-1):
            if keys[j] > keys[j+1]:
                keys[j], keys[j+1] = keys[j+1], keys[j]
    return keys

def sort_nested_dict(input_dict):
    """
    Sorts the countries and states in the input dictionary alphabetically.

    :param input_dict: Dictionary with countries as keys and states as nested dictionaries.
    :return: Sorted dictionary with countries and states in alphabetical order.
    """
    sorted_countries = bubble_sort_dictionary(input_dict)
    sorted_countries_dict = {}

    for country in sorted_countries:
        sorted_states = bubble_sort_dictionary(input_dict[country])
        sorted_states_dict = {}

        for state in sorted_states:
            sorted_states_dict[state] = input_dict[country][state]

        sorted_countries_dict[country] = sorted_states_dict

    return sorted_countries_dict

