import math
from functools import reduce
from operator import mul

def is_prime(n):
    """Check if a number is prime."""
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def prime_factors(n):
    """Return the list of prime factors of a number."""
    factors = []
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 2:
        factors.append(n)
    return factors

def is_perfect_square(n):
    """Check if a number is a perfect square."""
    root = int(math.sqrt(n))
    return n == root * root

def coin_combinations(coins, target, k, m, current_combination=[], used_coins=0, current_value=0, current_product=1):
    """Recursively find all valid combinations of coins."""
    if used_coins == k:
        if current_value == target and is_perfect_square(current_product) and len(set(prime_factors(current_product))) == m:
            print(f"Combination: {current_combination} with value: {current_value} Total product: {current_product}")
        return
    for i in range(len(coins)):
        new_value = current_value + coins[i]
        new_product = current_product * coins[i]
        if new_value <= target:
            coin_combinations(coins[i:], target, k, m, current_combination + [coins[i]], used_coins + 1, new_value, new_product)

def select_coins(n, S, k, m):
    """Generate coins and find all valid combinations."""
    coins = list(range(1, n + 1))
    coin_combinations(coins, S, k, m)

