def fib_sequence(n):
    """Generator function to yield Fibonacci numbers up to the n-th number
    in the sequence only if the number is a prime number."""
    a, b = 0, 1
    count = 0
    while count < n:
        next_fib = a
        a, b = b, a + b
        if is_prime(next_fib):
            yield next_fib
            count += 1
