def is_balanced(expression: str) -> bool:
    """
    Determines if the given expression of parentheses, brackets, and braces is balanced.

    :param expression: A string containing balanced parentheses, brackets, and braces.
    :return: True if the expression is balanced, False otherwise.
    """
    matching_pairs = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in expression:
        if char in matching_pairs.values():
            stack.append(char)
        elif char in matching_pairs.keys():
            if not stack or stack.pop() != matching_pairs[char]:
                return False

    return not stack

