def count_words(strings):
    """
    Counts the occurrences of each word in a list of strings.

    :param strings: List of strings to process.
    :return: Dictionary with words as keys and their counts as values.
    """
    word_count = {}
    for string in strings:
        words = string.split()
        for word in words:
            if word in word_count:
                word_count[word] += 1
            else:
                word_count[word] = 1
    return word_count

