def hex_encode_string(s):
    """
    Recursively converts a string into its hexadecimal representation based on Unicode code points.

    :param s: Input string to be converted.
    :return: Hexadecimal string representation of the input string.
    """
    # Base case: if the string is empty, return an empty string
    if s == '':
        return ''

    # Recursive case: encode the first character and append the result of the rest of the string
    def to_hex(char):
        """
        Converts a single character to its two-digit hexadecimal representation.

        :param char: Character to be converted.
        :return: Two-digit hexadecimal string.
        """
        # Convert character to its Unicode code point
        code_point = ord(char)

        # Convert the code point to a two-digit hexadecimal number
        def digit_to_char(digit):
            """
            Converts a single digit to its corresponding hexadecimal character.

            :param digit: Integer digit (0-15).
            :return: Hexadecimal character.
            """
            if digit < 10:
                return chr(digit + ord('0'))
            else:
                return chr(digit - 10 + ord('a'))

        # Recursive helper function to convert a number to a two-digit hex string
        def number_to_hex(number):
            """
            Converts a number to its two-digit hexadecimal string representation.

            :param number: Integer number to be converted.
            :return: Two-digit hexadecimal string.
            """
            if number == 0:
                return '00'
            elif number < 16:
                return '0' + digit_to_char(number)
            else:
                return digit_to_char(number // 16) + digit_to_char(number % 16)

        return number_to_hex(code_point)

    return to_hex(s[0]) + hex_encode_string(s[1:])
