class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Insert a new node with the given key into the BST."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert_recursively(self.root, key)

    def _insert_recursively(self, node, key):
        """Recursively insert a new node with the given key into the BST."""
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert_recursively(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert_recursively(node.right, key)

    def search(self, key):
        """Search for a node with the given key in the BST and return the node if found, otherwise return None."""
        return self._search_recursively(self.root, key)

    def _search_recursively(self, node, key):
        """Recursively search for a node with the given key in the BST."""
        if node is None or node.val == key:
            return node
        if key < node.val:
            return self._search_recursively(node.left, key)
        else:
            return self._search_recursively(node.right, key)

    def in_order_traversal(self):
        """Perform an in-order traversal of the BST and return the keys in a sorted list."""
        return self._in_order_traversal_recursively(self.root)

    def _in_order_traversal_recursively(self, node):
        """Recursively perform an in-order traversal of the BST."""
        if node is None:
            return []
        result = []
        result += self._in_order_traversal_recursively(node.left)
        result.append(node.val)
        result += self._in_order_traversal_recursively(node.right)
        return result
