class Vector2D:
    def __init__(self, x, y):
        """Initialize the vector with coordinates x and y."""
        self.x = x
        self.y = y

    def __add__(self, other):
        """Return a new Vector2D object representing the sum of the current vector and other."""
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        """Return a new Vector2D object representing the difference between the current vector and other."""
        return Vector2D(self.x - other.x, self.y - other.y)

    def dot_product(self, other):
        """Return the dot product of the current vector and other."""
        return self.x * other.x + self.y * other.y

    def __str__(self):
        """Return a string representation of the vector."""
        return f"Vector2D({self.x}, {self.y})"
