class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Insert a new node with the given key in the BST."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert(node.right, key)

    def search(self, key):
        """Search for a node with the given key in the BST."""
        return self._search(self.root, key)

    def _search(self, node, key):
        if node is None or node.val == key:
            return node is not None
        if key < node.val:
            return self._search(node.left, key)
        else:
            return self._search(node.right, key)

    def delete(self, key):
        """Delete a node with the given key from the BST."""
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        if node is None:
            return node

        if key < node.val:
            node.left = self._delete(node.left, key)
        elif key > node.val:
            node.right = self._delete(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            temp = self._min_value_node(node.right)
            node.val = temp.val
            node.right = self._delete(node.right, temp.val)

        return node

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current

    def inorder_traversal(self):
        """Return a list of keys in the BST in sorted order."""
        return self._inorder_traversal(self.root)

    def _inorder_traversal(self, node):
        res = []
        if node is not None:
            res = self._inorder_traversal(node.left)
            res.append(node.val)
            res = res + self._inorder_traversal(node.right)
        return res

    def preorder_traversal(self):
        """Return a list of keys in the BST in preorder."""
        return self._preorder_traversal(self.root)

    def _preorder_traversal(self, node):
        res = []
        if node is not None:
            res.append(node.val)
            res = res + self._preorder_traversal(node.left)
            res = res + self._preorder_traversal(node.right)
        return res

    def postorder_traversal(self):
        """Return a list of keys in the BST in postorder."""
        return self._postorder_traversal(self.root)

    def _postorder_traversal(self, node):
        res = []
        if node is not None:
            res = self._postorder_traversal(node.left)
            res = res + self._postorder_traversal(node.right)
            res.append(node.val)
        return res
