def length_of_lis(nums):
    """
    Returns the length of the longest increasing subsequence in the list of integers.

    :param nums: List[int] - The list of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    tails = []

    for num in nums:
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid

        if left == len(tails):
            tails.append(num)
        else:
            tails[left] = num

    return len(tails)


def longest_increasing_subsequence(nums):
    """
    Returns the longest increasing subsequence in the list of integers.

    :param nums: List[int] - The list of integers.
    :return: List[int] - The longest increasing subsequence.
    """
    if not nums:
        return []

    prev_index = [-1] * len(nums)
    tails = []

    for i, num in enumerate(nums):
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid][1] < num:
                left = mid + 1
            else:
                right = mid

        if left == len(tails):
            if tails:
                prev_index[i] = tails[-1][0]
            tails.append((i, num))
        else:
            prev_index[i] = tails[left-1][0] if left > 0 else -1
            tails[left] = (i, num)

    lis = []
    if tails:
        curr_index = tails[-1][0]
        while curr_index != -1:
            lis.append(nums[curr_index])
            curr_index = prev_index[curr_index]
        lis.reverse()
    return lis


# Test the function
