def merge_arrays(arr1, arr2):
    """
    Merges two sorted arrays into a single sorted array without duplicates.
    Each element in the resulting array is squared.

    :param arr1: List[int] - First sorted array.
    :param arr2: List[int] - Second sorted array.
    :return: List[int] - Merged sorted array with unique squared elements.
    """
    i, j = 0, 0
    result = []
    n1, n2 = len(arr1), len(arr2)

    while i < n1 and j < n2:
        if arr1[i] < arr2[j]:
            if not result or result[-1] != arr1[i] ** 2:
                result.append(arr1[i] ** 2)
            i += 1
        elif arr1[i] > arr2[j]:
            if not result or result[-1] != arr2[j] ** 2:
                result.append(arr2[j] ** 2)
            j += 1
        else:
            if not result or result[-1] != arr1[i] ** 2:
                result.append(arr1[i] ** 2)
            i += 1
            j += 1

    while i < n1:
        if not result or result[-1] != arr1[i] ** 2:
            result.append(arr1[i] ** 2)
        i += 1

    while j < n2:
        if not result or result[-1] != arr2[j] ** 2:
            result.append(arr2[j] ** 2)
        j += 1

    return result

