import json
import logging
import sys

class Application:
    def __init__(self):
        # Initialize application settings
        self.settings = {
            "theme": "default",
            "language": "en",
            "preferences": {
                "notifications": True,
                "privacy": {
                    "track_usage": False,
                    "send_statistics": False
                }
            }
        }

    def apply_configuration(self, config):
        """
        Recursively applies the given configuration to the application settings.

        :param config: A dictionary containing the configuration to apply.
        """
        try:
            def apply_recursive(original, updates):
                for key, value in updates.items():
                    if isinstance(value, dict) and key in original and isinstance(original[key], dict):
                        apply_recursive(original[key], value)
                    elif key in original:
                        original[key] = value
            apply_recursive(self.settings, config)
        except Exception as e:
            logging.error(f"Error applying configuration: {e}")
            sys.exit(1)

def read_config(file_path):
    """
    Reads and parses the JSON configuration file.

    :param file_path: A string representing the path to the JSON configuration file.
    :return: A dictionary containing the parsed configuration.
    """
    try:
        with open(file_path, 'r') as file:
            config = json.load(file)
        return config
    except FileNotFoundError:
        logging.error(f"Configuration file '{file_path}' was not found.")
        sys.exit(1)
    except json.JSONDecodeError:
        logging.error("Configuration file is not a valid JSON.")
        sys.exit(1)

def main(config_file):
    """
    Main function to load and apply the configuration to the application.

    :param config_file: A string representing the path to the JSON configuration file.
    """
    logging.basicConfig(level=logging.INFO)
    logging.info(f"Loading configuration from {config_file}")
    config = read_config(config_file)
    logging.info(f"Configuration loaded: {config}")
    app = Application()
    app.apply_configuration(config)
    logging.info(f"Updated application settings: {app.settings}")

if __name__ == "__main__":
    main("config.json")
