def get_longest_subsequence(numbers):
    """
    Returns the length of the longest increasing subsequence in the list of integers.

    :param numbers: List of integers
    :return: Length of the longest increasing subsequence
    """
    if not numbers:
        return 0

    lis = [1] * len(numbers)

    for i in range(1, len(numbers)):
        for j in range(0, i):
            if numbers[i] > numbers[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    return max(lis)
