def sum_of_primes_below(n):
    """
    Calculate the sum of all prime numbers less than a given number n.

    :param n: An integer representing the upper limit.
    :return: The sum of all prime numbers less than n.
    """
    if n <= 2:
        return 0

    sieve = [True] * n
    sieve[0] = sieve[1] = False

    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, n, i):
                sieve[j] = False

    return sum(index for index, value in enumerate(sieve) if value)
