def deep_copy(obj):
    """
    Recursively creates a deep copy of a nested dictionary, list, or tuple.

    :param obj: The object to be deep copied.
    :return: A new object that is a deep copy of the input.
    """
    if isinstance(obj, dict):
        result = {}
        for key, value in obj.items():
            result[key] = deep_copy(value)
        return result
    elif isinstance(obj, list):
        result = []
        for item in obj:
            result.append(deep_copy(item))
        return result
    elif isinstance(obj, tuple):
        result = []
        for item in obj:
            result.append(deep_copy(item))
        return tuple(result)
    else:
        return obj
