def power(x, n):
    """
    Computes x raised to the power of n using recursion.

    Parameters:
    x (float): The base number.
    n (int): The exponent, can be negative, zero, or positive.

    Returns:
    float: The result of x raised to the power of n.
    """
    # Base cases
    if n == 0:
        return 1
    elif n == 1:
        return x
    elif n == -1:
        return 1 / x

    # Recursive case for negative n
    if n < 0:
        return 1 / power(x, -n)

    # Recursive case for even n
    if n % 2 == 0:
        half_power = power(x, n // 2)
        return half_power * half_power
    else:
        # Recursive case for odd n
        return x * power(x, n - 1)
