class Matrix:
    def __init__(self, data):
        """
        Initialize the Matrix with the given 2D list data.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def add(self, other):
        """
        Add this matrix to another matrix and return the resulting matrix.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices dimensions must match for addition.")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def subtract(self, other):
        """
        Subtract another matrix from this matrix and return the resulting matrix.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices dimensions must match for subtraction.")
        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiply this matrix by another matrix and return the resulting matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must equal the number of rows in the second matrix.")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols))
             for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __str__(self):
        """
        Return a string representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])
