def min_piles(boxes):
    """
    Determine the minimal number of piles required to store all the boxes
    such that no two boxes of the same color are placed directly on top of each other.

    :param boxes: List of tuples, where each tuple contains (color, strength) of a box.
    :return: Integer, the minimal number of piles needed.
    """
    max_strength = {}

    for color, strength in boxes:
        if color in max_strength:
            if strength > max_strength[color]:
                max_strength[color] = strength
        else:
            max_strength[color] = strength

    return len(max_strength)

