def remove_line_breaks(input_string):
    """
    Replaces sequences of line breaks in the input string with a single space.
    If the input string is None, returns None.

    :param input_string: The string to process.
    :return: A new string with line breaks replaced by spaces, or None if input is None.
    """
    if input_string is None:
        return None

    result = []
    previous_was_line_break = False

    for char in input_string:
        if char in ('\n', '\r'):
            if not previous_was_line_break:
                result.append(' ')
                previous_was_line_break = True
        else:
            result.append(char)
            previous_was_line_break = False

