class LinkedList:
    def __init__(self):
        self.head = None

    def add_to_end(self, data):
        """
        Adds a new node with the given data to the end of the list.
        """
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            return
        last_node = self.head
        while last_node.next:
            last_node = last_node.next
        last_node.next = new_node

    def remove_by_value(self, value):
        """
        Removes the first node with the specified value from the list.
        """
        current = self.head
        previous = None
        while current and current.data != value:
            previous = current
            current = current.next
        if current is None:
            return  # Value not found in the list

        if previous is None:
            self.head = current.next  # Remove the head node
        else:
            previous.next = current.next

    def display(self):
        """
        Prints the elements of the list in order, separated by " -> ", and ending with "None".
        """
        current = self.head
        while current:
            print(current.data, end=" -> ")
            current = current.next
        print("None")  # Indicate the end of the list
