# Global dictionary for memoization
_fib_memo = {}

def optimize_fibonacci(func):
    """
    Decorator to optimize the fibonacci function using memoization.
    The memoization cache is shared across different instances of the fibonacci function.
    """
    def wrapper(n):
        """
        Wrapper function that checks the memoization cache before computing the fibonacci number.
        """
        if n in _fib_memo:
            return _fib_memo[n]
        else:
            result = func(n)
            _fib_memo[n] = result
            return result
    return wrapper

@optimize_fibonacci
def fibonacci(n):
    """
    Returns the nth Fibonacci number using memoization.
    """
    if n <= 1:
        return n
    else:
        return fibonacci(n-1) + fibonacci(n-2)
