def find_duplicates(lst):
    """
    Identifies all duplicate numbers in the list and returns a dictionary.
    The keys are the duplicate numbers, and the values are lists of indices
    where these numbers appear in the original list.

    :param lst: List of integers
    :return: Dictionary with duplicate numbers as keys and lists of indices as values
    """
    duplicates = {}
    for index, value in enumerate(lst):
        if value in duplicates:
            duplicates[value].append(index)
        else:
            duplicates[value] = [index]
    return {key: value for key, value in duplicates.items() if len(value) > 1}
