from collections import deque

def is_connected(edges):
    """
    Determines if an undirected graph is connected.

    :param edges: List of tuples representing edges in the graph.
    :return: True if the graph is connected, False otherwise.
    """
    if not edges:
        return True  # An empty graph is trivially connected

    adjacency_list = {}
    for a, b in edges:
        adjacency_list.setdefault(a, []).append(b)
        adjacency_list.setdefault(b, []).append(a)

    start_node = next(iter(adjacency_list), None)
    if start_node is None:
        return True  # No nodes in the graph, trivially connected

    visited = set()
    queue = deque([start_node])

    while queue:
        current_node = queue.popleft()
        visited.add(current_node)

        for neighbor in adjacency_list[current_node]:
            if neighbor not in visited:
                queue.append(neighbor)

    return len(visited) == len(adjacency_list)
