def isValidPhoneNumber(phoneNumber):
    """Validate a phone number based on specific criteria."""
    import re

    # Define regex patterns for the two valid phone number formats
    pattern1 = r'^\(\d{3}\)\d{3}-\d{4}$'
    pattern2 = r'^\d{3}-\d{3}-\d{4}$'

    # Check if the phone number matches any of the patterns
    if not re.match(pattern1, phoneNumber) and not re.match(pattern2, phoneNumber):
        return False

    # Extract area code, prefix, and line number from the phone number
    if re.match(pattern1, phoneNumber):
        area_code, prefix, line_number = phoneNumber[1:4], phoneNumber[5:8], phoneNumber[9:]
    else:
        area_code, prefix, line_number = phoneNumber[:3], phoneNumber[4:7], phoneNumber[8:]

    # Convert extracted parts to integers
    area_code = int(area_code)
    prefix = int(prefix)
    line_number = int(line_number)

    # Validate the area code
    if not (200 <= area_code <= 999) or not has_unique_digits(area_code):
        return False

    # Validate the prefix
    if not (200 <= prefix <= 999) or not is_prime(prefix):
        return False

    # Validate the line number
    if not (0 <= line_number <= 9999) or not sum_of_digits_is_even(line_number):
        return False

    return True
