class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with the given 2D list `data`.
        Raises a ValueError if the input is not a valid matrix.
        """
        if not data or not all(len(row) == len(data[0]) for row in data):
            raise ValueError("Matrix rows must be of the same length.")
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0])

    def __add__(self, other):
        """
        Adds two matrices.
        Raises a ValueError if the matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrix dimensions must match for addition.")
        result = [[self.data[i][j] + other.data[i][j] for j in range(self.cols)] for i in range(self.rows)]
        return Matrix(result)

    def __sub__(self, other):
        """
        Subtracts the second matrix from the first.
        Raises a ValueError if the matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrix dimensions must match for subtraction.")
        result = [[self.data[i][j] - other.data[i][j] for j in range(self.cols)] for i in range(self.rows)]
        return Matrix(result)

    def __mul__(self, other):
        """
        Multiplies two matrices.
        Raises a ValueError if the number of columns in the first matrix does not equal the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must equal the number of rows in the second matrix.")
        result = [[sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)] for i in range(self.rows)]
        return Matrix(result)

    def __str__(self):
        """
        Returns a string representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])

    def transpose(self):
        """
        Returns the transpose of the matrix.
        """
        result = [[self.data[j][i] for j in range(self.rows)] for i in range(self.cols)]
        return Matrix(result)

    def is_square(self):
        """
        Returns True if the matrix is square, otherwise returns False.
        """
        return self.rows == self.cols
