def binary_search(arr, target, low=0, high=None):
    """
    Recursively performs binary search on a sorted list to find the index of the target value.

    Parameters:
    arr (list of int): The sorted list of integers.
    target (int): The target integer to search for.
    low (int): The starting index of the search range.
    high (int): The ending index of the search range.

    Returns:
    int: The index of the target value if found, otherwise -1.
    """
    if high is None:
        high = len(arr) - 1

    if low > high:
        return -1

    mid = (low + high) // 2

    if arr[mid] == target:
        return mid
    elif arr[mid] > target:
        return binary_search(arr, target, low, mid - 1)
    else:
        return binary_search(arr, target, mid + 1, high)
