class ShoppingCart:
    def __init__(self):
        """Initialize an empty dictionary to store cart items and their quantities."""
        self.items = {}

    def add_item(self, product_name, quantity):
        """Add a specified quantity of a product to the cart. If the product already exists, update its quantity."""
        if product_name in self.items:
            self.items[product_name] += quantity
        else:
            self.items[product_name] = quantity

    def remove_item(self, product_name, quantity):
        """Remove a specified quantity of a product from the cart. If the quantity to remove is greater than or equal to the current quantity, remove the product entirely."""
        if product_name in self.items:
            if quantity >= self.items[product_name]:
                del self.items[product_name]
            else:
                self.items[product_name] -= quantity

    def get_total_items(self):
        """Calculate and return the total number of items in the cart."""
        return sum(self.items.values())

    def clear_cart(self):
        """Clear all items from the cart."""
        self.items = {}
