def extract_values(json_data, target_key):
    """
    Extracts all values associated with a specific key from a JSON object.

    :param json_data: A dictionary representing the JSON object.
    :param target_key: A string representing the key whose values need to be extracted.
    :return: A list of values associated with the target key.
    """
    values = []

    def _extract_recursive(data):
        if isinstance(data, dict):
            for key, value in data.items():
                if key == target_key:
                    values.append(value)
                _extract_recursive(value)
        elif isinstance(data, list):
            for item in data:
                _extract_recursive(item)

    _extract_recursive(json_data)
    return values

