def find_max_occurrences(sequence):
    """
    Returns a tuple containing the element that occurs most frequently in the sequence
    and the number of times it occurs. If there are multiple elements with the same
    maximum frequency, returns the one that appears first in the sequence.

    :param sequence: A list, tuple, or string of elements.
    :return: A tuple (element, count) where 'element' is the most frequently occurring
             element and 'count' is the number of times it occurs.
    """
    frequency_dict = {}
    for element in sequence:
        if element in frequency_dict:
            frequency_dict[element] += 1
        else:
            frequency_dict[element] = 1

    max_element = None
    max_count = 0
    for element in sequence:
        if frequency_dict[element] > max_count:
            max_count = frequency_dict[element]
            max_element = element

    return (max_element, max_count)
