import random

def count_distinct_prime_factors(n):
    """
    Counts the number of distinct prime factors of a given number n.

    :param n: Integer, the number to factorize.
    :return: Integer, the count of distinct prime factors.
    """
    if n <= 1:
        return 0

    count = 0
    if n % 2 == 0:
        count += 1
        while n % 2 == 0:
            n //= 2

    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            count += 1
            while n % i == 0:
                n //= i

    if n > 2:
        count += 1

    return count

def is_probable_prime(number):
    """
    Determines if a number is a probable prime using a modified Miller-Rabin test.

    :param number: Integer, the number to test.
    :return: Boolean, True if the number is a probable prime, False otherwise.
    """
    if number <= 1:
        return False
    if number <= 3:
        return True
    if number % 2 == 0:
        return False

    d = number - 1
    k = 0
    while d % 2 == 0:
        k += 1
        d //= 2

    num_iterations = count_distinct_prime_factors(number)
    for _ in range(num_iterations):
        a = random.randint(2, number - 2)
        x = pow(a, d, number)
        if x == 1 or x == number - 1:
            continue

        continue_loop = False
        for _ in range(k - 1):
            x = pow(x, 2, number)
            if x == number - 1:
                continue_loop = True
                break

        if continue_loop:
            continue
        return False

    return True
