from flask import Flask, request, jsonify

app = Flask(__name__)

# In-memory list to act as a database
books = []
next_id = 1  # To keep track of IDs for new books


def _get_book(book_id):
    """Helper function to get a book by its ID."""
    return next((book for book in books if book['id'] == book_id), None)


@app.route('/books', methods=['POST'])
def create_book():
    """Create a new book and return it with an automatically generated ID."""
    global next_id

    data = request.get_json()
    if not data or 'title' not in data or 'author' not in data or 'year' not in data:
        return jsonify({'error': 'Bad Request', 'message': 'Title, author and year are required.'}), 400

    new_book = {
        'id': next_id,
        'title': data['title'],
        'author': data['author'],
        'year': data['year']
    }

    books.append(new_book)
    next_id += 1

    return jsonify(new_book), 201


@app.route('/books', methods=['GET'])
def get_books():
    """Return a list of all books."""
    return jsonify(books)


@app.route('/books/<int:book_id>', methods=['GET'])
def get_book(book_id):
    """Return a book by its ID."""
    book = _get_book(book_id)
    if book is None:
        return jsonify({'error': 'Not Found', 'message': 'Book not found.'}), 404

    return jsonify(book)


@app.route('/books/<int:book_id>', methods=['PUT'])
def update_book(book_id):
    """Update a book by its ID and return the updated book."""
    book = _get_book(book_id)
    if book is None:
        return jsonify({'error': 'Not Found', 'message': 'Book not found.'}), 404

    data = request.get_json()
    if not data:
        return jsonify({'error': 'Bad Request', 'message': 'Request body is empty.'}), 400

    book['title'] = data.get('title', book['title'])
    book['author'] = data.get('author', book['author'])
    book['year'] = data.get('year', book['year'])

    return jsonify(book)


@app.route('/books/<int:book_id>', methods=['DELETE'])
def delete_book(book_id):
    """Delete a book by its ID and return a success message."""
    book = _get_book(book_id)
    if book is None:
        return jsonify({'error': 'Not Found', 'message': 'Book not found.'}), 404

    books.remove(book)
    return jsonify({'message': 'Book deleted successfully.'}), 200


if __name__ == '__main__':
