import json

def extract_values(json_str, target_key):
    """
    Extracts all values associated with a given key from a JSON string representing a nested dictionary.

    :param json_str: A JSON string representing a nested dictionary.
    :param target_key: The key whose values need to be extracted.
    :return: A list of values associated with the target_key.
    """
    def _extract(d, key):
        if isinstance(d, dict):
            for k, v in d.items():
                if k == key:
                    results.append(v)
                _extract(v, key)
        elif isinstance(d, list):
            for item in d:
                _extract(item, key)

