        """
        Withdraws a specified amount from the bank account if the balance is sufficient.
        Only allows withdrawals for positive amounts. Prints warning messages for insufficient funds or non-positive amounts.
        """
        if amount > 0:
            if self.balance >= amount:
                self.balance -= amount
            else:
                print("Insufficient funds. Withdrawal not allowed.")
        else:
            print("Withdrawal amount must be positive.")

