def is_minor_chord(chord_notes):
    """
    Determines whether the given chord is minor or major.

    :param chord_notes: A list of notes in the chord, starting with the root note, 
                        represented as integers where 0 = C, 1 = C#, 2 = D, etc.
                        The list should be sorted in ascending order.
    :return: A string "major" if the chord is major, "minor" if the chord is minor.
    """
    if len(chord_notes) < 2:
        raise ValueError("A chord must have at least two notes")

    intervals = [(chord_notes[i] - chord_notes[0]) % 12 for i in range(1, len(chord_notes))]

    third = None
    fifth = None

    for interval in intervals:
        if interval == 3:
            third = "minor"
        elif interval == 4:
            third = "major"
        elif interval == 7:
            fifth = "perfect"

    if third == "minor" and fifth == "perfect":
        return "minor"
    elif third == "major" and fifth == "perfect":
        return "major"
    else:
        raise ValueError("The chord is not a recognizable minor or major type with a third and fifth interval.")
