def generate_fibonacci_up_to(max_number):
    """
    Generate a list of Fibonacci numbers up to a given maximum number.
    """
    fibs = [0, 1]
    while True:
        next_fib = fibs[-1] + fibs[-2]
        if next_fib > max_number:
            break
        fibs.append(next_fib)
    return fibs

def can_reach_last_index(arr):
    """
    Determine if the last index can be reached with the given constraints.
    """
    n = len(arr)
    if n == 1:
        return True

    primes = generate_primes_up_to(max(arr))
    fibonacci_numbers = generate_fibonacci_up_to(n * n)  # Multiply by n as an upper estimate

    def is_valid_jump(jumps, next_jump, current_index):
        """
        Check if a jump is valid based on the constraints.
        """
        if next_jump not in primes:
            return False
        if len(jumps) >= 1 and jumps[-1] == next_jump:
            return False
        new_index = current_index + next_jump
        if 0 <= new_index < n:
            return True
        return False

    def backtrack(current_index, jumps, product_of_indices):
        """
        Use backtracking to determine if the last index can be reached.
        """
        if current_index == n - 1:
            return True
        if product_of_indices not in fibonacci_numbers:
            return False
        for jump in primes:
            if is_valid_jump(jumps, jump, current_index):
                jumps.append(jump)
                new_index = current_index + jump
                new_product = product_of_indices * new_index
                if backtrack(new_index, jumps, new_product):
                    return True
                jumps.pop()
        return False

    return backtrack(0, [], 1)
