class Matrix:
    def __init__(self, data):
        """
        Initialize the Matrix with given data.

        :param data: 2D list of integers representing the matrix.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def add(self, other):
        """
        Add another matrix to this matrix.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the sum.
        :raises ValueError: If matrices have different dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for addition")

        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def subtract(self, other):
        """
        Subtract another matrix from this matrix.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the difference.
        :raises ValueError: If matrices have different dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for subtraction")

        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiply this matrix by another matrix.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the product.
        :raises ValueError: If the number of columns in the first matrix is not equal to the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to number of rows in the second matrix")

        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def transpose(self):
        """
        Transpose this matrix.

        :return: A new Matrix object representing the transposed matrix.
        """
        result = [
            [self.data[j][i] for j in range(self.rows)]
            for i in range(self.cols)
        ]
        return Matrix(result)

    def __str__(self):
        """
        Return a string representation of the matrix.

        :return: A string with rows separated by newlines and elements in each row separated by tabs.
        """
        return '\n'.join(['\t'.join(map(str, row)) for row in self.data])
