def deep_copy(data: Any) -> Any:
    """
    Creates a deep copy of the given data structure, handling complex data types
    such as nested dictionaries, lists, tuples, and sets.

    :param data: The data structure to be copied.
    :return: A deep copy of the input data structure.
    """
    if isinstance(data, dict):
        return {key: deep_copy(value) for key, value in data.items()}
    elif isinstance(data, list):
        return [deep_copy(item) for item in data]
    elif isinstance(data, tuple):
        return tuple(deep_copy(item) for item in data)
    elif isinstance(data, set):
        return {deep_copy(item) for item in data}
    else:
        return data

