def compare_switch_names(name1, name2):
    """
    Compares two network switch names lexicographically without using built-in comparison functions.

    :param name1: First switch name as a string.
    :param name2: Second switch name as a string.
    :return: -1 if name1 < name2, 1 if name1 > name2, 0 if name1 == name2.
    """
    def parse_name(name):
        """
        Parses the switch name into its constituent parts.

        :param name: Switch name as a string.
        :return: List of parts [type, number, location, sublocation].
        """
        parts = []
        current_part = []
        for char in name:
            if char == '-':
                parts.append(''.join(current_part))
                current_part = []
            else:
                current_part.append(char)
        parts.append(''.join(current_part))
        return parts

    def compare_parts(part1, part2):
        """
        Compares two parts lexicographically without using built-in comparison functions.

        :param part1: First part as a string.
        :param part2: Second part as a string.
        :return: -1 if part1 < part2, 1 if part1 > part2, 0 if part1 == part2.
        """
        len1, len2 = 0, 0
        for _ in part1:
            len1 += 1
        for _ in part2:
            len2 += 1

        min_len = len1 if len1 < len2 else len2
        for i in range(min_len):
            if part1[i] != part2[i]:
                if part1[i] < part2[i]:
                    return -1
                else:
                    return 1

        if len1 == len2:
            return 0
        elif len1 < len2:
            return -1
        else:
            return 1

    parts1 = parse_name(name1)
    parts2 = parse_name(name2)

    for i in range(4):
        if parts1[i][0].isalpha() and parts2[i][0].isalpha():
            result = compare_parts(parts1[i], parts2[i])
            if result != 0:
                return result
        elif parts1[i][0].isdigit() and parts2[i][0].isdigit():
            num1, num2 = 0, 0
            for c in parts1[i]:
                num1 = num1 * 10 + (ord(c) - ord('0'))
            for c in parts2[i]:
                num2 = num2 * 10 + (ord(c) - ord('0'))

            if num1 == num2:
                continue
            elif num1 < num2:
                return -1
            else:
                return 1

    return 0
