def sort_nested_list(nested_list):
    """
    Extracts all integers from a nested list and returns them sorted in ascending order.

    :param nested_list: A nested list of integers with arbitrary depth.
    :return: A list of integers sorted in ascending order.
    """
    result = []
    stack = [iter(nested_list)]

    while stack:
        try:
            element = next(stack[-1])
            if isinstance(element, int):
                result.append(element)
            else:
                stack.append(iter(element))
        except StopIteration:
            stack.pop()

    return sorted(result)
