def recursive_replace_values(data, search_val, replace_val, seen=None):
    """
    Recursively search and replace values in a nested dictionary or list, handling circular references.

    :param data: nested dictionary or list of elements to search
    :param search_val: value to search in the data
    :param replace_val: value to replace with the search_val
    :param seen: dictionary to track seen objects for circular reference handling
    :return: nested dictionary or list with replaced values
    """
    if seen is None:
        seen = {}

    obj_id = id(data)

    if obj_id in seen:
        return seen[obj_id]

    seen[obj_id] = data

    if isinstance(data, dict):
        for k, v in data.items():
            if v == search_val:
                data[k] = replace_val
            else:
                recursive_replace_values(v, search_val, replace_val, seen)

    elif isinstance(data, list):
        for i in range(len(data)):
            if data[i] == search_val:
                data[i] = replace_val
            else:
                recursive_replace_values(data[i], search_val, replace_val, seen)

    seen[obj_id] = data

    return data
