def parse_json(json_str):
    """
    Parses a JSON string into a Python dictionary.

    :param json_str: A string representing a JSON document.
    :return: A Python dictionary representing the parsed JSON.
    """
    json_str = json_str.strip()
    idx = 0

    def parse():
        nonlocal idx
        while idx < len(json_str) and json_str[idx].isspace():
            idx += 1
        if json_str[idx] == '{':
            return parse_object()
        elif json_str[idx] == '[':
            return parse_array()
        elif json_str[idx] in '-0123456789':
            return parse_number()
        elif json_str[idx] == '"':
            return parse_string()
        elif json_str[idx:idx+4] == 'true':
            return parse_bool('true')
        elif json_str[idx:idx+5] == 'false':
            return parse_bool('false')
        elif json_str[idx:idx+4] == 'null':
            return parse_null()

    def parse_object():
        """
        Parses a JSON object into a Python dictionary.

        :return: A Python dictionary.
        """
        obj = {}
        nonlocal idx
        idx += 1
        while idx < len(json_str) and json_str[idx] != '}':
            while idx < len(json_str) and json_str[idx].isspace():
                idx += 1
            key = parse_string()
            while idx < len(json_str) and json_str[idx].isspace():
                idx += 1
            idx += 1
            while idx < len(json_str) and json_str[idx].isspace():
                idx += 1
            value = parse()
            obj[key] = value
            while idx < len(json_str) and json_str[idx].isspace():
                idx += 1
            if json_str[idx] == ',':
                idx += 1
        idx += 1
        return obj

    def parse_array():
        """
        Parses a JSON array into a Python list.

        :return: A Python list.
        """
        arr = []
        nonlocal idx
        idx += 1
        while idx < len(json_str) and json_str[idx] != ']':
            while idx < len(json_str) and json_str[idx].isspace():
                idx += 1
            arr.append(parse())
            while idx < len(json_str) and json_str[idx].isspace():
                idx += 1
            if json_str[idx] == ',':
                idx += 1
        idx += 1
        return arr

    def parse_number():
        """
        Parses a JSON number into a Python int or float.

        :return: A Python int or float.
        """
        nonlocal idx
        start = idx
        while idx < len(json_str) and json_str[idx].isdigit():
            idx += 1
        if idx < len(json_str) and json_str[idx] == '.':
            idx += 1
            while idx < len(json_str) and json_str[idx].isdigit():
                idx += 1
        num = json_str[start:idx]
        return float(num) if '.' in num else int(num)

    def parse_string():
        """
        Parses a JSON string into a Python string.

        :return: A Python string.
        """
        nonlocal idx
        idx += 1
        start = idx
        while idx < len(json_str) and json_str[idx] != '"':
            idx += 1
        s = json_str[start:idx]
        idx += 1
        return s

    def parse_bool(value):
        """
        Parses a JSON boolean into a Python bool.

        :param value: A string 'true' or 'false'.
        :return: A Python bool.
        """
        nonlocal idx
        idx += len(value)
        return value == 'true'

    def parse_null():
        """
        Parses a JSON null into a Python None.

        :return: None.
        """
        nonlocal idx
        idx += 4
        return None

    result = parse()
    if idx < len(json_str):
        raise ValueError("Unexpected character after JSON")
    return result
```

