def count_words(text, word):
    """
    Counts the number of times a given word appears in a text, ignoring case and punctuation.

    :param text: The text in which to search for the word.
    :param word: The word to count in the text.
    :return: The number of times the word appears in the text.
    """
    # Normalize both text and word to lower case
    text_lower = ""
    word_lower = ""
    for char in text:
        if 'A' <= char <= 'Z':
            text_lower += chr(ord(char) + 32)
        else:
            text_lower += char

    for char in word:
        if 'A' <= char <= 'Z':
            word_lower += chr(ord(char) + 32)
        else:
            word_lower += char

    # Remove punctuation from text_lower
    text_no_punct = ""
    for char in text_lower:
        if ('a' <= char <= 'z') or ('0' <= char <= '9') or (char == ' '):
            text_no_punct += char

    # Count occurrences of word_lower in text_no_punct
    count = 0
    word_length = len(word_lower)
    i = 0
    while i <= len(text_no_punct) - word_length:
        match = True
        for j in range(word_length):
            if text_no_punct[i + j] != word_lower[j]:
                match = False
                break
        if match:
            count += 1
        i += 1

    return count
