            custom_list = CustomList()
            for item in value:
                custom_list.append(item)
            custom_in_dict.insert(key, custom_list)
        else:
            custom_in_dict.insert(key, value)

    for key, inner_dict in k_v_map.items():
        custom_inner_dict = CustomDict()
        for inner_key, inner_value in inner_dict.items():
            custom_inner_dict.insert(inner_key, inner_value)
        custom_k_v_map.insert(key, custom_inner_dict)

    # Perform transformation
    for key in in_dict.keys():
        if custom_k_v_map.contains_key(key):
            original_value = custom_in_dict.get(key)
            k_v_map_inner_dict = custom_k_v_map.get(key)

            if isinstance(original_value, CustomList):
                new_value = None
                for item in original_value:
                    if k_v_map_inner_dict.contains_key(item):
                        new_value = k_v_map_inner_dict.get(item)
                        break
                if new_value is not None:
                    custom_in_dict.insert(key, new_value)
            else:
                if k_v_map_inner_dict.contains_key(original_value):
                    custom_in_dict.insert(key, k_v_map_inner_dict.get(original_value))

    # Convert CustomDict back to dictionary
    transformed_dict = {}
    for i in range(len(custom_in_dict.keys)):
        key = custom_in_dict.keys[i]
        value = custom_in_dict.values[i]
        if isinstance(value, CustomList):
            transformed_dict[key] = [item for item in value]
        else:
            transformed_dict[key] = value

    return transformed_dict
