def mobius_function(x, primes):
    """
    Computes the Mobius function value for a given number x using the list of primes.
    """
    mu = 1
    if x == 1:
        return mu
    for p in primes:
        if p * p > x:
            break
        if x % p == 0:
            mu = -mu
            x //= p
            if x % p == 0:
                return 0
    if x != 1:
        mu = -mu
    return mu

def count_divisible_numbers(K, primes, queries):
    """
    Counts the number of integers between Ai and Bi (both inclusive) that are divisible by at least one of the K given primes.
    """
    from collections import defaultdict

    max_B = max(q[1] for q in queries)
    sqrt_max_B = int(max_B ** 0.5) + 1
    mobius_values = defaultdict(int)

    for x in range(1, sqrt_max_B + 1):
        mobius_values[x] = mobius_function(x, primes)

    for Ai, Bi in queries:
        result = 0
        for i in range(1, sqrt_max_B + 1):
            product = 1
            for j in range(K):
                product *= primes[j]
                if product <= Bi:
                    sign = mobius_values[i]
                    if sign != 0:
                        counted = Bi // product - (Ai - 1) // product
                        result += sign * counted
                else:
                    break
        print(result)

