def optimize_route(cities, distances):
    """Finds the shortest route visiting all cities and returning using a greedy algorithm

    Args:
        cities (List[str]): List of city names
        distances (Dict[Tuple[str, str], float]): Pairwise distances between each city

    Returns:
        Tuple[List[str], float]: A tuple consisting of the list of cities in the shortest route and the total distance of the route
    """
    if not cities or len(cities) < 2:
        return (cities, 0.0)

    current_city = cities[0]
    visited_cities = [current_city]
    route_distance = 0.0

    while len(visited_cities) < len(cities):
        nearest_city = None
        nearest_distance = float('inf')

        for city in cities:
            if city not in visited_cities and (current_city, city) in distances:
                if distances[(current_city, city)] < nearest_distance:
                    nearest_city = city
                    nearest_distance = distances[(current_city, city)]
        if nearest_city is None:
            break
        visited_cities.append(nearest_city)
        route_distance += nearest_distance
        current_city = nearest_city

    if visited_cities[-1] != visited_cities[0] and (visited_cities[-1], visited_cities[0]) in distances:
        route_distance += distances[(visited_cities[-1], visited_cities[0])]
        visited_cities.append(visited_cities[0])

    return (visited_cities, route_distance)
