def get_named_value(data: dict, name: str, default: any = None) -> any:
    """
    Retrieves the value associated with the key `name` from a nested structure of dictionaries and lists.
    If the key is not found, returns the `default` value.

    :param data: A dictionary that may contain nested dictionaries and lists.
    :param name: A string representing the key to search for.
    :param default: The value to return if the key is not found.
    :return: The value associated with the key `name` if found, otherwise the `default` value.
    """
    def recursive_search(d):
        if isinstance(d, dict):
            for key, value in d.items():
                if key == name:
                    return value
                elif isinstance(value, (dict, list)):
                    result = recursive_search(value)
                    if result is not None:
                        return result
        elif isinstance(d, list):
            for item in d:
                result = recursive_search(item)
                if result is not None:
                    return result
        return None

    return recursive_search(data) or default
