def convert_argument_to_size(arg):
    """
    Convert a string argument into an integer if the argument 
    does not exceed 32-bit unsigned integer range.

    :param arg: String representation of an integer, hexadecimal, or register/memory reference
    :return: converted integer if within 32-bit unsigned integer range, otherwise None
