class Stack:
    def __init__(self):
        """Initialize an empty stack."""
        self.items = []

    def is_empty(self):
        """Check if the stack is empty."""
        return len(self.items) == 0

    def push(self, item):
        """Add an item to the top of the stack."""
        self.items.append(item)

    def pop(self):
        """Remove and return the item from the top of the stack. Return None if the stack is empty."""
        if not self.is_empty():
            return self.items.pop()
        return None

    def peek(self):
        """Return the item at the top of the stack without removing it. Return None if the stack is empty."""
        if not self.is_empty():
            return self.items[-1]
        return None

    def size(self):
        """Return the number of items in the stack."""
        return len(self.items)

# Demonstration of stack operations
if __name__ == "__main__":
    stack = Stack()
    stack.push(1)
    stack.push(2)
    stack.push(3)
    print("Current stack items:", stack.items)  # Output: [1, 2, 3]
    print("Top item:", stack.peek())  # Output: 3
    print("Stack size:", stack.size())  # Output: 3

    popped_item = stack.pop()
    print(f"Popped item: {popped_item}")  # Output: 3
    print("Current stack items after pop:", stack.items)  # Output: [1, 2]

    stack.push(4)
    print("Current stack items after last push:", stack.items)  # Output: [1, 2, 4]
