def sum_of_primes(n):
    """
    Computes the sum of all prime numbers up to and including n.

    Parameters:
    n (int): The upper limit integer up to which primes are summed.

    Returns:
    int: The sum of all prime numbers up to and including n.
    """
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    total_sum = 0
    for number in range(2, n + 1):
        if is_prime(number):
            total_sum += number
    return total_sum
