def running_average():
    """Coroutine to calculate the running average, highest, and lowest values."""
    total_sum = 0
    count = 0
    highest = None
    lowest = None

    while True:
        number = yield (total_sum / count if count else 0, highest, lowest)
        total_sum += number
        count += 1
        if highest is None or number > highest:
            highest = number
        if lowest is None or number < lowest:
            lowest = number


