class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def insert_into_bst(root, val):
    """
    Inserts a new value into the binary search tree and returns the root of the modified tree.

    :param root: TreeNode, the root of the binary search tree.
    :param val: int, the value to be inserted into the BST.
    :return: TreeNode, the root of the modified BST.
    """
    if root is None:
        return TreeNode(val)

    current = root
    while True:
        if val < current.val:
            if current.left is None:
                current.left = TreeNode(val)
                break
            else:
                current = current.left
        else:
            if current.right is None:
                current.right = TreeNode(val)
                break
            else:
                current = current.right
    return root
