        """Subtract a value from the current result and return the calculator instance for chaining."""
        self.result -= value
        return self

    def multiply(self, value):
        """Multiply the current result by a value and return the calculator instance for chaining."""
        self.result *= value
        return self

    def divide(self, value):
        """Divide the current result by a value, handle division by zero, and return the calculator instance for chaining."""
        if value != 0:
            self.result /= value
        else:
