def calculate_ridge_penalty(l2_lambda, feature_weights, regularization_type='l2'):
    """
    Calculate the regularization penalty for a linear regression model.

    Parameters:
    l2_lambda (float): The regularization parameter, must be non-negative.
    feature_weights (list or tuple of float): The weights of the features.
    regularization_type (str): The type of regularization, either 'l1' or 'l2'.

    Returns:
    float: The calculated regularization penalty.

    Raises:
    ValueError: If l2_lambda is negative, feature_weights is not a list or tuple, or regularization_type is invalid.
    """
    if not (isinstance(l2_lambda, (int, float)) and l2_lambda >= 0):
        raise ValueError("l2_lambda must be a non-negative number.")

    if not isinstance(feature_weights, (list, tuple)):
        raise ValueError("feature_weights must be a list or tuple of numbers.")

    if regularization_type not in ['l1', 'l2']:
        raise ValueError("regularization_type must be either 'l1' or 'l2'.")

    if regularization_type == 'l2':
        return l2_lambda * sum(w ** 2 for w in feature_weights)
    elif regularization_type == 'l1':
        return l2_lambda * sum(abs(w) for w in feature_weights)
