class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, data):
        """Inserts a new node with the given data into the BST."""
        if not self.root:
            self.root = Node(data)
        else:
            self._insert_recursively(self.root, data)

    def _insert_recursively(self, node, data):
        if data < node.data:
            if node.left is None:
                node.left = Node(data)
            else:
                self._insert_recursively(node.left, data)
        elif data > node.data:
            if node.right is None:
                node.right = Node(data)
            else:
                self._insert_recursively(node.right, data)

    def delete(self, data):
        """Deletes a node with the given data from the BST."""
        self.root = self._delete_recursively(self.root, data)

    def _delete_recursively(self, node, data):
        if node is None:
            return node

        if data < node.data:
            node.left = self._delete_recursively(node.left, data)
        elif data > node.data:
            node.right = self._delete_recursively(node.right, data)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            node.data = self._min_value_node(node.right).data
            node.right = self._delete_recursively(node.right, node.data)

        return node

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current

    def inorder_traversal(self, node, traversal_list=None):
        """Returns the inorder traversal of the BST as a list."""
        if traversal_list is None:
            traversal_list = []
        if node:
            self.inorder_traversal(node.left, traversal_list)
            traversal_list.append(node.data)
            self.inorder_traversal(node.right, traversal_list)
        return traversal_list

