def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def group_and_count_elements(lst):
    """Group and count consecutive prime numbers in the list."""
    if not lst:
        return []

    grouped_primes = []
    current_number = lst[0]
    count = 0

    for number in lst:
        if number != current_number:
            if is_prime(current_number):
                grouped_primes.append((current_number, count))
            current_number = number
            count = 1
        else:
            count += 1

    # Check the last group
    if is_prime(current_number):
        grouped_primes.append((current_number, count))

    return grouped_primes
