def find_largest_prime(limit):
    """
    Finds the largest prime number less than or equal to the given limit using the Sieve of Eratosthenes algorithm.

    Parameters:
    limit (int): The upper limit to search for the largest prime number.

    Returns:
    int or None: The largest prime number less than or equal to limit, or None if no such prime exists.
    """
    if limit < 2:
        return None

    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False

    for num in range(2, int(limit**0.5) + 1):
        if sieve[num]:
            for multiple in range(num*num, limit + 1, num):
                sieve[multiple] = False

    for num in range(limit, 1, -1):
        if sieve[num]:
            return num
