def word_count(s):
    """
    Returns a dictionary with words that appear at least three times in the input string `s`.

    :param s: A string of words separated by single spaces.
    :return: A dictionary with words as keys and their counts as values.
    """
    words = s.split()
    word_dict = {}
    for word in words:
        if word in word_dict:
            word_dict[word] += 1
        else:
            word_dict[word] = 1
    return {word: count for word, count in word_dict.items() if count >= 3}
