def is_valid_bracket_sequence(s: str) -> bool:
    """
    Determines if the given string s is a valid bracket sequence.

    :param s: A string consisting of '(', ')', '{', '}', '[' and ']'.
    :return: True if the string is a valid bracket sequence, otherwise False.
    """
    bracket_map = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map:
            if not stack or bracket_map[char] != stack.pop():
                return False
        else:
            return False

    return not stack
