    num = 2
    while len(primes) < count:
        if is_prime(num):
            primes.append(num)
        num += 1
    return primes

def build_tag_mapping(tags):
    """Build a mapping from IOBES tags to unique integers with S-<tag>=prime requirement."""
    mapping = {}
    current = 1
    mapping['O'] = 0

    all_tags = []
    for tag in tags:
        all_tags.extend([f'B-{tag}', f'I-{tag}', f'E-{tag}', f'S-{tag}'])

    num_s_tags = len(tags)
    primes = generate_primes(num_s_tags)

    prime_index = 0
    for tag in all_tags:
        if tag.startswith('S-'):
            mapping[tag] = primes[prime_index]
            prime_index += 1
        else:
            mapping[tag] = current
            current += 1

    return mapping

