import threading

def matrix_multiply(a, b):
    """Multiplies two 2x2 matrices a and b and returns the result."""
    return [
        [a[0][0] * b[0][0] + a[0][1] * b[1][0], a[0][0] * b[0][1] + a[0][1] * b[1][1]],
        [a[1][0] * b[0][0] + a[1][1] * b[1][0], a[1][0] * b[0][1] + a[1][1] * b[1][1]]
    ]

def matrix_power(matrix, n):
    """Computes matrix^n using exponentiation by squaring and returns the result."""
    result = [[1, 0], [0, 1]]  # Identity matrix
    base = matrix

    while n > 0:
        if n % 2 == 1:
            result = matrix_multiply(result, base)
        base = matrix_multiply(base, base)
        n //= 2
    return result

def fibonacci(n):
    """Returns the nth Fibonacci number using matrix exponentiation."""
    if n == 0:
        return 0
    elif n == 1:
        return 1

    # Transformation matrix for Fibonacci sequence
    fib_matrix = [[1, 1], [1, 0]]

    result_matrix = matrix_power(fib_matrix, n-1)
    return result_matrix[0][0]

class FibonacciCalculator:
    """Thread-safe Fibonacci number calculator using matrix exponentiation."""
    def __init__(self):
        self.lock = threading.Lock()

    def get_fibonacci(self, n):
        """Returns the nth Fibonacci number in a thread-safe manner."""
        with self.lock:
            return fibonacci(n)

# Example usage
if __name__ == "__main__":
    fib_calculator = FibonacciCalculator()
    results = []
    threads = []
    numbers = [10, 30, 50, 80, 100]

    for number in numbers:
        t = threading.Thread(target=lambda num: results.append((num, fib_calculator.get_fibonacci(num))), args=(number,))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    for num, result in results:
        print(f"Fibonacci({num}) = {result}")
