        """Return the product of a and b."""
        return a * b

    def divide(self, a, b):
        """Return the quotient of a and b, handling division by zero."""
        try:
            return a / b
        except ZeroDivisionError:
            return "Error: Division by zero is not allowed."

    def square_root(self, a):
        """Return the square root of a, handling negative input."""
        try:
            return math.sqrt(a)
        except ValueError:
            return "Error: Square root of a negative number is not allowed."

    def power(self, a, b):
        """Return a raised to the power of b."""
        return a ** b

