    emails = []

    def find_emails(obj):
        if isinstance(obj, dict):
            for value in obj.values():
                find_emails(value)
        elif isinstance(obj, list):
            for item in obj:
                find_emails(item)
        elif isinstance(obj, str):
            if email_pattern.match(obj):
                emails.append(obj)

    find_emails(data)
    return emails
