def find_anagrams(word_list):
    """
    Identifies and groups all the anagrams from the given list of words.

    Parameters:
    word_list (list of str): A list of words to find anagrams for.

    Returns:
    dict: A dictionary where each key is a word and the value is a list of its anagrams.
    """
    anagrams = {}
    for word in word_list:
        sorted_word = ''.join(sorted(word))
        if sorted_word in anagrams:
            anagrams[sorted_word].append(word)
        else:
            anagrams[sorted_word] = [word]
    return {original_word: anagrams[word] for word in anagrams for original_word in anagrams[word] if anagrams[word][0] == original_word}
