def find_smallest_missing(arr):
    """
    Finds the smallest positive integer that is not present in the given array.

    Parameters:
    arr (list of int): The input array of integers.

    Returns:
    int: The smallest positive integer missing from the array.
    """
    if not arr:
        return 1

    n = len(arr)
    for i in range(n):
        while 1 <= arr[i] <= n and arr[arr[i] - 1] != arr[i]:
            arr[arr[i] - 1], arr[i] = arr[i], arr[arr[i] - 1]

    for i in range(n):
        if arr[i] != i + 1:
            return i + 1

    return n + 1
