def get_viewing_products_string(page_num, total_products, products_per_page):
    """
    Returns a string indicating the range of products being viewed on a given page,
    or an error message if the input is invalid.

    :param page_num: The current page number (1-indexed).
    :param total_products: The total number of products in the category.
    :param products_per_page: The number of products displayed per page.
    :return: A Result object containing either the viewing range string or an error message.
    """
    def check_inputs(page_num, total_products, products_per_page):
        if page_num < 1:
            return Result(error="Page number must be greater than 0.")
        if products_per_page < 1:
            return Result(error="Products per page must be greater than 0.")
        if total_products < 1:
            return Result(error="Total products must be greater than 0.")
        max_page_num = (total_products + products_per_page - 1) // products_per_page
        if page_num > max_page_num:
            return Result(error=f"Page number {page_num} exceeds the maximum page number {max_page_num}.")
        return Result((page_num, total_products, products_per_page))

    def calculate_viewing_products(info):
        page_num, total_products, products_per_page = info
        start_product_index = (page_num - 1) * products_per_page + 1
        end_product_index = min(page_num * products_per_page, total_products)
        return Result(f"Viewing {start_product_index}-{end_product_index} of {total_products} products")

    return check_inputs(page_num, total_products, products_per_page).bind(calculate_viewing_products)
