def merge_dicts(dict1, dict2):
    """
    Recursively merges dict2 into dict1.
    If a key is present in both dictionaries, dict2's value will overwrite dict1's value.
    Nested dictionaries are merged recursively.

    :param dict1: The first dictionary to merge.
    :param dict2: The second dictionary to merge, whose values will overwrite dict1's values in case of key conflicts.
    :return: The merged dictionary.
    """
    for key, value in dict2.items():
        if key in dict1:
            if isinstance(dict1[key], dict) and isinstance(value, dict):
                merge_dicts(dict1[key], value)
            else:
                dict1[key] = value
        else:
            dict1[key] = value
    return dict1
