def longest_increasing_subsequence(numbers):
    """
    Returns the length of the longest increasing subsequence in the given list of integers.

    :param numbers: List[int] - A list of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not numbers:
        return 0

    n = len(numbers)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if numbers[j] < numbers[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

