def find_common_elements(numbers1, numbers2):
    """
    Returns a sorted list of integers that are present in both input lists without duplicates.

    :param numbers1: List of integers.
    :param numbers2: List of integers.
    :return: Sorted list of common integers without duplicates.
    """
    common_elements = []

    for element in numbers1:
        if element in numbers2 and element not in common_elements:
            common_elements.append(element)

    n = len(common_elements)
    for i in range(n):
        for j in range(0, n-i-1):
            if common_elements[j] > common_elements[j+1]:
                common_elements[j], common_elements[j+1] = common_elements[j+1], common_elements[j]

    return common_elements
```

