def print_file_paths(tree, path=''):
    """
    Recursively traverses the given tree and prints the path to each file.

    :param tree: dict, representing the tree structure of files and directories
    :param path: str, the current path in the tree up to the current node
    """
    for key, value in tree.items():
        current_path = f"{path}/{key}" if path else key
        if value:  # if there are children, it's a directory
            print_file_paths(value, current_path)
        else:  # if there are no children, it's a file
