def is_prime(n):
    """
    Determines if a given integer n is a prime number.

    Parameters:
    n (int): The integer to check for primality.

    Returns:
    bool: True if n is a prime number, False otherwise.
    """
    known_primes = [2, 3, 5, 7, 11, 13]  # Preset list of prime numbers

    if n < 2:
        return False
    elif n in known_primes:
        return True
    elif n % 2 == 0 or n % 3 == 0:
        return False
    else:
        import math
        limit = int(math.sqrt(n)) + 1
        for prime in known_primes:
            if prime > limit:
                break
            if n % prime == 0:
                return False

        for i in range(known_primes[-1] + 2, limit, 2):
            for prime in known_primes:
                if prime * prime > i:
                    known_primes.append(i)
                    break
                if i % prime == 0:
                    break
            if n % i == 0:
                return False

    known_primes.append(n)
    return True
