def merge_unique_elements(list1, list2=None):
    """
    Merges two lists of integers, which may contain nested lists, and returns a new list
    containing only the unique elements from both input lists, maintaining the order of
    their first appearance.

    :param list1: First list of integers, which may contain nested lists.
    :param list2: Second list of integers, which may contain nested lists. Defaults to None.
    :return: A new list with unique elements from both input lists.
    """
    def flatten(lst):
        """Flattens a nested list."""
        for item in lst:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    seen = set()
    result = []

    def process_list(lst):
        """Processes a list to add unique elements to the result."""
        for item in flatten(lst):
            if item not in seen:
                seen.add(item)
                result.append(item)

    process_list(list1)
    if list2 is not None:
        process_list(list2)

    return result
