def transform_bbox(bbox):
    """
    Recursively transforms a list of bounding boxes from (Cx, Cy, W, H) to (X1, Y1, X2, Y2) format.

    :param bbox: List of lists, where each inner list contains four numbers [Cx, Cy, W, H].
    :return: List of lists, where each inner list contains four numbers [X1, Y1, X2, Y2].
    """
    def single_transform(bbox):
        Cx, Cy, W, H = bbox
        X1 = Cx - W / 2
        Y1 = Cy - H / 2
        X2 = Cx + W / 2
        Y2 = Cy + H / 2
        return [X1, Y1, X2, Y2]

    def recursive_transform(index, result):
        if index == len(bbox):
            return result
        else:
            new_bbox = single_transform(bbox[index])
            result.append(new_bbox)
            return recursive_transform(index + 1, result)

    return recursive_transform(0, [])
