        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        """
        Inserts a new node with the given value into the binary tree.
        """
        if not self.root:
            self.root = TreeNode(value)
        else:
            self._insert_recursively(self.root, value)

    def _insert_recursively(self, node, value):
        """
        Helper method to insert a new node recursively.
        """
        if value < node.value:
            if node.left is None:
                node.left = TreeNode(value)
            else:
                self._insert_recursively(node.left, value)
        else:
            if node.right is None:
                node.right = TreeNode(value)
            else:
                self._insert_recursively(node.right, value)

    def inorder_traversal(self):
        """
        Returns a list of values obtained by performing an in-order traversal of the tree.
        """
        return self._inorder_traversal_recursively(self.root)

    def _inorder_traversal_recursively(self, node):
        """
        Helper method to perform in-order traversal recursively.
        """
        if node is None:
            return []
        return (self._inorder_traversal_recursively(node.left) +
                [node.value] +
                self._inorder_traversal_recursively(node.right))

    def find_max(self):
        """
        Returns the maximum value present in the binary tree.
        """
        return self._find_max_recursively(self.root)

    def _find_max_recursively(self, node):
        """
        Helper method to find the maximum value recursively.
        """
        if node is None:
            return float('-inf')
        left_max = self._find_max_recursively(node.left)
        right_max = self._find_max_recursively(node.right)
        return max(node.value, left_max, right_max)
