def recursive_power(base: float, exponent: int) -> float:
    """
    Computes the power of a given base raised to a specified exponent using recursion.

    Parameters:
    base (float): The base number.
    exponent (int): The exponent to which the base is raised.

    Returns:
    float: The result of base raised to the power of exponent.
    """
    # Base case for exponent 0
    if exponent == 0:
        return 1
    # Handle negative exponents
    elif exponent < 0:
        return 1 / recursive_power(base, -exponent)
    # Recursive case for positive exponents
    else:
        return base * recursive_power(base, exponent - 1)
