def ternary_search(target, sorted_list):
    """
    Determines if the target integer is present in the sorted list using a recursive ternary search algorithm.

    Parameters:
    target (int): The integer to search for in the list.
    sorted_list (list of int): The sorted list of integers to search within.

    Returns:
    bool: True if the target is found in the list, False otherwise.
    """
    def ternary_search_recursive(target, sorted_list, left, right):
        if right >= left:
            mid1 = left + (right - left) // 3
            mid2 = right - (right - left) // 3

            if sorted_list[mid1] == target:
                return True
            if sorted_list[mid2] == target:
                return True

            if target < sorted_list[mid1]:
                return ternary_search_recursive(target, sorted_list, left, mid1 - 1)
            elif target > sorted_list[mid2]:
                return ternary_search_recursive(target, sorted_list, mid2 + 1, right)
            else:
                return ternary_search_recursive(target, sorted_list, mid1 + 1, mid2 - 1)

        return False

    return ternary_search_recursive(target, sorted_list, 0, len(sorted_list) - 1)
