def find_item_line_number(file_content, item_name):
    """
    Returns the line number of the item with the specified name in the given file content.
    If the item is not found, returns 0.

    :param file_content: A string representing the content of a text file.
    :param item_name: A string representing the name of the item to find.
    :return: An integer representing the line number of the item, or 0 if not found.
    """
    lines = []
    i = 0
    while i < len(file_content):
        start = i
        while i < len(file_content) and file_content[i] != '\n':
            i += 1
        lines.append(file_content[start:i])
        if i < len(file_content):
            i += 1

    for line_number, line in enumerate(lines, start=1):
        if not line or line[0] == '#':
            continue

        colon_space_index = -1
        for j in range(len(line)):
            if j + 1 < len(line) and line[j] == ':' and line[j + 1] == ' ':
                colon_space_index = j + 2
                break

        if colon_space_index != -1:
            current_item_name = ''
            for k in range(colon_space_index, len(line)):
                current_item_name += line[k]

            if current_item_name == item_name:
                return line_number

    return 0
