def find_last_occurrence(numbers, target):
    """
    Finds the last occurrence of the target in a nested list of integers.

    Parameters:
    numbers (list of list of int): The nested list of integers.
    target (int): The integer to find.

    Returns:
    tuple: A tuple (i, j) representing the last occurrence of target, or (-1, -1) if not found.
    """
    for i in range(len(numbers) - 1, -1, -1):
        for j in range(len(numbers[i]) - 1, -1, -1):
            if numbers[i][j] == target:
                return (i, j)
    return (-1, -1)
