def calculate_average(nested_list):
    """
    Calculate the average of all floating point numbers in a nested list structure.

    :param nested_list: A list that may contain integers, floats, and other nested lists.
    :return: The average of all floating point numbers, or None if there are no floats.
    """
    def flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from flatten(item)
            elif isinstance(item, float):
                yield item

    flat_list = list(flatten(nested_list))

    if not flat_list:
        return None

    return sum(flat_list) / len(flat_list)
