def merge_dictionaries(dict_list):
    """
    Merges a list of dictionaries into a single dictionary, keeping only the first occurrence of each key.
    The resulting dictionary is sorted in descending order by keys.

    :param dict_list: List of dictionaries to be merged.
    :return: A dictionary with merged and sorted key-value pairs.
    """
    merged_dict = {}
    for dictionary in dict_list:
        for key, value in dictionary.items():
            if key not in merged_dict:
                merged_dict[key] = value

    # Sorting the dictionary by keys in descending order
    sorted_keys = []
    for key in merged_dict:
        inserted = False
        for i in range(len(sorted_keys)):
            if key > sorted_keys[i]:
                sorted_keys.insert(i, key)
                inserted = True
                break
        if not inserted:
            sorted_keys.append(key)

    # Creating a new dictionary with sorted keys
    sorted_dict = {}
    for key in sorted_keys:
        sorted_dict[key] = merged_dict[key]

    return sorted_dict

