def swap_keys_values(input_dict):
    """
    Swaps the keys and values of the input dictionary. If multiple keys share the same value,
    the value in the resulting dictionary will be a list of keys.

    :param input_dict: Dictionary with string keys and integer values.
    :return: Dictionary with integer keys and string or list of strings as values.
    """
    swapped_dict = {}
    for key, value in input_dict.items():
        if value not in swapped_dict:
            swapped_dict[value] = key
        else:
            if not isinstance(swapped_dict[value], list):
                swapped_dict[value] = [swapped_dict[value]]
            swapped_dict[value].append(key)
    return swapped_dict

