        """
        Add or update the quantity of the book in the inventory.

        :param title: str, the title of the book
        :param quantity: int, the number of copies to add
        """
        if title in self.inventory:
            self.inventory[title] += quantity
        else:
            self.inventory[title] = quantity
        print(f"Added {quantity} copies of '{title}' to inventory.")

    def remove_book(self, title, quantity):
        """
        Remove the specified quantity of the book from the inventory.

        :param title: str, the title of the book
        :param quantity: int, the number of copies to remove
        """
        if title in self.inventory:
            if self.inventory[title] >= quantity:
                self.inventory[title] -= quantity
                print(f"Removed {quantity} copies of '{title}' from inventory.")
                if self.inventory[title] == 0:
                    del self.inventory[title]
                    print(f"'{title}' is now out of stock and removed from inventory.")
            else:
                print(f"Cannot remove {quantity} copies of '{title}'. Only {self.inventory[title]} copies available.")
        else:
            print(f"Book '{title}' not found in inventory.")

    def search_book(self, title):
        """
        Search for a book by title and print its available quantity.

        :param title: str, the title of the book
        """
        if title in self.inventory:
            print(f"Book '{title}' found. Available quantity: {self.inventory[title]}")
        else:
