def decode_special_characters(encoded_text, extended):
    """
    Decodes escape sequences in the given encoded_text.

    Parameters:
    encoded_text (str): The string containing escape sequences to be decoded.
    extended (bool): Flag to indicate whether to decode extended escape sequences.

    Returns:
    str: The decoded string with escape sequences replaced by their corresponding characters.
    """
    def decode_basic(substring):
        decoding_map = {
            '\\n': '\n',  # Newline
            '\\t': '\t',  # Tab
            '\\\\': '\\',  # Backslash
            '\\r': '\r',  # Carriage return
            '\\b': '\b',  # Backspace
        }
        for key, value in decoding_map.items():
            substring = substring.replace(key, value)
        return substring

    extended_decoding_map = {
        '\\a': '\a',  # Bell
        '\\v': '\v',  # Vertical Tab
        '\\f': '\f',  # Formfeed
    }

    def decode_recursive(text):
        if '\\' in text:
            start = text.index('\\')
            for end in range(start + 2, len(text) + 1):
                if text[end - 1] in '"\'':
                    continue
                potentially_escaped = text[start:end]
                if potentially_escaped in decoding_map or (extended and potentially_escaped in extended_decoding_map):
                    text = text[:start] + (extended_decoding_map.get(potentially_escaped, decoding_map.get(potentially_escaped))) + text[end:]
                    return decode_recursive(text)
        return text

    decoding_map = {
        '\\n': '\n', '\\t': '\t', '\\\\': '\\', '\\r': '\r', '\\b': '\b'}

    if extended:
        decoding_map.update(extended_decoding_map)

    return decode_recursive(encoded_text)
