def count_primes(n):
    """
    Counts the number of prime numbers less than or equal to n using the Sieve of Eratosthenes algorithm.

    :param n: An integer representing the upper limit.
    :return: An integer count of prime numbers less than or equal to n.
    """
    if n < 2:
        return 0

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for num in range(2, int(n**0.5) + 1):
        if is_prime[num]:
            for multiple in range(num * num, n + 1, num):
                is_prime[multiple] = False 

    return sum(is_prime)
