def filter_data(data, keys_to_filter, _seen=None):
    """
    Recursively filters out dictionary keys or list items present in keys_to_filter from a deeply nested data structure.

    :param data: A deeply nested dictionary or list.
    :param keys_to_filter: A list of keys or values to be filtered out.
    :param _seen: A set to keep track of seen objects to avoid infinite loops in circular references.
    :return: A new data structure with the specified keys or values removed.
    """
    if _seen is None:
        _seen = set()
    obj_id = id(data)
    if obj_id in _seen:
        return data
    _seen.add(obj_id)

    if isinstance(data, dict):
        filtered = {}
        for key, value in data.items():
            if key not in keys_to_filter:
                filtered[key] = filter_data(value, keys_to_filter, _seen)
        return filtered
    elif isinstance(data, list):
        filtered = []
        for item in data:
            filtered_item = filter_data(item, keys_to_filter, _seen)
            if filtered_item not in keys_to_filter:
                filtered.append(filtered_item)
        return filtered
    else:
        return data
