def extract_unique_values(data, target_key):
    """
    Extracts all unique values associated with a specific key from a nested JSON object.

    :param data: A dictionary representing the JSON object.
    :param target_key: A string representing the key whose values need to be extracted.
    :return: A list of unique values associated with the target key.
    """
    unique_values = set()

    def dfs(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                if key == target_key:
                    if isinstance(value, list):
                        unique_values.update(value)
                    else:
                        unique_values.add(value)
                dfs(value)
        elif isinstance(obj, list):
            for item in obj:
                dfs(item)

    dfs(data)
    return list(unique_values)
```

