def find_feature_value(features, feature_name):
    """
    Recursively finds the value of a feature in a list of features, including nested features.

    :param features: List of dictionaries, each representing a feature.
    :param feature_name: String, the name of the feature.
    :return: The value of the specified feature if found, otherwise None.
    """
    for feature in features:
        if feature.get('name') == feature_name:
            return feature.get('value')
        elif 'features' in feature:
            nested_result = find_feature_value(feature['features'], feature_name)
            if nested_result is not None:
                return nested_result
    return None
