def get_highest_version_alleles(allele_identifiers):
    """
    Processes a list of allele identifiers and returns a list containing only the highest version of each allele name.

    :param allele_identifiers: List of strings, each representing an allele identifier in the format "NAME-VERSION".
    :return: List of strings, each representing the highest version of each unique allele name.
    """
    alleles = []

    for identifier in allele_identifiers:
        name, version_str = identifier.split('-')
        version = int(version_str)

        found = False
        for allele in alleles:
            if allele.name == name:
                if version > allele.version:
                    allele.version = version
                found = True
                break

        if not found:
            alleles.append(Allele(name, version))

    return [str(a) for a in alleles]
