def state_diff(current_state, previous_state):
    """
    Computes the difference between two states represented by dictionaries.

    Parameters:
    current_state (dict): The current state of the system.
    previous_state (dict): The previous state of the system.

    Returns:
    tuple: A tuple of three dictionaries (added, removed, changed).
    """
    added = {}
    removed = {}
    changed = {}

    # Collect all keys from both states
    keys = []
    for key in current_state:
        keys.append(key)
    for key in previous_state:
        found = 0
        for k in keys:
            if k == key:
                found = 1
                break
        if found == 0:
            keys.append(key)

    for key in keys:
        in_current = 0
        in_previous = 0
        for k in current_state:
            if k == key:
                in_current = 1
                break
        for k in previous_state:
            if k == key:
                in_previous = 1
                break

        if in_current == 0:
            # Key was in previous_state but not in current_state
            removed[key] = previous_state[key]
        elif in_previous == 0:
            # Key was in current_state but not in previous_state
            added[key] = current_state[key]
        else:
            # Key is in both states, check if the values are different
            if current_state[key] != previous_state[key]:
                changed[key] = current_state[key]

    return (added, removed, changed)
```

