def next_version(version):
    """
    Computes the next version string based on the given version string.

    Parameters:
    version (str): A string representing the current version in the format "X.Y.Z".

    Returns:
    str: The next version string or "Invalid Version" if the input is invalid.
    """
    try:
        major, minor, patch = map(int, version.split('.'))
        if not (0 <= major < 10 and 0 <= minor < 10 and 0 <= patch < 10):
            return "Invalid Version"
        if patch < 9:
            return f"{major}.{minor}.{patch + 1}"
        elif minor < 9:
            return f"{major}.{minor + 1}.0"
        else:
            return f"{major + 1}.0.0"
    except ValueError:
        return "Invalid Version"
