class InventoryManager:
    def __init__(self):
        self.items = {}
        self.total_items = 0

    def add_item(self, name, quantity):
        """
        Adds the specified quantity of the item to the inventory.
        If the item already exists, its quantity is updated.
        Raises ValueError if the quantity is negative.
        """
        if quantity < 0:
            raise ValueError("Quantity cannot be negative")
        if name in self.items:
            self.items[name] += quantity
        else:
            self.items[name] = quantity
        self.total_items += quantity

    def remove_item(self, name, quantity):
        """
        Removes the specified quantity of the item from the inventory.
        Raises KeyError if the item does not exist.
        Raises ValueError if the quantity to remove is greater than the available quantity.
        If the quantity of an item becomes zero after removal, it is removed from the inventory.
        """
        if quantity < 0:
            raise ValueError("Quantity cannot be negative")
        if name not in self.items:
            raise KeyError(f"Item '{name}' not found in inventory")
        if self.items[name] < quantity:
            raise ValueError(f"Not enough '{name}' in inventory to remove {quantity}")
        self.items[name] -= quantity
        self.total_items -= quantity
        if self.items[name] == 0:
            del self.items[name]

    def list_items(self):
        """
        Returns a copy of the current inventory as a dictionary.
        """
        return self.items.copy()
