def unique_sorted(lst):
    """
    Returns a new list containing the unique elements of the original list, sorted in ascending order.

    :param lst: List of integers
    :return: List of unique integers sorted in ascending order
    """
    # Creating a dictionary to count occurrences of each element
    counts = {}
    for num in lst:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    # Extract the unique elements
    unique_elements = []
    for num in counts:
        unique_elements.append(num)

    # Sorting the unique elements using bubble sort
    n = len(unique_elements)
    for i in range(n):
        for j in range(0, n-i-1):
            if unique_elements[j] > unique_elements[j+1]:
                unique_elements[j], unique_elements[j+1] = unique_elements[j+1], unique_elements[j]

    return unique_elements

# Example usage:
input_list = [4, 2, 5, 2, 3, 1, 4, 5]
