def group_bug_reports(bug_reports):
    """
    Groups bug reports by changeset and reason, considering only untrusted and currently damaging reports.

    Parameters:
    bug_reports (list of dict): A list of bug reports, each represented as a dictionary.

    Returns:
    list of dict: A list of dictionaries grouped by changeset and reason.
    """
    filtered_reports = [
        report for report in bug_reports 
        if not report['trusted'] and report['damaged_now']
    ]

    grouped_reports = {}
    for report in filtered_reports:
        changeset = report['changeset']
        reason = report['reason']
        item = {'osm_id': report['osm_id'], 'type': report['type']}
        user = report['user']

        if changeset not in grouped_reports:
            grouped_reports[changeset] = {'user': user, 'reasons': []}

        reasons = grouped_reports[changeset]['reasons']
        reason_found = False

        for r in reasons:
            if r['reason'] == reason:
                r['items'].append(item)
                reason_found = True
                break

        if not reason_found:
            reasons.append({'reason': reason, 'items': [item]})

    result = [
        {'changeset': changeset, **details}
        for changeset, details in grouped_reports.items()
    ]

    return result
