def has_cycle(maze):
    """
    Determines if there is a cycle in the given maze.

    :param maze: A dictionary where keys are room names and values are sets of room names.
    :return: True if there is a cycle, False otherwise.
    """
    def dfs(room, visited, rec_stack):
        visited.add(room)
        rec_stack.add(room)

        for neighbor in maze.get(room, set()):
            if neighbor not in visited:
                if dfs(neighbor, visited, rec_stack):
                    return True
            elif neighbor in rec_stack:
                return True

        rec_stack.remove(room)
        return False

    visited = set()

    for room in maze:
        if room not in visited:
            if dfs(room, visited, set()):
                return True

    return False

