def update_dict_values(whole_dict, part_dict, keys=None):
    """
    Updates the values in whole_dict with the values from part_dict for a given set of keys.
    If keys is None, updates all keys. Maintains insertion order and performs deep updates for nested dictionaries.

    :param whole_dict: Dictionary containing the complete set of key-value pairs.
    :param part_dict: Dictionary containing a subset of key-value pairs.
    :param keys: List of keys to update in whole_dict. If None, update all keys.
    :return: Updated whole_dict.
    """
    def deep_update(main_dict, update_dict):
        for key, value in update_dict.items():
            if isinstance(main_dict.get(key, {}), dict) and isinstance(value, dict):
                deep_update(main_dict[key], value)
            else:
                main_dict[key] = value

    if keys is None:
        deep_update(whole_dict, part_dict)
    else:
        for key in keys:
            if key in part_dict:
                if isinstance(whole_dict.get(key, {}), dict) and isinstance(part_dict[key], dict):
                    deep_update(whole_dict[key], part_dict[key])
                else:
                    whole_dict[key] = part_dict[key]

    return whole_dict
