class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, value):
        """Adds a new node with the specified value to the end of the list."""
        if not self.head:
            self.head = Node(value)
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = Node(value)

    def prepend(self, value):
        """Adds a new node with the specified value to the beginning of the list."""
        new_node = Node(value)
        new_node.next = self.head
        self.head = new_node

    def delete(self, value):
        """Removes the first node with the specified value from the list."""
        if not self.head:
            return

        if self.head.value == value:
            self.head = self.head.next
            return

        current = self.head
        while current.next:
            if current.next.value == value:
                current.next = current.next.next
                return
            current = current.next

    def search(self, value):
        """Returns True if a node with the specified value exists in the list, otherwise returns False."""
        current = self.head
        while current:
            if current.value == value:
                return True
            current = current.next
        return False

    def to_list(self):
        """Returns a list containing all the values in the linked list in the order they appear."""
        values = []
        current = self.head
        while current:
            values.append(current.value)
            current = current.next
        return values
