```python
def merge_configurations(default_config, task_config):
    """
    Merges two configuration dictionaries. If a key exists in both dictionaries,
    the value from task_config overwrites the value in default_config. If a value
    in task_config is None, the corresponding key-value pair is removed from the
    merged configuration. Handles nested dictionaries recursively.

    :param default_config: A dictionary representing the default configuration.
    :param task_config: A dictionary representing the configuration for a specific task.
    :return: A dictionary representing the merged configuration.
    """
    def merge(d1, d2):
        merged = d1.copy()
        for key, value in d2.items():
            if value is None and key in merged:
                del merged[key]
            elif isinstance(value, dict) and key in merged and isinstance(merged[key], dict):
                merged[key] = merge(merged[key], value)
            else:
                merged[key] = value
        return merged

    return merge(default_config, task_config)
```

