def get_port_ip_version(network_config, port, ip_version):
    """
    Returns the IP address of the given port in the specified IP version.

    :param network_config: Dictionary containing network configurations.
    :param port: String representing the port name.
    :param ip_version: String representing the IP version.
    :return: IP address as a string if found, otherwise None.
    """
    port = port.lower()
    ip_version = ip_version.lower()

    for interface_dict in [network_config['INTERFACE'], network_config['PORTCHANNEL_INTERFACE']]:
        for interface, config in interface_dict.items():
            if interface.lower() == port:
                for ip, version in config.items():
                    if version.lower() == ip_version:
                        return ip

    return None
