        Deletes the first node with the specified key from the list.
        """
        temp = self.head

        if temp is not None:
            if temp.data == key:
                self.head = temp.next
                temp = None
                return

        prev = None
        while temp is not None:
            if temp.data == key:
                break
            prev = temp
            temp = temp.next

        if temp is None:
            return

        prev.next = temp.next
        temp = None

    def find(self, key):
        """
        Returns True if a node with the specified key exists in the list, otherwise returns False.
        """
        temp = self.head
        while temp:
            if temp.data == key:
                return True
            temp = temp.next
        return False

    def display(self):
        """
        Prints the elements of the list in order.
        """
        temp = self.head
        while temp:
