def safe_convert(value):
    """
    Recursively converts string elements in the input structure to floats.
    If a string is None, it remains None. If a string cannot be converted,
    it is replaced with "<unable to convert>".

    Parameters:
    value (str, list, tuple, dict): The input structure to convert.

    Returns:
    float, list, tuple, dict: A new structure with converted values.
    """
    if value is None:
