import random
from functools import partial

def modular_exponentiation(base, exponent, modulus):
    """Recursively computes (base^exponent) % modulus."""
    if exponent == 0:
        return 1
    elif exponent % 2 == 0:
        half_pow = modular_exponentiation(base, exponent // 2, modulus)
        return (half_pow * half_pow) % modulus
    else:
        return (base * modular_exponentiation(base, exponent - 1, modulus)) % modulus

def rabin_miller_test_iteration(n, a, d, s):
    """Performs one iteration of the Rabin-Miller test recursively."""
    def inner_rabin_miller_iteration(x, r):
        if r >= s:
            return x % n != 1
        elif x % n == n - 1:
            return False
        else:
            return inner_rabin_miller_iteration((x * x) % n, r + 1)

    x = modular_exponentiation(a, d, n)
    return inner_rabin_miller_iteration(x, 0)

def is_probable_prime(n, k=5):
    """Determines if a number is a probable prime using the Rabin-Miller test recursively."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0:
        return False

    def compute_s_d(n_minus_1, s):
        if n_minus_1 % 2 != 0:
            return (s, n_minus_1)
        else:
            return compute_s_d(n_minus_1 // 2, s + 1)

    s, d = compute_s_d(n - 1, 0)

    def rabin_miller(s, d, k):
        if k <= 0:
            return True
        else:
            a = random.randrange(2, n - 1)
            return not rabin_miller_test_iteration(n, a, d, s) and rabin_miller(s, d, k - 1)

    return rabin_miller(s, d, k)
