def gcd(a, b):
    """Compute the greatest common divisor of a and b using the Euclidean algorithm."""
    while b:
        a, b = b, a % b
    return a

def lcm_two_numbers(a, b):
    """Compute the LCM of two numbers given their GCD."""
    return (a * b) // gcd(a, b)

def lcm_of_list(numbers):
    """Compute the LCM of a list of numbers."""
    lcm_result = 1
    for number in numbers:
        lcm_result = lcm_two_numbers(lcm_result, number)
    return lcm_result

def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_factors(n):
    """Return all the prime factors of n."""
    factors = []
    # Check for number of 2's
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    # Check for odd factors from 3 onwards
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            if is_prime(i):
                factors.append(i)
            n //= i
    # n must be a prime number greater than 2
    if n > 2:
        factors.append(n)
    return factors

def prime_factors_of_lcm(numbers):
    """Compute the LCM of the list of numbers and return its prime factors."""
    lcm = lcm_of_list(numbers)
    return prime_factors(lcm)

