def prime_sum(limit):
    """
    Computes the sum of all prime numbers less than or equal to the given limit using the Sieve of Eratosthenes algorithm.

    :param limit: An integer representing the upper bound for finding prime numbers.
    :return: The sum of all prime numbers less than or equal to limit.
    """
    if limit < 2:
        return 0

    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(limit ** 0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, limit + 1, start):
                is_prime[multiple] = False

    return sum(index for index, prime in enumerate(is_prime) if prime)
