class Matrix:
    def __init__(self, data):
        """
        Initializes the Matrix with a 2D list of integers.
        Raises ValueError if the input is not a valid 2D list with rows of the same length.
        """
        if not data or not all(len(row) == len(data[0]) for row in data):
            raise ValueError("Input must be a 2D list with rows of the same length")
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0])

    def __str__(self):
        """
        Returns a string representation of the matrix.
        Each row is on a new line with elements separated by spaces.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])

    def add(self, other):
        """
        Adds two matrices and returns a new Matrix object representing the sum.
        Raises ValueError if the matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to be added")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiplies two matrices and returns a new Matrix object representing the product.
        Raises ValueError if the number of columns in the first matrix is not equal to the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to number of rows in the second matrix")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def transpose(self):
        """
        Returns a new Matrix object representing the transpose of the matrix.
        """
        result = [
            [self.data[j][i] for j in range(self.rows)]
            for i in range(self.cols)
        ]
        return Matrix(result)

    def __add__(self, other):
        """
        Overloads the + operator to add two matrices.
        """
        return self.add(other)

    def __mul__(self, other):
        """
        Overloads the * operator to multiply two matrices.
        """
        return self.multiply(other)
