import math

def is_prime(num):
    """Check if a number is prime."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_generator():
    """Generate an infinite sequence of prime numbers."""
    yield 2
    yield 3
    candidate = 5
    while True:
        if is_prime(candidate):
            yield candidate
        candidate += 2

def find_nth_prime(n):
    """Return the nth prime number."""
    gen = prime_generator()
    prime = next(gen)
    for _ in range(1, n):
        prime = next(gen)
    return prime

