def extract_priors(input_dict):
    """
    Processes a dictionary of objects and their parameters to extract priors.

    Parameters:
    input_dict (dict): A dictionary where keys are object names and values are dictionaries of parameters.

    Returns:
    dict: A dictionary mapping (object_name, parameter_name) to a string representing the prior.
    """
    priors = {}
    for obj_name, params_dict in input_dict.items():
        for param in params_dict.values():
            if isinstance(param, list) and len(param) >= 3:
                param_name, jumps, prior_info, *condition = param
                if jumps == 1 and (not condition or condition[0]):
                    prior_type, prior_params = prior_info
                    prior_str = f'{prior_type}: {prior_params}'
                    priors[(obj_name, param_name)] = prior_str
    return priors
```

