class Graph:
    def __init__(self):
        self.adjacency_list = {}

    def add_edge(self, u, v):
        """Adds an undirected edge between nodes u and v."""
        if u not in self.adjacency_list:
            self.adjacency_list[u] = set()
        if v not in self.adjacency_list:
            self.adjacency_list[v] = set()

        self.adjacency_list[u].add(v)
        self.adjacency_list[v].add(u)

    def remove_edge(self, u, v):
        """Removes the undirected edge between nodes u and v if it exists."""
        if u in self.adjacency_list and v in self.adjacency_list:
            self.adjacency_list[u].discard(v)
            self.adjacency_list[v].discard(u)

    def has_edge(self, u, v):
        """Returns True if there is an undirected edge between nodes u and v, otherwise False."""
        return u in self.adjacency_list and v in self.adjacency_list[u]

    def neighbors(self, u):
        """Returns a list of all nodes that are directly connected to node u."""
        return list(self.adjacency_list.get(u, []))
