def can_complete_roundtrip(reaches):
    """
    Determines if a jumper can complete a round trip visiting each trampoline
    at least once in both directions (left to right and then right to left).

    :param reaches: List of integers representing the maximum horizontal distance
                    each trampoline can safely propel the jumper.
    :return: True if the round trip is feasible, False otherwise.
    """
    num_trampolines = len(reaches)
    positions = [0]  # Starting from the first trampoline

    # Try to make the forward journey
    while positions:
        current = positions.pop(0)
        max_reach = reaches[current]
        for next_tramp in range(current + 1, num_trampolines):
            if 10 * (next_tramp - current) <= max_reach:
                positions.append(next_tramp)
            else:
                break
        else:
            break
    else:
        return False

    # Try to make the backward journey
    positions = [num_trampolines - 1]  # Now starting from the last trampoline
    while positions:
        current = positions.pop(0)
        max_reach = reaches[current]
        for prev_tramp in range(current - 1, -1, -1):
            if 10 * (current - prev_tramp) <= max_reach:
                positions.append(prev_tramp)
            else:
                break
        else:
            break
    else:
        return False

    return True

