```python
def shunting_yard(expression):
    """
    Convert an infix expression to a postfix expression using the Shunting Yard algorithm.

    :param expression: A string representing the infix expression.
    :return: A list of tokens representing the postfix expression.
    """
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    output_queue = []
    operator_stack = []

    tokens = expression.split()

    for token in tokens:
        if token.isdigit():
            output_queue.append(token)
        elif token in precedence:
            while (operator_stack and operator_stack[-1] != '(' and
                   precedence[operator_stack[-1]] >= precedence[token]):
                output_queue.append(operator_stack.pop())
            operator_stack.append(token)
        elif token == '(':
            operator_stack.append(token)
        elif token == ')':
            while operator_stack and operator_stack[-1] != '(':
                output_queue.append(operator_stack.pop())
            operator_stack.pop()

    while operator_stack:
        output_queue.append(operator_stack.pop())

    return output_queue

def evaluate_postfix(postfix):
    """
    Evaluate a postfix expression using a stack.

    :param postfix: A list of tokens representing the postfix expression.
    :return: The result of the evaluated postfix expression.
    """
    stack = []

    for token in postfix:
        if token.isdigit():
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)

    return stack.pop()

def evaluate_expression(expression):
    """
    Evaluate a mathematical expression using the Shunting Yard algorithm.

    :param expression: A string representing the mathematical expression.
    :return: The result of the evaluated expression.
    """
    expression = expression.replace('(', ' ( ').replace(')', ' ) ').replace('+', ' + ').replace('-', ' - ').replace('*', ' * ').replace('/', ' / ')
    postfix = shunting_yard(expression)
    return evaluate_postfix(postfix)

# Example usage
expression = "( 3 + 5 ) * ( 2 - 4 )"
print(f"Evaluating expression: {expression}")
result = evaluate_expression(expression)
print(f"Result: {result}")
