class SinglyLinkedList:
    def __init__(self):
        self.head = None

    def add(self, data):
        """Adds a new node with the specified data to the end of the list."""
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            return
        last = self.head
        while last.next:
            last = last.next
        last.next = new_node

    def remove(self, data):
        """Removes the first node with the specified data from the list."""
        current = self.head
        previous = None
        while current and current.data != data:
            previous = current
            current = current.next
        if not current:
            return
        if not previous:
            self.head = current.next
        else:
            previous.next = current.next

    def display(self):
        """Prints the data of each node in the list, from head to end."""
        current = self.head
        while current:
            print(current.data, end=" -> ")
            current = current.next
        print("None")
