def validate_brackets(s):
    """
    Determines if the input string s is correctly bracketed according to the specified rules.

    :param s: A string consisting of characters from the set { '[', ']', '{', '}' }
    :return: True if the string is correctly bracketed, otherwise False
    """
    if not s:
        return True

    if any(s[i] == s[i + 1] for i in range(len(s) - 1)):
        return False

    stack = []
    matching_bracket = {')': '(', '}': '{', ']': '['}
    opening_brackets = {'(', '{', '['}
    closing_brackets = {')', '}', ']'}

    for char in s:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack or stack[-1] != matching_bracket[char]:
                return False
            stack.pop()

    return not stack
```

