def find_primes_in_range(start, end):
    """
    Returns a list of all prime numbers within the inclusive range [start, end].

    :param start: The starting integer of the range.
    :param end: The ending integer of the range.
    :return: A list of prime numbers in ascending order.
    """
    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    if end < 2:
        return []

    primes = []
    if start <= 2:
        primes.append(2)
        start = 3
    if start % 2 == 0:
        start += 1

    for num in range(start, end + 1, 2):
        if is_prime(num):
            primes.append(num)

    return primes

