class ListIterator:
    def __init__(self, lst):
        self.lst = lst
        self.index = 0

    def has_next(self):
        return self.index < len(self.lst)

    def peek(self):
        if self.has_next():
            return self.lst[self.index]
        raise StopIteration

    def next(self):
        if self.has_next():
            value = self.lst[self.index]
            self.index += 1
            return value
        raise StopIteration


def merge_sorted_lists(list1, list2):
    """
    Merges two sorted lists into a new sorted list.

    :param list1: First sorted list of integers.
    :param list2: Second sorted list of integers.
    :return: A new sorted list containing all elements from list1 and list2.
    """
    iter1 = ListIterator(list1)
    iter2 = ListIterator(list2)
    merged_list = []

    while iter1.has_next() and iter2.has_next():
        if iter1.peek() <= iter2.peek():
            merged_list.append(iter1.next())
        else:
            merged_list.append(iter2.next())

    while iter1.has_next():
        merged_list.append(iter1.next())

    while iter2.has_next():
        merged_list.append(iter2.next())

    return merged_list
