def transform_nested_dict(nested_dict, transform_fn):
    """
    Recursively transforms all keys and values in a nested dictionary
    using the provided transformation function. Handles up to 1000 
    levels of nesting efficiently.

    :param nested_dict: (dict) The nested dictionary to be transformed.
    :param transform_fn: (function) The function to apply to keys and values.
    :return: (dict) The transformed nested dictionary.
    """
    if not isinstance(nested_dict, dict):
        return transform_fn(nested_dict) if isinstance(nested_dict, str) else nested_dict

    transformed_dict = {}
    for key, value in nested_dict.items():
        new_key = transform_fn(key)
        if isinstance(value, dict):
            new_value = transform_nested_dict(value, transform_fn)
        elif isinstance(value, str):
            new_value = transform_fn(value)
        else:
            new_value = value

        transformed_dict[new_key] = new_value

    return transformed_dict


