def fibonacci_recursive(n):
    """Recursively returns the nth Fibonacci number. Raises ValueError for non-positive integers."""
    if n <= 0:
        raise ValueError("Input should be a positive integer")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return fibonacci_recursive(n - 1) + fibonacci_recursive(n - 2)

def fibonacci_iterative(n):
    """Iteratively returns the nth Fibonacci number. Raises ValueError for non-positive integers."""
    if n <= 0:
        raise ValueError("Input should be a positive integer")
    elif n == 1:
        return 0
    elif n == 2:
        return 1

    a, b = 0, 1
    for _ in range(2, n):
        a, b = b, a + b
    return b

