class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with the given 2D list data.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def __add__(self, other):
        """
        Adds two matrices if they have the same dimensions.
        """
        if isinstance(other, Matrix) and self.rows == other.rows and self.cols == other.cols:
            result = [
                [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
                for i in range(self.rows)
            ]
            return Matrix(result)
        else:
            raise ValueError("Matrices must have the same dimensions for addition")

    def __sub__(self, other):
        """
        Subtracts the second matrix from the first if they have the same dimensions.
        """
        if isinstance(other, Matrix) and self.rows == other.rows and self.cols == other.cols:
            result = [
                [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
                for i in range(self.rows)
            ]
            return Matrix(result)
        else:
            raise ValueError("Matrices must have the same dimensions for subtraction")

    def __mul__(self, other):
        """
        Multiplies two matrices if the number of columns in the first matrix equals the number of rows in the second matrix.
        """
        if isinstance(other, Matrix) and self.cols == other.rows:
            result = [
                [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
                for i in range(self.rows)
            ]
            return Matrix(result)
        else:
            raise ValueError("Incompatible dimensions for matrix multiplication")

    def transpose(self):
        """
        Returns the transpose of the matrix.
        """
        result = [
            [self.data[j][i] for j in range(self.rows)]
            for i in range(self.cols)
        ]
        return Matrix(result)

    def __str__(self):
        """
        Returns a string representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])
