def sort_dict_by_values(d):
    """
    Sorts a dictionary by its values in descending order.
    Nested dictionaries remain unsorted.

    Parameters:
    d (dict): The dictionary to be sorted.

    Returns:
    dict: A new dictionary with the same key-value pairs, sorted by values.
    """
    def sort_inner_dict(d):
        if isinstance(d, dict):
            return {k: sort_inner_dict(v) for k, v in sorted(d.items(), key=lambda item: (not isinstance(item[1], dict), item[1] if not isinstance(item[1], dict) else 0), reverse=True)}
        else:
            return d

    return sort_inner_dict(d)

