def is_balanced(expression):
    """
    Check if the given expression has balanced brackets and valid variables within angle brackets.

    :param expression: A string representing the expression to be checked.
    :return: True if the expression is balanced, False otherwise.
    """
    def is_alphanumeric(var):
        """
        Check if the given variable is strictly alphanumeric.

        :param var: A string representing the variable to be checked.
        :return: True if the variable is alphanumeric, False otherwise.
        """
        return var.isalnum()

    def check_braces(string, opening, closing):
        """
        Check if the braces in the string are balanced.

        :param string: A string to check for balanced braces.
        :param opening: The opening brace character.
        :param closing: The closing brace character.
        :return: True if the braces are balanced, False otherwise.
        """
        stack = []
        for char in string:
            if char == opening:
                stack.append(char)
            elif char == closing:
                if not stack or stack[-1] != opening:
                    return False
                stack.pop()
        return not stack

    stack = []
    i = 0
    n = len(expression)

    while i < n:
        char = expression[i]
        if char in '({[':
            stack.append(char)
        elif char == ')':
            if not stack or stack[-1] != '(':
                return False
            stack.pop()
        elif char == '}':
            if not stack or stack[-1] != '{':
                return False
            stack.pop()
        elif char == ']':
            if not stack or stack[-1] != '[':
                return False
            stack.pop()
        elif char == '<':
            j = i + 1
            while j < n and expression[j] != '>':
                if not expression[j].isalnum():
                    return False
                j += 1
            if j == n or expression[j] != '>':
                return False
            i = j
        i += 1

    return not stack
