def find_delimiter(data):
    """
    Determines the delimiter used in a CSV header row.

    Parameters:
    data (str): The header row of a CSV file.

    Returns:
    str: The delimiter used in the CSV file.
    """
    possible_delimiters = [",", ";", "\t", "|", "&", "*", "$"]
    delimiter_count = {delimiter: 0 for delimiter in possible_delimiters}

    for char in data:
        if char in delimiter_count:
            delimiter_count[char] += 1

    max_count = max(delimiter_count.values())
    for delimiter in possible_delimiters:
        if delimiter_count[delimiter] == max_count:
            return delimiter
