def find_sequence(words, prefixes):
    """
    Finds the start and end indices of a sequence of words in the list that can be replaced by the given prefixes.

    :param words: List of words (strings).
    :param prefixes: List of prefixes (strings).
    :return: Tuple of start and end indices if a matching sequence is found, otherwise (-1, -1).
    """
    prefix_map = {}
    for i, word in enumerate(words):
        if word in prefix_map:
            prefix_map[word].append(i)
        else:
            prefix_map[word] = [i]

    for start in prefix_map.get(prefixes[0], []):
        match = True
        for offset in range(1, len(prefixes)):
            if (start + offset) >= len(words) or words[start + offset] != prefixes[offset]:
                match = False
                break
        if match:
            return (start, start + len(prefixes) - 1)

    return (-1, -1)
