def merge_dicts(d1, d2):
    """
    Merges two dictionaries with values from d1 taking precedence over d2.
    Handles nested dictionaries recursively.

    :param d1: First dictionary with default values.
    :param d2: Second dictionary with row data.
    :return: Merged dictionary.
    """
    if d1 is None and d2 is None:
        return None
    if d1 is None:
        return d2
    if d2 is None:
        return d1

    d3 = d2.copy()
    for key, value in d1.items():
        if isinstance(value, dict) and isinstance(d3.get(key), dict):
            d3[key] = merge_dicts(value, d3[key])
        else:
            d3[key] = value

    return d3
