class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with the given 2D list data.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def __add__(self, other):
        """
        Adds two matrices of the same dimensions.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same dimensions to add.")

        result = [[self.data[i][j] + other.data[i][j] for j in range(self.cols)] for i in range(self.rows)]
        return Matrix(result)

    def __sub__(self, other):
        """
        Subtracts two matrices of the same dimensions.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same dimensions to subtract.")

        result = [[self.data[i][j] - other.data[i][j] for j in range(self.cols)] for i in range(self.rows)]
        return Matrix(result)

    def __mul__(self, other):
        """
        Multiplies two matrices where the number of columns in the first matrix
        equals the number of rows in the second matrix.
        """
        if not isinstance(other, Matrix) or self.cols != other.rows:
            raise ValueError("Number of columns in first matrix must equal number of rows in second matrix for multiplication.")

        result = [[sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)] for i in range(self.rows)]
        return Matrix(result)

    def transpose(self):
        """
        Returns the transpose of the matrix.
        """
        result = [[self.data[j][i] for j in range(self.rows)] for i in range(self.cols)]
        return Matrix(result)

    def determinant(self):
        """
        Returns the determinant of the matrix (only for square matrices).
        """
        if self.rows != self.cols:
            raise ValueError("Matrix must be square to calculate determinant.")

        if self.rows == 1:
            return self.data[0][0]
        elif self.rows == 2:
            return self.data[0][0] * self.data[1][1] - self.data[0][1] * self.data[1][0]
        else:
            det = 0
            for c in range(self.cols):
                sub_matrix = self._get_submatrix(0, c)
                sign = (-1) ** c
                sub_det = sub_matrix.determinant()
                det += sign * self.data[0][c] * sub_det
            return det

    def _get_submatrix(self, exclude_row, exclude_col):
        """
        Returns a submatrix excluding the specified row and column.
        """
        return Matrix([
            [self.data[r][c] for c in range(self.cols) if c != exclude_col]
            for r in range(self.rows) if r != exclude_row
        ])

    def __str__(self):
        """
        Returns a string representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])
