    Calculate the range of a particle in centimeters given its energy in MeV and type ('electron' or 'muon').

    Parameters:
    energy (float): The energy of the particle in MeV.
    particle_type (str): The type of the particle, either 'electron' or 'muon'.

    Returns:
    float or None: The range of the particle in centimeters, or None if the energy is outside the valid range.
    """
    # Convert energy from MeV to eV
    energy *= 1e6

    # Validate energy range
    if not (100e6 <= energy <= 1000e6):
        return None

    # Calculate range based on particle type
    if particle_type == 'electron':
        return 0.01 * (energy ** 1.77)
    elif particle_type == 'muon':
        return 0.002 * (energy ** 2.1)
    else:
        return None
