def serialize_data(data):
    """
    Serializes the input data according to specific rules:
    - Lists are converted to tuples with elements in the same order.
    - Dictionaries are converted to tuples of sorted key-value pairs.
    - Other data types are returned unchanged.
    Handles nested data structures recursively.
    """
    if isinstance(data, list):
        return tuple(serialize_data(item) for item in data)
    elif isinstance(data, dict):
        return tuple((key, serialize_data(value)) for key, value in sorted(data.items()))
    else:
        return data
