def prime_sum(n):
    """
    Calculate the sum of all prime numbers less than n.

    Parameters:
    n (int): The upper limit (exclusive) for calculating the sum of primes.

    Returns:
    int: The sum of all prime numbers less than n.
    """
    if n <= 2:
        return 0

    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(n**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, n, start):
                is_prime[multiple] = False

    return sum(index for index, prime in enumerate(is_prime) if prime)
