def is_not_prime(num):
    """
    Check if a number has divisors other than 1 and itself.

    :param num: Integer to check
    :return: True if the number is not prime, False otherwise
    """
    if num < 4:
        return False
    for i in range(2, num):
        if num % i == 0:
            return True
    return False

def find_consecutive_non_primes(n):
    """
    Find n consecutive non-prime numbers.

    :param n: Number of consecutive non-prime numbers to find
    :return: Tuple (start, end) where start and end are the first and last of the n consecutive non-prime numbers
    """
    number = 4
    count = 0
    while True:
        if is_not_prime(number):
            count += 1
        else:
            count = 0
        if count == n:
            return number - n + 1, number
        number += 1
