def get_overlap(feat, cns):
    """
    Calculate the overlap between a genomic feature and a region of interest (cns) considering strand specificity.

    :param feat: dict, genomic feature with 'start' and 'end' keys
    :param cns: tuple, region of interest as (start, end, strand)
    :return: tuple, overlap range as (start, end) or None if no overlap
    """
    feat_start, feat_end = feat['start'], feat['end']
    cns_start, cns_end, cns_strand = cns

    overlap_start = max(feat_start, cns_start)
    overlap_end = min(feat_end, cns_end)

    if overlap_start <= overlap_end:
        if cns_strand == '+':
            return (overlap_start, overlap_end)
        elif cns_strand == '-':
            return (overlap_end, overlap_start)

    return None
