class Graph:
    def __init__(self):
        """Initialize an empty dictionary to store the graph data."""
        self.adjacency_list = {}

    def add_edge(self, vertex1, vertex2):
        """Add an edge between vertex1 and vertex2."""
        if vertex1 not in self.adjacency_list:
            self.adjacency_list[vertex1] = []
        if vertex2 not in self.adjacency_list:
            self.adjacency_list[vertex2] = []

        self.adjacency_list[vertex1].append(vertex2)
        self.adjacency_list[vertex2].append(vertex1)

    def remove_edge(self, vertex1, vertex2):
        """Remove an edge between vertex1 and vertex2 if it exists."""
        if vertex1 in self.adjacency_list and vertex2 in self.adjacency_list:
            self.adjacency_list[vertex1].remove(vertex2)
            self.adjacency_list[vertex2].remove(vertex1)

            if not self.adjacency_list[vertex1]:
                del self.adjacency_list[vertex1]
            if not self.adjacency_list[vertex2]:
                del self.adjacency_list[vertex2]

    def has_edge(self, vertex1, vertex2):
        """Return True if there is an edge between vertex1 and vertex2, otherwise False."""
        return (vertex1 in self.adjacency_list and vertex2 in self.adjacency_list[vertex1])

    def get_neighbors(self, vertex):
        """Return a list of all neighbors of the given vertex."""
        return self.adjacency_list.get(vertex, [])

    def print_graph(self):
        """Print the graph in a readable format."""
        for vertex, neighbors in self.adjacency_list.items():
            print(f"{vertex}: {neighbors}")

