def countWays(S1, S2):
    """
    Counts the number of distinct subsequences of S1 that are equal to S2 without using dynamic programming.

    :param S1: The source string from which subsequences are to be counted.
    :param S2: The target string which subsequences of S1 should match.
    :return: The number of distinct subsequences of S1 that are equal to S2.
    """
    def helper(m, n):
        if n == 0:
            return 1
        if m == 0:
            return 0
        if S1[m-1] == S2[n-1]:
            return helper(m-1, n-1) + helper(m-1, n)
        else:
            return helper(m-1, n)

    return helper(len(S1), len(S2))
