from collections import Counter, defaultdict

def filter_events(data):
    """
    Filters out duplicate events, keeping only one unique event per day and per source.

    Parameters:
    data (dict): A dictionary where keys are event identifiers and values are lists
                 containing event details and associated issues, IDs, and URLs.

    Returns:
    dict: A dictionary with unique event tuples as keys and dictionaries containing
          issues, IDs, sources, and URLs as values.
    """
    filtered_data = defaultdict(lambda: {'issues': Counter(), 'ids': [], 'sources': [], 'urls': []})

    for event in data.values():
        date, source, target, event_code, *issues_info = event
        event_key = (date, source, target, event_code)

        for issue_info in issues_info:
            if issue_info.startswith('ID_'):
                if issue_info not in filtered_data[event_key]['ids']:
                    filtered_data[event_key]['ids'].append(issue_info)
            elif issue_info.startswith('http'):
                if issue_info not in filtered_data[event_key]['urls']:
                    filtered_data[event_key]['urls'].append(issue_info)
            else:
                issue, count = issue_info.split(',')
                filtered_data[event_key]['issues'][issue] += int(count)

        if source not in filtered_data[event_key]['sources']:
            filtered_data[event_key]['sources'].append(source)

    return dict(filtered_data)
