import math

def find_closest_pair(points):
    """
    Finds the closest pair of points in a 2D space and returns their indices.

    :param points: List of tuples, where each tuple contains the (x, y) coordinates of a point.
    :return: Tuple containing the indices of the closest pair of points.
    """
    def distance(p1, p2):
        return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    min_dist = float('inf')
    closest_pair = (0, 0)

    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            d = distance(points[i], points[j])
            if d < min_dist:
                min_dist = d
                closest_pair = (i, j)

    return closest_pair
