def generate_primes(n):
    """
    Generate a list of prime numbers up to a given number n using the Sieve of Eratosthenes algorithm.

    Parameters:
    n (int): The upper limit for generating prime numbers (inclusive).

    Returns:
    list: A list of prime numbers less than or equal to n.
    """
    primes = []
    sieve = [True] * (n + 1)
    for num in range(2, int(n**0.5) + 1):
        if sieve[num]:
            for multiple in range(num*num, n + 1, num):
                sieve[multiple] = False
    for num in range(2, n + 1):
        if sieve[num]:
            primes.append(num)
    return primes
```

