def apply_operation(d, func):
    """
    Applies a given function to all integer values in a nested dictionary.

    Parameters:
    d (dict): The input dictionary which may contain nested dictionaries and integer values.
    func (function): A function that takes an integer and returns an integer.

    Returns:
    dict: A new dictionary with the same structure as `d`, but with all integer values transformed by `func`.
    """
    def recursive_apply(item):
        if isinstance(item, dict):
            return {k: recursive_apply(v) for k, v in item.items()}
        elif isinstance(item, int):
            return func(item)
        else:
            return item
    return {k: recursive_apply(v) for k, v in d.items()}
