def sum_of_primes_below_n(n):
    """
    Computes the sum of all prime numbers less than a given integer n.

    Parameters:
    n (int): The upper limit (exclusive) for finding prime numbers.

    Returns:
    int: The sum of all prime numbers less than n.
    """
    if n <= 2:
        return 0
    sieve = [True] * n
    sieve[0] = sieve[1] = False  # 0 and 1 are not primes
    for p in range(2, int(n**0.5) + 1):
        if sieve[p]:
            for multiple in range(p * p, n, p):
                sieve[multiple] = False
    return sum(i for i in range(2, n) if sieve[i])
