import json

def extract_values(json_string):
    """
    Extracts all values from a JSON object, including nested objects and arrays.

    :param json_string: A string representing a JSON object.
    :return: A list of all values from the JSON object.
    """
    def recursive_extract(obj):
        if isinstance(obj, dict):
            for value in obj.values():
                yield from recursive_extract(value)
        elif isinstance(obj, list):
            for item in obj:
                yield from recursive_extract(item)
        else:
            yield obj

    data = json.loads(json_string)
    return list(recursive_extract(data))

