class DataViewer:
    def __init__(self, visible_data=None):
        """
        Initializes the DataViewer with an optional list of visible data keys.

        :param visible_data: List of keys that are visible in the data view.
        """
        self.data_view = {}
        self.visible_data = visible_data if visible_data is not None else []

    def get_data_view(self, name=None, data_element=None, default_data_view=None):
        """
        Retrieves or updates the data view based on the provided parameters.

        :param name: The name of the data element to retrieve.
        :param data_element: A dictionary of data elements to update.
        :param default_data_view: A dictionary to set as the default data view.
        :return: A dictionary of visible data elements or a specific data element if name is provided.
        """
        if default_data_view is not None:
            self.data_view = self._merge_dicts(self.data_view, default_data_view)

        if data_element is not None:
            self.data_view = self._merge_dicts(self.data_view, data_element)

        if name is not None:
            return self.data_view.get(name) if name in self.visible_data else None

        return {k: v for k, v in self.data_view.items() if k in self.visible_data}

    @staticmethod
    def _merge_dicts(base, additional):
        """
        Recursively merges two dictionaries, preferring values from the additional dictionary.

        :param base: The base dictionary to merge into.
        :param additional: The dictionary with additional data to merge.
        :return: The merged dictionary.
        """
        for key, value in additional.items():
            if isinstance(base.get(key), dict) and isinstance(value, dict):
                base[key] = DataViewer._merge_dicts(base[key], value)
            else:
                base[key] = value
        return base
