class DisjointSet:
    def __init__(self, n):
        self.parent = [i for i in range(n)]
        self.rank = [1 for _ in range(n)]  # Using for height
        self.sum_of_squares = [i*i for i in range(n)]  # Initially, each set has only one element and its square is i*i

    def find(self, u):
        """Find the root of the set containing u with path compression."""
        if self.parent[u] != u:
            originalParent = self.parent[u]
            self.parent[u] = self.find(self.parent[u])  # Path compression
            self.rank[u] = self.rank[self.parent[u]] + 1 if self.parent[u] != originalParent else self.rank[u]
        return self.parent[u]

    def union(self, x, y):
        """Union the sets containing x and y using the modified heuristic."""
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX != rootY:
            sumX = self.sum_of_squares[rootX]
            sumY = self.sum_of_squares[rootY]

            if sumX < sumY:
                rootX, rootY = rootY, rootX

            self.parent[rootY] = rootX
            self.sum_of_squares[rootX] += self.sum_of_squares[rootY]

            if self.rank[rootX] == self.rank[rootY]:
                self.rank[rootX] += 1

    def isConnected(self, x, y):
        """Check if x and y are in the same set."""
        return self.find(x) == self.find(y)
