def deserialize_set(data):
    """
    Parses a string representing a JSON-like array of integers and returns a set of integers.

    :param data: A string representing a JSON-like array of integers.
    :return: A set of integers.
    """
    data = data.strip()
    if not (data.startswith('[') and data.endswith(']')):
        raise ValueError("Input string is not properly formatted as a JSON array.")
    data = data[1:-1]
    if not data.strip():
        return set()
    int_strings = data.split(',')
    result_set = set()
    for int_str in int_strings:
        try:
            result_set.add(int(int_str.strip()))
        except ValueError:
            raise ValueError("Input string contains non-integer values.")
    return result_set
