from flask import Flask, jsonify, request, abort

app = Flask(__name__)

# In-memory "database"
posts = []

def find_post(post_id):
    """
    Helper function to find a post by its ID.

    :param post_id: ID of the post to find.
    :return: The post if found, otherwise None.
    """
    return next((post for post in posts if post['id'] == post_id), None)

@app.route('/posts', methods=['GET'])
def get_posts():
    """
    Endpoint to get all posts.

    :return: JSON response with all posts.
    """
    return jsonify(posts)

@app.route('/posts/<int:post_id>', methods=['GET'])
def get_post(post_id):
    """
    Endpoint to get a single post by ID.

    :param post_id: ID of the post to retrieve.
    :return: JSON response with the post or 404 error if not found.
    """
    post = find_post(post_id)
    if post is None:
        abort(404)
    return jsonify(post)

@app.route('/posts', methods=['POST'])
def create_post():
    """
    Endpoint to create a new post.

    :return: JSON response with the created post and 201 status code.
    """
    if not request.json or 'title' not in request.json or 'content' not in request.json:
        abort(400)
    new_post_id = 1 if len(posts) == 0 else posts[-1]['id'] + 1
    new_post = {
        'id': new_post_id,
        'title': request.json['title'],
        'content': request.json['content']
    }
    posts.append(new_post)
    return jsonify(new_post), 201

@app.route('/posts/<int:post_id>', methods=['PUT'])
def update_post(post_id):
    """
    Endpoint to update an existing post.

    :param post_id: ID of the post to update.
    :return: JSON response with the updated post or 404 error if not found.
    """
    post = find_post(post_id)
    if post is None:
        abort(404)
    if not request.json:
        abort(400)
    post['title'] = request.json.get('title', post['title'])
    post['content'] = request.json.get('content', post['content'])
    return jsonify(post)

