from typing import List, Tuple

def check_valid_fov(directories: List[Tuple[str, List[int]]], target_directory: str, target_fov: int) -> bool:
    """
    Recursively checks if the given FOV index is valid for the specified directory.

    :param directories: List of tuples containing directory names and their valid FOV indices.
    :param target_directory: The directory name to check.
    :param target_fov: The FOV index to validate.
    :return: True if the FOV index is valid for the directory, False otherwise.
    """
    if not directories:
        return False

    current_directory, valid_fovs = directories[0]

    if current_directory == target_directory:
        def check_fov_in_list(fov_list: List[int]) -> bool:
            if not fov_list:
                return False
            if fov_list[0] == target_fov:
                return True
            return check_fov_in_list(fov_list[1:])

        return check_fov_in_list(valid_fovs)

    return check_valid_fov(directories[1:], target_directory, target_fov)
