class Node:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Insert a new node with the given key into the BST."""
        if self.root is None:
            self.root = Node(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        if key < node.val:
            if node.left is None:
                node.left = Node(key)
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = Node(key)
            else:
                self._insert(node.right, key)

    def search(self, key):
        """Search for a node with the given key in the BST."""
        return self._search(self.root, key)

    def _search(self, node, key):
        if node is None or node.val == key:
            return node

        if key < node.val:
            return self._search(node.left, key)

        return self._search(node.right, key)

    def inorder_traversal(self):
        """Return a list of keys in the BST in in-order traversal."""
        return self._inorder_traversal(self.root, [])

    def _inorder_traversal(self, node, result):
        if node is not None:
            self._inorder_traversal(node.left, result)
            result.append(node.val)
            self._inorder_traversal(node.right, result)
        return result

    def preorder_traversal(self):
        """Return a list of keys in the BST in pre-order traversal."""
        return self._preorder_traversal(self.root, [])

    def _preorder_traversal(self, node, result):
        if node is not None:
            result.append(node.val)
            self._preorder_traversal(node.left, result)
            self._preorder_traversal(node.right, result)
        return result

    def postorder_traversal(self):
        """Return a list of keys in the BST in post-order traversal."""
        return self._postorder_traversal(self.root, [])

    def _postorder_traversal(self, node, result):
        if node is not None:
            self._postorder_traversal(node.left, result)
            self._postorder_traversal(node.right, result)
            result.append(node.val)
        return result

    def delete_node(self, key):
        """Delete a node with the given key from the BST."""
        self.root = self._delete_node(self.root, key)

    def _delete_node(self, node, key):
        if node is None:
            return node

        if key < node.val:
            node.left = self._delete_node(node.left, key)
        elif key > node.val:
            node.right = self._delete_node(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            temp = self._min_value_node(node.right)
            node.val = temp.val
            node.right = self._delete_node(node.right, temp.val)

        return node

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current
