import threading

class SocialNetwork:
    def __init__(self):
        self.connections = {}  # key: actor, value: dict of connections (other_actors: (type, weight, activity))
        self.lock = threading.Lock()  # Lock for thread-safe modifications

    def add_actor(self, actor):
        """Adds a new actor to the network."""
        with self.lock:
            if actor not in self.connections:
                self.connections[actor] = {}

    def add_connection(self, actor, other_actor, connection_type, weight, activity):
        """Adds a connection from actor to other_actor with the specified type, weight, and activity."""
        with self.lock:
            if actor not in self.connections:
                self.add_actor(actor)
            self.connections[actor][other_actor] = (connection_type, weight, activity)

    def remove_connection(self, actor, other_actor):
        """Removes the connection from actor to other_actor."""
        with self.lock:
            if actor in self.connections and other_actor in self.connections[actor]:
                del self.connections[actor][other_actor]
                if not self.connections[actor]:
                    del self.connections[actor]

    def get_connection(self, actor, other_actor):
        """Returns the connection details from actor to other_actor if it exists, otherwise returns None."""
        with self.lock:
            return self.connections.get(actor, {}).get(other_actor)

    def get_all_connections(self, actor):
        """Returns all connections of actor as a dictionary."""
        with self.lock:
            return self.connections.get(actor, {})

