def has_nested_property(obj, prop_path):
    """
    Checks if a given object has a nested property located at the specified path.

    :param obj: The object to search within.
    :param prop_path: A string representing the path to the nested property.
    :return: True if the nested property exists, False otherwise.
    """
    props = prop_path.split('.')
    current_obj = obj
    for prop in props:
        if isinstance(current_obj, dict) and prop in current_obj:
            current_obj = current_obj[prop]
        elif isinstance(current_obj, list) and prop.isdigit() and int(prop) < len(current_obj):
            current_obj = current_obj[int(prop)]
        else:
            return False
    return True

