class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with the given 2D list `data`.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def __add__(self, other):
        """
        Adds two matrices of the same dimensions.
        """
        if isinstance(other, Matrix) and self.rows == other.rows and self.cols == other.cols:
            result = [
                [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
                for i in range(self.rows)
            ]
            return Matrix(result)
        else:
            raise ValueError("Matrices must be of the same dimensions for addition")

    def __sub__(self, other):
        """
        Subtracts two matrices of the same dimensions.
        """
        if isinstance(other, Matrix) and self.rows == other.rows and self.cols == other.cols:
            result = [
                [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
                for i in range(self.rows)
            ]
            return Matrix(result)
        else:
            raise ValueError("Matrices must be of the same dimensions for subtraction")

    def __mul__(self, other):
        """
        Multiplies two matrices if their dimensions are compatible, or multiplies a matrix by a scalar.
        """
        if isinstance(other, Matrix):
            if self.cols == other.rows:
                result = [
                    [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
                    for i in range(self.rows)
                ]
                return Matrix(result)
            else:
                raise ValueError("Number of columns in the first matrix must be equal to the number of rows in the second matrix for multiplication")
        elif isinstance(other, (int, float)):
            result = [
                [self.data[i][j] * other for j in range(self.cols)]
                for i in range(self.rows)
            ]
            return Matrix(result)
        else:
            raise ValueError("Multiplication is only supported between Matrix and Matrix or Matrix and Scalar")

    def transpose(self):
        """
        Returns the transpose of the matrix.
        """
        result = [
            [self.data[j][i] for j in range(self.rows)]
            for i in range(self.cols)
        ]
        return Matrix(result)

    def __str__(self):
        """
        Returns a string representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])
