def is_perfect_square(n: int) -> bool:
    """Determine whether n is a perfect square using an efficient algorithm."""
    if n < 0:
        return False
    if n == 0 or n == 1:
        return True

    x = n // 2
    while x * x > n:
        x = (x + n // x) // 2
    return x * x == n
