                            new_dp[i][num][(m + num) % 5] += dp[i-1][x][m]
                            new_dp[i][num][(m + num) % 5] %= MOD

        if a[i-1] != 0:
            dp[i] = [[0 for _ in range(5)] for _ in range(4)]
            dp[i][a[i-1]][a[i-1] % 5] = 1
        else:
            dp = new_dp

        ans = dp[i][0][2]
        if i > 1 and a[i-1] != 0:
            ans = 0
            for num in range(1, 4):
                if (a[i-2], num) in good_pairs:
                    ans += dp[i-1][a[i-2]][(2 - num) % 5]
                    ans %= MOD

        print(ans)

        if i-1 < len(queries):
            ind, val = queries[i-1]
            a[ind-1] = val

