def parse_csv_header(csv_data, column_header):
    """
    Parses the CSV data to find the index of the column with the given header.

    :param csv_data: A string representing the CSV data.
    :param column_header: A string representing the column header to find.
    :return: An integer representing the index of the column with the given header, or None if the header is not found.
    """
    def parse_row(row):
        columns = []
        in_quotes = False
        current_column = []

        for char in row:
            if char == '"':
                in_quotes = not in_quotes
            elif char == ',' and not in_quotes:
                columns.append(''.join(current_column).strip())
                current_column = []
            else:
                current_column.append(char)

        columns.append(''.join(current_column).strip())
        return columns

    rows = csv_data.strip().split('\n')
    headers = parse_row(rows[0])

    try:
        return headers.index(column_header)
    except ValueError:
        return None
