def group_segments(segments):
    """
    Groups segments based on their frequency distribution.

    :param segments: List of lists, where each sublist is a segment of integers.
    :return: List of lists, where each sublist contains segments with the same frequency distribution.
    """
    # Dictionary to hold the group of segments
    groups = {}

    for segment in segments:
        # Create a frequency count dictionary for the current segment
        freq_count = {}
        for freq in segment:
            if freq in freq_count:
                freq_count[freq] += 1
            else:
                freq_count[freq] = 1

        # Convert frequency count dictionary to a tuple of (frequency, count) sorted by frequency
        freq_tuple = tuple(sorted(freq_count.items()))

        # Use the sorted tuple as key to group the segments
        if freq_tuple in groups:
            groups[freq_tuple].append(segment)
        else:
            groups[freq_tuple] = [segment]

    # Return the grouped segments
    return list(groups.values())
