class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with the given data.
        :param data: 2D list representing the matrix.
        """
        if not all(isinstance(row, list) and len(row) == len(data[0]) for row in data):
            raise ValueError("Data should be a 2D list with rows of equal length.")
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0])

    def __add__(self, other):
        """
        Adds two matrices.
        :param other: Another Matrix object.
        :return: New Matrix object representing the sum.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices dimensions must match for addition.")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __sub__(self, other):
        """
        Subtracts one matrix from another.
        :param other: Another Matrix object.
        :return: New Matrix object representing the difference.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices dimensions must match for subtraction.")
        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __mul__(self, other):
        """
        Multiplies two matrices.
        :param other: Another Matrix object.
        :return: New Matrix object representing the product.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must match the number of rows in the second matrix for multiplication.")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __str__(self):
        """
        Returns a string representation of the matrix.
        :return: String representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])
