def calculate_dimensions(shape):
    """
    Calculate the dimensions of an image based on the input shape.

    Parameters:
    shape (int or tuple or list): The input shape which can be a single integer,
                                  a tuple/list of two integers, or a tuple/list of three integers.

    Returns:
    tuple: A tuple of two integers representing the height and width of the image.

    Raises:
    ValueError: If the input is not a valid shape.
    """
    if isinstance(shape, int):
        return (shape, shape)
    elif isinstance(shape, (tuple, list)):
        if len(shape) == 2:
            return tuple(shape)
        elif len(shape) == 3:
            return (shape[0], shape[1])
