def is_balanced(expression: str) -> bool:
    """
    Checks if a given expression is balanced in terms of parentheses, brackets, and braces.

    :param expression: A string consisting of '(', ')', '[', ']', '{', and '}'.
    :return: True if the expression is balanced, False otherwise.
    """
    matching_pairs = {')': '(', ']': '[', '}': '{'}
    stack = []

    for char in expression:
        if char in matching_pairs.values():
            stack.append(char)
        elif char in matching_pairs:
            if not stack or stack[-1] != matching_pairs[char]:
                return False
            stack.pop()

    return not stack
