def find_parameter(model, target_param):
    """
    Recursively searches for a parameter with the specified name within a nested model structure.

    :param model: A dictionary representing the nested structure of a machine learning model.
    :param target_param: The name of the parameter to search for.
    :return: The name of the parameter if found, otherwise None.
    """
    if not isinstance(model, dict):
        if getattr(model, 'name', None) == target_param:
            return getattr(model, 'name')
        return None

    for key, value in model.items():
        if isinstance(value, dict) or hasattr(value, 'parameters'):
            found = find_parameter(value, target_param)
            if found:
                return found
        elif getattr(value, 'name', None) == target_param:
            return getattr(value, 'name')
    return None
