from functools import reduce

def text_justify(text: str, width: int) -> str:
    """
    Formats the given text to fit within the specified width, preserving existing line breaks.

    :param text: The input text to be justified.
    :param width: The maximum width of each line.
    :return: The justified text as a string.
    """
    words = text.split(' ')

    def add_word(state, word):
        current_lines, current_line = state
        if word == '\n':
            return current_lines + [current_line.strip()], ''
        elif not current_line or len(current_line) + len(word) + (1 if current_line else 0) <= width:
            return current_lines, (current_line + (' ' if current_line else '') + word)
        else:
            return current_lines + [current_line.strip()], word

    lines, last_line = reduce(add_word, words, ([], ''))
    return '\n'.join(lines + ([last_line.strip()] if last_line.strip() else []))
