def firstUniqChar(s: str) -> int:
    """
    Finds the index of the first non-repeating character in the string.

    Parameters:
    s (str): The input string consisting of lowercase English letters.

    Returns:
    int: The index of the first non-repeating character, or -1 if no such character exists.
    """
    count = {}
    for char in s:
        if char in count:
            count[char] += 1
        else:
            count[char] = 1
    for i, char in enumerate(s):
        if count[char] == 1:
            return i
    return -1
