class TreeNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, val):
        """Inserts a value into the binary search tree."""
        self.root = self._insert_rec(self.root, val)

    def _insert_rec(self, node, val):
        if node is None:
            return TreeNode(val)
        if val < node.val:
            node.left = self._insert_rec(node.left, val)
        else:
            node.right = self._insert_rec(node.right, val)
        return node

    def search(self, val):
        """Returns True if the value is in the tree, False otherwise."""
        return self._search_rec(self.root, val)

    def _search_rec(self, node, val):
        if node is None:
            return False
        if node.val == val:
            return True
        elif val < node.val:
            return self._search_rec(node.left, val)
        else:
            return self._search_rec(node.right, val)

    def inorder_traversal(self):
        """Returns a list of all the values in the tree in inorder (ascending) order."""
        result = []
        self._inorder_traversal_rec(self.root, result)
        return result

    def _inorder_traversal_rec(self, node, result):
        if node is not None:
            self._inorder_traversal_rec(node.left, result)
            result.append(node.val)
            self._inorder_traversal_rec(node.right, result)

    def delete(self, val):
        """Deletes a value from the tree if it exists."""
        self.root = self._delete_rec(self.root, val)

    def _delete_rec(self, node, val):
        if node is None:
            return node

        if val < node.val:
            node.left = self._delete_rec(node.left, val)
        elif val > node.val:
            node.right = self._delete_rec(node.right, val)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            node.val = self._min_value_node(node.right).val
            node.right = self._delete_rec(node.right, node.val)

        return node

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current
