def validate_parentheses(s):
    """
    Determines if a string of parentheses is valid.

    :param s: A string consisting of '(', ')', '{', '}', '[' and ']'.
    :return: True if the string is valid, False otherwise.
    """
    stack = []
    matching_bracket = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in matching_bracket:
            top_element = stack.pop() if stack else '#'
            if matching_bracket[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack
