def check_variable_existence(var_name: str, namespace: dict) -> bool:
    """
    Determines if a variable with the specified name exists in the given namespace
    and has a non-None value. Recursively searches through nested dictionaries.

    :param var_name: The name of the variable to check.
    :param namespace: The namespace to search within, represented as a dictionary.
    :return: True if the variable exists and its value is not None, False otherwise.
    """
    if not isinstance(var_name, str):
        return False

    if not isinstance(namespace, dict):
        return False

    for key, value in namespace.items():
        if key == var_name:
            return value is not None
        elif isinstance(value, dict):
            if check_variable_existence(var_name, value):
                return True

    return False
