def compare_systems(system_a, system_b):
    """
    Recursively compares two nested structures (lists, dictionaries, or other data types).

    :param system_a: The configuration of System A
    :param system_b: The configuration of System B
    :return: True if the configurations are the same, False otherwise
    """
    type_a, type_b = type(system_a), type(system_b)

    if type_a is not type_b:
        return False

    if type_a is list:
        if len(system_a) != len(system_b):
            return False
        return all(compare_systems(sub_a, sub_b) for sub_a, sub_b in zip(system_a, system_b))

    elif type_a is dict:
        if system_a.keys() != system_b.keys():
            return False
        return all(compare_systems(system_a[key], system_b[key]) for key in system_a)

    else:
        return system_a == system_b
