def power(x, y):
    """
    Calculate the power of a number x raised to y using recursion.

    Parameters:
    x (int): The base number.
    y (int): The exponent.

    Returns:
    float: The result of x raised to the power of y.
    """
    # Base case: any number raised to the power of 0 is 1
    if y == 0:
        return 1.0
    # If y is negative, calculate the positive power and take reciprocal
    elif y < 0:
        return 1.0 / power(x, -y)
    # Recursive case: multiply x by the result of x raised to the power of (y-1)
    else:
        return x * power(x, y - 1)
