import math

def shape_normalizer(shape):
    """
    Normalize the shape parameter by replacing each integer with its factorial.

    Parameters:
    shape (int or tuple of int): The shape parameter to normalize.

    Returns:
    tuple: A tuple of factorials of the integers in the input shape.

    Raises:
    ValueError: If the input is neither an integer nor a tuple of integers.
    """
    if isinstance(shape, int):
        return (math.factorial(shape),)
    elif isinstance(shape, tuple):
        return tuple(math.factorial(x) for x in shape)
    else:
        raise ValueError("shape must be either an integer or a tuple of integers")
