def replace_dict_keys(dictionary, key_map):
    """
    Replaces keys in the given dictionary based on the key_map without using built-in dictionary methods.

    :param dictionary: A dictionary with keys as integers or strings and values as lists.
    :param key_map: A dictionary with string keys mapping to new string keys.
    :return: A new dictionary with keys replaced according to key_map, or None if dictionary is None.
    """
    if dictionary is None:
        return None

    res = {}
    for map_key in key_map:
        found = False
        for dict_key in dictionary:
            if map_key == dict_key:
                res[key_map[map_key]] = dictionary[dict_key]
                found = True
                break
        if not found:
            continue

    return res
