def filter_and_format_data(data: dict, keys: list) -> dict:
    """
    Recursively filters out empty strings and converts remaining strings to title case
    for specified keys in the given dictionary.

    :param data: Dictionary with keys mapping to lists of strings.
    :param keys: List of keys to process in the dictionary.
    :return: Dictionary with processed lists for specified keys.
    """
    def helper(data: dict, keys: list, result: dict) -> dict:
        if not keys:
            return result
        key = keys[0]
        if key in data:
            new_values = filter_and_format_list(data[key])
            result[key] = new_values
        return helper(data, keys[1:], result)

    def filter_and_format_list(lst: list) -> list:
        """
        Recursively filters out empty strings and converts remaining strings to title case.

        :param lst: List of strings to process.
        :return: List of processed strings.
        """
        if not lst:
            return []
        head, tail = lst[0], lst[1:]
        if head:
            formatted_head = head.title()
        else:
            formatted_head = None
        rest = filter_and_format_list(tail)
        if formatted_head:
            return [formatted_head] + rest
        else:
            return rest

    return helper(data, keys, {})
