def find_largest_prime_factor(n):
    """
    Returns the largest prime factor of the given integer n.
    If n has no prime factors (i.e., n is 1), returns None.

    :param n: Integer, the number to find the largest prime factor of.
    :return: Integer, the largest prime factor of n, or None if n is 1.
    """
    def is_prime(num):
        """Check if a number is prime."""
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    if n == 1:
        return None

    largest_prime = None

    while n % 2 == 0:
        largest_prime = 2
        n //= 2

    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            largest_prime = i
            n //= i

    if n > 2 and is_prime(n):
        largest_prime = n

    return largest_prime

