def invert_dictionary(original_dict):
    """
    Inverts a dictionary by swapping keys and values.
    If a value appears more than once, the corresponding key in the inverted dictionary
    is a list of all original keys that mapped to that value.

    :param original_dict: Dictionary with string keys and string values.
    :return: Inverted dictionary with string keys and values as either strings or lists of strings.
    """
    inverted_dict = {}
    for key, value in original_dict.items():
        if value not in inverted_dict:
            inverted_dict[value] = key
        else:
            if isinstance(inverted_dict[value], list):
                inverted_dict[value].append(key)
            else:
                inverted_dict[value] = [inverted_dict[value], key]
    return inverted_dict

