class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Inserts a new node with the given key into the tree."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert_recursively(self.root, key)

    def _insert_recursively(self, node, key):
        """Recursively inserts a new node with the given key into the tree."""
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert_recursively(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert_recursively(node.right, key)

    def search(self, key):
        """Returns True if the key exists in the tree, otherwise False."""
        return self._search_recursively(self.root, key)

    def _search_recursively(self, node, key):
        """Recursively searches for the key in the tree."""
        if node is None:
            return False
        if node.val == key:
            return True
        elif key < node.val:
            return self._search_recursively(node.left, key)
        else:
            return self._search_recursively(node.right, key)

    def in_order_traversal(self):
        """Returns a list of keys in the tree in in-order traversal order."""
        return self._in_order_recursively(self.root)

    def _in_order_recursively(self, node):
        """Recursively performs in-order traversal of the tree."""
        result = []
        if node is not None:
            result = self._in_order_recursively(node.left)
            result.append(node.val)
            result = result + self._in_order_recursively(node.right)
        return result
