def find_fibonacci(n, memo=None):
    """
    Computes the nth Fibonacci number using memoization.

    Parameters:
    n (int): The position in the Fibonacci sequence.

    Returns:
    int: The nth Fibonacci number.
    """
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        memo[n] = find_fibonacci(n-1, memo) + find_fibonacci(n-2, memo)
        return memo[n]
