def is_clique(nodes, G):
    """
    Determines if the nodes in the list form a clique in the graph G.

    :param nodes: List of nodes to check for clique formation.
    :param G: Adjacency list representing the graph.
    :return: True if the nodes form a clique, False otherwise.
    """
    if not nodes:
        return True

    unique_nodes = set(nodes)

    for node in unique_nodes:
        if node not in G:
            return False

        neighbors = set(G[node])

        for other_node in unique_nodes:
            if other_node != node and other_node not in neighbors:
                return False

    return True
