import json

class Book:
    def __init__(self, title, author, isbn, num_copies):
        self.title = title
        self.author = author
        self.isbn = isbn
        self.num_copies = num_copies

    def __str__(self):
        return f"'{self.title}' by {self.author}, ISBN: {self.isbn}, Copies: {self.num_copies}"

    def update(self, title=None, author=None, isbn=None, num_copies=None):
        """Update the book details."""
        if title is not None:
            self.title = title
        if author is not None:
            self.author = author
        if isbn is not None:
            self.isbn = isbn
        if num_copies is not None:
            self.num_copies = num_copies

class Bookstore:
    def __init__(self):
        self.books = {}

    def add_book(self, book):
        """Add a book to the inventory. If the book exists, increase the number of copies."""
        if book.isbn in self.books:
            self.books[book.isbn].num_copies += book.num_copies
        else:
            self.books[book.isbn] = book

    def remove_book(self, isbn):
        """Remove a book from the inventory using its ISBN."""
        if isbn in self.books:
            del self.books[isbn]

    def search_books_by_title(self, title):
        """Find all books with a specific title."""
        return [book for book in self.books.values() if book.title == title]

    def search_books_by_author(self, author):
        """Find all books by a specific author."""
        return [book for book in self.books.values() if book.author == author]

    def search_books_by_isbn(self, isbn):
        """Find a book by its ISBN."""
        return [self.books[isbn]] if isbn in self.books else []

    def update_book(self, isbn, **kwargs):
        """Update details of a book identified by its ISBN."""
        if isbn in self.books:
            self.books[isbn].update(**kwargs)

    def total_books(self):
        """Return the total number of books in the inventory."""
        return sum(book.num_copies for book in self.books.values())

    def all_books(self):
        """Return a string representation of all books in the inventory."""
        return '\n'.join(str(book) for book in self.books.values())

    def save_inventory(self, file_path):
        """Save the current inventory to a file in JSON format."""
        with open(file_path, 'w') as f:
            json.dump({isbn: book.__dict__ for isbn, book in self.books.items()}, f)

    def load_inventory(self, file_path):
        """Load the inventory from a JSON file."""
        with open(file_path, 'r') as f:
            data = json.load(f)
            self.books = {isbn: Book(**book_dict) for isbn, book_dict in data.items()}
