    """
    Determines if a string of parentheses is balanced.

    Args:
    s (str): A string containing only the characters '(', ')', '{', '}', '[' and ']'.

    Returns:
    bool: True if the string is balanced, False otherwise.
    """
    matching_parenthesis = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in matching_parenthesis:
            top_element = stack.pop() if stack else '#'
            if matching_parenthesis[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack
