def is_prime(n):
    """Check if a number n is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def next_prime(x):
    """Find the smallest prime number greater than x."""
    candidate = x + 1
    while True:
        if is_prime(candidate):
            return candidate
        candidate += 1

