def merge_sorted_arrays(nums_a, nums_b):
    """
    Merges two sorted arrays into a single sorted array with no consecutive duplicates.

    :param nums_a: List[int] - First sorted array.
    :param nums_b: List[int] - Second sorted array.
    :return: List[int] - Merged sorted array with no consecutive duplicates.
    """
    merged = []
    i, j = 0, 0

    while i < len(nums_a) and j < len(nums_b):
        if merged and merged[-1] == nums_a[i]:
            i += 1
        elif merged and merged[-1] == nums_b[j]:
            j += 1
        elif nums_a[i] < nums_b[j]:
            merged.append(nums_a[i])
            i += 1
        else:
            merged.append(nums_b[j])
            j += 1

    while i < len(nums_a):
        if not merged or merged[-1] != nums_a[i]:
            merged.append(nums_a[i])
        i += 1

    while j < len(nums_b):
        if not merged or merged[-1] != nums_b[j]:
            merged.append(nums_b[j])
        j += 1

    return merged
