def find_longest_increasing_subsequence(nums):
    """
    Returns the longest increasing subsequence from the list of integers.
    If there are multiple subsequences of the same length, returns any one of them.

    :param nums: List[int] - The list of integers.
    :return: List[int] - The longest increasing subsequence.
    """
    if not nums:
        return []

    lis = [[num] for num in nums]

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j] and len(lis[i]) < len(lis[j]) + 1:
                lis[i] = lis[j] + [nums[i]]

    return max(lis, key=len)
```

