def extract_nested_values(json_obj):
    """
    Recursively extracts all values from a JSON object, including those nested within other objects or arrays.

    :param json_obj: A JSON object represented as a Python dictionary or list.
    :return: A list of all extracted values.
    """
    values = []

    if isinstance(json_obj, dict):
        for key, value in json_obj.items():
            values.extend(extract_nested_values(value))
    elif isinstance(json_obj, list):
        for item in json_obj:
