def calculate_average(*scores):
    """
    Calculate the average of a given set of test scores.

    Args:
    *scores: A variable number of arguments representing test scores. 
             Each score can be a string, integer, or float.

    Returns:
    float: The average of the valid test scores, or None if no valid scores are provided.
    """
    if not scores:
        return None

    numeric_scores = []
    for score in scores:
        try:
            numeric_score = float(score)
            numeric_scores.append(numeric_score)
        except ValueError:
            continue

    if not numeric_scores:
        return None

    return sum(numeric_scores) / len(numeric_scores)
