class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class SinglyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None

    def insert(self, value):
        """
        Inserts a new node with the specified value at the end of the list.
        """
        new_node = Node(value)
        if self.head is None:
            self.head = new_node
            self.tail = new_node
        else:
            self.tail.next = new_node
            self.tail = new_node

    def remove(self, value):
        """
        Removes the first node with the specified value from the list.
        Returns True if the node was found and removed, otherwise returns False.
        """
        current = self.head
        previous = None
        while current is not None:
            if current.value == value:
                if previous is None:
                    self.head = current.next
                else:
                    previous.next = current.next
                if current.next is None:
                    self.tail = previous
                return True
            previous = current
            current = current.next
        return False

    def display(self):
        """
        Prints all the values in the list in order, separated by ' -> '.
        """
        current = self.head
        elements = []
        while current:
            elements.append(str(current.value))
            current = current.next
        print(' -> '.join(elements))
