class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        """Initialize an empty Binary Search Tree."""
        self.root = None

    def insert(self, key):
        """Insert a new value into the BST. Duplicates are inserted into the right subtree."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        """Helper method to insert a new value into the BST."""
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert(node.left, key)
        else:  # key >= node.val, insert duplicates to the right
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert(node.right, key)

    def delete(self, key):
        """Delete a value from the BST. If the value does not exist, do nothing."""
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        """Helper method to delete a value from the BST."""
        if node is None:
            return node

        if key < node.val:
            node.left = self._delete(node.left, key)
        elif key > node.val:
            node.right = self._delete(node.right, key)
        else:
            # Node with only one child or no child
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            # Node with two children: Get the inorder successor
            node.val = self._min_value_node(node.right).val
            node.right = self._delete(node.right, node.val)

        return node

    def search(self, key):
        """Search for a value in the BST. Return True if the value is found, otherwise False."""
        return self._search(self.root, key)

    def _search(self, node, key):
        """Helper method to search for a value in the BST."""
        if node is None or node.val == key:
            return node is not None

        if key < node.val:
            return self._search(node.left, key)

        return self._search(node.right, key)

    def inorder_traversal(self):
        """Return a list of values in the BST in in-order traversal order."""
        return self._inorder_traversal(self.root)

    def _inorder_traversal(self, node):
        """Helper method to perform in-order traversal of the BST."""
        res = []
        if node:
            res = self._inorder_traversal(node.left)
            res.append(node.val)
            res = res + self._inorder_traversal(node.right)
        return res

    def _min_value_node(self, node):
        """Helper method to find the node with the minimum value in the BST."""
        current = node
        while current.left is not None:
            current = current.left
        return current
