import math

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def distance_to(self, other):
        """Calculate the Euclidean distance between two points."""
        return math.sqrt((self.x - other.x) ** 2 + (self.y - other.y) ** 2)

    def midpoint_to(self, other):
        """Calculate the midpoint between two points and return a new Point object."""
        midpoint_x = (self.x + other.x) / 2
        midpoint_y = (self.y + other.y) / 2
        return Point(midpoint_x, midpoint_y)

    def slope_to(self, other):
        """Calculate the slope between two points. Returns None if the line is vertical."""
        if self.x == other.x:
            return None
        return (other.y - self.y) / (other.x - self.x)
