def pack_and_unpack(numbers, separator=' '):
    """
    Returns a string representation of the list of integers with every third integer enclosed in parentheses.

    :param numbers: List of integers to be formatted.
    :param separator: String used to separate numbers and parentheses in the output.
    :return: Formatted string representation of the list.
    """
    result = []
    for index, number in enumerate(numbers):
        if (index + 1) % 3 == 0:
            result.append(f"({number})")
        else:
            result.append(str(number))
    return separator.join(result)
