class Matrix:
    def __init__(self, data):
        """
        Initializes a Matrix object with the given data.
        :param data: List of lists representing the matrix.
        :raises ValueError: If the input data is not a valid matrix.
        """
        if not data or not all(len(row) == len(data[0]) for row in data):
            raise ValueError("Invalid matrix data")
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0])

    def add(self, other):
        """
        Adds two matrices.
        :param other: Another Matrix object.
        :return: A new Matrix object representing the sum.
        :raises ValueError: If the matrices have different dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices dimensions must be the same for addition")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def subtract(self, other):
        """
        Subtracts the second matrix from the first.
        :param other: Another Matrix object.
        :return: A new Matrix object representing the difference.
        :raises ValueError: If the matrices have different dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices dimensions must be the same for subtraction")
        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiplies two matrices.
        :param other: Another Matrix object.
        :return: A new Matrix object representing the product.
        :raises ValueError: If the number of columns in the first matrix is not equal to the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to number of rows in the second matrix for multiplication")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __str__(self):
        """
        Returns a string representation of the matrix.
        :return: String representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])
