def remove_markdown_formatting(text: str) -> str:
    """
    Removes all Markdown formatting elements from the input string and returns the plain text.

    :param text: A string containing Markdown formatted text.
    :return: A string representing the plain text after removing all Markdown formatting elements.
    """
    stack = []
    result = []
    marker_pairs = {
        '**': '**',
        '__': '__',
        '*': '*',
        '_': '_',
        '~~': '~~'
    }

    i = 0
    while i < len(text):
        if i + 1 < len(text) and text[i:i+2] in marker_pairs:
            marker = text[i:i+2]
            if stack and stack[-1] == marker:
                stack.pop()
            else:
                stack.append(marker)
            i += 2
        elif text[i] in '*_~':
            marker = text[i]
            if stack and stack[-1] == marker:
                stack.pop()
            else:
                stack.append(marker)
            i += 1
        else:
            result.append(text[i])
            i += 1

    return ''.join(result)

# Example usage
print(remove_markdown_formatting("**Hello** *World* ~~Example~~"))  # Output: "Hello World Example"
print(remove_markdown_formatting("**_Hello_ World~~!~~**"))         # Output: "Hello World!"
```

