def generate_fallback_url(config):
    """
    Generates a fallback URL based on the provided configuration.

    Parameters:
    config (dict): A dictionary containing 'base_url', 'fallback_url', and 'fallback_endpoint'.

    Returns:
    str: The constructed fallback URL.
    """
    base_url = config.get('base_url', '')
    fallback_url = config.get('fallback_url', '')
    fallback_endpoint = config.get('fallback_endpoint', '')

    if fallback_url:
        return fallback_url

    if base_url.endswith('/'):
        if fallback_endpoint.startswith('/'):
            return base_url[:-1] + fallback_endpoint
        else:
            return base_url + fallback_endpoint
    else:
        if fallback_endpoint.startswith('/'):
            return base_url + fallback_endpoint
        else:
            return base_url + '/' + fallback_endpoint
