def convert_to_floats(numbers):
    """
    Converts a list of integers, where each integer represents a floating-point number
    multiplied by 100, back to their corresponding floating-point numbers. If an integer
    is 0, the corresponding floating-point number is None.

    :param numbers: List of integers representing floating-point numbers multiplied by 100.
    :return: List of floating-point numbers or None values.
    """
    def helper(index):
        if index == len(numbers):
            return []
        elif numbers[index] == 0:
            return [None] + helper(index + 1)
        else:
            return [numbers[index] / 100.0] + helper(index + 1)

    return helper(0)
