        return self.author

    def set_isbn(self, isbn):
        """Set the ISBN of the book."""
        self.isbn = isbn

    def get_isbn(self):
        """Get the ISBN of the book."""
        return self.isbn

    def set_publisher(self, publisher):
        """Set the publisher of the book."""
        self.publisher = publisher

    def get_publisher(self):
        """Get the publisher of the book."""
        return self.publisher

    def summary(self):
        """Return a summary of the book's details."""
        return f"Title: {self.title}, Author: {self.author}, ISBN: {self.isbn}, Publisher: {self.publisher}"

    def is_valid_isbn(self):
        """Check if the ISBN is a valid ISBN-13 number."""
        if len(self.isbn) != 13 or not self.isbn[:-1].isdigit():
            return False
        if self.isbn[-1] not in '0123456789X':
            return False

        total = 0
        for i, c in enumerate(self.isbn[:-1]):
            digit = int(c)
            if i % 2 == 0:
                total += digit
            else:
                total += digit * 3

        check_digit = (10 - (total % 10)) % 10
        expected_check_digit = self.isbn[-1]

        if expected_check_digit == 'X':
            return check_digit == 10
        else:
            return check_digit == int(expected_check_digit)
