def set_param(key: str, param: str, data: dict, args: list) -> bool:
    """
    Navigates through a nested dictionary to check for a specified key and its boolean value.
    Appends a parameter to the args list if the key exists and its value is True.

    :param key: A string representing the key to search for, with nested levels separated by dots.
    :param param: A string representing the parameter to add to the args list.
    :param data: A dictionary that may contain nested dictionaries.
    :param args: A list to which the parameter will be appended if conditions are met.
    :return: True if the key is found and its value is True, False otherwise.
    """
    def find_key_in_dict(d: dict, key_parts: list):
        if not key_parts:
            return d
        if isinstance(d, dict):
            next_part = key_parts[0]
            if next_part in d:
                return find_key_in_dict(d[next_part], key_parts[1:])
        return None

    key_parts = key.split('.')
    value = find_key_in_dict(data, key_parts)
    if value is True:
        args.append(param)
        return True
    return False

