def is_valid_product_code(product_code, used_product_codes):
    """
    Validates a given product code based on specific rules.

    Parameters:
    product_code (str): The product code to be validated.
    used_product_codes (set): A set of previously used product codes.

    Returns:
    str: A message indicating whether the product code is valid or not, and the reason for invalidity if applicable.
    """
    if len(product_code) != 10:
        return "Invalid: Product code must be exactly 10 characters long."

    if not product_code[0].isupper():
        return "Invalid: The first character must be an uppercase letter."

    if not product_code[1].isdigit():
        return "Invalid: The second character must be a digit."

    for char in product_code[2:]:
        if not (char.isupper() or char.isdigit()):
            return "Invalid: The remaining characters must be uppercase letters or digits."

    for i in range(1, len(product_code)):
        if product_code[i] == product_code[i - 1]:
            return "Invalid: No two consecutive characters can be the same."

    if product_code in used_product_codes:
        return "Invalid: Product code has been used previously."

    return "Valid: Product code is valid."
