class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def serialize(root: TreeNode) -> str:
    """Encodes a tree to a single string using preorder traversal."""
    def build_string(node):
        if not node:
            return 'None,'
        return str(node.val) + ',' + build_string(node.left) + build_string(node.right)

    return build_string(root)

def deserialize(data: str) -> TreeNode:
    """Decodes your encoded data to tree using preorder traversal."""
    def build_tree(values):
        value = next(values)
        if value == 'None':
            return None
        node = TreeNode(int(value))
        node.left = build_tree(values)
        node.right = build_tree(values)
        return node

    value_iter = iter(data.split(','))
    return build_tree(value_iter)
