def binary_search_iterative(arr, target):
    """
    Iterative approach for Binary Search Algorithm.

    :param arr: A sorted list of elements where the search is performed.
    :param target: The element to search for in the list.
    :return: Returns the index of the target if found, otherwise returns -1.
    """
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        mid_value = arr[mid]

        if mid_value == target:
            return mid
        elif mid_value < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

def binary_search_recursive(arr, target, left=0, right=None):
    """
    Recursive approach for Binary Search Algorithm.

    :param arr: A sorted list of elements where the search is performed.
    :param target: The element to search for in the list.
    :param left: The left boundary for the search, initially set to 0.
    :param right: The right boundary for the search, initially set to len(arr) - 1.
    :return: Returns the index of the target if found, otherwise returns -1.
    """
    if right is None:
        right = len(arr) - 1

    if left > right:
        return -1

    mid = (left + right) // 2
    mid_value = arr[mid]

    if mid_value == target:
        return mid
    elif mid_value < target:
        return binary_search_recursive(arr, target, mid + 1, right)
    else:
        return binary_search_recursive(arr, target, left, mid - 1)
