def flatten_dict(d, parent_key='', sep='.'):
    """
    Flattens a nested dictionary that may contain lists as values.

    Parameters:
    d (dict or list): The dictionary or list to flatten.
    parent_key (str): The base key string for recursion.
    sep (str): The separator to use between keys.

    Returns:
    dict: A flat dictionary with path keys as keys and original values as values.
    """
    items = []
    if isinstance(d, dict):
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            items.extend(flatten_dict(v, new_key, sep=sep).items())
    elif isinstance(d, list):
        for i, item in enumerate(d):
            new_key = f"{parent_key}{sep}{i}" if parent_key else str(i)
            items.extend(flatten_dict(item, new_key, sep=sep).items())
    else:
        items.append((parent_key, d))
    return dict(items)

