def find_largest_prime(n):
    """
    Returns the largest prime number less than or equal to n.
    If no such prime exists, returns None.

    :param n: Integer, the upper limit to search for the largest prime.
    :return: Integer, the largest prime number less than or equal to n, or None if no prime exists.
    """
    if n < 2:
        return None

    def is_prime(num):
        """
        Checks if a number is prime.

        :param num: Integer, the number to check for primality.
        :return: Boolean, True if num is prime, False otherwise.
        """
        if num < 2:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    for number in range(n, 1, -1):
        if is_prime(number):
            return number

    return None
