def first_non_repeating_character(s):
    """
    Finds the first non-repeating character in the given string.

    Parameters:
    s (str): The input string.

    Returns:
    char or None: The first non-repeating character, or None if no such character exists.
    """
    char_count = {}

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in s:
        if char_count[char] == 1:
            return char

    return None

