def check_types(elements, types):
    """
    Checks if the types of elements in the list match the specified types in order.
    Handles nested lists and tuples by recursively checking their internal types.

    :param elements: List of elements with various types, may include nested lists and tuples.
    :param types: List specifying the expected types of the elements, may include nested lists and tuples.
    :return: True if types match in order, False otherwise.
    """
    def matches(element, type_):
        if isinstance(element, list) and isinstance(type_, list):
            return len(element) == len(type_) and all(matches(e, t) for e, t in zip(element, type_))
        elif isinstance(element, tuple) and isinstance(type_, tuple):
            return len(element) == len(type_) and all(matches(e, t) for e, t in zip(element, type_))
        else:
            return isinstance(element, type_)

    if len(elements) != len(types):
        return False
    return all(matches(e, t) for e, t in zip(elements, types))
