class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Insert a new node with the given key into the binary search tree."""
        if not self.root:
            self.root = TreeNode(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert(node.right, key)

    def delete(self, key):
        """Delete the node with the given key from the binary search tree."""
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        if not node:
            return node

        if key < node.val:
            node.left = self._delete(node.left, key)
        elif key > node.val:
            node.right = self._delete(node.right, key)
        else:
            if not node.left:
                return node.right
            elif not node.right:
                return node.left

            temp = self.find_min(node.right)
            node.val = temp.val
            node.right = self._delete(node.right, temp.val)

        return node

    def find_min(self, node):
        """Find and return the node with the minimum key in the subtree rooted at node."""
        current = node
        while current.left is not None:
            current = current.left
        return current

    def inorder_traversal(self):
        """Return a list of keys in the binary search tree in in-order traversal order."""
        return self._inorder_traversal(self.root)

    def _inorder_traversal(self, node):
        res = []
        if node:
            res = self._inorder_traversal(node.left)
            res.append(node.val)
            res = res + self._inorder_traversal(node.right)
        return res

    def is_balanced(self):
        """Check if the binary search tree is balanced."""
        return self._is_balanced(self.root) != -1

    def _is_balanced(self, node):
        if not node:
            return 0

        left_height = self._is_balanced(node.left)
        if left_height == -1:
            return -1

        right_height = self._is_balanced(node.right)
        if right_height == -1 or abs(left_height - right_height) > 1:
            return -1

        return max(left_height, right_height) + 1
