def is_union_equal_to_universe(univ, conjs, limits):
    """
    Determines if the union of selected subsets from conjs can match the universal set univ.

    :param univ: set, the universal set
    :param conjs: list of sets, the subsets of the universal set
    :param limits: list of int, the maximum number of times each subset in conjs can be used
    :return: bool, True if the union of selected subsets equals the universal set, False otherwise
    """
    from itertools import combinations

    def explore(used_sets):
        if set().union(*used_sets) == univ:
            return True
        for i, subset in enumerate(conjs):
            if limits[i] > 0:
                limits[i] -= 1
                if explore(used_sets + [subset]):
                    return True
                limits[i] += 1
        return False

    return explore([])
