    Calculate the average time taken to solve each problem from a list of submissions.

    :param submissions: List of dictionaries, each containing 'user_id', 'problem_id', and 'time_taken'.
    :return: Dictionary with problem IDs as keys and average time taken as values.
    """
    problem_data = {}

    for submission in submissions:
        problem_id = submission['problem_id']
        time_taken = submission['time_taken']

        if problem_id not in problem_data:
            problem_data[problem_id] = {'total_time': 0, 'attempts': 0}

        problem_data[problem_id]['total_time'] += time_taken
        problem_data[problem_id]['attempts'] += 1

    average_times = {}

    for problem_id, data in problem_data.items():
        average_times[problem_id] = data['total_time'] / data['attempts']

    return average_times

