class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Inserts a new key into the BST."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert_rec(self.root, key)

    def _insert_rec(self, node, key):
        """Helper method to insert a new key into the BST recursively."""
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert_rec(node.left, key)
        elif key > node.val:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert_rec(node.right, key)

    def delete(self, key):
        """Deletes a key from the BST."""
        self.root = self._delete_rec(self.root, key)

    def _delete_rec(self, node, key):
        """Helper method to delete a key from the BST recursively."""
        if node is None:
            return node

        if key < node.val:
            node.left = self._delete_rec(node.left, key)
        elif key > node.val:
            node.right = self._delete_rec(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            node.val = self._min_value_node(node.right).val
            node.right = self._delete_rec(node.right, node.val)

        return node

    def _min_value_node(self, node):
        """Helper method to find the node with the minimum value in the BST."""
        current = node
        while current.left is not None:
            current = current.left
        return current

    def search(self, key):
        """Searches for a key in the BST and returns the node if found, otherwise returns None."""
        return self._search_rec(self.root, key)

    def _search_rec(self, node, key):
        """Helper method to search for a key in the BST recursively."""
        if node is None or node.val == key:
            return node

        if key > node.val:
            return self._search_rec(node.right, key)
        return self._search_rec(node.left, key)
