def count_substrings(s1, s2):
    """
    Counts the number of times s1 appears as a substring in s2 using the Rabin-Karp algorithm.

    :param s1: The substring to search for.
    :param s2: The string to search in.
    :return: The number of times s1 appears as a substring in s2.
    """
    if not s1:
        return len(s2) + 1  # An empty string s1 is a substring between every character in s2, plus at the start and end.

    if not s2 or len(s1) > len(s2):
        return 0

    q = 101  # A small prime number, can be adjusted for larger strings
    d = 256  # Number of characters in the input alphabet

    hash_s1 = 0
    hash_s2 = 0
    h = 1

    for i in range(len(s1)):
        hash_s1 = (d * hash_s1 + ord(s1[i])) % q
        hash_s2 = (d * hash_s2 + ord(s2[i])) % q
        if i < len(s1) - 1:
            h = (h * d) % q

    count = 0

    for i in range(len(s2) - len(s1) + 1):
        if hash_s1 == hash_s2:
            if s2[i:i + len(s1)] == s1:
                count += 1

        if i < len(s2) - len(s1):
            hash_s2 = (d * (hash_s2 - ord(s2[i]) * h) + ord(s2[i + len(s1)])) % q

            if hash_s2 < 0:
                hash_s2 += q

    return count
```

