def load_cargo(*items):
    """
    Distributes cargo items into wagons according to specified rules.

    Parameters:
    *items (dict): Variable number of cargo items, each represented as a dictionary
                   with keys 'weight', 'type', and 'destination'.

    Returns:
    list of list of dict: A list of wagons, each containing a list of cargo items.
    """
    def find_wagon(wagons, cargo):
        for i, wagon in enumerate(wagons):
            if (
                sum(item['weight'] for item in wagon) + cargo['weight'] <= 1000 and 
                sum(1 for item in wagon if item['type'] == cargo['type']) < 3
            ):
                return i
        return None

    def prioritize_items_by_destination(items):
        return sorted(items, key=lambda item: item['destination'])

    items = prioritize_items_by_destination(items)
    wagons = []

    for cargo in items:
        wagon_index = find_wagon(wagons, cargo)
        if wagon_index is not None:
            wagons[wagon_index].append(cargo)
        else:
            wagons.append([cargo])

    return wagons
