def convert_hashtags_to_links(s):
    """
    Converts unique hashtags in the input string to HTML anchor tags.

    :param s: A string containing words and hashtags.
    :return: A string with unique hashtags converted to HTML links.
    """
    words = s.split()
    seen_hashtags = set()
    result = []

    for word in words:
        if word.startswith('#'):
            if word not in seen_hashtags:
                seen_hashtags.add(word)
                result.append(f"<a href='{word}'>{word}</a>")
            else:
                result.append(word)
        else:
            result.append(word)

    return ' '.join(result)
