def find_new_parents(repo, revmap):
    """
    Updates the parent relationships in the commit graph according to the revision map.

    :param repo: A dictionary representing the commit graph where keys are revision numbers
                 and values are commit nodes with a 'parents' key.
    :param revmap: A dictionary mapping old revision numbers to new revision numbers.
    :return: A dictionary where each key is a new revision number and each value is a list
             of new parent revision numbers for that commit.
    """
    new_parents = {}
    visited = set()

    def dfs(commit_id):
        if commit_id in visited:
            return
        visited.add(commit_id)

        commit = repo.get(commit_id)
        if not commit:
            return

        new_commit_id = revmap.get(commit_id, commit_id)
        new_parents[new_commit_id] = set()

        for parent_id in commit['parents']:
            new_parent_id = revmap.get(parent_id, parent_id)
            new_parents[new_commit_id].add(new_parent_id)
            dfs(parent_id)

        for parent_id in commit['parents']:
            new_parent_id = revmap.get(parent_id, parent_id)
            if new_parent_id not in repo:
                new_parents[new_commit_id].add(new_parent_id)

    for commit_id in repo.keys():
        if commit_id not in visited:
            dfs(commit_id)

    result = {commit_id: list(parents) for commit_id, parents in new_parents.items()}
    return result
