def flip_array(arr, axes):
    """
    Flips a 3D array along the specified axes.

    Parameters:
    arr (list of list of list of int): The 3D array to be flipped.
    axes (list of int): The axes along which to flip the array.

    Returns:
    list of list of list of int: The flipped 3D array.
    """
    # Get dimensions of the 3D array
    d1 = len(arr)
    d2 = len(arr[0])
    d3 = len(arr[0][0])

    # Create a copy of the array to store the result
    result = [[[0 for _ in range(d3)] for _ in range(d2)] for _ in range(d1)]

    # Process each axis specified in the axes list
    for axis in axes:
        if axis == 0:
            for i in range(d1):
                for j in range(d2):
                    for k in range(d3):
                        result[d1-1-i][j][k] = arr[i][j][k]
            arr, result = result, arr
        elif axis == 1:
            for i in range(d1):
                for j in range(d2):
                    for k in range(d3):
                        result[i][d2-1-j][k] = arr[i][j][k]
            arr, result = result, arr
        elif axis == 2:
            for i in range(d1):
                for j in range(d2):
                    for k in range(d3):
                        result[i][j][d3-1-k] = arr[i][j][k]
            arr, result = result, arr

    return arr
