import argparse
import sys

def is_prime(num):
    """Check if a number is prime."""
    if num <= 1:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def prime_factors_sum(num):
    """Calculate the sum of prime factors of a number."""
    factors_sum = 0
    while num % 2 == 0:
        factors_sum += 2
        num //= 2
    for i in range(3, int(num ** 0.5) + 1, 2):
        while num % i == 0:
            factors_sum += i
            num //= i
    if num > 2:
        factors_sum += num
    return factors_sum

def addParserOptions(parser):
    """Add command-line options to the parser."""
    parser.add_argument('operation', choices=['add', 'remove', 'display', 'sort', 'reverse'], help='Operation to perform on the list')
    parser.add_argument('--value', '-v', type=int, help='Integer value to add or remove (required for add or remove)')
    parser.add_argument('--file', '-f', type=str, default='numbers.txt', help='File to store the list of numbers (default: numbers.txt)')

def main():
    """Main function to handle command-line arguments and perform operations."""
    parser = argparse.ArgumentParser(description='List of integers CLI application')
    addParserOptions(parser)
    args = parser.parse_args()

    try:
        with open(args.file, 'r') as f:
            numbers = [int(num.strip()) for num in f.readlines()]
    except FileNotFoundError:
        numbers = []

    if args.operation == 'add' and args.value is not None:
        if args.value not in numbers:
            numbers.append(args.value)
    elif args.operation == 'remove' and args.value is not None:
        if args.value in numbers:
            numbers.remove(args.value)
    elif args.operation == 'display':
        print(numbers)
    elif args.operation == 'sort':
        numbers.sort(key=prime_factors_sum)
    elif args.operation == 'reverse':
