def number_to_words(n):
    """
    Convert an integer to its English word representation.

    Args:
    n (int): An integer between 0 and 999 inclusive.

    Returns:
    str: The English word representation of the integer.
    """
    def one(n):
        switcher = {
            1: "one", 2: "two", 3: "three", 4: "four", 5: "five",
            6: "six", 7: "seven", 8: "eight", 9: "nine"
        }
        return switcher.get(n, "")

    def two_less_20(n):
        switcher = {
            10: "ten", 11: "eleven", 12: "twelve", 13: "thirteen", 14: "fourteen",
            15: "fifteen", 16: "sixteen", 17: "seventeen", 18: "eighteen", 19: "nineteen"
        }
        return switcher.get(n, "")

    def ten(n):
        switcher = {
            2: "twenty", 3: "thirty", 4: "forty", 5: "fifty",
            6: "sixty", 7: "seventy", 8: "eighty", 9: "ninety"
        }
        return switcher.get(n, "")

    def two(n):
        if not n:
            return ""
        elif n < 10:
            return one(n)
        elif n < 20:
            return two_less_20(n)
        else:
            tenner = n // 10
            rest = n - tenner * 10
            return ten(tenner) + (" " + one(rest) if rest else "")

    def three(n):
        hundred = n // 100
        rest = n - hundred * 100
        if hundred and rest:
            return one(hundred) + " hundred " + two(rest)
        elif not hundred and rest:
            return two(rest)
        elif hundred and not rest:
            return one(hundred) + " hundred"

    if not n:
        return "zero"

    words = ""
    if n < 0:
        words += "negative "
        n = -n

    if n < 1000:
        words += three(n)
    return words.strip()

def numbers_to_words_list(lst):
    """
    Convert a list of integers to their English word representations.

    Args:
    lst (list of int): A list of integers between 0 and 999 inclusive.

    Returns:
    list of str: A list of the English word representations of the integers.
    """
    return [number_to_words(i) for i in lst]
