def natural_sort(strings):
    """
    Sorts a list of strings in natural order.

    :param strings: List of strings to be sorted.
    :return: List of strings sorted in natural order.
    """
    def compare(s1, s2):
        chunks1 = split_chunks(s1)
        chunks2 = split_chunks(s2)

        for c1, c2 in zip(chunks1, chunks2):
            if c1.isdigit() and c2.isdigit():
                n1, n2 = int(c1), int(c2)
                if n1 != n2:
                    return n1 - n2
            else:
                if c1 != c2:
                    return (c1 > c2) - (c1 < c2)

        return len(chunks1) - len(chunks2)

    def split_chunks(s):
        chunks = []
        current_chunk = []

        for char in s:
            if char.isdigit() == (current_chunk and current_chunk[-1].isdigit()):
                current_chunk.append(char)
            else:
                chunks.append(''.join(current_chunk))
                current_chunk = [char]

        if current_chunk:
            chunks.append(''.join(current_chunk))

        return chunks

    def bubble_sort(arr):
        n = len(arr)
        for i in range(n):
            for j in range(0, n-i-1):
                if compare(arr[j], arr[j+1]) > 0:
                    arr[j], arr[j+1] = arr[j+1], arr[j]

    bubble_sort(strings)
    return strings

