def merge_settings(user_settings: dict, default_settings: dict) -> dict:
    """
    Merges two dictionaries, prioritizing values from user_settings in case of key collisions.
    The resulting dictionary has keys sorted alphabetically.

    :param user_settings: A dictionary representing user-specific settings.
    :param default_settings: A dictionary representing default settings.
    :return: A new dictionary with merged settings and keys sorted alphabetically.
    """
    if user_settings is None:
        user_settings = {}

    if default_settings is None:
        default_settings = {}

    merged_settings = default_settings.copy()
    merged_settings.update(user_settings)

    return dict(sorted(merged_settings.items()))
