def check_shape_compatibility(actual_shape, desired_shape):
    """
    Determines if the actual_shape is compatible with the desired_shape.

    Parameters:
    - actual_shape: A tuple of integers representing the dimensions of a multi-dimensional array.
    - desired_shape: A tuple of integers, None values, and negative integers representing the desired dimensions.

    Returns:
    - A boolean value indicating whether the actual_shape is compatible with the desired_shape.
    """
    if len(actual_shape) != len(desired_shape):
        return False

    for actual_dim, desired_dim in zip(actual_shape, desired_shape):
        if desired_dim is None:
            continue
        elif desired_dim < 0:
            if actual_dim % abs(desired_dim) != 0:
                return False
        elif actual_dim != desired_dim:
            return False

    return True
