def tuples_to_dict(tuples_list):
    """
    Convert a list of tuples to a dictionary. Each key is the first item of the tuple,
    and each value is the second item of the tuple. If multiple tuples have the same
    first item, concatenate the values associated with that key into a list.

    :param tuples_list: List of tuples, where each tuple contains two elements.
    :return: Dictionary with keys from the tuples and values as integers or lists of integers.
    """
    result_dict = {}
    for key, value in tuples_list:
        if key in result_dict:
            if isinstance(result_dict[key], list):
                result_dict[key].append(value)
            else:
                result_dict[key] = [result_dict[key], value]
        else:
            result_dict[key] = value
    return result_dict

