def is_palindrome(s: str) -> bool:
    """
    Recursively checks if the given string is a palindrome, ignoring non-alphanumeric characters and case.

    :param s: The input string to check.
    :return: True if the string is a palindrome, False otherwise.
    """
    def is_alnum(c):
        """Check if a character is alphanumeric."""
        return c.isalnum()

    def to_lower(c):
        """Convert a character to lowercase."""
        return c.lower()

    if len(s) <= 1:
        return True

    filtered_chars = [to_lower(c) for c in s if is_alnum(c)]

    if filtered_chars[0] == filtered_chars[-1]:
        return is_palindrome(filtered_chars[1:-1])
    else:
        return False

