def find_prime_factors(n):
    """
    Returns a list of unique prime factors of the given integer n in ascending order.

    :param n: Integer, the number to find prime factors for.
    :return: List of unique prime factors in ascending order.
    """
    if n == 0:
        return []

    def prime_factors(num):
        i = 2
        factors = set()
        while i * i <= num:
            if num % i:
                i += 1
            else:
                num //= i
                factors.add(i)
        if num > 1:
            factors.add(num)
        return factors

    n = abs(n)  # Handle negative numbers
    return sorted(prime_factors(n))
