class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self):
        """Initializes an empty binary search tree."""
        self.root = None

    def insert(self, value):
        """Inserts a new value into the tree."""
        new_node = TreeNode(value)
        if self.root is None:
            self.root = new_node
        else:
            self._insert_recursively(self.root, new_node)

    def _insert_recursively(self, current_node, new_node):
        """Helper method to insert a new node recursively."""
        if new_node.value < current_node.value:
            if current_node.left is None:
                current_node.left = new_node
            else:
                self._insert_recursively(current_node.left, new_node)
        else:
            if current_node.right is None:
                current_node.right = new_node
            else:
                self._insert_recursively(current_node.right, new_node)

    def search(self, value):
        """Returns True if the value exists in the tree, and False otherwise."""
        return self._search_recursively(self.root, value)

    def _search_recursively(self, current_node, value):
        """Helper method to search for a value recursively."""
        if current_node is None:
            return False
        if current_node.value == value:
            return True
        elif value < current_node.value:
            return self._search_recursively(current_node.left, value)
        else:
            return self._search_recursively(current_node.right, value)

    def inorder_traversal(self):
        """Returns a list of values in the tree in sorted order using an in-order traversal."""
        result = []
        self._inorder_traversal_recursively(self.root, result)
        return result

    def _inorder_traversal_recursively(self, current_node, result):
        """Helper method to perform in-order traversal recursively."""
        if current_node is not None:
            self._inorder_traversal_recursively(current_node.left, result)
            result.append(current_node.value)
            self._inorder_traversal_recursively(current_node.right, result)
