import math

def factorial(n):
    """
    Computes the factorial of a given number n.

    Parameters:
    n (int or float): The number to compute the factorial of.

    Returns:
    int or float: The factorial of n if n is an integer, or the gamma function result for n+1 if n is a float.

    Raises:
    ValueError: If n is neither an integer nor a float.
    """
    if isinstance(n, int):
        if n == 0:
            return 1
        else:
            return n * factorial(n-1)
    elif isinstance(n, float):
        return math.gamma(n + 1)
    else:
        raise ValueError("Input must be an integer or a float")

