def compare_lists_by_elements(list1, list2):
    """
    Compares two lists to determine if they contain the same elements with the same frequency.

    Parameters:
    list1 (list): The first list of integers.
    list2 (list): The second list of integers.

    Returns:
    bool: True if both lists contain the same elements with the same frequency, False otherwise.
    """
    # If lengths are different, the lists do not contain the same elements with the same frequency
    if len(list1) != len(list2):
        return False

    # Create a dictionary to count the frequency of each element in list1
    element_count = {}
    for element in list1:
        if element in element_count:
            element_count[element] += 1
        else:
            element_count[element] = 1

    # Decrease the count for each element found in list2
    for element in list2:
        if element in element_count:
            element_count[element] -= 1
            if element_count[element] < 0:
                return False
        else:
            # If an element in list2 is not found in list1, they are not the same
            return False

    # If all counts are zero, the lists contain the same elements with the same frequency
    return True
