def ip_to_binary(ip):
    """
    Convert an IPv4 address to a 32-character binary string.

    Parameters:
    ip (str or int): The IPv4 address in dot-separated string format or as a decimal integer.

    Returns:
    str: A 32-character binary string representation of the IPv4 address.

    Raises:
    ValueError: If the input is a string not in the correct format or an integer out of range.
    TypeError: If the input is neither a string nor an integer.
    """
    if isinstance(ip, int):
        if not (0 <= ip <= 2**32 - 1):
            raise ValueError("Decimal IP address must be in the range 0 to 2^32 - 1")
        return f'{ip:032b}'
    elif isinstance(ip, str):
        if not ip.count('.') == 3:
            raise ValueError("IPv4 address must be in the dot-separated format with exactly 4 octets")
        try:
            octets = ip.split('.')
            binary_parts = [f'{int(octet):08b}' for octet in octets]
            return ''.join(binary_parts)
        except ValueError:
            raise ValueError("Each octet must be a number between 0 and 255")
    else:
        raise TypeError("IP address must be either a string in dot-separated format or an integer")
