        elif idx == notes_count:
            return chord_str.strip() if idx == 3 else "Error: Less than three notes"
        else:
            if chord_str == '':
                return build_chord(lst, idx + 1, lst[idx])
            else:
                return build_chord(lst, idx + 1, chord_str + ' ' + lst[idx])

