def echo_args(*args):
    """
    Flattens a variable number of arguments, which may include nested lists and dictionaries,
    into a dictionary with keys representing the full path to each value and values as the
    respective values from the input, excluding any None values.

    :param args: Variable number of arguments (integers, lists, or dictionaries)
    :return: Flattened dictionary with paths as keys and values as values
    """
    def flatten(current_path, value, result):
        if isinstance(value, dict):
            for key, val in value.items():
                if val is not None:
                    flatten(f"{current_path}.{key}" if current_path else key, val, result)
        elif isinstance(value, list):
            for index, val in enumerate(value):
                if val is not None:
                    flatten(f"{current_path}[{index}]" if current_path else f"[{index}]", val, result)
        else:
            if value is not None:
                result[current_path] = value

    result = {}
    for index, arg in enumerate(args):
        flatten(f"arg{index}", arg, result)

    return result
