class Graph:
    def __init__(self):
        """Initialize an empty graph represented as an adjacency list."""
        self.graph = {}

    def add_edge(self, u, v):
        """Add an undirected edge between vertices u and v."""
        if u in self.graph:
            self.graph[u].add(v)
        else:
            self.graph[u] = {v}

        if v in self.graph:
            self.graph[v].add(u)
        else:
            self.graph[v] = {u}

    def remove_edge(self, u, v):
        """Remove the undirected edge between vertices u and v if it exists."""
        if u in self.graph and v in self.graph[u]:
            self.graph[u].remove(v)
            if not self.graph[u]:
                del self.graph[u]

        if v in self.graph and u in self.graph[v]:
            self.graph[v].remove(u)
            if not self.graph[v]:
                del self.graph[v]

    def is_connected(self, u, v):
        """Return True if there is a path between vertices u and v, otherwise False."""
        if u not in self.graph or v not in self.graph:
            return False

        visited = set()
        queue = [u]

        while queue:
            node = queue.pop(0)
            visited.add(node)

            if node == v:
                return True

            for neighbor in self.graph[node] - visited:
                queue.append(neighbor)

        return False
