def calculate_fibonacci(n, memo=None):
    """
    Computes the nth Fibonacci number using memoization.

    Parameters:
    n (int): The index of the Fibonacci number to compute.

    Returns:
    int: The nth Fibonacci number.
    """
    if memo is None:
        memo = {}

    if n in memo:
        return memo[n]

    if n == 0:
        return 0
    elif n == 1 or n == -1:
        return 1
    else:
        if n > 0:
            memo[n] = calculate_fibonacci(n - 1, memo) + calculate_fibonacci(n - 2, memo)
        else:
            memo[n] = ((-1) ** (n + 1)) * calculate_fibonacci(-n, memo)
        return memo[n]

