def check_brackets_balance(s: str) -> bool:
    """
    Determines if the brackets in the string are balanced.

    :param s: A string consisting of opening and closing brackets.
    :return: True if the brackets are balanced, False otherwise.
    """
    def helper(s: str, index: int, balance: int) -> bool:
        if balance < 0:
            return False

        if index == len(s):
            return balance == 0

        current_char = s[index]
        if current_char == '(':
            return helper(s, index + 1, balance + 1)
        elif current_char == ')':
            return helper(s, index + 1, balance - 1)
        elif current_char == '[':
            return helper(s, index + 1, (balance << 2) + 1)
        elif current_char == ']':
            if balance & 3 != 1:
                return False
            return helper(s, index + 1, balance >> 2)
        elif current_char == '{':
            return helper(s, index + 1, (balance << 4) + 2)
        elif current_char == '}':
            if (balance & 15) != 2:
                return False
            return helper(s, index + 1, balance >> 4)

    return helper(s, 0, 0)
