def evaluate_postfix(expression):
    """
    Evaluates a mathematical expression given in postfix notation.

    Args:
    expression (str): A string representing the postfix expression.

    Returns:
    float or str: The result of the expression as a float, or an error message as a string.
    """
    stack = []
    operators = {'+', '-', '*', '/'}

    tokens = expression.split()

    for token in tokens:
        if token not in operators:
            stack.append(int(token))
        else:
            if len(stack) < 2:
                return "Invalid Expression"
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                if b == 0:
                    return "Division by zero error"
                stack.append(a / b)

    if len(stack) != 1:
        return "Invalid Expression"
    return stack.pop()

