def min_parentheses_to_balance(expression: str) -> int:
    """
    Determines the minimum number of parentheses needed to balance the given expression.

    :param expression: A string consisting of '(' and ')' characters.
    :return: An integer representing the minimum number of parentheses to add for balance.
    """
    open_count = 0
    close_count = 0

    for char in expression:
        if char == '(':
            open_count += 1
        elif char == ')':
            if open_count > 0:
                open_count -= 1
            else:
                close_count += 1

    return open_count + close_count
