import json

def convert_to_boolean(input_string):
    """
    Evaluates a boolean expression given as a JSON string and returns the result as a boolean value.

    :param input_string: A string representing a boolean expression in JSON format.
    :return: The result of the boolean expression as a boolean value.
    :raises ValueError: If the input string is not a valid JSON or contains invalid expression format.
    """
    def evaluate_expression(expr):
        if isinstance(expr, bool):
            return expr
        elif isinstance(expr, dict):
            if 'not' in expr and len(expr) == 1:
                return not evaluate_expression(expr['not'])
            elif 'and' in expr and len(expr) == 1:
                return all(evaluate_expression(sub_expr) for sub_expr in expr['and'])
            elif 'or' in expr and len(expr) == 1:
                return any(evaluate_expression(sub_expr) for sub_expr in expr['or'])
        elif isinstance(expr, list):
            return all(evaluate_expression(sub_expr) for sub_expr in expr)  # Assuming list means an 'and' of all elements
        elif isinstance(expr, str):
            if expr.lower() == 'true':
                return True
            elif expr.lower() == 'false':
                return False
        raise ValueError("Invalid expression format")

    try:
        parsed_expr = json.loads(input_string)
        return evaluate_expression(parsed_expr)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON string")
