def normalize_text(text):
    """
    Normalizes the input text based on the Python version.

    Args:
        text: The input text to be normalized.

    Returns:
        The normalized text as a string (str in Python 3, unicode in Python 2).

    Raises:
        ValueError: If the input is not a valid string type for the Python version.
        ValueError: If the Python version is not supported.
    """
    try:
        python_version = __import__('sys').version_info[0]
    except:
        raise ValueError("Unable to determine Python version")

    if python_version == 2:
        if hasattr(text, 'encode'):
            return text
        elif isinstance(text, type(''.join([]))):
            return text.decode('utf-8', 'ignore')
        else:
            raise ValueError("Input is neither unicode nor str in Python 2")
    elif python_version == 3:
        if isinstance(text, type(''.join([]))):
            return text
        elif hasattr(text, 'decode'):
            return text.decode('utf-8', 'ignore')
        else:
            raise ValueError("Input is neither str nor bytes in Python 3")
    else:
        raise ValueError("Unsupported Python version: {}".format(python_version))
