class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        """Insert a new value into the binary search tree."""
        if not self.root:
            self.root = TreeNode(value)
        else:
            self._insert_recursively(self.root, value)

    def _insert_recursively(self, node, value):
        """Helper method to insert a value recursively."""
        if value < node.value:
            if node.left is None:
                node.left = TreeNode(value)
            else:
                self._insert_recursively(node.left, value)
        else:
            if node.right is None:
                node.right = TreeNode(value)
            else:
                self._insert_recursively(node.right, value)

    def in_order_traversal(self):
        """Return a list of values from an in-order traversal of the tree."""
        return self._in_order_traversal_recursively(self.root)

    def _in_order_traversal_recursively(self, node):
        """Helper method to perform in-order traversal recursively."""
        traversal = []
        if node is not None:
            traversal = self._in_order_traversal_recursively(node.left)
            traversal.append(node.value)
            traversal = traversal + self._in_order_traversal_recursively(node.right)
        return traversal

    def max_depth(self):
        """Return the maximum depth of the tree."""
        return self._max_depth_recursively(self.root)

    def _max_depth_recursively(self, node):
        """Helper method to determine the maximum depth recursively."""
        if node is None:
            return 0
        else:
            left_depth = self._max_depth_recursively(node.left)
            right_depth = self._max_depth_recursively(node.right)
            return max(left_depth, right_depth) + 1
