class MessageEncoder:
    def __init__(self, shift: int):
        """
        Initializes the MessageEncoder with a given shift value.
        The shift value is adjusted to be within the range of 0 to 25.
        """
        self.shift = shift % 26

    def encode(self, message: str) -> str:
        """
        Encodes the input message using the Caesar cipher.
        Non-alphabetic characters remain unchanged.
        """
        encoded_message = []
        for char in message:
            if char.isalpha():
                shift_base = ord('A') if char.isupper() else ord('a')
                encoded_char = chr((ord(char) - shift_base + self.shift) % 26 + shift_base)
                encoded_message.append(encoded_char)
            else:
                encoded_message.append(char)
        return ''.join(encoded_message)

    def decode(self, message: str) -> str:
        """
        Decodes the input message using the Caesar cipher.
        Non-alphabetic characters remain unchanged.
        """
        decoded_message = []
        for char in message:
            if char.isalpha():
                shift_base = ord('A') if char.isupper() else ord('a')
                decoded_char = chr((ord(char) - shift_base - self.shift) % 26 + shift_base)
                decoded_message.append(decoded_char)
            else:
                decoded_message.append(char)
        return ''.join(decoded_message)
