def tag_words(words, level=0):
    """
    Processes a nested list of words and encloses each word in HTML tags based on its position.

    Args:
    words (list): A nested list of words to be tagged.
    level (int): The current level of nesting (default is 0 for the top-level list).

    Returns:
    list: A new list with words enclosed in the appropriate HTML tags.
    """
    if not isinstance(words, list):
        return words  # If it's not a list, return the element itself

    tagged_words = []
    for i, word in enumerate(words):
        if isinstance(word, list):
            # Recursively process nested lists
            tagged_words.append(tag_words(word, level + 1))
        else:
            # Enclose each word in tags based on its position
            if level == 0:
                if i == 0:
                    tagged_words.append(f"<strong>{word}</strong>")
                elif i == len(words) - 1:
                    tagged_words.append(f"<em>{word}</em>")
                else:
                    tagged_words.append(f"<p>{word}</p>")
            else:
                # For nested lists, just use <span> tags for simplicity
                tagged_words.append(f"<span>{word}</span>")

    return tagged_words
