def can_form_sentence(word_list, sentence):
    """
    Determines if the given sentence can be constructed by concatenating words from the word_list.

    :param word_list: List of words that can be used to form the sentence.
    :param sentence: The sentence to be formed.
    :return: True if the sentence can be formed, False otherwise.
    """
    def can_form(s, word_set, memo):
        if s in memo:
            return memo[s]
        if not s:
            return True
        for word in word_set:
            if s.startswith(word):
                if can_form(s[len(word):], word_set, memo):
                    memo[s] = True
                    return True
        memo[s] = False
        return False

    word_set = set(word_list)
    memo = {}
    return can_form(sentence, word_set, memo)
