def apply_mutator(s: str, mutator: callable = None, conditions: list = None) -> str:
    """
    Applies a mutator function to a string s if all conditions are met.

    :param s: The input string to be processed.
    :param mutator: A function that takes a string and returns a modified string.
    :param conditions: A list of functions that take a string and return a boolean.
    :return: The modified string if conditions are met, otherwise the original string.
    """
    if conditions is not None:
        for condition in conditions:
            if not condition(s):
                return s
    if mutator is None:
        return s
    return mutator(s)
