def merge_dictionaries(*dicts):
    """
    Merges multiple dictionaries into a single dictionary with the following rules:
    - If a key appears in more than one dictionary, the value from the dictionary that appears later in the argument list is used.
    - Empty dictionaries are ignored.
    - Nested dictionaries are merged recursively.
    - If no dictionaries are provided, returns an empty dictionary.

    :param dicts: Variable number of dictionary arguments.
    :return: A single merged dictionary.
    """
    def merge_two_dicts(d1, d2):
        for key, value in d2.items():
            if key in d1 and isinstance(d1[key], dict) and isinstance(value, dict):
                merge_two_dicts(d1[key], value)
            else:
                d1[key] = value
        return d1

    result = {}
    for dictionary in dicts:
        if dictionary:
            merge_two_dicts(result, dictionary)
    return result
