        """Returns the sum of a and b."""
        return a + b

    def subtract(self, a, b):
        """Returns the difference between a and b."""
        return a - b

    def multiply(self, a, b):
        """Returns the product of a and b."""
        return a * b

    def divide(self, a, b):
        """Returns the quotient of a divided by b. Raises ValueError if b is zero."""
        if b == 0:
            raise ValueError("Cannot divide by zero.")
        return a / b

    def calculate(self, expression):
        """Evaluates the arithmetic expression provided as a string. Raises ValueError for invalid input."""
        parts = expression.split()
        if len(parts) != 3:
            raise ValueError("Expression must be in the form 'a operator b'.")

        a, operator, b = parts
        a, b = float(a), float(b)

        if operator == '+':
            return self.add(a, b)
        elif operator == '-':
            return self.subtract(a, b)
        elif operator == '*':
            return self.multiply(a, b)
        elif operator == '/':
            return self.divide(a, b)
        else:
            raise ValueError(f"Unknown operator: {operator}")
