class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, value):
        """Adds a new node with the specified value to the end of the list."""
        new_node = Node(value)
        if not self.head:
            self.head = new_node
            return
        last_node = self.head
        while last_node.next:
            last_node = last_node.next
        last_node.next = new_node

    def prepend(self, value):
        """Adds a new node with the specified value to the beginning of the list."""
        new_node = Node(value)
        new_node.next = self.head
        self.head = new_node

    def remove(self, value):
        """Removes the first node with the specified value from the list."""
        current_node = self.head
        prev_node = None
        while current_node and current_node.value != value:
            prev_node = current_node
            current_node = current_node.next
        if current_node is None:
            return  # Value not found
        if prev_node is None:
            self.head = current_node.next
        else:
            prev_node.next = current_node.next

    def find(self, value):
        """Returns the index of the first node with the specified value, or -1 if the value is not found."""
        current_node = self.head
        index = 0
        while current_node:
            if current_node.value == value:
                return index
            current_node = current_node.next
            index += 1
        return -1  # Value not found

    def print_list(self):
        """Prints the values of the nodes in the list in order, separated by spaces."""
        current_node = self.head
        values = []
        while current_node:
            values.append(str(current_node.value))
            current_node = current_node.next
        print(" ".join(values))
