def generate_query_parameters(name, param_type, param_value):
    """
    Constructs a dictionary representing a named parameter for a query.

    Parameters:
    name (str): The name of the parameter.
    param_type (str): The type of the parameter (e.g., "STRING", "INT64", "FLOAT64", "BOOL", "TIMESTAMP").
    param_value: The value of the parameter.

    Returns:
    dict: A dictionary representing the named parameter.

    Raises:
    ValueError: If the parameter type is unsupported or if the value cannot be converted to the expected type.
    """
    type_mapping = {
        "STRING": str,
        "INT64": int,
        "FLOAT64": float,
        "BOOL": bool,
        "TIMESTAMP": str
    }

    if param_type not in type_mapping:
        raise ValueError(f"Invalid parameter type: {param_type}. Supported types: {list(type_mapping.keys())}")

    expected_type = type_mapping[param_type]

    try:
        if expected_type == bool:
            if isinstance(param_value, str):
                param_value = param_value.lower() in ['1', 'true', 't', 'yes', 'y']
            elif isinstance(param_value, (int, float)):
                param_value = bool(param_value)
            else:
                param_value = bool(param_value)
        else:
            param_value = expected_type(param_value)
    except (ValueError, TypeError) as e:
        raise ValueError(f"Invalid value for parameter '{name}' with type '{param_type}': {e}")

    return {
        "name": name,
        "parameterType": {
            "type": param_type
        },
        "parameterValue": {
            "value": param_value
        }
    }
