    Recursively processes a list of book dictionaries and returns a list of tuples.
    Each tuple contains the book title, chapter number, and the total number of words in that chapter.

    :param books: List of dictionaries, where each dictionary represents a book.
    :return: List of tuples (book_title, chapter_number, total_words).
    """
    def recurse_books(book_list, result):
        if not book_list:
            return result
        book = book_list[0]
        result = recurse_chapters(book['chapters'], book['title'], result)
        return recurse_books(book_list[1:], result)

    def recurse_chapters(chapter_list, book_title, result):
        if not chapter_list:
            return result
        chapter = chapter_list[0]
        total_words = len(chapter['words'])
        result.append((book_title, chapter['chapter_number'], total_words))
        return recurse_chapters(chapter_list[1:], book_title, result)

