def tokenize_sentence(sentence):
    """
    Recursively tokenizes a given sentence into words, numbers, and nested groups.

    :param sentence: A string containing the sentence to be tokenized.
    :return: A list of tokens, where each token is either a word, a number (including fractions), or a list of tokens representing a nested group.
    """
    def helper(index):
        if index >= len(sentence):
            return [], index

        tokens = []
        while index < len(sentence):
            char = sentence[index]
            if char.isalnum():
                start_index = index
                while index < len(sentence) and (sentence[index].isalnum() or sentence[index] == '/'):
                    index += 1
                tokens.append(sentence[start_index:index])
            elif char == '(':
                nested_tokens, index = helper(index + 1)
                tokens.append(nested_tokens)
            elif char == ')':
                return tokens, index + 1
            else:
                index += 1

        return tokens, index

    return helper(0)[0]
