def majorityElement(nums, k):
    """
    Returns all elements that appear more than n/k times in the array.

    :param nums: List[int] - The array of integers.
    :param k: int - The given integer.
    :return: List[int] - Elements that appear more than n/k times.
    """
    n = len(nums)
    count = {}
    threshold = n // k
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    result = []
    for num, c in count.items():
        if c > threshold:
            result.append(num)

    return result
