class Stack:
    def __init__(self):
        self.items = []

    def is_empty(self):
        """Returns True if the stack is empty, otherwise False."""
        return len(self.items) == 0

    def push(self, item):
        """Adds an item to the top of the stack."""
        self.items.append(item)

    def pop(self):
        """Removes and returns the top item of the stack. Raises IndexError if the stack is empty."""
        if self.is_empty():
            raise IndexError("pop from empty stack")
        return self.items.pop()

    def peek(self):
        """Returns the top item of the stack without removing it. Raises IndexError if the stack is empty."""
        if self.is_empty():
            raise IndexError("peek from empty stack")
        return self.items[-1]

    def size(self):
        """Returns the number of items in the stack."""
        return len(self.items)

    def __str__(self):
        """Returns a string representation of the stack."""
        return "Stack: " + str(self.items)


class Queue:
    def __init__(self):
        self.items = []

    def is_empty(self):
        """Returns True if the queue is empty, otherwise False."""
        return len(self.items) == 0

    def enqueue(self, item):
        """Adds an item to the end of the queue."""
        self.items.append(item)

    def dequeue(self):
        """Removes and returns the front item of the queue. Raises IndexError if the queue is empty."""
        if self.is_empty():
            raise IndexError("dequeue from empty queue")
        return self.items.pop(0)

    def peek(self):
        """Returns the front item of the queue without removing it. Raises IndexError if the queue is empty."""
        if self.is_empty():
            raise IndexError("peek from empty queue")
        return self.items[0]

    def size(self):
        """Returns the number of items in the queue."""
        return len(self.items)

