def is_prime(num):
    """
    Check if a number is prime.

    :param num: Integer to check for primality.
    :return: True if num is prime, False otherwise.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def find_max_prime(n):
    """
    Find the largest prime number less than n.

    :param n: Integer to find the largest prime less than.
    :return: The largest prime number less than n, or -1 if no such prime exists.
    """
    for num in range(n-1, 1, -1):
        if is_prime(num):
            return num
    return -1
