class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        """Insert a new value into the BST."""
        if not self.root:
            self.root = Node(value)
        else:
            self._insert_recursively(self.root, value)

    def _insert_recursively(self, node, value):
        """Helper method to insert a value recursively."""
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._insert_recursively(node.left, value)
        else:
            if node.right is None:
                node.right = Node(value)
            else:
                self._insert_recursively(node.right, value)

    def preorder_traversal(self):
        """Return a list of values obtained by performing a preorder traversal."""
        return self._preorder_recursively(self.root)

    def _preorder_recursively(self, node):
        """Helper method to perform preorder traversal recursively."""
        result = []
        if node:
            result.append(node.value)
            result += self._preorder_recursively(node.left)
            result += self._preorder_recursively(node.right)
        return result

    def inorder_traversal(self):
        """Return a list of values obtained by performing an inorder traversal."""
        return self._inorder_recursively(self.root)

    def _inorder_recursively(self, node):
        """Helper method to perform inorder traversal recursively."""
        result = []
        if node:
            result += self._inorder_recursively(node.left)
            result.append(node.value)
            result += self._inorder_recursively(node.right)
        return result

    def postorder_traversal(self):
        """Return a list of values obtained by performing a postorder traversal."""
        return self._postorder_recursively(self.root)

    def _postorder_recursively(self, node):
        """Helper method to perform postorder traversal recursively."""
        result = []
        if node:
            result += self._postorder_recursively(node.left)
            result += self._postorder_recursively(node.right)
            result.append(node.value)
        return result
