def sort_tuples(tuples_list):
    """
    Sorts a list of tuples based on the second element of each tuple.
    If the second elements are equal, sorts based on the first element.
    Handles errors such as incorrect input types or tuples with insufficient elements.

    :param tuples_list: List of tuples to be sorted.
    :return: Sorted list of tuples.
    """
    try:
        if not isinstance(tuples_list, list):
            raise TypeError("Input should be a list of tuples.")

        for item in tuples_list:
            if not isinstance(item, tuple):
                raise TypeError("All elements in the list should be tuples.")

        for item in tuples_list:
            if len(item) < 2:
                raise ValueError("All tuples should have at least two elements.")

        return sorted(tuples_list, key=lambda x: (x[1], x[0]))

    except TypeError as te:
        print(f"TypeError: {te}")
    except ValueError as ve:
        print(f"ValueError: {ve}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

