```python
def extract_data(data_source, fields, formatters=None):
    """
    Extracts specified fields from a data source and applies optional formatting functions.

    Parameters:
    - data_source: A dictionary or an object with attributes.
    - fields: A tuple of strings representing the field names to extract.
    - formatters: An optional dictionary mapping field names to callable functions for formatting.

    Returns:
    - A dictionary with extracted fields and their formatted values.
    """
    if formatters is None:
        formatters = {}

    seen_ids = set()

    def extract_from_dict(data, field):
        if isinstance(data, dict):
            value = data.get(field, None)
            if value is not None:
                formatter = formatters.get(field, None)
                if formatter:
                    value = formatter(value)
            return value
        return None

    def extract_from_obj(obj, field):
        if isinstance(obj, dict):
            return extract_from_dict(obj, field)
        if hasattr(obj, field):
            value = getattr(obj, field)
            formatter = formatters.get(field, None)
            if formatter:
                value = formatter(value)
            return value
        return None

    def safe_extract(data, field):
        if id(data) in seen_ids:
            return None
        seen_ids.add(id(data))
        try:
            if isinstance(data, dict):
                return extract_from_dict(data, field)
            else:
                return extract_from_obj(data, field)
        finally:
            seen_ids.remove(id(data))

    extracted_data = {}
    for field in fields:
        value = safe_extract(data_source, field)
        if value is not None:
            extracted_data[field] = value
    return extracted_data
