def apply_to_elements(fn, seq):
    """
    Applies a given function to each non-iterable element in a nested structure.

    Parameters:
    fn (function): A function to apply to each non-iterable element.
    seq (list or tuple): A nested structure consisting of lists and tuples.

    Returns:
    list or tuple: A new nested structure with the same shape as `seq`, where each non-iterable element is the result of applying `fn` to the corresponding element in `seq`.
    """
    def is_iterable(item):
        try:
            iter(item)
            return not isinstance(item, (str, bytes))
        except TypeError:
            return False

    def apply_fn(item):
        if is_iterable(item):
            return type(item)(apply_fn(sub_item) for sub_item in item)
        else:
            return fn(item)

    return apply_fn(seq)
