def swap_keys_values(input_dict):
    """
    Swaps the keys and values of the input dictionary.
    If multiple keys share the same value, the value becomes a key in the new dictionary
    with its value being a list of all corresponding original keys.

    :param input_dict: Dictionary with unique keys
    :return: New dictionary with keys and values swapped
    """
    swapped_dict = {}
    for key, value in input_dict.items():
        if value not in swapped_dict:
            swapped_dict[value] = [key]
        else:
            swapped_dict[value].append(key)
    return swapped_dict

