import re

def extract_headline(text):
    """
    Extracts the headline from a given text based on the language.

    Args:
    text (str): The input text which may be in English or Chinese.

    Returns:
    str: The extracted headline.
    """
    # Determine the language
    is_chinese = bool(re.search(r'[\u4e00-\u9fff]', text))  # Simple Chinese character detection

    if is_chinese:
        # For Chinese: Extract text before the first occurrence of sentence-ending punctuation followed by a full-width space
        match = re.search(r'^(.*?)[。！？]　', text)
        if match:
            return match.group(1)
    else:
        # For English: Extract text before the first occurrence of sentence-ending punctuation followed by a space
        match = re.search(r'^(.*?)[.!?] ', text)
        if match:
            return match.group(1)

    # In case no headline pattern is found, return the entire text
    return text.strip()
