class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def is_symmetric(root: TreeNode) -> bool:
    """
    Determines if a binary tree is symmetric around its center.

    :param root: TreeNode, the root of the binary tree.
    :return: bool, True if the tree is symmetric, False otherwise.
    """
    def is_mirror(t1: TreeNode, t2: TreeNode) -> bool:
        """
        Helper function to check if two trees are mirror images of each other.

        :param t1: TreeNode, the first tree node.
        :param t2: TreeNode, the second tree node.
        :return: bool, True if t1 and t2 are mirror images, False otherwise.
        """
        if not t1 and not t2:
            return True
        if not t1 or not t2:
            return False
        return (t1.val == t2.val) and is_mirror(t1.right, t2.left) and is_mirror(t1.left, t2.right)

    if not root:
        return True

    return is_mirror(root.left, root.right)
