class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with the given 2D list data.
        Raises ValueError if data is not a valid 2D list with rows of equal length.
        """
        if not all(isinstance(row, list) and len(row) == len(data[0]) for row in data):
            raise ValueError("Data should be a 2D list with rows of equal length.")
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0])

    def add(self, other):
        """
        Adds the current matrix to another matrix and returns a new Matrix object.
        Raises ValueError if the matrices are not of the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be the same size to add.")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def subtract(self, other):
        """
        Subtracts another matrix from the current matrix and returns a new Matrix object.
        Raises ValueError if the matrices are not of the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be the same size to subtract.")
        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiplies the current matrix with another matrix and returns a new Matrix object.
        Raises ValueError if the number of columns in the current matrix does not match the number of rows in other.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must match number of rows in the second matrix.")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def transpose(self):
        """
        Transposes the current matrix and returns a new Matrix object.
        """
        result = [
            [self.data[j][i] for j in range(self.rows)]
            for i in range(self.cols)
        ]
        return Matrix(result)

    def __str__(self):
        """
        Returns a string representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])
