def validate_and_convert_date(date: str) -> tuple:
    def is_leap_year(year: int) -> bool:
        """Determine if a given year is a leap year."""
        return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

    def days_in_month(year: int, month: int) -> int:
        """Calculate the number of days in a specific month of a given year."""
        if month == 2:
            return 29 if is_leap_year(year) else 28
        elif month in {4, 6, 9, 11}:
            return 30
        else:
            return 31

    parts = date.split('-')
    if len(parts) != 3:
        return ('Invalid format', False)

    try:
        year = int(parts[0])
        month = int(parts[1])
        day = int(parts[2])
    except ValueError:
        return ('Invalid numbers', False)

    if year < 0:
        return ('Invalid year', False)

    if month < 1 or month > 12:
        return ('Invalid month', False)

    if day < 1 or day > days_in_month(year, month):
        return ('Invalid day', False)

    formatted_date = f"{year:04d}-{month:02d}-{day:02d}"
    return (formatted_date, True)
