def find_schema_differences(class_schema, db_schema):
    """
    Identifies and returns a list of differences between two schemas.

    Parameters:
    - class_schema: List of dictionaries representing the class schema.
    - db_schema: List of dictionaries representing the database schema.

    Returns:
    - List of dictionaries, each representing a difference between the schemas.
    """
    class_names = {col['name']: col for col in class_schema}
    db_names = {col['name']: col for col in db_schema}

    differences = []

    for col_name, col_info in class_names.items():
        if col_name not in db_names:
            differences.append({
                'column': col_name,
                'issue': 'missing_in_db',
                'class_info': col_info,
            })
        else:
            db_col_info = db_names[col_name]
            if col_info['type'] != db_col_info['type'] or col_info['nullable'] != db_col_info['nullable']:
                differences.append({
                    'column': col_name,
                    'issue': 'type_or_nullable_mismatch',
                    'class_info': col_info,
                    'db_info': db_col_info,
                })

    for col_name, col_info in db_names.items():
        if col_name not in class_names:
            differences.append({
                'column': col_name,
                'issue': 'missing_in_class',
                'db_info': col_info,
            })

    return differences
