import json

def process_json_data(json_data):
    """
    Processes a JSON string to compute the sum of all numeric values within it.

    Parameters:
    json_data (str): A JSON formatted string.

    Returns:
    dict: A dictionary with a single key 'sum_of_numbers' containing the sum of all numeric values.
          Returns an empty dictionary if the input is not a valid JSON string.
    """
    def sum_numeric_values(data):
        if isinstance(data, dict):
            return sum(sum_numeric_values(v) for v in data.values())
        elif isinstance(data, list):
            return sum(sum_numeric_values(i) for i in data)
        elif isinstance(data, (int, float)):
            return data
        else:
            return 0

