from typing import List

class Matrix:
    def __init__(self, data: List[List[int]]):
        """Initialize the matrix with the given 2D list data."""
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def __str__(self) -> str:
        """Return a string representation of the matrix."""
        return '\n'.join([' '.join(map(str, row)) for row in self.data])

    def transpose(self) -> 'Matrix':
        """Return the transpose of the matrix."""
        transposed_data = [[self.data[row][col] for row in range(self.rows)] for col in range(self.cols)]
        return Matrix(transposed_data)

    def multiply(self, other: 'Matrix') -> 'Matrix':
        """Multiply the matrix with another matrix and return the result."""
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to the number of rows in the second matrix")

        result_data = [[0 for _ in range(other.cols)] for _ in range(self.rows)]

        for i in range(self.rows):
            for j in range(other.cols):
                for k in range(self.cols):
                    result_data[i][j] += self.data[i][k] * other.data[k][j]

        return Matrix(result_data)
