import csv

def calculate_average_column(filename, column_name):
    """
    Calculate the average of a specified column in a CSV file.

    Parameters:
    filename (str): The name of the CSV file.
    column_name (str): The name of the column to calculate the average for.

    Returns:
    None: Prints the average of the column or an error message if applicable.
