            for row in reader:
                if column_name not in row:
                    raise KeyError(f"Column '{column_name}' not found in the CSV file.")
                try:
                    column_data.append(float(row[column_name]))
                except ValueError:
                    print(f"Warning: Non-numeric value found in column '{column_name}'. Skipping that entry.")
            if not column_data:
                raise ValueError(f"No valid numeric data found in column '{column_name}'.")
            average = sum(column_data) / len(column_data)
            print(f"The average of column '{column_name}' is: {average}")
    except FileNotFoundError:
        print(f"Error: The file '{filename}' was not found.")
    except KeyError as ke:
        print(f"Error: {ke}")
    except ValueError as ve:
        print(f"Error: {ve}")

if __name__ == "__main__":
