import os

def group_files_by_extension(file_paths):
    """
    Groups files by their extensions from a list of file paths.

    Parameters:
    file_paths (list): A list of file paths (strings).

    Returns:
    dict: A dictionary where keys are file extensions and values are lists of file names with that extension.
    """
    extension_dict = {}
    for path in file_paths:
        try:
            file_name = os.path.basename(path)
            ext = os.path.splitext(file_name)[1]
            if ext:
                ext = ext[1:]
                if ext in extension_dict:
                    extension_dict[ext].append(file_name)
                else:
                    extension_dict[ext] = [file_name]
            else:
                if 'no_extension' in extension_dict:
                    extension_dict['no_extension'].append(file_name)
                else:
                    extension_dict['no_extension'] = [file_name]
        except Exception as e:
            print(f"Error processing file path {path}: {e}")
    return extension_dict
