def is_valid_operation(val1, val2, operation):
    """
    Determines if the specified arithmetic operation can be performed on the given values.

    Parameters:
    val1 (int or float): The first operand.
    val2 (int or float): The second operand.
    operation (str): The arithmetic operation to perform ('+', '-', '*', '/', '**').

    Returns:
    bool: True if the operation is valid, False otherwise.
    """
    if not isinstance(val1, (int, float)) or not isinstance(val2, (int, float)):
        return False

    if operation == '+':
        return True
    elif operation == '-':
        return True
    elif operation == '*':
        return True
    elif operation == '/':
        return val2 != 0
    elif operation == '**':
        return val2 >= 0
    else:
        return False
